(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,549460,(e,n,i)=>{n.exports=JSON.parse('{"nameplate.???":"???","nameplate.Dark Figure":"Dunkle Gestalt","nameplate.Eerie Voice":"Unheimliche Stimme","nameplate.Elder Grah":"Elder Grah","nameplate.Eriole":"Eriole","nameplate.Grahdens":"Grahdens","nameplate.Kar & Seria":"Kar & Seria","nameplate.Karl":"Karl","nameplate.Lin":"Lin","nameplate.Lugina":"Lugina","nameplate.Man\'s Voice":"Männerstimme","nameplate.Mare":"Mare","nameplate.Mysterious Man":"Geheimnisvoller Mann","nameplate.Mysterious Woman":"Geheimnisvolle Frau","nameplate.Paris":"Paris","nameplate.Seria":"Seria","nameplate.Seria & Karl":"Seria & Karl","nameplate.Seria & Lugina":"Seria & Lugina","nameplate.Seria・Lugina":"Seria・Lugina","nameplate.Tilith":"Tilith","nameplate.Tilith & Seria":"Tilith & Seria","nameplate.Woman\'s Voice":"Frauenstimme","nameplate.Zebra":"Zebra","nameplate.静かな男の声":"Ruhige Männerstimme","story.map1-dungeon0-1end.001":"Im Village of the Venturer kannst du jetzt Materialien vom <color=00FF00>Hof</color> erhalten!","story.map1-dungeon0-2end.001":"Im Village of the Venturer kannst du jetzt Materialien vom <color=00FF00>Berg</color> erhalten!","story.map1-dungeon0-3end.001":"Im Village of the Venturer kannst du jetzt das <color=00FF00>Sphärenhaus</color> betreten!","story.map1-dungeon0-3end.002":"Im Sphärenhaus kannst du aus Materialien <color=00FFFF>Sphären</color> schmieden, mit denen du deine Einheiten ausrüstest.","story.map1-dungeon0-3end.003":"Schmiede mächtige Sphären, um deine Einheiten zu stärken!","story.map1-dungeon1.001":"<size=13>Ist das heiß! <wait=40>Ich will nach Hause! <wait=40>Das ist ja unerträglich...","story.map1-dungeon1.002":"<size=20>Oh! <wait=20><rep_handlename>!","story.map1-dungeon1.003":"Hey, du bist spät dran! <wait=40>Was hast du denn getrieben?!","story.map1-dungeon1.004":"Wie kannst du mich in dieser glühend heißen Höhle warten lassen!","story.map1-dungeon1.005":"Ich mache mir langsam Sorgen um unsere Reise...","story.map1-dungeon1.006":"Na gut, <wait=40>ich hab ja versprochen, dir genauer zu erklären, was hier eigentlich los ist...","story.map1-dungeon1.007":"Es ist ernst, also hör gut zu, okay?","story.map1-dungeon1.008":"Grand Gaia steckt mitten in einer großen Krise...","story.map1-dungeon1.009":"Der Grund ist, dass einige der mächtigen Götter, die über uns wachen, dem Bösen verfallen sind.","story.map1-dungeon1.010":"Sie widersetzen sich dem Heiligen Kaiser Karna Masta <wait=19>und richten nun Verwüstung an.","story.map1-dungeon1.011":"Unter diesen bösen Mächten <wait=40>nennt man die wenigen mit den außergewöhnlichsten Kräften...","story.map1-dungeon1.012":".<wait=10>.<wait=10>.<wait=10>die Vier Gefallenen Götter.","story.map1-dungeon1.013":"Früher waren sie hochrangige Götter...","story.map1-dungeon1.014":"...<wait=20>Aber jetzt wollen sie Grand Gaia für sich allein.","story.map1-dungeon1.015":"Die Vier Gefallenen Götter haben sich nicht nur Monster und Geister untertan gemacht,","story.map1-dungeon1.016":"...sie haben mit ihren Kräften auch die legendären Helden von Grand Gaia beschworen und manipuliert.","story.map1-dungeon1.017":"Wenn wir sie nicht aufhalten, <wait=40>wird Grand Gaia zerstört...","story.map1-dungeon1.018":"Selbst der Heilige Kaiser Karna Masta und die anderen Götter...","story.map1-dungeon1.019":"...<wait=20>können sie nicht ewig zurückhalten.","story.map1-dungeon1.020":"Deshalb hat Lord Lucius das Tor zu dieser Welt geöffnet.","story.map1-dungeon1.021":"Er möchte sich deine Kräfte leihen.","story.map1-dungeon1.022":"Darum können nur die Auserwählten das Tor sehen.","story.map1-dungeon1.023":"Lord Lucius setzt große Hoffnungen in dich.","story.map1-dungeon1.024":"Also enttäusch uns bloß nicht, <wait=20><rep_handlename>!","story.map1-dungeon1.025":"Damit wäre das geklärt. <wait=40>Dein erstes Ziel ist einer der Vier Gefallenen Götter...","story.map1-dungeon1.026":"Die Göttin der Schöpfung, <wait=20>Maxwell!","story.map1-dungeon1.027":"Maxwell <wait=20>hat St. Lamia erobert. Einst ein heiliges Land, ist es jetzt ihre Festung.","story.map1-dungeon1.028":"Von hier in Mistral aus <wait=40>musst du über Morgan hinaus, um dorthin zu gelangen.","story.map1-dungeon1.029":"Das ist ein ziemlich weiter Weg, <wait=40>aber du schaffst das bestimmt!","story.map1-dungeon1.030":"Gehen wir es Schritt für Schritt an, bis du den Dreh als Beschwörer raushast!","story.map1-dungeon1.031":"Um nach Morgan zu kommen, müssen wir zuerst zum Turm von Mistral.","story.map1-dungeon1.032":"Dafür <wait=20>müssen wir durch die Höhle der Flammen.","story.map1-dungeon1.033":"Man munkelt, <wait=20>dass es in dieser Höhle vor wilden Bestien wimmelt.","story.map1-dungeon1.034":"Aber trotzdem <wait=20>wirst du das schon schaffen!","story.map1-dungeon1.035":"<size=20>Argh! <wait=40>Ich halte diese Hitze nicht mehr aus!","story.map1-dungeon1.036":"Ich geh duschen. Pass auf dich auf und geh schon mal vor!","story.map1-dungeon2.001":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.002":"<size=36>Hatschi!!","story.map1-dungeon2.003":"...Meine Güte,<wait=30> ist das eiskalt!","story.map1-dungeon2.004":"Hey! <wait=40>Wie kannst du ein Mädchen an so einem kalten Ort warten lassen!","story.map1-dungeon2.005":"Brr... <wait=30>ist das kalt!!","story.map1-dungeon2.006":"Also, <wait=20>um zum Turm von Mistral zu kommen, <wait=40>musst du das Egor-Schneefeld durchqueren und durch den Wald...","story.map1-dungeon2.007":"Dann durch den Sumpf <wait=30>und danach durch die Ruinen...","story.map1-dungeon2.008":"Allein die Vorstellung ist schon weit genug, <wait=40>und dabei ist das extreme Wetter noch gar nicht mitgerechnet!","story.map1-dungeon2.009":"Jedenfalls <wait=20>hast du noch einen weiten Weg bis zum Turm.","story.map1-dungeon2.010":"Aber sei vorsichtig. <wait=20>Je näher du ihm kommst, desto stärker werden die Gegner.","story.map1-dungeon2.011":"Wenn du auf einen Gegner triffst, den du nicht besiegen kannst, <wait=20>geh am besten zum vorigen Dungeon zurück und trainiere ein bisschen.","story.map1-dungeon2.012":"Ach ja, <wait=20>es wird auch Zeit, dass du deinen Trupp mit Blick auf die Elemente zusammenstellst.","story.map1-dungeon2.013":"Die meisten Gegner in der Höhle waren Feuerwesen, also hätte dir ein Trupp aus Wasser-Einheiten einen riesigen Vorteil verschafft!","story.map1-dungeon2.014":"Diesmal sind wir auf einem Schneefeld. <wait=40>Ich glaube, hier sehen wir viele Wasserwesen.","story.map1-dungeon2.015":"Also... <wait=20>Überraschungsfrage! <wait=40>Welches Element ist stark gegen Wasser?","story.map1-dungeon2.016":"Ja, <wait=40>genau!","story.map1-dungeon2.017":"Du hast wohl gelernt. <wait=40>Jep, Donner schlägt Wasser.","story.map1-dungeon2.018":"Feuer-Einheiten sind dagegen gegen die Gegner vom Schneefeld im Nachteil, also sei vorsichtig.","story.map1-dungeon2.019":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.020":"<size=36>Hatschi!!","story.map1-dungeon2.021":"Mann, <wait=20>ich halt\'s nicht mehr aus. <wait=40>Ich geh nach Hause!","story.map1-dungeon2.022":"...Ah, <wait=20>fast hätte ich\'s vergessen.","story.map1-dungeon2.023":"Anscheinend stiftet ein von Maxwell beschworener Ritter irgendwo am Ende dieses Schneefelds Chaos.","story.map1-dungeon2.024":"Er soll ziemlich stark sein. Pass auf dich auf!","story.map1-dungeon3.001":"Oh, <wait=20><rep_handlename>! <wait=40>Gut gemacht, du hast das Schneefeld durchquert.","story.map1-dungeon3.002":"Hmm, <wait=40>ich muss sagen, du wirkst jetzt viel würdevoller als bei unserem ersten Treffen.","story.map1-dungeon3.003":"Na dann, <wait=20>auf durch den Wald der Bestien!","story.map1-dungeon3.004":"Wie der Name schon sagt, wimmelt es in diesem Wald von wilden Bestien...","story.map1-dungeon3.005":"Aber dein eigentlicher Gegner <wait=20>ist der, der sie jagt.","story.map1-dungeon3.006":"Ach, <wait=40>und hast du schon eine Sphäre ausgerüstet?","story.map1-dungeon3.007":"Mit Sphären kannst du die Fähigkeiten deiner Einheiten verbessern.","story.map1-dungeon3.008":"Als Beschwörer musst du das wissen, wenn du lange überleben willst.","story.map1-dungeon3.009":"Sphären kannst du im Sphärenhaus in deiner Welt schmieden.","story.map1-dungeon3.010":"Rüste deine Einheiten mit Sphären aus und stelle einen stärkeren Trupp zusammen!","story.map1-dungeon3.011":"Für Sphären brauchst du bestimmte Materialien, die du erst sammeln musst.","story.map1-dungeon3.012":"Na, jedenfalls <wait=20>viel Glück und kämpf tapfer!<br>","story.map1-dungeon4.001":"<size=18>Argh, <wait=20>das ist ja furchtbar!! Was soll diese irre Luftfeuchtigkeit?!","story.map1-dungeon4.002":"Meine Haare und Klamotten kleben total eklig!!","story.map1-dungeon4.003":"Ah... <wait=20><rep_handlename>.","story.map1-dungeon4.004":"Du hast es durch den Wald geschafft. Wenigstens hab ich meine Zeit nicht umsonst mit dir verschwendet.","story.map1-dungeon4.005":"Ach, <wait=20>genau. <wait=40>Setzt du Funken auch gut ein?","story.map1-dungeon4.006":"Wenn deine Einheiten gleichzeitig angreifen und du einen Funken erzielst, steigt dein Schaden deutlich.","story.map1-dungeon4.007":"Das ist eine sehr wichtige Technik. Besonders gegen schwierige Gegner hilft sie.","story.map1-dungeon4.008":"Übe weiter, bis du das Timing raushast und jede Menge Funken erzielst!","story.map1-dungeon4.009":"<wait=20>Na dann, beeilen wir uns durch den Magutagal-Sumpf! Hier ist es so eklig...","story.map1-dungeon4.010":"Argh, <wait=20>mich stechen die Insekten. Wenn ich länger bleibe, sind meine glatten Beine voller Stiche.","story.map1-dungeon4.011":"Das reicht! <wait=40>Ich warte bei den Ruinen auf dich!","story.map1-dungeon5.001":"Oh, <wait=20><rep_handlename>! <wait=40>Du hast es endlich zu den Ruinen geschafft!","story.map1-dungeon5.002":"Ehrlich gesagt <wait=20>wirktest du bei unserem ersten Treffen unzuverlässig, <wait=20>ahnungslos <wait=20>und hattest keinen Schimmer, was um dich herum los war...","story.map1-dungeon5.003":"Ich hab mich echt gefragt... <wait=40>ist das wirklich ein Beschwörer?","story.map1-dungeon5.004":"Aber Lord Lucius hatte wohl recht. <wait=20>Du hast Potenzial!","story.map1-dungeon5.005":"Übrigens, <wait=20>du kennst doch sicher schon Leader-Skills, oder?","story.map1-dungeon5.006":"Um dir einen Vorteil gegenüber deinem Gegner zu verschaffen oder die Schwächen deines Trupps auszugleichen...","story.map1-dungeon5.007":"ist es wichtig, verschiedene Leader auszuprobieren und ihre Leader-Skills zu testen.","story.map1-dungeon5.008":"Außerdem: <wait=40>Wenn dir ein anderer Beschwörer hilft...","story.map1-dungeon5.009":"...wird dessen Leader-Skill auch aktiviert.","story.map1-dungeon5.010":"Das ist wichtig, also merk es dir!","story.map1-dungeon5.011":"Komm schon, <wait=20>wir sind nur noch einen Katzensprung vom Turm von Mistral entfernt!","story.map1-dungeon5.012":"Diese Überreste von Mirza <wait=40>sind die Reste eines Bauwerks, das vor Tausenden von Jahren errichtet wurde...","story.map1-dungeon5.013":"Aber in letzter Zeit hab ich nichts von Kreaturen gehört, die hier herumschleichen.","story.map1-dungeon5.014":"Vielleicht, <wait=20>nur vielleicht, <wait=20>kommst du ja ohne Zwischenfall durch!","story.map1-dungeon5.015":"Na ja... <wait=20>das wissen wir erst, wenn du es versuchst.","story.map1-dungeon5.016":"Aber bei allem, was du bisher geschafft hast, <wait=20>kann dich wohl kaum etwas aufhalten!","story.map1-dungeon5.017":"Sei selbstbewusst! Viel Glück!","story.map1-dungeon6.001":"Oh, <wait=20><rep_handlename>.<br><wait=40>Du bist lebend aus den Ruinen gekommen...","story.map1-dungeon6.002":"Brr... <wait=20>Hier ist es kalt und unheimlich. <wait=40>Sieh dir nur das zwielichtige Gebäude da drüben an.","story.map1-dungeon6.003":"Ich hab gehört, man nennt es das Monsternest...","story.map1-dungeon6.004":"Bei dem Ort kriege ich Gänsehaut!","story.map1-dungeon6.005":"Und in letzter Zeit gibt es Berichte über einen geheimnisvollen Schwertkämpfer, der hier umherstreift.","story.map1-dungeon6.006":"<size=20>I-<wait=10>Ich <size=19>sag <size=18>j-<size=17>ja <size=16>nicht, <size=15>dass <size=14>ich <size=13>A-<size=12>Angst <size=11>hab<size=9>!","story.map1-dungeon6.007":"J-Jedenfalls <wait=20>soll er eine seltsame Kluft tragen und ein merkwürdiges Schwert führen. <wait=20>Seine wahre Stärke sollte man trotzdem nicht unterschätzen.","story.map1-dungeon6.008":"Bleib also unbedingt wachsam...","story.map1-dungeon6.009":"<size=20>Iiih!!<br><wait=20><size=18>Da-<size=20>Da <size=16>ist <size=19>gerade <size=17>was <size=18>a-<size=15>auf <size=17>meinem Arm <size=19>gelandet...","story.map1-dungeon6.010":"Oh, <wait=20>ein Blatt?<br><wait=60>Was... <wait=20>was guckst du denn so?","story.map1-dungeon6.011":"J-Jedenfalls, <wait=20>pass auf!","story.map1-dungeon6.012":"Wenn wir hier durch sind, <wait=20>stehen wir am Fuß des Turms von Mistral!","story.map1-dungeon6.013":"Viel Glück, <wait=20><rep_handlename>!","story.map1-dungeon7.001":"Wir sind endlich am Turm von Mistral angekommen.","story.map1-dungeon7.002":"Obwohl der Turm noch in Mistral liegt, hat Maxwell ihn bereits unter ihre Kontrolle gebracht.","story.map1-dungeon7.003":"Ehrlich gesagt <wait=20>sind die Gegner bisher nichts im Vergleich zu Maxwells Untergebenen.","story.map1-dungeon7.004":"Wir müssen bestens vorbereitet sein, um diesen Kampf zu gewinnen und den Turm aus Maxwells Gewalt zu befreien.","story.map1-dungeon7.005":"Im obersten Stockwerk <wait=20>wartet ein Monster, das Maxwell selbst erschaffen haben soll.","story.map1-dungeon7.006":"Aber wir können es uns nicht leisten, dass du hier zerquetscht wirst.","story.map1-dungeon7.007":"Wir sind noch weit von St. Lamia entfernt, wo Maxwell lauert.","story.map1-dungeon7.008":"Du schaffst das bestimmt. <wait=40>Inzwischen hast du sogar meinen Respekt. <wait=20>Vertrau ein bisschen auf dich!","story.map1-dungeon7.009":"Los, <wait=40><rep_handlename>!","story.map1-dungeon7.010":"Entfessle deine Kraft <wait=20>und befreie Mistral aus den Klauen des Bösen!","story.map1-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_clear.002":"<size=21>Da bist du ja!</size>","story.map1-dungeon_ex_clear.003":"<rep_handlename>! <wait=40>Du hast es geschafft!","story.map1-dungeon_ex_clear.004":"Wir haben das Erlöschen einer gewaltigen Macht festgestellt.","story.map1-dungeon_ex_clear.005":"Anscheinend hast du Skramya besiegt.","story.map1-dungeon_ex_clear.006":"Ich wusste: Wenn es einer schafft, dann du!","story.map1-dungeon_ex_clear.007":"Oh, <wait=20>du bist doch nicht etwa verletzt?","story.map1-dungeon_ex_clear.008":"Ich pflege dich, wenn wir zurück sind!","story.map1-dungeon_ex_clear.009":"Hehe, war nur Spaß.","story.map1-dungeon_ex_clear.010":"Ähm, <wait=20>dank dir haben wir jetzt allerlei neue Informationen.","story.map1-dungeon_ex_clear.011":"Anscheinend wollte vor langer Zeit eine kleine Nation in der Mystral Region Skramyas Kraft nutzen.","story.map1-dungeon_ex_clear.012":"Ihr Plan ging nach hinten los, und Skramya zerstörte sie in seiner Wut.","story.map1-dungeon_ex_clear.013":"Skramyas Zorn hielt an, und er zog weiter zu anderen Nationen.","story.map1-dungeon_ex_clear.014":"Doch ein einzelner Held erschien und versiegelte Skramya mit Bravour. ","story.map1-dungeon_ex_clear.015":"Danach ruhte Skramya wohl ungestört im Egor-Gebirge. ","story.map1-dungeon_ex_clear.016":"Ich wüsste zu gern, was für ein Held das war, aber mehr Informationen haben wir nicht.","story.map1-dungeon_ex_clear.017":"Ich hoffe, wir erfahren eines Tages mehr über diese Person.","story.map1-dungeon_ex_clear.018":"Na dann, <wait=40>ich melde mich, sobald wir mehr wissen!","story.map1-dungeon_ex_clear.019":"Viel Erfolg bei deiner weiteren Erkundung von Grand Gaia!","story.map1-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_open.002":"H-<wait=20>Hallo...","story.map1-dungeon_ex_open.003":"Hört mich jemand?","story.map1-dungeon_ex_open.004":"Hörst du mich, <wait=40>Herr Beschwörer?","story.map1-dungeon_ex_open.005":"Ah! <wait=40>Ich bin durchgekommen!","story.map1-dungeon_ex_open.006":"<rep_handlename>!","story.map1-dungeon_ex_open.007":"Du bist ja schon im Egor-Gebirge!","story.map1-dungeon_ex_open.008":"Ich wusste, dass du das schaffst!","story.map1-dungeon_ex_open.009":"Oh, <wait=20>ich stelle mich noch einmal vor.","story.map1-dungeon_ex_open.010":"Ich bin Lin Merylham von der Logistikunterstützung...","story.map1-dungeon_ex_open.011":"...des Ermittlungsbüros im Vermessungsamt von Grand Gaia, zu deinen Diensten.","story.map1-dungeon_ex_open.012":"Heute...","story.map1-dungeon_ex_open.013":"...bitten wir dich, <rep_handlename>, als Mitglied der Beschwörerarmee der Akras-Beschwörerhalle...","story.map1-dungeon_ex_open.014":"...das Egor-Gebirge zu erkunden!","story.map1-dungeon_ex_open.015":"Es liegt zwar in der Mystral Region, aber die Erkundung verzögerte sich, weil es unter Maxwells Kontrolle stand...","story.map1-dungeon_ex_open.016":"...doch seit sie besiegt ist, können wir es endlich gründlicher untersuchen!","story.map1-dungeon_ex_open.017":"Es gibt wirklich beeindruckende Beschwörer da draußen, nicht wahr?","story.map1-dungeon_ex_open.018":"Gib auch du bitte dein Bestes!","story.map1-dungeon_ex_open.019":"Oh, <wait=20>zurück zum Thema.","story.map1-dungeon_ex_open.020":"Also, das Egor-Gebirge...","story.map1-dungeon_ex_open.021":"Laut unseren Ermittlungen schläft dort ein ungeheuer mächtiger Dämon. ","story.map1-dungeon_ex_open.022":"Wir sind uns noch nicht ganz sicher, aber...","story.map1-dungeon_ex_open.023":"...es ist sehr wahrscheinlich der Eisdämon, der in der Mystral Region hausen soll.","story.map1-dungeon_ex_open.024":"Hä?","story.map1-dungeon_ex_open.025":"Du kennst Skramya, den Eisdämon, nicht?","story.map1-dungeon_ex_open.026":"Das überrascht mich aber sehr...","story.map1-dungeon_ex_open.027":"Verstanden! <wait=40>Dann erkläre ich es dir!","story.map1-dungeon_ex_open.028":"Vor langer Zeit, in der Mystral Region...","story.map1-dungeon_ex_open.029":"...gab es neben dem alten Königreich St. Lamia wohl noch einige andere kleinere Nationen.","story.map1-dungeon_ex_open.030":"Es heißt, sie wurden alle von den Göttern zerstört, nachdem diese einfielen.","story.map1-dungeon_ex_open.031":"Eine davon soll jedoch nicht von einem Gott zerstört worden sein, sondern von Skramya.","story.map1-dungeon_ex_open.032":"So klein es auch gewesen sein mag – dass ein Königreich von einem einzigen Dämon ausgelöscht wird...","story.map1-dungeon_ex_open.033":"......","story.map1-dungeon_ex_open.034":".........","story.map1-dungeon_ex_open.035":"Ähm, <wait=20>mehr Informationen habe ich nicht.","story.map1-dungeon_ex_open.036":"Mehr musst du auch nicht wissen!","story.map1-dungeon_ex_open.037":"Er hat die Macht, Königreiche zu zerstören!","story.map1-dungeon_ex_open.038":"Er ist extrem gefährlich!","story.map1-dungeon_ex_open.039":"Als Beschwörer kannst du ihn nicht einfach gewähren lassen!","story.map1-dungeon_ex_open.040":"Wow, dich scheint gar nicht zu kümmern, wie gefährlich er ist.","story.map1-dungeon_ex_open.041":"Aber dieser Dämon ist wirklich brutal, <wait=20>also übernimm dich bitte nicht!","story.map1-dungeon_ex_open.042":"Na dann, ich freue mich auf einen guten Bericht von dir!","story.map1-ending.001":"<size=24><rep_handlename>!!<br>Du hast es geschafft!!</size>","story.map1-ending.002":"Dein Kampf gegen den Juggernaut war einfach <wait=40>klasse!","story.map1-ending.003":"Jetzt darfst du dich stolz einen fähigen Beschwörer nennen.","story.map1-ending.004":"Vielleicht... <wait=40>bist du Maxwells geborener Erzfeind...","story.map1-ending.005":"Nein, <wait=40>da gibt\'s kein Vielleicht!","story.map1-ending.006":"Du musst der Beschwörer sein, der dazu bestimmt ist, Grand Gaia zu retten!","story.map1-ending.007":"...<wait=20>Hey! <wait=40>Du könntest ruhig etwas mehr Dankbarkeit zeigen, wenn man dich lobt!","story.map1-ending.008":"Kannst du dich nicht ein bisschen freuen? <wait=40>Es ist peinlich, wenn nur ich hier so aus dem Häuschen bin.","story.map1-ending.009":"Oh! <wait=40>Lord Lucius ruft nach uns!","story.map1-ending.010":"<speed=12>Endlich können wir nach Morgan aufbrechen<wait=10>.<wait=20>.<wait=30>.","story.map1-ending.011":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ich bin Lucius...<br><wait=40>Gott dieses Tores...","story.map1-ending.012":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Retter von St. Lamia...","story.map1-ending.013":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Nutze meine Kraft <wait=40>und zieh in neue Länder...","story.map1-ending.014":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Schreite voran <wait=20>und bringe dieser Welt mit deiner Kraft Frieden...","story.map1-ending.015":"<anchor=center><color=000000><speed=5><size=12>...Wach auf!","story.map1-ending.016":"<anchor=center><color=000000><speed=7><size=18>...Hörst du mich?","story.map1-ending.017":"<anchor=center><color=000000><speed=15><size=40><rep_handlename>, wach auf!!","story.map1-ending.018":"Mann, <wait=40>du schläfst echt viel zu viel!!","story.map1-ending.019":"Was? <wait=40>Wo wir sind? Das ist Morgan... <wait=20>Morgan!","story.map1-ending.020":"Ist das nicht wunderbar! <wait=20>Die Tore nach Morgan sind endlich offen.","story.map1-ending.021":"Endlich, was... <wait=20>Morgan...","story.map1-ending.022":"Dieser Ort war einst für seine malerische Landschaft berühmt...","story.map1-ending.023":"Aber viele Jahre sind vergangen, <wait=20> und inzwischen ist er in Maxwells Hände gefallen.","story.map1-ending.024":"Die Monster hier sind viel stärker als die in Mistral...","story.map1-ending.025":"Wir wissen nicht, was uns erwartet, <wait=40>also kehrst du besser in dein Dorf zurück und bereitest dich vor.","story.map1-ending.026":"Ich warte hier.","story.map1-ending.027":"Wenn du zurück bist, gehen wir zum Turm von Morgan <wait=19>und befreien dort dieses Land!","story.map1-ending.028":"Na dann, <wait=20>bis später!","story.map10-dungeon1.001":"<size=20>Du bist spät dran! <wait=40>Wo warst du, <rep_handlename>!</size>","story.map10-dungeon1.002":"Ich schufte mich ab, um deinen Freund zu retten, und du wagst es, mich warten zu lassen!","story.map10-dungeon1.003":"Du <size=20>lahmer </size>Trottel!","story.map10-dungeon1.004":"Ich weiß ja, dass es ein Auftrag der Ältesten Beschwörer ist, aber warum muss ausgerechnet ich ihm hinterherjagen?","story.map10-dungeon1.005":"Hey, was soll denn das Gesicht?","story.map10-dungeon1.006":"Du glaubst doch nicht etwa, dass ich mich vor dieser Mission drücke, oder?","story.map10-dungeon1.007":"<size=20>Verarsch mich nicht!</size>","story.map10-dungeon1.008":"Wenn ich meine Pflichten perfekt erfülle, steht am Ende dieser Blender Karl wie ein Narr da.","story.map10-dungeon1.009":"So eine Chance bekomme ich nicht oft.","story.map10-dungeon1.010":"Also reiß dich gefälligst zusammen und hilf mir!","story.map10-dungeon1.011":"Dann sind wir mit unserer Untersuchung hier vielleicht schnell fertig.","story.map10-dungeon1.012":"Ob das hier die Hauptstadt des Agni-Imperiums war oder nicht – diese staubigen alten Stadtruinen sehen doch alle gleich aus.","story.map10-dungeon1.013":"<size=20>Hey!</size>","story.map10-dungeon1.014":"Hör auf rumzutrödeln und such diesen faulen Karl!","story.map10-dungeon1.015":"Hm?","story.map10-dungeon1.016":"Wo du anfangen sollst?","story.map10-dungeon1.017":"Du bist so ein Idiot!","story.map10-dungeon1.018":"Ich frage mich, ob der Kopf auf deinen Schultern nur zur Dekoration da ist.","story.map10-dungeon1.019":"Aber diese Jüngerin Mare ist doch immer noch hinter dir her, oder nicht?","story.map10-dungeon1.020":"Wenn du hier für Aufruhr sorgst, kommt sie bestimmt – mit Karl als Druckmittel.","story.map10-dungeon1.021":"Das wäre unsere Chance, diesen Trottel Karl zu retten.","story.map10-dungeon1.022":"Wenn du verstehst, was ich meine, dann tu weiter so, als würdest du ermitteln, du Narr, und mach so viel Wirbel wie möglich!","story.map10-dungeon2.001":"<size=20>Verdammt! </size><wait=40><size=22>Wie ärgerlich!","story.map10-dungeon2.002":"Was bildet sich diese bleichgesichtige Frau ein, sich vor uns zu verstecken!","story.map10-dungeon2.003":"Hey! <wait=40><rep_handlename>!","story.map10-dungeon2.004":"Du könntest ruhig ein bisschen mehr Lärm machen, findest du nicht?","story.map10-dungeon2.005":"Lauf einfach wie immer offen herum, da fällst du leichter auf!","story.map10-dungeon2.006":"Wie erbärmlich bist du eigentlich? Du kannst nicht mal den Köder spielen!","story.map10-dungeon2.007":"Nngh! <wait=40>So geduldig ich auch bin, du treibst mich an meine Grenzen.","story.map10-dungeon2.008":"Ich kann nicht länger auf diese Jüngerin warten.","story.map10-dungeon2.009":"Ich suche Karl allein!","story.map10-dungeon2.010":"Du suchst ihn auch auf eigene Faust!","story.map10-dungeon2.011":"So nett bin ich nicht, dass ich jemanden beschütze, der mir nichts nützt.","story.map10-dungeon2.012":"Also lauf mir nicht hinterher, verstanden?","story.map10-dungeon2.013":"<size=20>Hey! <rep_handlename>!</size>","story.map10-dungeon2.014":"Fast hätte ich vergessen, es dir zu sagen.","story.map10-dungeon2.015":"Lass dich auf keinen Fall von dieser Jüngerin erwischen.","story.map10-dungeon2.016":"Wenn du dich erwischen lässt, darf ich dich am Ende bestimmt auch noch retten.","story.map10-dungeon2.017":"Noch mehr lästige Aufträge kann ich nicht gebrauchen.","story.map10-dungeon2.018":"Ehrlich gesagt, wenn du gefangen wirst, wäre es besser, sie würde dich gleich in Stücke schlagen.","story.map10-dungeon2.019":"<size=20>Hast du mich verstanden!?</size>","story.map10-dungeon3.001":"Anscheinend bin ich diese Plagegeister endlich los.","story.map10-dungeon3.002":"Hm. <wait=40>Was soll dieser überraschte Blick?","story.map10-dungeon3.003":"Sieht so aus, als wärst du endlich allein.","story.map10-dungeon3.004":"Selbst ein dummer Mensch hätte vorhersehen können, dass ich vor dir erscheine, meiner Beute.","story.map10-dungeon3.005":"Oder bist du so dumm, dass du es nicht einmal bemerkt hast?","story.map10-dungeon3.006":"......","story.map10-dungeon3.007":"Suchst du etwa diese mickrige grüne Ausrede für ein Lebewesen?","story.map10-dungeon3.008":"Er ist bestimmt auf die gefälschten Informationen über Karls Aufenthaltsort hereingefallen, die ich hinterlassen habe.","story.map10-dungeon3.009":"Wahrscheinlich rennt er gerade panisch durch ganz Agni.","story.map10-dungeon3.010":"Trotz seiner großen Klappe ist er eben nur ein Mensch.","story.map10-dungeon3.011":"Deine kleinen Freunde waren vorhin ziemlich lästig, weil ich nichts von ihnen wusste.","story.map10-dungeon3.012":"Aber jetzt scheint niemand mehr da zu sein, der dir helfen könnte.","story.map10-dungeon3.013":"Ich würde gern noch einmal versuchen, dir das Leben zu nehmen.","story.map10-dungeon3.014":"......","story.map10-dungeon3.015":"Allerdings bist du der Beschwörer, der schon viele Götter besiegt hat.","story.map10-dungeon3.016":"Ich sollte dich noch ein wenig mehr verausgaben lassen.","story.map10-dungeon3.017":"Wenn du Karl retten willst, dann folge mir.","story.map10-dungeon3.018":"Sonst ist sein Leben vorbei.","story.map10-dungeon3.019":"Ich frage mich, ob du mir folgst, obwohl du weißt, dass der Weg voller Fallen ist.","story.map10-dungeon3.020":"Pah. <wait=40>Ihr Menschen seid wirklich törichte Wesen.","story.map10-dungeon3.021":"Kämpf dich nur voran, damit ich dich später leichter erledigen kann.","story.map10-dungeon3.022":"Ich freue mich schon darauf, dich geschwächt zu sehen.","story.map10-dungeon4.001":"Du hast also die Granasta-Hochebene bezwungen.","story.map10-dungeon4.002":"Das war wohl zu erwarten von dem, der sowohl Maxwell als auch Cardes besiegt hat.","story.map10-dungeon4.003":"......","story.map10-dungeon4.004":"Wenn ich dich ansehe, erinnere ich mich an den Krieg, in dem die Menschen vernichtet wurden.","story.map10-dungeon4.005":"Diese Menschen, die so töricht waren zu glauben, sie könnten sich den Göttern widersetzen.","story.map10-dungeon4.006":"Ach ja, damals gab es noch einen anderen Menschen, der genauso hartnäckig war wie du.","story.map10-dungeon4.007":"Die anderen Menschen nannten ihn wohl einen Helden.","story.map10-dungeon4.008":"Doch auch er war genauso hilflos und hoffnungslos verängstigt wie du jetzt.","story.map10-dungeon4.009":"So mächtig er für einen Menschen auch war...","story.map10-dungeon4.010":"...es änderte nichts daran, dass er kaum mehr als ein unwissender Mensch war.","story.map10-dungeon4.011":"Auch du wirst bald einen ähnlichen Ausdruck tragen.","story.map10-dungeon4.012":"Ich freue mich darauf, das zu genießen.","story.map10-dungeon4.013":"......","story.map10-dungeon4.014":"Pah. <wait=40>Dieser Blick von dir interessiert mich nicht.","story.map10-dungeon4.015":"Ich muss dich wohl einfach noch etwas mehr leiden lassen.","story.map10-dungeon4.016":"Was hältst du davon?","story.map10-dungeon4.017":"Zeig mir, wie weit du allein kommst.","story.map10-dungeon5.001":"<rep_handlename>. Du leistest also immer noch Widerstand.","story.map10-dungeon5.002":"Ich hasse diese Augen von dir, <wait=40>in denen keine Verzweiflung liegt.","story.map10-dungeon5.003":"Wie kannst du in so einer Lage noch Hoffnung haben?","story.map10-dungeon5.004":"Keiner deiner Verbündeten, die dich unterstützt haben, ist noch da.","story.map10-dungeon5.005":"Nicht einmal dein Kindheitsfreund.","story.map10-dungeon5.006":"Nicht die Beschwörerin, die dich ständig beschimpft hat.","story.map10-dungeon5.007":"Nicht der alte Mann mit seinen lächerlichen Erwartungen an dich.","story.map10-dungeon5.008":"Nicht diese unglaublich ordinäre Kreatur.","story.map10-dungeon5.009":"Nicht einmal die niedere Göttin, die dich die ganze Zeit benutzt hat.","story.map10-dungeon5.010":"......","story.map10-dungeon5.011":"Oder willst du mir etwa sagen, dass du dich von Anfang an nie auf jemand anderen verlassen hast?","story.map10-dungeon5.012":"Und trotzdem versuchst du verzweifelt, deine Freunde zu retten?","story.map10-dungeon5.013":"Was für ein unbegreiflicher Gedanke.","story.map10-dungeon5.014":"......","story.map10-dungeon5.015":"Verstehe, jetzt erinnere ich mich.","story.map10-dungeon5.016":"Ach ja, <wait=20>damals, als dieser Mann bis zum Hals in Schwierigkeiten steckte...","story.map10-dungeon5.017":"...erweckte er eine neue Kraft in sich.","story.map10-dungeon5.018":"Er trug gewaltige Flammenflügel auf dem Rücken.","story.map10-dungeon5.019":"Die Schmach dieser Kraft, die er führte, wollte ich schon lange vergessen.","story.map10-dungeon5.020":"Wenn ich annehmen muss, dass du dieselbe Kraft in dir trägst, habe ich keine Zeit mehr für Spielereien.","story.map10-dungeon5.021":"Pah...","story.map10-dungeon5.022":"Aber ich kann dich nicht ewig herumstehen und meine Zeit verschwenden lassen.","story.map10-dungeon5.023":"Der Kampf zwischen Lord Zefalhua und Afla Dilith steht kurz bevor.","story.map10-dungeon5.024":"Ich muss dich erledigen, bevor du meine Vorhersagen durchkreuzen kannst.","story.map10-dungeon5.025":"Bist du bereit?","story.map10-dungeon5.026":"Ich zeige dir eine Welt der Verzweiflung, wie du sie noch nie gesehen hast.","story.map10-dungeon5.027":"Ich halte mich nicht zurück, also sieh nun meine wahre Kraft!","story.map10-dungeon5.028":"Nimm sie mit allem auf, was du hast!","story.map10-dungeon6.001":"Das ist weit genug, <wait=40><rep_handlename>.","story.map10-dungeon6.002":"Du hast bisher gut gegen die Götter gekämpft.","story.map10-dungeon6.003":"Doch an den Wunden, die deinen Körper bedecken, sehe ich, dass du nicht mehr kämpfen kannst.","story.map10-dungeon6.004":"Ich lasse nicht zu, dass Lucius und seine Vorhersagen noch weiter voranschreiten!","story.map10-dungeon6.005":"Stirb!","story.map10-dungeon6.006":"<size=18>*Kliiiing*","story.map10-dungeon6.007":"Nngh!","story.map10-dungeon6.008":"Wie konntest du dir von so einer Frau so viel Ärger machen lassen?","story.map10-dungeon6.009":"Ehrlich, <wait=20>du bist so ein Idiot.","story.map10-dungeon6.010":"Hey, reiß dich zusammen!","story.map10-dungeon6.011":"Lass dich nicht besiegen, bevor wir Karl retten konnten!","story.map10-dungeon6.012":"Narr! <wait=20>Du willst dich trotz deiner Verletzungen noch bewegen?","story.map10-dungeon6.013":"Verarsch mich nicht.","story.map10-dungeon6.014":"Hast du wirklich geglaubt, so ein Angriff würde mich erledigen?","story.map10-dungeon6.015":"Für eine Jüngerin bist du ganz schön dumm.","story.map10-dungeon6.016":"Wie überaus menschlich von dir.","story.map10-dungeon6.017":"<size=18>*Klaaaang*","story.map10-dungeon6.018":"Nngh!","story.map10-dungeon6.019":"Was stehst du da nur herum?","story.map10-dungeon6.020":"Hat dich der Kampf mit <rep_handlename> vielleicht erstarren lassen?","story.map10-dungeon6.021":"Ach ja, <wait=20>was Karl angeht: <wait=20>Lugina ist bereits unterwegs, um ihn aus dem Meeresschrein zu befreien.","story.map10-dungeon6.022":"Und du dachtest, du hättest ihn so geschickt getäuscht. <wait=20>Wie bedauerlich.","story.map10-dungeon6.023":"Das ist unmöglich.","story.map10-dungeon6.024":"Nngh, <rep_handlename>. <wait=20>Diesmal bist du dem Tod wohl knapp entkommen.","story.map10-dungeon6.025":"Auch wenn alles, was zu dir zurückgekehrt ist, eine von Wunden übersäte Beschwörerin ist.","story.map10-dungeon6.026":"Ich vernichte euch beide, sobald ich mich um diese ordinäre Kreatur gekümmert habe.","story.map10-dungeon6.027":"......","story.map10-dungeon6.028":"......<wait=40>Ich spüre sie nicht mehr.","story.map10-dungeon6.029":"Nngh.","story.map10-dungeon6.030":"*Keuch* <wait=20>*keuch* <wait=20>*Keuch* ","story.map10-dungeon6.031":"M-<wait=20>Mir geht\'s gut.","story.map10-dungeon6.032":"Nur ein Teil der Schmerzen ist zurückgekommen, als sie weg war.","story.map10-dungeon6.033":"Trotzdem bin ich froh, dass wir sie täuschen konnten.","story.map10-dungeon6.034":"Hör zu...<wait=40>Wir können nicht einfach herumstehen, wir müssen zum Meeresschrein.","story.map10-dungeon6.035":"Ich bin sicher, dass Karl dort festgehalten wird.","story.map10-dungeon6.036":"Was soll dieser Gesichtsausdruck?","story.map10-dungeon6.037":"Ich habe keine Zeit, hier herumzusitzen und mit dir zu reden.","story.map10-dungeon6.038":"Ich verspreche, wir reden später, also lass uns jetzt Karl hinterher.","story.map10-dungeon7.001":"*Keuch* *keuch* *keuch*","story.map10-dungeon7.002":"Wir haben es endlich zum Meeresschrein geschafft.","story.map10-dungeon7.003":"Wie ich sehe, bist du so ziemlich am Ende.","story.map10-dungeon7.004":"Sie schon wieder.","story.map10-dungeon7.005":"Ich erkenne den Mut an, den es braucht, so zerschunden und gebrochen vor mich zu treten.","story.map10-dungeon7.006":"Pah. <wait=40>Wie eingebildet von dir.","story.map10-dungeon7.007":"Dabei habe ich dich dazu gebracht, mir zu verraten, wo ihr Karl festhaltet.","story.map10-dungeon7.008":"...Ihr Narren.","story.map10-dungeon7.009":"Wie ich sehe, habt ihr euch durch die Lognea-Bucht zu mir durchgekämpft.","story.map10-dungeon7.010":"Glaubt ihr, ihr könnt mir mit solchen Verletzungen entkommen?","story.map10-dungeon7.011":"Nngh...","story.map10-dungeon7.012":"Meine Diener!","story.map10-dungeon7.013":"Versammelt euch und befreit die Welt von diesen Insekten!","story.map10-dungeon7.014":"W-Was ist das? <wait=20>Wo kommen die alle her!?","story.map10-dungeon7.015":"Ist es nicht peinlich für eine Göttin wie dich, so viele herbeizurufen, nur um gegen uns Menschen zu kämpfen?","story.map10-dungeon7.016":"Hör auf mit deinem törichten Gerede.","story.map10-dungeon7.017":"Hier werde ich mich endlich von euch befreien.","story.map10-dungeon7.018":"Das ist alles.","story.map10-dungeon7.019":"<rep_handlename>!","story.map10-dungeon7.020":"Bereue deinen törichten Widerstand gegen die Götter und stirb!","story.map10-dungeon7.021":"Nngh... <wait=40>Das ist übel, <wait=40>es sind einfach zu viele.","story.map10-dungeon7.022":"Es passt gar nicht zu dir, in so einer Lage so zaghaft zu sein.","story.map10-dungeon7.023":"Diese Stimme!","story.map10-dungeon7.024":"W-Wie hast du...","story.map10-dungeon7.025":"Hallo. <wait=40>Tut mir leid, dass ich dich warten ließ.","story.map10-dungeon7.026":"Karl!","story.map10-dungeon7.027":"Wie hast du...","story.map10-dungeon7.028":"Als ich zuletzt nachgesehen habe, warst du noch in diesem Raum eingesperrt...","story.map10-dungeon7.029":"Erst als du nachsehen kamst, wurde mir klar, wo ich war.","story.map10-dungeon7.030":"Oh, du Göttin von so geringer Intelligenz.","story.map10-dungeon7.031":"Wie kannst du es wagen...","story.map10-dungeon7.032":"Lugina! <wait=20>Was hat denn so lange gedauert!","story.map10-dungeon7.033":"Ruhe!","story.map10-dungeon7.034":"Die Rettung hat ewig gedauert, weil der hier so faul ist!","story.map10-dungeon7.035":"Ich hab doch schon gesagt, dass es mir leidtut.","story.map10-dungeon7.036":"Ach ja, und Seria...","story.map10-dungeon7.037":"Wie konntest du dich so zurichten lassen?","story.map10-dungeon7.038":"Das ist nicht meine Schuld, jemand Bestimmtes hat mich ausgebremst!","story.map10-dungeon7.039":"Schon gut, vergessen wir das!","story.map10-dungeon7.040":"Wir haben hier noch etwas zu erledigen.","story.map10-dungeon7.041":"Nicht wahr, Mare?","story.map10-dungeon7.042":"Dein Plan ist bereits gescheitert.","story.map10-dungeon7.043":"Was hast du jetzt vor?","story.map10-dungeon7.044":"Mensch, wagst du es etwa zu glauben, du stündest über den Göttern?","story.map10-dungeon7.045":"Ich lobe dich dafür, dass du meine Erwartungen übertroffen hast.","story.map10-dungeon7.046":"Doch trotz meines Respekts gebe ich meine Pläne nun auf und lasse dich einfach vernichten.","story.map10-dungeon7.047":"Ich, Mare, Jüngerin von Lord Zevalhua, befehle euch!","story.map10-dungeon7.048":"Meine Diener!","story.map10-dungeon7.049":"Versammelt euch um mich und vernichtet meine Feinde!","story.map10-dungeon7.050":"Tötet alle Menschen vor mir!","story.map10-dungeon7.051":"Hier haben sich wohl schon ziemlich viele von ihnen versammelt.","story.map10-dungeon7.052":"Es sind viel mehr als vorhin.","story.map10-dungeon7.053":"Menschen. <wait=40>Ihr habt gut gekämpft.","story.map10-dungeon7.054":"Ich werde mich an euch erinnern...","story.map10-dungeon7.055":"...und an das tragische Ende, das euch bald erwartet.","story.map10-dungeon7.056":"Wo willst du denn hin!","story.map10-dungeon7.057":"Aus dem Weg, ihr alle!","story.map10-dungeon7.058":"Es sind so viele.","story.map10-dungeon7.059":"Karl, <wait=40>du bist verletzt...","story.map10-dungeon7.060":"Haha, <wait=20>diese Jüngerin hat mich nur ein bisschen herumgeschubst, das ist alles...","story.map10-dungeon7.061":"Spiel das nicht so herunter!","story.map10-dungeon7.062":"Aber Seria, du bist doch auch verletzt...","story.map10-dungeon7.063":"D-Das ist doch nur...","story.map10-dungeon7.064":"Seht euch nur all diese erbärmlichen Kreaturen an!","story.map10-dungeon7.065":"Hey! <wait=40><rep_handlename>!","story.map10-dungeon7.066":"Ich hab es satt, nur herumzurennen.","story.map10-dungeon7.067":"Du jagst diese bleiche Frau und erledigst sie!","story.map10-dungeon7.068":"Ich kümmere mich um die beiden hier, solange du weg bist!","story.map10-dungeon7.069":"Wir brauchen niemanden, der sich um uns kümmert!","story.map10-dungeon7.070":"Tut mir leid, dass du dir Sorgen machen musstest, <rep_handlename>.","story.map10-dungeon7.071":"Überlass das hier uns und verfolge diese Jüngerin.","story.map10-dungeon7.072":"Ich mache es danach auf jeden Fall wieder gut.","story.map10-dungeon7.073":"Wir zählen auf dich, <wait=20><rep_handlename>.","story.map10-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_clear.002":"<size=18>Kannst du...</size> <wait=20><size=20> *Bzz...zzz*</size>","story.map10-dungeon_ex_clear.003":"<size=20>*Bzz*</size> <size=18>...Herr Beschwörer...?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_clear.004":"<size=18>*Bzz*</size><wait=20><size=20> Ah, jetzt klappt\'s!</size>","story.map10-dungeon_ex_clear.005":"In diesen Dungeons ist es so schwer, ein Signal zu bekommen.","story.map10-dungeon_ex_clear.006":"Jedenfalls <wait=20>will ich dir erzählen, was ich herausgefunden habe.","story.map10-dungeon_ex_clear.007":"Laut alten Schriften...","story.map10-dungeon_ex_clear.008":"...war dieser Ort seit der Spätzeit des Agni-Imperiums versiegelt.","story.map10-dungeon_ex_clear.009":"Aber 100 Jahre davor wurde dort heimlich ein Kaiser eingesperrt.","story.map10-dungeon_ex_clear.010":"Lange Zeit verging, ohne dass jemand wusste, dass er dort unten war. ","story.map10-dungeon_ex_clear.011":"Dieser Kaiser wurde von seinem Umfeld gefürchtet und als Tyrann angesehen.","story.map10-dungeon_ex_clear.012":"Tatsächlich <wait=20>fürchteten ihn nicht nur seine Untertanen, sondern auch deren Kinder.","story.map10-dungeon_ex_clear.013":"Eines Tages erkrankte ein Kind, das unter ihm gelitten hatte, und starb.","story.map10-dungeon_ex_clear.014":"Deshalb wurde er heimlich eingesperrt.","story.map10-dungeon_ex_clear.015":"Mit der Zeit wuchs im pechschwarzen Kerker der Zorn des Kaisers zusammen mit seiner Einsamkeit.","story.map10-dungeon_ex_clear.016":"Er wurde als ungeheuer mächtiges Phantom wiedergeboren und nahm 100 Jahre lang Rache am Reich.","story.map10-dungeon_ex_clear.017":"Daraufhin <wait=20>wurde der Geist des Kaisers zusammen mit dem Dungeon versiegelt.","story.map10-dungeon_ex_clear.018":"Er ist immer noch irgendwo dort unten, <wait=20>und sein Zorn wächst mit jeder Sekunde.","story.map10-dungeon_ex_clear.019":"Allein der Gedanke daran macht mir Angst.","story.map10-dungeon_ex_clear.020":"Herr Beschwörer, <wait=20>du musst dich nicht zwingen, diesen Geist zu finden!","story.map10-dungeon_ex_clear.021":"Du sollst nur gründlich untersuchen, wie gefährlich dieser Ort genau ist.","story.map10-dungeon_ex_clear.022":"W-<wait=20>Was ist?<wait=40> Was hast du gerade gesagt?","story.map10-dungeon_ex_clear.023":"Niemals!","story.map10-dungeon_ex_clear.024":"Du hast den Geist des Kaisers einfach besiegt, während ich noch recherchiert habe!?","story.map10-dungeon_ex_clear.025":"Wow, Herr Beschwörer...<wait=20>du bist unglaublich.","story.map10-dungeon_ex_clear.026":"Aber warte! <wait=40>Warte doch mal kurz!","story.map10-dungeon_ex_clear.027":"Ich wollte eigentlich, dass du noch ein bisschen wartest, bis ich mit meiner Recherche fertig bin...","story.map10-dungeon_ex_clear.028":"Hmm...<wait=20> Na ja, egal!","story.map10-dungeon_ex_clear.029":"Nächstes Mal gebe ich mein Bestes, dir die Informationen so schnell wie möglich zu liefern!","story.map10-dungeon_ex_clear.030":"Ich beweise dir, dass du nicht der Einzige bist, der besser geworden ist!","story.map10-dungeon_ex_clear.031":"Ich melde mich bald wieder, also warte nur ab!","story.map10-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_open.002":"<size=18>Her...</size> <wait=20><size=20>*Bzz...zzz*</size>","story.map10-dungeon_ex_open.003":"<size=20>*Bzz*</size> <size=18>...hörst...du mich?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_open.004":"<size=18>*Bzz*</size><wait=20><size=20>Herr Beschwörer!</size>","story.map10-dungeon_ex_open.005":"Endlich haben wir eine Verbindung!","story.map10-dungeon_ex_open.006":"Du scheinst an einem Ort mit ziemlich schlechtem Empfang zu sein.","story.map10-dungeon_ex_open.007":"Jedenfalls <wait=20>fange ich noch mal von vorne an.","story.map10-dungeon_ex_open.008":"Ich bin Lin Merylham von der Logistikunterstützung...","story.map10-dungeon_ex_open.009":"...des Ermittlungsbüros im Vermessungsamt von Grand Gaia, zu deinen Diensten.","story.map10-dungeon_ex_open.010":"Wir haben neulich das Verschwinden einer großen Macht in der Agni Region festgestellt. ","story.map10-dungeon_ex_open.011":"Dadurch ist wohl ein früher versiegeltes unterirdisches Bauwerk aufgebrochen. ","story.map10-dungeon_ex_open.012":"Laut unseren Aufzeichnungen <wait=20>wurde dort etwas ziemlich Unheimliches festgehalten.","story.map10-dungeon_ex_open.013":"Deine Mission ist diesmal, dem ein Ende zu setzen...","story.map10-dungeon_ex_open.014":"...bevor es herauskommen und Schaden anrichten kann!","story.map10-dungeon_ex_open.015":"Das Bauwerk war wohl vor sehr langer Zeit einmal ein Kerker.","story.map10-dungeon_ex_open.016":"Hä? <wait=40>Du bist schon dort?","story.map10-dungeon_ex_open.017":"Das überrascht mich nicht!","story.map10-dungeon_ex_open.018":"Na gut, <wait=20>dann versuche ich mal, mehr über den Dungeon herauszufinden.","story.map10-dungeon_ex_open.019":"Ich habe neue Informationen für dich, bevor du mit deiner Erkundung fertig bist.","story.map10-dungeon_ex_open.020":"Halte noch ein kleines bisschen durch!","story.map10-ending.001":"I-<wait=20>Ihr Narren...","story.map10-ending.002":"Wie konnte eine Göttin wie ich von Menschen besiegt werden...","story.map10-ending.003":"D-Dann soll es so sein!","story.map10-ending.004":"<size=20>Ich begrabe euch alle zusammen mit diesem Schrein!</size>","story.map10-ending.005":"<size=14>*Grollen* *Grollen*</size>","story.map10-ending.006":"<size=21>Das lasse ich nicht zu!</size>","story.map10-ending.007":"Nngh, <wait=40>du hast also auch überlebt!","story.map10-ending.008":"Tilith, Jüngerin von Lucius!","story.map10-ending.009":"Ich bin hier, <rep_handlename>!","story.map10-ending.010":"Also los, lasst uns alle hier verschwinden!","story.map10-ending.011":"Halt, <rep_handlename>!","story.map10-ending.012":"Glaub bloß nicht, dass du schon gewonnen hast!","story.map10-ending.013":"Es ist egal, wie viele von euch sich zusammentun.","story.map10-ending.014":"Vor Lord Zevalhua seid ihr nichts!","story.map10-ending.015":"Und darüber hinaus ist die Schlüsselfigur unter euch...","story.map10-ending.016":"<size=15>*Grollen* *Grollen*</size>","story.map10-ending.017":"Mare! <wait=40>Sieh es ein, du hast verloren!","story.map10-ending.018":"<rep_handlename>! <wait=40>Alle warten schon!","story.map10-ending.019":"Los geht\'s!","story.map10-ending.020":"<size=16>*Grollen* *Grollen*</size>","story.map10-ending.021":"Nngh...","story.map10-ending.022":"<size=19>Lord Zevalhua...</size>","story.map10-ending.023":"<size=18>*Grollen* *Grollen*</size>","story.map10-ending.024":"<rep_handlename>!","story.map10-ending.025":"Du hast es geschafft!","story.map10-ending.026":"Ich wusste, dass du Mare besiegen kannst, mein <rep_handlename>!","story.map10-ending.027":"A-Aua...","story.map10-ending.028":"Wie immer ein ziemlich wilder Flugstil, <wait=40> Göttin.","story.map10-ending.029":"Kannst du nicht wenigstens ein bisschen vorsichtiger sein?","story.map10-ending.030":"Hey, <wait=20>hört auf zu meckern, ihr zwei!","story.map10-ending.031":"Trotzdem bin ich froh, dass es euch beiden gut geht, Karl und Seria.","story.map10-ending.032":"Ich hab mir echt Sorgen gemacht, als ich dich so verwundet getragen hab, Seria!","story.map10-ending.033":"Danke dafür...","story.map10-ending.034":"Ja, <wait=20>ich bin dir auch dankbar, Göttin.","story.map10-ending.035":"Und natürlich auch dir, <rep_handlename>!","story.map10-ending.036":"Aber lass es dir nicht zu Kopf steigen, sonst stehen wir schlecht da.","story.map10-ending.037":"Tut mir leid, dass ich so lange gebraucht habe, um mich zu erholen.","story.map10-ending.038":"Jedenfalls warst du wie immer unglaublich, <rep_handlename>!","story.map10-ending.039":"Du hast Mare besiegt!","story.map10-ending.040":"Ja, <wait=20>genau.","story.map10-ending.041":"<rep_handlename>, <wait=40>ich bin echt stolz, dich einen engen Freund nennen zu dürfen.","story.map10-ending.042":"Genau, Karl.","story.map10-ending.043":"Ähm...","story.map10-ending.044":"Ich will euch ja nicht die Stimmung verderben, aber vergessen wir nicht jemanden?","story.map10-ending.045":"Stimmt! <wait=40>Lugina!","story.map10-ending.046":"Wo kann er nur sein?","story.map10-ending.047":"Wer ist Lugina?","story.map10-ending.048":"Ach so, du hast Lugina noch gar nicht persönlich getroffen, Göttin, oder?","story.map10-ending.049":"Nicht im Ernst, <wait=40>willst du sagen, du hast nur uns mitgebracht?","story.map10-ending.050":"Ähm, <wait=40>erstens wusste ich gar nicht, dass da noch jemand war.","story.map10-ending.051":"Meint ihr vielleicht die Person, die halb im Boden vergraben war?","story.map10-ending.052":"<size=21>Lugina!</size>","story.map10-ending.053":"<size=22>Ihr Trottel! <wait=40>Ich hau euch alle k. o.!</size>","story.map10-ending.054":"Hey, wenigstens bist du heil hier angekommen.","story.map10-ending.055":"Hehe... <wait=20>Du warst da hinten ja ganz schön übel dran, Lugina.","story.map10-ending.056":"<size=20>Dummes Mädchen! <wait=40>Du kriegst es am schlimmsten ab!","story.map10-ending.057":"Seria, ich hab gesagt, hör auf!","story.map10-ending.058":"Lugina, <wait=40>diesmal hast du uns wirklich gerettet.","story.map10-ending.059":"Danke.","story.map10-ending.060":"Pah, <wait=20>ich hab euch nur geholfen, weil die Beschwörerhalle mich darum gebeten hat.","story.map10-ending.061":"Ehrlich gesagt wäre es egal gewesen, um wen es ging.","story.map10-ending.062":"Trotzdem, woher wusstest du, wo ich festgehalten wurde?","story.map10-ending.063":"Das war einfach.","story.map10-ending.064":"Ich wusste, dass diese Frau versuchen würde, diesen Dummkopf allein zu erwischen.","story.map10-ending.065":"Also wusste ich, wenn ich so eine Situation herbeiführe, würde sie bestimmt angerannt kommen.","story.map10-ending.066":"Allerdings war sie sehr vorsichtig.","story.map10-ending.067":"Karl, <wait=20>ich habe vorhergesehen, dass sie dich als Köder benutzen würde, während sie sich langsam näherte.","story.map10-ending.068":"Den Rest habe ich erledigt, bevor ich Elgaia verlassen habe.","story.map10-ending.069":"Ich musste diesem dummen Mädchen nur sagen, dass sie diesen Trottel retten soll.","story.map10-ending.070":"<size=20>Wen nennst du hier dumm!</size>","story.map10-ending.071":"Na ja, <wait=40>dein Vorschlag hat mich am Ende gerettet.","story.map10-ending.072":"Sobald ich dort war, habe ich dieser Jüngerin den Namen des Ortes in der Nähe genannt, von dem du mir erzählt hast.","story.map10-ending.073":"Kaum hatte ich ihn ausgesprochen, ist sie genau wie von dir gesagt verschwunden.","story.map10-ending.074":"Pah, <wait=40>das war leicht zu erraten, wenn man wusste, wann du ankommst.","story.map10-ending.075":"So viele Orte, an denen man jemanden verstecken kann, gab es wirklich nicht.","story.map10-ending.076":"Diese dumme Jüngerin <wait=20>hat genau das getan, was ich erwartet hatte.","story.map10-ending.077":"Sie ist zum Meeresschrein aufgebrochen, um nach ihrem Gefangenen zu sehen.","story.map10-ending.078":"Und damit hat sie mich direkt zu ihm geführt.","story.map10-ending.079":"Wow, das ist unglaublich, Lugina.","story.map10-ending.080":"<size=19>Kaum zu glauben, dass jemand wie du so etwas hinkriegt.</size>","story.map10-ending.081":"<size=21>Was fällt dir ein!<\\\\size>","story.map10-ending.082":"Du bist also Lugina!","story.map10-ending.083":"Freut mich, dich kennenzulernen!","story.map10-ending.084":"Ich bin Tilith, die Göttin, die über <rep_handlename> wacht.","story.map10-ending.085":"Ich bin eine Jüngerin von Lucius.","story.map10-ending.086":"Eine Göttin, die eine Jüngerin von Lucius ist?","story.map10-ending.087":"Hey, <rep_handlename>!","story.map10-ending.088":"Ist das Mädchen verrückt oder was?","story.map10-ending.089":"Du bist gemein!","story.map10-ending.090":"Und dabei hab ich dich vom Meeresschrein zurückgebracht!","story.map10-ending.091":"Das warst du?","story.map10-ending.092":"Na, wenn das so ist...","story.map10-ending.093":"Ja, sie ist eine echte Göttin.","story.map10-ending.094":"<size=18>Nicht im Ernst...</size>","story.map10-ending.095":"Dieser törichte Alte, Grahdens.","story.map10-ending.096":"Wovon zum Teufel hat er eigentlich geredet...","story.map10-ending.097":"Ach, und Lugina...","story.map10-ending.098":"Es war Grahdens, der dich gebeten hat, uns zu retten, nicht wahr?","story.map10-ending.099":"Was treibt der Alte denn jetzt?","story.map10-ending.100":"Was!? <wait=20>Woher soll ich das wissen?","story.map10-ending.101":"Bestimmt wandert er irgendwo herum.","story.map10-ending.102":"Wenn ihr den Ältesten Grahdens meint: Er wurde von Zevalhua gefangen genommen.","story.map10-ending.103":"Du bist es...","story.map10-ending.104":"Lange nicht gesehen, <rep_handlename>.","story.map10-ending.105":"Deine Freunde dort habe ich allerdings wohl noch nicht kennengelernt.","story.map10-ending.106":"Ich habe mich schon darauf gefreut, euch alle zu treffen.","story.map10-ending.107":"Was macht eine miese Gardistin der Kaiserlichen Garde wie du hier?","story.map10-ending.108":"Vorher: Was meinst du damit, dass der Alte gefangen genommen wurde?","story.map10-ending.109":"Hehehe, <wait=20>nur nicht so ungeduldig.","story.map10-ending.110":"Ich habe auch ein paar Fragen.","story.map10-ending.111":"Zum Beispiel, warum du noch lebst, obwohl dich diese Jüngerin gefangen genommen hat.","story.map10-ending.112":"Aber die Einzelheiten können wir in Milvana besprechen.","story.map10-ending.113":"Ist das für euch beide in Ordnung...","story.map10-ending.114":"<rep_handlename> und Tilith, Jüngerin von Lord Lucius?","story.map10-ending.115":"Ja, das ist mir recht.","story.map10-ending.116":"Bestimmt öffnet Lord Lucius uns bald einen Weg nach Milvana.","story.map10-ending.117":"Das wird jetzt schon lästig.","story.map10-ending.118":"Karl, <wait=40>geht es dir gut?","story.map10-ending.119":"Grahdens...","story.map10-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ich bin Lucius...<br><wait=40>Gott dieses Tors...","story.map10-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Du, <rep_handlename>,<wait=39> der Ryvern befreit hat...","story.map10-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Nutze meine Kraft <wait=40>und wage dich in neue Länder...","story.map10-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Um dieser Welt ohne Ordnung neue Hoffnung zu bringen...","story.map10-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Du musst an deine Kraft glauben <wait=20>und weiter voranschreiten...","story.map10-open.006":"<size=21><rep_handlename>! <wait=40>Was hat denn so lange gedauert!</size>","story.map10-open.007":"Wie immer lässt du die Person warten, die dir das Leben gerettet hat – unglaublich.","story.map10-open.008":"Egal.","story.map10-open.009":"Ich bin mal nett und erkläre es dir und deinem Spatzenhirn.","story.map10-open.010":"Warum du mich dort gefunden hast, natürlich!","story.map10-open.011":"Ich hatte eine Vision.","story.map10-open.012":"Mit meinem genialen Verstand konnte ich die Klemme vorhersehen, in die du dich irgendwann bringen würdest.","story.map10-open.013":"......","story.map10-open.014":"Du glaubst mir nicht, <wait=20>oder?","story.map10-open.015":"Pah, <wait=20>egal.","story.map10-open.016":"Es war der alte Grahdens.","story.map10-open.017":"Er hat mich gebeten, euch allen zu folgen.","story.map10-open.018":"Es war ein direkter Auftrag der Ältesten Beschwörer an mich.","story.map10-open.019":"Das beweist, dass die Beschwörerhalle an meine Stärke glaubt!","story.map10-open.020":"<size=21>Hahaha!</size>","story.map10-open.021":"Jedenfalls <wait=20>wollten sie eigentlich, dass ich diesen Versager Karl rette.","story.map10-open.022":"......","story.map10-open.023":"Und du hilfst mir dabei.","story.map10-open.024":"Du würdest doch nicht wagen, den Wunsch der Person abzulehnen, der du dein Leben verdankst, oder?","story.map10-open.025":"Na gut, dann mache ich mich auf den Weg ins Agni-Imperium.","story.map10-open.026":"Wenn meine Informationen stimmen, wird Karl dort festgehalten.","story.map10-open.027":"Es wird nicht leicht, aber alles beginnt im Reich.","story.map10-open.028":"Das ist nicht die Zeit zum Zögern! Hast du gehört?","story.map10-open.029":"Ach ja!","story.map10-open.030":"Diese Jüngerin Mare hat dich immer noch im Visier, oder?","story.map10-open.031":"Bete lieber, dass sie dich nicht einholt!","story.map10-open.032":"<size=22>Hahaha!</size>","story.map11-dungeon1.001":"<rep_handlename>...<wait=40>du bist spät dran!! ","story.map11-dungeon1.002":"Sei nicht so faul!","story.map11-dungeon1.003":"Also echt...","story.map11-dungeon1.004":"Warum hast du uns an so einem heißen Ort so lange warten lassen?","story.map11-dungeon1.005":"Na, sieh mal einer an! <wait=20>Ihr zwei versteht euch ja prächtig.","story.map11-dungeon1.006":"<speed=15><size=21>Verarsch mich nicht! Hör auf, mich zu verarschen!</size></speed>","story.map11-dungeon1.007":"Wow...<wait=20>ihr sagt sogar genau dasselbe!","story.map11-dungeon1.008":"<speed=15><size=21>Was hast du gesagt?! Was sagst du da?!</size></speed>","story.map11-dungeon1.009":"Göttin, <wait=40>ist das die Paris von der Kaiserlichen Garde?","story.map11-dungeon1.010":"Ich flehe dich an, lade mir bitte nicht noch mehr auf die Schultern...","story.map11-dungeon1.011":"Die Eltern, die mich großgezogen haben, haben schon genug Ärger...","story.map11-dungeon1.012":"Hehe... <wait=20>Tut mir leid.","story.map11-dungeon1.013":"Und<wait=20><rep_handlename> ist auch mitgekommen.","story.map11-dungeon1.014":"Kannst du uns den Rest der Geschichte so schnell wie möglich erzählen?","story.map11-dungeon1.015":"Stimmt es, dass der Älteste Grahdens von Zevalhua gefangen genommen wurde?","story.map11-dungeon1.016":"Ja, es stimmt.","story.map11-dungeon1.017":"Einzelheiten kann ich euch nicht wirklich nennen,","story.map11-dungeon1.018":"aber ich habe die Information von einem zuverlässigen Mitglied der Kaiserlichen Garde, also ist sie ziemlich glaubwürdig.","story.map11-dungeon1.019":"Verstehe...","story.map11-dungeon1.020":"Tss.<wait=40> Warum musste sich dieser alte Beschwörer auch gefangen nehmen lassen? ","story.map11-dungeon1.021":"Wie lästig.","story.map11-dungeon1.022":"Lugy! <wait=40> Sag so was nicht!","story.map11-dungeon1.023":"Du weißt doch, dass Elder Grah sich für uns alle abmüht!","story.map11-dungeon1.024":"Lugy?!","story.map11-dungeon1.025":"Lugy... <wait=80> Hehe...","story.map11-dungeon1.026":"Was für ein widerlicher Spitzname...","story.map11-dungeon1.027":"Du hast wirklich eine Art an dir, die Menschen nicht verstehen können, Göttin.","story.map11-dungeon1.028":"Frau Gardistin, da liegst du falsch.","story.map11-dungeon1.029":"Sie ist nur ein bisschen verrückt, das ist alles.","story.map11-dungeon1.030":"Ihr zwei seid so gemein!!!","story.map11-dungeon1.031":"Seria, <wait=40>das reicht jetzt, okay?","story.map11-dungeon1.032":"Wenn ihr so weitermacht, kommen wir nie voran.","story.map11-dungeon1.033":"Und du...<wait=20> Dürfen wir dich einfach Paris nennen?","story.map11-dungeon1.034":"Hehe.<wait=20> Es ehrt mich schon, dass du meinen Namen sagst, oh berühmter Beschwörer Karl.","story.map11-dungeon1.035":"Mach dich nicht über mich lustig.","story.map11-dungeon1.036":"Jedenfalls sind wir sicher, dass der Älteste irgendwo hier in Mirvana ist, richtig?","story.map11-dungeon1.037":"Ja. <wait=40>Leider schon.","story.map11-dungeon1.038":"Wenn Elder Grah von Zevalhua gefangen genommen wurde, ist er wohl auch irgendwo in Mirvana.","story.map11-dungeon1.039":"Denn dank all der Mühen von <rep_handlename> ","story.map11-dungeon1.040":"ist dieser Ort der einzige, der noch unter Zevalhuas Kontrolle steht.","story.map11-dungeon1.041":"Und wenn das so ist, <wait=40> geht es schneller, wenn wir uns aufteilen und nach verdächtigen Orten suchen.","story.map11-dungeon1.042":"Uns aufzuteilen lässt sich wohl doch nicht vermeiden, was?","story.map11-dungeon1.043":"Dann bleibt mir einfach aus dem Weg!","story.map11-dungeon1.044":"Ja, ja. Haben wir schon verstanden.","story.map11-dungeon1.045":"Gib dein Bestes, Lugy!","story.map11-dungeon1.046":"Dummes Mädchen! <wait=40>Ich mach dich zu Brei!","story.map11-dungeon1.047":"Sieht aus, als würde es mit einer Aufgabe wieder Spaß machen!","story.map11-dungeon1.048":"Wie öde...","story.map11-dungeon1.049":"<rep_handlename>, <wait=40><br>wir zählen diesmal auf dich.","story.map11-dungeon1.050":"Hilf dem Ältesten mit derselben Kraft, mit der du mir geholfen hast!","story.map11-dungeon2.001":"Hmm...","story.map11-dungeon2.002":"Hier scheint es keine verdächtigen Orte zu geben...","story.map11-dungeon2.003":"Hä...?","story.map11-dungeon2.004":"Ah, Karl!","story.map11-dungeon2.005":"Hallo, Göttin.","story.map11-dungeon2.006":"Hast du dort drüben Hinweise gefunden?","story.map11-dungeon2.007":"Leider nicht.","story.map11-dungeon2.008":"Aber mal ehrlich, <wait=20>wo kann der Älteste nur sein...?","story.map11-dungeon2.009":"Weil er in seinem Alter solche verrückten Sachen macht, ist er überhaupt erst gefangen genommen worden.","story.map11-dungeon2.011":"Ach was. Ich sehe doch, dass du dir nur Sorgen um ihn machst, Karl.","story.map11-dungeon2.012":"Haha. Gegen eine Göttin komme ich wohl nicht an.","story.map11-dungeon2.013":"Du musst dir keine Sorgen um ihn machen!","story.map11-dungeon2.014":"Elder Grah geht es bestimmt bestens!","story.map11-dungeon2.015":"Dir ging es doch auch gut, als du gefangen genommen wurdest, oder?","story.map11-dungeon2.016":"Also ist klar, dass es einem noch großartigeren Kerl wie Elder Grah auch gut geht.","story.map11-dungeon2.017":"An dieser Aussage gibt es ein paar Dinge, denen ich nicht zustimmen kann...","story.map11-dungeon2.018":"Aber auch wenn ich mir Sorgen mache, wird er wohl nicht so bald den Löffel abgeben.","story.map11-dungeon2.019":"Danke, Göttin!","story.map11-dungeon2.020":"Aber es ist schon etwas seltsam.","story.map11-dungeon2.021":"Du...","story.map11-dungeon2.022":"Paris-Bärchen.","story.map11-dungeon2.023":"B-Bärchen?!","story.map11-dungeon2.024":"Es fällt mir wirklich schwer, das einer Göttin zu sagen, aber...","story.map11-dungeon2.025":"...könntest du mich bitte nicht mehr „Bärchen“ nennen?","story.map11-dungeon2.026":"Nenn mich einfach „Paris“. Das macht mir nichts aus.","story.map11-dungeon2.027":"Okay, schon gut.","story.map11-dungeon2.028":"Also, Paris, warum genau bist du hier?","story.map11-dungeon2.029":"Nun, <wait=20>ich suche ebenfalls den Ältesten Grahdens.","story.map11-dungeon2.030":"Da ist es kein Wunder, dass ich euch über den Weg gelaufen bin.","story.map11-dungeon2.031":"Na gut, wie auch immer.","story.map11-dungeon2.032":"Und was findest du an all dem so seltsam?","story.map11-dungeon2.033":"Oh, <wait=20>jemand wie Karl von Nyonne weiß nicht, worauf ich hinauswill?","story.map11-dungeon2.034":"Ich hab keine Zeit für deine dummen Spielchen. Sag es endlich.","story.map11-dungeon2.035":"Hehe, <wait=20>du bist wohl doch anders als Lugina.","story.map11-dungeon2.036":"Na schön.","story.map11-dungeon2.037":"Du findest es doch bestimmt auch seltsam, oder?","story.map11-dungeon2.038":"Warum sollten die Götter ihn gefangen nehmen und am Leben lassen?","story.map11-dungeon2.039":"...","story.map11-dungeon2.040":"Wenn der Älteste Grahdens an deiner Seite gegen Zevalhua gekämpft hat und dabei gefangen wurde,","story.map11-dungeon2.041":"warum haben sie dann keinen Grund, ihn zu töten?","story.map11-dungeon2.042":"...","story.map11-dungeon2.043":"Könnte das alles uns in eine Falle locken?","story.map11-dungeon2.044":"...","story.map11-dungeon2.045":"Können wir darüber nicht später nachdenken?! Wir müssen Elder Grah retten!","story.map11-dungeon2.046":"Du hast recht.","story.map11-dungeon2.047":"Karl, <wait=20><rep_handlename>, ","story.map11-dungeon2.048":"die Göttin hat recht. Ich setze meine Suche nach dem Ältesten ebenfalls fort.","story.map11-dungeon2.049":"Geben wir gemeinsam unser Bestes.","story.map11-dungeon2.050":"Ja, da hast du mich erwischt. Danke für deine Hilfe.","story.map11-dungeon2.051":"Hehe, <wait=20>vielleicht kann Grahdens uns dieses kleine Rätsel ja ohnehin beantworten.","story.map11-dungeon2.052":"Ja, vielleicht...","story.map11-dungeon2.053":"Hehe...","story.map11-dungeon3.001":"Oh, <wait=20><rep_handlename>.","story.map11-dungeon3.002":"Bist du gerade allein?","story.map11-dungeon3.003":"Hehe, <wait=20>mir tun alle Beschwörer leid, die von dieser Göttin beschützt werden.","story.map11-dungeon3.004":"Wegen Lugina konnte ich deine Antwort letztes Mal nicht hören, aber","story.map11-dungeon3.005":"aufgegeben habe ich dich noch lange nicht.","story.map11-dungeon3.006":"Ich freue mich, so wieder an deiner Seite kämpfen zu können.","story.map11-dungeon3.007":"Deshalb--","story.map11-dungeon3.008":"<size=23>Auf keinen Fall!!!</size>","story.map11-dungeon3.009":"<size=21>Paris! <wait=20><br>Hör auf!</size>","story.map11-dungeon3.010":"<size=21><rep_handlename> ist mein Beschwörer!</size>","story.map11-dungeon3.011":"Ah, <rep_handlename> ist also dein Beschwörer?","story.map11-dungeon3.012":"Nun, <wait=20>und was genau soll das heißen?","story.map11-dungeon3.013":"<size=20>Es heißt genau das, wonach es klingt!</size>","story.map11-dungeon3.014":"<size=20><rep_handlename> ist mein Beschwörer! <wait=20> Punkt, aus!</size>","story.map11-dungeon3.015":"V-<wait=20>Verstehe...","story.map11-dungeon3.016":"<rep_handlename>...<wait=40><br>du hast es <wait=20>gerade ganz schön schwer, was?","story.map11-dungeon3.017":"Nun, <wait=20>jedenfalls führen wir unser kleines Gespräch ein andermal.","story.map11-dungeon3.018":"Ich suche jetzt erst einmal nach dem Ältesten Grahdens.","story.map11-dungeon3.019":"Es sollten auch neue Informationen eintreffen, also halte bitte die Augen offen.","story.map11-dungeon3.020":"Ah! <wait=40>Paris, das ist so unfair!","story.map11-dungeon3.021":"Gegen dich verliere ich nicht, damit du\'s weißt!","story.map11-dungeon3.022":"<rep_handlename>!","story.map11-dungeon3.023":"Ich zeig ihr, dass diese hübsche und unbesiegbare Göttin diejenige sein wird, die dich findet, Elder Grah!","story.map11-dungeon3.024":"Also mach dir keine Sorgen und warte einfach auf mich!","story.map11-dungeon3.025":"<rep_handlename>, <wait=40><br>du tust mir wirklich leid....","story.map11-dungeon4.001":"Tsch, du bist es.","story.map11-dungeon4.002":"Wenn du hier immer noch rumhängst, bist du wohl immer noch derselbe Idiot wie eh und je.","story.map11-dungeon4.003":"Hä? <wait=40>Hast du gesagt, wir sind beide immer noch am selben Ort?","story.map11-dungeon4.004":"Tsch, <wait=20>genau deshalb hasse ich Trottel.","story.map11-dungeon4.005":"Ich habe einen echten Grund, hier zu sein.","story.map11-dungeon4.006":"Aber viel wichtiger, <rep_handlename>:","story.map11-dungeon4.007":"Sei sehr vorsichtig mit dieser Gardistin, Paris.","story.map11-dungeon4.008":"Diese Tussi <wait=20>führt definitiv etwas im Schilde.","story.map11-dungeon4.009":"Sie behauptet, die Adligen des Randall-Reichs arbeiten mit der Akras-Beschwörerhalle zusammen und so...","story.map11-dungeon4.010":"das kann einfach nicht stimmen.","story.map11-dungeon4.011":"Und ich bin sicher, sie hat auch einen Grund, warum sie sich so sehr für dich interessiert...","story.map11-dungeon4.012":"<size=23>Hey, ihr Trottel!</size>","story.map11-dungeon4.013":"<size=23>Warum steht ihr nur herum?!</size>","story.map11-dungeon4.014":"Tsch, aber jetzt ist eine noch nervigere Tussi da.","story.map11-dungeon4.015":"<size=20>Wen nennst du hier eine nervige Tussi?!</size>","story.map11-dungeon4.016":"<size=16>Das ist nicht die Zeit zum Kläffen! Der Älteste Grahdens braucht unsere Hilfe!</size>","story.map11-dungeon4.017":"Ihr seid so dicke miteinander, dass es mir unheimlich wird...","story.map11-dungeon4.018":"<size=21>Wen nennst du hier dicke?! <wait=40><br>Trottel!</size>","story.map11-dungeon4.019":"<size=22>Wen nennst du hier einen Trottel?!</size>","story.map11-dungeon4.020":"<size=21>Spiel dich nicht so auf, wo du doch mit dem Kopf im Boden gesteckt hast!</size>","story.map11-dungeon4.021":"Grr, <wait=20>das war die Schuld dieser komischen Göttin...","story.map11-dungeon4.022":"Lugy, du solltest dich ein bisschen mehr anstrengen!","story.map11-dungeon4.023":"<size=23>Ich verprügel dieses dumme Mädchen nach Strich und Faden!</size>","story.map11-dungeon4.024":"<size=21>Hey, <rep_handlename>!</size>","story.map11-dungeon4.025":"<size=21>Wo rennst du denn hin?!</size>","story.map11-dungeon4.026":"<size=18>Warte, <rep_handlename>! Wo willst du hin?!</size>","story.map11-dungeon4.027":"<size=16>Lass mich nicht mit diesen zwei Spinnern allein!</size>","story.map11-dungeon4.028":"<size=14>Wer weiß, was die mit mir anstellen!</size>","story.map11-dungeon4.029":"<size=12>Als ob ich mit dir überhaupt was anstellen wollte!</size>","story.map11-dungeon4.030":"<size=10>Und was soll das heißen?!</size>","story.map11-dungeon4.031":"<size=9>Kapierst du\'s nicht?!</size><wait=20><br><size=9>So ein Idiot!</size>","story.map11-dungeon4.032":"<size=8>Halt die Klappe!</size><wait=20><br><size=8>Du Versager!</size>","story.map11-dungeon5.001":"<rep_handlename>!!<wait=40> Hör zu, hör zu!!","story.map11-dungeon5.002":"Ich weiß, <wait=20>wo Elder Grah ist!","story.map11-dungeon5.003":"Also, ähm... <wait=20>Er ist wohl an einem Ort namens „Turm der Götter“.","story.map11-dungeon5.004":"Zevalhua hat den Turm der Götter zu seinem Stützpunkt gemacht.","story.map11-dungeon5.005":"Kurz gesagt: <wait=20>Wenn wir zu diesem Turm gehen,","story.map11-dungeon5.006":"können wir Zevalhua besiegen <wait=20>und dabei Elder Grah retten.","story.map11-dungeon5.007":"Also sag Karl und den anderen, dass sie zum Turm der Götter sollen!","story.map11-dungeon5.008":"Von der Dienerin von Lord Lucius, Lady Tilith, war nichts anderes zu erwarten.","story.map11-dungeon5.009":"Ah, <wait=20>Paris!","story.map11-dungeon5.010":"Hehehe, <wait=20>ich bin ziemlich gut, oder?","story.map11-dungeon5.011":"Allerdings.<wait=20><br>Wie von einer Göttin zu erwarten.","story.map11-dungeon5.012":"Aber <wait=20>wie hast du herausgefunden, wo der Älteste Grahdens ist?","story.map11-dungeon5.013":"Na ja...","story.map11-dungeon5.014":"Es gibt noch eine andere Dienerin von Lord Lucius wie mich, die Zevalhua beobachtet hat.","story.map11-dungeon5.015":"Sie ist zum Turm der Götter gegangen und hat berichtet, dass dort ein alter Mann in einem Raum gefangen ist.","story.map11-dungeon5.016":"Verstehe. <wait=20><br>Jetzt begreife ich...","story.map11-dungeon5.017":"Lord Lucius <wait=20>sammelt immer mehr großartige göttliche Diener um sich!","story.map11-dungeon5.018":"Natürlich gehöre ich auch dazu.","story.map11-dungeon5.019":"Ja, ich weiß sehr wohl, dass du erstaunliche Kräfte besitzt, Göttin.","story.map11-dungeon5.020":"Aber <wait=20>das ist merkwürdig.","story.map11-dungeon5.021":"Hä? <wait=20>Was denn?","story.map11-dungeon5.022":"Wenn er so viele hervorragende göttliche Wesen auf seiner Seite hat,","story.map11-dungeon5.023":"warum geht er dann nicht selbst gegen die Gefallenen Götter vor?","story.map11-dungeon5.024":"Ähm, <wait=20>also...","story.map11-dungeon5.025":"Und außerdem <wait=20>weckt auch der Bote des höchsten Gottes,","story.map11-dungeon5.026":"der Heilige Kaiser Karna Masta, meine Neugier.","story.map11-dungeon5.027":"Obwohl Grand Gaia in Not ist, zeigt er keinerlei Anzeichen, etwas dagegen tun zu wollen.","story.map11-dungeon5.028":"Wenn Lord Lucius und Karna Masta zusammenarbeiten, brauchen sie uns Menschen doch gar nicht.","story.map11-dungeon5.029":"Ich habe das Gefühl, sie könnten die zwei übrigen Gefallenen Götter mühelos allein besiegen.","story.map11-dungeon5.030":"Also... <wait=40><br>Äh, <wait=20>ähm...","story.map11-dungeon5.031":"Kann es sein, dass Lord Lucius und die anderen sich nicht frei bewegen können?","story.map11-dungeon5.032":"Zum Beispiel, <wait=20>dass er nach der Niederlage gegen die Vier Gefallenen Götter von einer Macht versiegelt wurde, oder--","story.map11-dungeon5.033":"Das... <wait=20>Das ist es nicht!","story.map11-dungeon5.034":"Lord Lucius geht es bestens!","story.map11-dungeon5.035":"Ich kann dir nicht alles sagen, aber er kann sich gerade nicht wirklich bewegen...","story.map11-dungeon5.036":"Und...<wait=20>Und Karna Masta hat dasselbe Problem!","story.map11-dungeon5.037":"Aber versiegelt sind sie nirgendwo!","story.map11-dungeon5.038":"Verzeih mir.","story.map11-dungeon5.039":"Bitte vergib diesem törichten und misstrauischen Menschen.","story.map11-dungeon5.040":"Eine Närrin wie ich kann die großen Gedanken der Götter nicht begreifen.","story.map11-dungeon5.041":"Ich bin einfach ein ständig ängstlicher Mensch.","story.map11-dungeon5.042":"Nein, <wait=20>schon gut.","story.map11-dungeon5.043":"Ich hätte nie gedacht, dass du mich so etwas fragst, deshalb hast du mich überrumpelt.","story.map11-dungeon5.044":"Deine Worte allein haben mir sehr geholfen.","story.map11-dungeon5.045":"Nun, <wait=20>wir sollten aufbrechen, um den Ältesten Grahdens zu retten.","story.map11-dungeon5.046":"Karl und die anderen sind wohl gerade vorausgegangen, zur Ruinenstadt Mirvana.","story.map11-dungeon5.047":"O-<wait=20>Okay. <wait=40><br>Genau!","story.map11-dungeon5.048":"Wir müssen Karl und den anderen so schnell wie möglich sagen, wo Elder Grah ist!","story.map11-dungeon5.049":"Also los, <rep_handlename>! <wait=40> Auf geht\'s!","story.map11-dungeon6.001":"Ah, <wait=20>Karl!","story.map11-dungeon6.002":"Hallo, <wait=20>Göttin und <rep_handlename>.","story.map11-dungeon6.003":"Wir haben auf euch gewartet.","story.map11-dungeon6.004":"Wie es aussieht, habt ihr herausgefunden, wo der Älteste Grahdens ist, was?","story.map11-dungeon6.005":"Vielen Dank.","story.map11-dungeon6.006":"Hey, <wait=20>woher weißt du das?","story.map11-dungeon6.007":"Paris ist vorhin vorbeigekommen <wait=20>und hat es uns erzählt.","story.map11-dungeon6.008":"Waaaas?!<wait=40> Paris, du Dummkopf!!","story.map11-dungeon6.009":"Ich wollte doch diejenige sein, die sie überrascht!!","story.map11-dungeon6.010":"Aber sag mal, <wait=20>wo ist Paris jetzt?","story.map11-dungeon6.011":"Tja, <wait=20>sie sagte, es gebe da etwas, das sie interessiert, und ist schon zum Turm der Götter vorausgegangen.","story.map11-dungeon6.012":"Verstehe...","story.map11-dungeon6.013":"Was könnte es sein, <wait=20> das sie so interessiert...?","story.map11-dungeon6.014":"Göttin, <wait=40>was ist los?","story.map11-dungeon6.015":"Du siehst nicht gut aus.<wait=20> Ist etwas passiert?","story.map11-dungeon6.016":"N-<wait=20>Nein, es ist nichts!","story.map11-dungeon6.017":"Ich bin doch immer voller Energie!","story.map11-dungeon6.018":"Stimmt\'s, <wait=20><rep_handlename>?","story.map11-dungeon6.019":"Na gut.","story.map11-dungeon6.020":"Nun, <wait=20>nachdem wir den Ältesten Grahdens gerettet haben, will ich, dass er uns die ganze Geschichte erzählt.","story.map11-dungeon6.021":"Dieser alte Mann... <wait=20>Ich habe das Gefühl, er verheimlicht uns noch vieles.","story.map11-dungeon6.022":"Die Göttin von ihren Sorgen zu befreien, könnte uns auf lange Sicht nützlich sein.","story.map11-dungeon6.023":"Karl ist so ein netter Kerl.","story.map11-dungeon6.024":"Aber so sind eben die Freunde von <rep_handlename>!","story.map11-dungeon6.025":"Haha. <wait=20>Wenn du das direkt vor mir sagst, werde ich ein bisschen rot.","story.map11-dungeon6.026":"Übrigens, <wait=20>um das Thema zu wechseln...","story.map11-dungeon6.027":"Und wie geht\'s diesem Ding?","story.map11-dungeon6.028":"Diesem Ding...?","story.map11-dungeon6.029":"Na ja, <wait=20>wie immer. <wait=40><br>Also mach dir keine Sorgen...","story.map11-dungeon6.030":"Verstehe! <wait=20><br>Also wie immer, was?","story.map11-dungeon6.031":"Na dann <wait=20>mache ich mir keine Sorgen.","story.map11-dungeon6.032":"Ich hab\'s dir doch gesagt! <wait=20>Ich komme als Erste am Turm der Götter an!","story.map11-dungeon6.033":"Das weißt du doch gar nicht!","story.map11-dungeon6.034":"Bleib einfach am Eingang und halte Wache!","story.map11-dungeon6.035":"<size=18>Warum muss ausgerechnet ich Wache stehen?!</size>","story.map11-dungeon6.036":"Weil das der perfekte Job für ein dummes Mädchen wie dich ist.","story.map11-dungeon6.037":"<size=18>Ich bin nicht dumm!</size>","story.map11-dungeon6.038":"Wache halten ist trotzdem eine wichtige Aufgabe!","story.map11-dungeon6.039":"Wenn du das nicht kapierst, wirst du in Zukunft jede Menge Aufträge vermasseln!","story.map11-dungeon6.040":"<size=18>Was hast du gesagt?!</size>","story.map11-dungeon6.041":"Wenn Wache halten so wichtig ist, warum machst du es dann nicht selbst?!","story.map11-dungeon6.042":"Das sind doch zwei verschiedene Dinge!","story.map11-dungeon6.043":"Mann. <wait=20>Die beiden machen mich echt nervös...","story.map11-dungeon7.001":"Endlich, <wait=40><br><rep_handlename>!","story.map11-dungeon7.002":"Elder Grah ist hier,","story.map11-dungeon7.003":"und ebenso einer der Vier Gefallenen Götter, „Der Göttliche Kaiser Zevalhua“.","story.map11-dungeon7.004":"Ich spüre da draußen eine gewaltige Macht...","story.map11-dungeon7.005":"Bei einem der Gefallenen Götter ist das wohl nicht überraschend.","story.map11-dungeon7.006":"Tss, <wait=20>mir egal, wie groß er ist. Wenn er mich nervt, mache ich Kleinholz aus ihm.","story.map11-dungeon7.007":"Aber sag mal, <wait=20>wo ist diese Frau von der Kaiserlichen Garde?","story.map11-dungeon7.008":"Sieht nicht so aus, als wäre sie hier.","story.map11-dungeon7.009":"Ha, <wait=20>auf die Soldaten von Randalls kaiserlicher Armee ist wohl doch kein Verlass.","story.map11-dungeon7.010":"Aber <wait=20>sie hat auch ihren eigenen Auftrag zu erledigen.","story.map11-dungeon7.011":"Sie scheint hier und da mit allem Möglichen beschäftigt zu sein.","story.map11-dungeon7.012":"Sie interessiert sich sogar dafür, warum der Älteste gefangen genommen wurde...","story.map11-dungeon7.013":"Karl!","story.map11-dungeon7.014":"Wir haben jetzt keine Zeit, über so was nachzudenken!","story.map11-dungeon7.015":"Wir müssen uns beeilen und Elder Grah retten, bevor es zu spät ist!","story.map11-dungeon7.016":"Du hast recht. <wait=40><br>Es ist genau, wie die Göttin sagt.","story.map11-dungeon7.017":"Es bringt nichts, jetzt darüber nachzudenken!","story.map11-dungeon7.018":"Also dann, <wait=20>teilen wir uns auf und suchen den Ältesten!","story.map11-dungeon7.019":"Eigentlich würde ich gern, dass wir uns alle vor dem Kampf gegen Zevalhua wieder sammeln, aber","story.map11-dungeon7.020":"je nach Lage klappt das vielleicht nicht. Notfalls müssen wir allein gegen ihn kämpfen.","story.map11-dungeon7.021":"Kein Problem.","story.map11-dungeon7.022":"Selbst wenn er nicht der Echte ist oder es eine Falle ist, ich werde trotzdem kämpfen!","story.map11-dungeon7.023":"Ha! <wait=20>Von euren Kräften habe ich nie viel erwartet.","story.map11-dungeon7.024":"<rep_handlename>, <wait=20>wir zählen wieder auf deine Kraft.","story.map11-dungeon7.025":"Also gut, <wait=20>lasst euch da draußen nicht umbringen!","story.map11-dungeon7.026":"Das ist...","story.map11-dungeon7.027":"Mir bleibt wohl nichts anderes übrig, als meine ursprünglichen Pläne zu ändern...","story.map11-ending.001":"Wir haben es geschafft, <wait=40><br><rep_handlename>!","story.map11-ending.002":"Dass du sogar Zevalhua besiegt hast! Du bist unglaublich, <rep_handlename>!","story.map11-ending.003":"Und Karl und der Älteste sind...","story.map11-ending.005":"*Keuch* *keuch* *keuch* <wait=40><br><rep_handlename>...","story.map11-ending.006":"*Pff*<wait=40><br>*Keuch*","story.map11-ending.007":"Wow, du hast es geschafft!","story.map11-ending.008":"Ich habe gespürt, wie eine gewaltige Macht noch stärker wurde, also bin ich hergeeilt,","story.map11-ending.009":"aber ich hätte wohl gar nicht rennen müssen...","story.map11-ending.010":"Verdammt, <wait=20>sieht aus, als wäre ich nicht rechtzeitig gekommen.","story.map11-ending.011":"<rep_handlename>!","story.map11-ending.012":"Du Mistkerl, <wait=20>du hattest den ganzen Spaß für dich allein, was?!","story.map11-ending.013":"Genau deshalb kann ich dich nicht leiden!","story.map11-ending.014":"Oh, <wait=20>sieht aus, als wären alle unverletzt durchgekommen!","story.map11-ending.015":"<rep_handlename>!","story.map11-ending.016":"Ich wusste, dass du Zevalhua besiegst! Du bist schließlich mein Freund.","story.map11-ending.017":"Ich bin froh, dass alle wohlauf sind.","story.map11-ending.018":"Also, <wait=20>habt ihr Elder Grah gefunden?","story.map11-ending.019":"Er ist nicht hier?","story.map11-ending.020":"In den anderen Räumen war er nicht,","story.map11-ending.021":"also war ich sicher, dass er hier ist, weil nur noch dieser Raum übrig war. Deshalb bin ich hergerannt.","story.map11-ending.022":"Ugh, <wait=20>jetzt müssen wir uns mit noch mehr nervigem Mist herumschlagen.","story.map11-ending.023":"Hoffentlich ist der Älteste Grahdens <wait=20>irgendwo in Sicherheit...","story.map11-ending.024":"Oh, <wait=20>tut mir leid, Karl. <wait=20> So wollte ich das nicht sagen...","story.map11-ending.025":"Nein, schon gut.","story.map11-ending.026":"Es gibt keine Spuren, <wait=20>dass er hier war, also","story.map11-ending.027":"ist er wahrscheinlich selbst entkommen.","story.map11-ending.028":"Ho ho ho. <wait=40><br>Ganz genau.","story.map11-ending.029":"Diese Stimme!","story.map11-ending.030":"Elder Grah!","story.map11-ending.031":"Ho ho ho.","story.map11-ending.032":"Sieht aus, als hätte ich euch allen ziemlich viel Ärger gemacht.","story.map11-ending.033":"Ältester Grahdens...","story.map11-ending.034":"Mach nicht so ein kindisches Gesicht.","story.map11-ending.035":"Ich habe dir vielleicht Sorgen gemacht, <wait=20><br>aber ein Schwächling bin ich noch lange nicht.","story.map11-ending.036":"W-Wer hat sich denn Sorgen um dich gemacht?!","story.map11-ending.037":"Und viel wichtiger: <wait=20>Was hast du die ganze Zeit gemacht, und wo?!","story.map11-ending.038":"Erklär allen, warum wir überall nach dir suchen mussten!","story.map11-ending.039":"Hmpf, <wait=20>nun, ich habe etwas Schlimmes getan.","story.map11-ending.040":"Etwas an diesem Turm ließ mir keine Ruhe, <wait=20>nur ein bisschen.","story.map11-ending.041":"Ich habe so getan, als hätte mich diese Gefallene Göttin Mare-oder-so gefangen, und mich von ihr herbringen lassen.","story.map11-ending.042":"Vielleicht <wait=20>hoffte sie, sich durch meine Gefangennahme einen Vorteil im Kampf gegen euch zu verschaffen.","story.map11-ending.043":"Aber bevor Mare das nutzen konnte, habt ihr sie besiegt.","story.map11-ending.044":"Da sie im Kampf mit Zevalhua und Afla Dilith Wissen über die beiden gewonnen hatte,","story.map11-ending.045":"wollte ich nicht selbst gegen sie kämpfen.","story.map11-ending.046":"Und tatsächlich: <wait=20>Meine Gefangennahme hat eure Hilfe herbeigeführt.","story.map11-ending.047":"Dadurch hatte ich genug Zeit, in Ruhe meine Nachforschungen anzustellen.","story.map11-ending.048":"Dann <wait=20>hättest du uns das einfach sagen sollen.","story.map11-ending.049":"Lästiger alter Knacker.","story.map11-ending.050":"Ho ho ho. <wait=40>Tut mir leid, Lugina.","story.map11-ending.051":"Ich stehe für deine Taten in deiner Schuld.","story.map11-ending.052":"Ich werde dich gut dafür belohnen.","story.map11-ending.053":"Das will ich hoffen.","story.map11-ending.054":"Und nicht nur das, <wait=20>du musst auch anderen wichtigen Leuten <wait=20>von allem erzählen, was ich getan habe.","story.map11-ending.055":"Ehrlich, <wait=20>der Typ hat null Stil.","story.map11-ending.056":"Das sagt der Richtige!","story.map11-ending.057":"Also, <wait=20>Ältester.<wait=40> Du weißt, was ich dich fragen will, oder?","story.map11-ending.058":"Hmpf. <wait=40>Über deine Herkunft, habe ich recht?","story.map11-ending.059":"Das steht in meinem Testament. Kannst du nicht warten, bis du es liest?","story.map11-ending.060":"Kommt nicht infrage.","story.map11-ending.061":"Ho ho ho. <wait=40>Das war ein Scherz. <wait=20>Kein Grund, so wütend zu werden.","story.map11-ending.062":"Aber <wait=20>so ein großes Geheimnis ist es eigentlich nicht.","story.map11-ending.063":"Karl.","story.map11-ending.064":"Ich habe dich als Säugling gefunden und großgezogen. So viel weißt du, oder?","story.map11-ending.065":"Ja, <wait=20>und dafür bin ich dir dankbar.","story.map11-ending.066":"Aber <wait=20>ist an dem Ort, wo du mich gefunden hast, irgendetwas Besonderes?","story.map11-ending.067":"Hmpf. <wait=20><br>Nun, ja.","story.map11-ending.068":"Du hast es vielleicht selbst schon leise gespürt, <wait=20><br>aber ich habe dich in Grand Gaia gefunden.","story.map11-ending.069":"Moment, <wait=20>was?!","story.map11-ending.070":"Tss, <wait=20>so ist das also.","story.map11-ending.071":"...","story.map11-ending.072":"Aber <wait=20>ich dachte, in Grand Gaia gäbe es keine menschlichen Überlebenden...?","story.map11-ending.073":"Nicht einmal ich verstehe es.","story.map11-ending.074":"Ich kam mit anderen Beschwörern hierher, und als wir das Gebiet erkundeten,","story.map11-ending.075":"fanden wir in den Ruinen von Mistral einen Säugling.","story.map11-ending.076":"Und so <wait=40>nahmen wir ihn mit zurück nach Elgaia.","story.map11-ending.077":"Das ist alles.","story.map11-ending.078":"Ich hatte keine Ahnung, was für ein Wesen dieser Säugling wirklich war.","story.map11-ending.079":"Karl.","story.map11-ending.080":"Ich weiß nicht, ob du ein überlebendes Waisenkind aus Grand Gaia bist ","story.map11-ending.081":"oder ein Kind der Götter.","story.map11-ending.082":"Aber--","story.map11-ending.083":"Ältester. <wait=40><br>Du musst mir nichts weiter erzählen.","story.map11-ending.084":"Denn ich bin dir und allen anderen Beschwörern wirklich dankbar.","story.map11-ending.085":"...","story.map11-ending.086":"Karl...","story.map11-ending.087":"Wow, Karl hatte also so ein Geheimnis, was?","story.map11-ending.088":"Hmm... <wait=40>Ein Baby, zurückgelassen in Grand Gaia.","story.map11-ending.089":"Von so etwas habe ich nie gehört.","story.map11-ending.090":"Ob Lord Lucius etwas darüber weiß?","story.map11-ending.091":"Ich glaube, <wait=20>ich gehe ihn fragen!","story.map11-ending.092":"<rep_handlename>!","story.map11-ending.093":"Jetzt müssen wir uns nur noch um einen Gefallenen Gott kümmern, den Bestiengott Afla Dilith!","story.map11-ending.094":"Wenn wir alle zusammenarbeiten, besiegen wir ihn bestimmt!","story.map11-ending.095":"Und natürlich <wait=20>zählen wir auch auf deine Kräfte als Beschwörer, <rep_handlename>.","story.map11-ending.096":"Also dann, <wait=20>ich frage wegen Karl nach und melde mich beim nächsten Mal bei euch!","story.map11-ending.097":"Oh, <wait=20>warte! <wait=20><br>Göttin!","story.map11-ending.098":"Ich wollte ihr sagen, dass es mir eigentlich egal ist...","story.map11-ending.099":"Sie hört einfach nicht zu, oder?","story.map11-ending.100":"Ho ho ho. <wait=40><br>Weil Tilith ein gutherziges Mädchen ist.","story.map11-ending.101":"Also, <wait=20>was machen wir mit dieser üblen Präsenz, die aufgetaucht ist, nachdem die Göttin weg war?","story.map11-ending.102":"Mit üblen Präsenzen gehe ich nicht gerade sanft um.","story.map11-ending.103":"Du bist...","story.map11-ending.104":"Ich bin Eriole.","story.map11-ending.105":"Ich komme aus dem Randall-Imperium,","story.map11-ending.106":"wo ich als Kommandant der Kaiserlichen Garde diene, die das Kaiserhaus beschützt.","story.map11-ending.107":"Heh, <wait=20>von dem Namen habe ich Gerüchte gehört.","story.map11-ending.108":"Gerüchte über einen fiesen Kerl, der als Jüngster überhaupt den Rang des Kommandanten erhielt.","story.map11-ending.109":"Wie unverschämt!","story.map11-ending.110":"Oh, <wait=20>die Dame, die zu viel Angst vor den Vier Gefallenen Göttern hatte, ist zurück!","story.map11-ending.111":"Dieser Mann ist ein--","story.map11-ending.112":"Paris, halte dich etwas zurück.","story.map11-ending.113":"Was? <wait=20>A-<wait=20>Aber--","story.map11-ending.114":"Paris.","story.map11-ending.115":"V-<wait=20>Verstanden...","story.map11-ending.116":"Also, <wait=20>was genau will der Kommandant der Kaiserlichen Garde von uns?","story.map11-ending.117":"Ich wäre auch dankbar, wenn du uns erklärst, wer die unheimliche Person hinter dir ist.","story.map11-ending.118":"...","story.map11-ending.119":"Diese Person ist mein Gefährte. <wait=40><br>Macht euch um ihn keine Sorgen.","story.map11-ending.120":"Ihr habt sicher schon vieles von meiner Untergebenen Paris gehört.","story.map11-ending.121":"Ich wollte wenigstens einmal mit euch allen sprechen,","story.map11-ending.122":"aber als Gesandter des Kaisers von Randall","story.map11-ending.123":"bin ich diesmal gekommen, um eigens mit dem Beschwörer Grahdens zu sprechen.","story.map11-ending.124":"Ho ho ho.","story.map11-ending.125":"Wenn du nur mit mir reden wolltest, <wait=20>hättest du nicht den ganzen Weg herkommen müssen.","story.map11-ending.126":"Ha ha ha.","story.map11-ending.127":"Wir haben unsere Gründe dafür.","story.map11-ending.128":"Wir werden es später ausführlich erklären.","story.map11-ending.129":"Hast du vor, den Ältesten mitzunehmen?","story.map11-ending.130":"Glaubst du wirklich, dass er brav mitkommt?","story.map11-ending.131":"Bitte versteht uns nicht falsch.","story.map11-ending.132":"Wir sind nicht gekommen, um zu kämpfen.","story.map11-ending.133":"Das weiß ich.","story.map11-ending.134":"Denn wenn mir etwas zustößt, wäre das für euch sehr ungünstig.","story.map11-ending.135":"...","story.map11-ending.136":"Alle, <wait=20>entschuldigt mich. <wait=40><br>Ich unterhalte mich kurz mit diesen Herrschaften.","story.map11-ending.137":"Ich wollte mich bei euch allen richtig bedanken, aber das muss wohl bis zum nächsten Mal warten.","story.map11-ending.138":"Karl.","story.map11-ending.139":"Es hat mich diesmal gefreut zu sehen,<wait=20> wie sehr du gewachsen bist.","story.map11-ending.140":"Ältester Grahdens...","story.map11-ending.141":"Und du, <rep_handlename>.","story.map11-ending.142":"Gut gemacht, dass du Zevalhua besiegt hast.","story.map11-ending.143":"Aber <wait=20>als Nächstes trittst du gegen Afla Dilith an.","story.map11-ending.144":"Und anders als die anderen Gefallenen Götter wird er sicher auf einen Kampf mit dir vorbereitet sein.","story.map11-ending.145":"Es wird zweifellos ein schwerer Kampf, aber du musst dich und deine Freunde fordern.","story.map11-ending.146":"Außerdem <wait=20>lege ich Karl in deine Hände.","story.map11-ending.147":"Du weißt es vielleicht schon, aber","story.map11-ending.148":"ihm fehlt hier und da noch so einiges, darum mache ich mir Sorgen um ihn.","story.map11-ending.149":"Ich brauche niemanden, der auf mich aufpasst...","story.map11-ending.150":"Ho ho ho.","story.map11-ending.151":"Nun denn, Gesandter des Randall-Imperiums, <wait=40><br>wollen wir aufbrechen?","story.map11-ending.152":"Ich danke dir<wait=20> für deine Rücksicht und dein Verständnis.","story.map11-ending.153":"Paris, <wait=40>wir gehen.","story.map11-ending.154":"Jawohl!","story.map11-ending.155":"Er ist einfach so gegangen, was?","story.map11-ending.156":"Da es der Älteste Grahdens ist, wird er sicher klarkommen. Aber trotzdem...","story.map11-ending.157":"Hmpf. <wait=20>Die Typen vom Randall-Imperium können dem alten Beschwörer kein Haar krümmen.","story.map11-ending.158":"Du hast recht.","story.map11-ending.159":"Wir reden immerhin vom Ältesten Grahdens. <wait=40><br>Ihm wird nichts passieren.","story.map11-ending.160":"Viel wichtiger ist, <wait=20>dass wir uns darauf konzentrieren, wie wir von unserer Seite helfen können.","story.map11-ending.161":"<rep_handlename>,","story.map11-ending.162":"du wirst gegen Afla Dilith kämpfen, <wait=20> den letzten der Vier Gefallenen Götter, <wait=20>oder?","story.map11-ending.163":"Eigentlich wollen Seria und ich dir dabei helfen, aber den Dämon Graham können wir auch nicht ignorieren.","story.map11-ending.164":"Stimmt! <wait=40><br>Den hatte ich total vergessen!","story.map11-ending.165":"Wenn wir ihn nicht besiegen...","story.map11-ending.166":"<rep_handlename>!","story.map11-ending.167":"Wir müssen uns trennen, <wait=20><br>aber du kommst klar, oder?","story.map11-ending.168":"Wir besiegen Graham und kommen sofort zurück, also pass auf dich auf!","story.map11-ending.169":"Na, na... <wait=20>Die große Dämonin Seria hat wohl doch eine nette Seite.","story.map11-ending.170":"Idi-- <wait=20>Trott-- <wait=20>Das sagt man in solchen Momenten eben!","story.map11-ending.171":"Hey, <rep_handlename>!","story.map11-ending.172":"Glaub ja nicht, du kannst dir den Sieg <wait=20>über Zevalhua ganz allein auf die Fahne schreiben.","story.map11-ending.173":"Vergiss auch nicht all das, <wait=40><br>was ich getan habe.","story.map11-ending.174":"Ob ich dich nächstes Mal rette oder nicht, hängt vielleicht davon ab, wie dankbar du mir bist.","story.map11-ending.175":"Haha, <wait=20>typisch Lugina.","story.map11-ending.176":"<rep_handlename>, <wait=40><br>wir müssen jetzt los.","story.map11-ending.177":"Wenn du die Göttin wiedersiehst, sag ihr bitte, dass ich ihr für ihre Hilfe sehr dankbar bin.","story.map11-ending.178":"Und <wait=20>wenn du etwas über mich hörst und mit mir darüber reden willst, liegt das bei dir.","story.map11-ending.179":"Denn wenn du es mir sagst, <wait=20>werde ich bestimmt mit jeder Wahrheit fertig, die auf mich zukommt.","story.map11-ending.180":"Also dann, <wait=20>ich freue mich aufs nächste Mal.","story.map11-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ich bin Lucius...<wait=40><br>Gott dieses Tors...","story.map11-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Befreier von Agni...<wait=40><br><rep_handlename>...","story.map11-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Nutze meine Kraft...<wait=40><br>und brich auf in ein neues Land...","story.map11-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>um unser Wort<wait=40><br>in diese im Chaos versunkene Welt zu tragen...","story.map11-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Glaube an dich<wait=20><br>und schreite weiter voran...","story.map11-open.006":"<rep_handlename>! <wait=40><br>Es ist so weit!","story.map11-open.007":"Das ist Mirvana, die Region, die Zevalhua im Krieg gegen die Götter zu seinem Stützpunkt machte.","story.map11-open.008":"Deshalb wurde die Agni-Region wohl <wait=20>zum größten Schlachtfeld des Krieges.","story.map11-open.009":"Die Landschaft hier ist so düster...","story.map11-open.010":"Oh! <wait=20>Sorry, sorry!","story.map11-open.011":"Jetzt ist keine Zeit für Sentimentalitäten!","story.map11-open.013":"Also, <wait=20>besiegen wir Zevalhua und retten Elder Grah!","story.map11-open.014":"Ich weiß, dass wir uns voll auf dich verlassen können, <rep_handlename>. Ich glaube an dich!","story.map2-dungeon1.001":"<size=22>Oh?! <rep_handlename>!!","story.map2-dungeon1.002":"Nicht zu fassen, <wait=20>dass wir uns ausgerechnet hier wiedersehen!","story.map2-dungeon1.003":"Verstehe, <wait=40>du willst auch zum Turm von Morgan, oder?","story.map2-dungeon1.004":"Dann bist du wohl auch bei der Beschwörerarmee und jagst die Vier Gefallenen Götter...","story.map2-dungeon1.005":"Nein? <wait=40>Tilith hat dich hergeschickt?","story.map2-dungeon1.006":"Ah, <wait=20>das muss das Mädchen sein, von dem du mal erzählt hast.","story.map2-dungeon1.007":"Klingt, als wärst du gut aufgehoben.  <wait=20>Ich sollte sie höflich begrüßen, wenn wir uns treffen. <wait=19>Stellst du uns vor?","story.map2-dungeon1.008":"Hä? <wait=20>Sie ist nicht hier? <wait=40>Du suchst sie auch?","story.map2-dungeon1.009":"Hmm... <wait=40>Na ja, <wait=40>dann frag ich wohl besser nicht weiter.","story.map2-dungeon1.010":"Wir Dämonenjäger sind hinter dem Dämon Graham her.","story.map2-dungeon1.011":"Ein paarmal hatten wir ihn schon in die Enge getrieben, <wait=20>aber er entwischt uns jedes Mal...","story.map2-dungeon1.012":"Er ist in die Wüste geflohen, also ziehen wir jetzt los, um ihn dort zu suchen.","story.map2-dungeon1.013":"Na dann, <wait=20>sollen wir uns auf den Weg machen?","story.map2-dungeon1.014":"Übrigens, <wait=40>in dieser Wüste ist es höllisch heiß, also pass gut auf dich auf.","story.map2-dungeon1.015":"Und halt die Augen offen: In letzter Zeit soll hier ein Trottel mit einem flammenden Schwert herumfuchteln!","story.map2-dungeon1.016":"Sei vorsichtig, <wait=20>wir sehen uns bald wieder!","story.map2-dungeon2.001":"Oh, <rep_handlename>!!","story.map2-dungeon2.002":"Spürst du das? <wait=40>Ist die Meeresbrise hier nicht einfach herrlich?","story.map2-dungeon2.003":"Hä? <wait=40>Warum wir hier sind?","story.map2-dungeon2.004":"Weil es da hinten viel zu heiß war...","story.map2-dungeon2.005":"<size=22>Ah! <wait=40>Das nehme ich zurück!!","story.map2-dungeon2.006":"Wir sind nicht nur wegen der Hitze hier...","story.map2-dungeon2.007":"Ich habe hier tatsächlich etwas zu erledigen! <wait=40>Und hör endlich auf, mich so zweifelnd anzusehen!","story.map2-dungeon2.008":"Also gut, ich muss los! <wait=40>Ich hole dich ein, sobald ich hier fertig bin.","story.map2-dungeon2.009":"Geh du schon mal vor, <rep_handlename>!<br><wait=40>Und trödel nicht, OK?","story.map2-dungeon2.010":"Übrigens, <wait=40>an diesem Strand soll eine feindliche Schwertkämpferin sein, und ich habe gehört, sie kann kalte Luft beherrschen!","story.map2-dungeon2.011":"Angeblich ist sie wunderschön, aber ich bin bestimmt viel süßer als sie!","story.map2-dungeon2.012":"Besieg sie unbedingt, <wait=20>und zwar schnell, ja?","story.map2-dungeon2.013":"Jedenfalls, <wait=20>ich warte hier! <wait=40>Viel Glück!","story.map2-dungeon3.001":"Bist du das, <rep_handlename>?!<br><wait=40>Hast du Graham gesehen?!","story.map2-dungeon3.002":"Oh, <wait=20>hast du nicht... <wait=40>Verdammt... <wait=40>Argh...","story.map2-dungeon3.003":"Ach, <wait=20>mach dir keine Sorgen. <wait=40>Das ist bloß ein Kratzer, nicht der Rede wert...","story.map2-dungeon3.004":"Viel schlimmer ist, <wait=20>dass die meisten meiner Kameraden ausgelöscht wurden...","story.map2-dungeon3.005":"Graham... <wait=30>Er ist jetzt im Nächtlichen Wald.","story.map2-dungeon3.006":"Dieser Wald ist wohl das Revier eines von Grahams Rittern.","story.map2-dungeon3.007":"Dieser Ritter kennt die Schatten des Waldes wie seine Westentasche und nutzt die schlechte Sicht zu seinem Vorteil.","story.map2-dungeon3.008":"Er erledigt einen Beschwörer nach dem anderen.","story.map2-dungeon3.009":"Wenn wir diesen Ritter besiegen, können wir Graham wahrscheinlich aus dem Wald jagen.","story.map2-dungeon3.010":"Ich weiß nur, dass dieser Ritter mit einem Speer kämpft.","story.map2-dungeon3.011":"So wie es um die Dämonenjäger steht, können wir kaum mehr tun, als Graham einzukreisen...","story.map2-dungeon3.012":"Und ich werde bestimmt nicht tatenlos zusehen, wie meine Kameraden einer nach dem anderen fallen.","story.map2-dungeon3.013":"Egal wie, ich zerre ihn aus diesem Wald, und wenn ich es allein tun muss!","story.map2-dungeon3.014":"Also dann, machen wir uns auf den Weg.<br><wait=40>Ich erwarte, dass du auch alles gibst!","story.map2-dungeon4.001":"Hey, <wait=20><rep_handlename>!<br><wait=40>Schön, dich in einem Stück zu sehen!","story.map2-dungeon4.002":"Na ja, <wait=20>ich hab ja auch nicht geglaubt, dass du gegen so einen verlierst!","story.map2-dungeon4.003":"Du willst zum Turm von Morgan, richtig?","story.map2-dungeon4.004":"Dann musst du durch das Asekutt-Ödland.","story.map2-dungeon4.005":"Die Bestien, die sich im Asekutt-Ödland herumtreiben, sind ziemlich stark.","story.map2-dungeon4.006":"Wenn deine Einheiten elementar im Nachteil gegen diese Bestien sind, wird\'s gefährlich, also sei vorsichtig.","story.map2-dungeon4.007":"Hm? <wait=40>Du machst dir Sorgen, wie es bei uns läuft?","story.map2-dungeon4.008":"Na ja, irgendwie habe ich es geschafft, Graham aus dem Wald zu zerren.","story.map2-dungeon4.009":"Aber anders als der Nächtliche Wald ist Asekutt offenes Gelände.","story.map2-dungeon4.010":"Da kann er nicht weglaufen und sich verstecken wie im Nächtlichen Wald.","story.map2-dungeon4.011":"Auch wenn unsere Dämonenjäger-Truppe nur noch halb so stark ist...","story.map2-dungeon4.012":"...will ich die Sache in Asekutt ein für alle Mal klären.","story.map2-dungeon4.013":"Das bin ich meinen Kameraden schuldig, <wait=40>für ihr Opfer.","story.map2-dungeon4.014":"Also kann ich dich leider <wait=40>nicht begleiten.","story.map2-dungeon4.015":"Aber ich bin fest davon überzeugt, dass du Maxwell besiegen wirst.","story.map2-dungeon4.016":"Bis dann!","story.map2-dungeon5.001":"Hey, <rep_handlename>.<br><wait=40>Graham ist schon wieder entkommen...","story.map2-dungeon5.002":"Verflucht, <wait=40>wir waren so nah dran!","story.map2-dungeon5.003":"Und ich habe noch mehr Kameraden verloren... <wait=40>Ich schwöre, wenn ich ihn erwische, mache ich ihn fertig.","story.map2-dungeon5.004":"...<wait=20>Aber im Moment sind wir Dämonenjäger zu wenige.","story.map2-dungeon5.005":"Deshalb kehren wir zur Beschwörerhalle zurück, um Verstärkung zu holen.","story.map2-dungeon5.006":"Eigentlich wollte ich sie hier auch treffen, aber...","story.map2-dungeon5.007":"Oh, <wait=20>da ist sie ja!","story.map2-dungeon5.008":"Na, Seria, <wait=40>du siehst ja munter aus!","story.map2-dungeon5.009":"Karl! <wait=40>Das ist keine Zeit für Plaudereien!","story.map2-dungeon5.010":"Was macht <rep_handlename> hier?!","story.map2-dungeon5.011":"Du gehörst doch gar nicht zu den Dämonenjägern, oder?!","story.map2-dungeon5.012":"Ach, <wait=40><rep_handlename> und ich haben uns hier zufällig getroffen.","story.map2-dungeon5.013":"Dein nächstes Ziel <wait=20>ist der Schrein von Lystia, nehme ich an?","story.map2-dungeon5.014":"Wenn du kein Mitglied der Dämonenjäger bist, hast du hier nichts verloren.","story.map2-dungeon5.015":"Hey, <wait=20>Seria. <wait=40>Kein Grund, so harte Worte zu benutzen!","story.map2-dungeon5.016":"<size=12>...<wait=40>Warum werde eigentlich ich angeschrien??","story.map2-dungeon5.017":"Viel wichtiger: Ich habe Neuigkeiten für dich, Karl.","story.map2-dungeon5.018":"Laut Informationen der Beschwörerhalle <wait=20>war Graham wohl einer von Abaddons Lieblingen.","story.map2-dungeon5.019":"Er steht in Abaddons Gunst? <wait=40>Was soll das denn heißen?","story.map2-dungeon5.020":"Er scheint sogar bei den anderen Göttern ungeheuer beliebt zu sein...","story.map2-dungeon5.021":"Wenn Graham also in Gefahr ist, kannst du sicher sein, dass bald noch mehr Ärger folgt.","story.map2-dungeon5.022":"Vielleicht taucht sogar Abaddon selbst auf...","story.map2-dungeon5.023":"Wenn das stimmt, müssen wir Graham erledigen, um Abaddon hervorzulocken.","story.map2-dungeon5.024":"Deshalb haben wir von der Beschwörerhalle den Befehl erhalten, zum Turm von Morgan vorzurücken. ","story.map2-dungeon5.025":"Verstehe.","story.map2-dungeon5.026":"Deshalb wurde unsere Bitte um Verstärkung also so schnell angenommen.","story.map2-dungeon5.027":"Wie auch immer, findest du nicht, dass wir langsam mit dem Gequatsche aufhören sollten!?","story.map2-dungeon5.028":"Du solltest doch auf dem Weg zum Turm von Morgan sein, oder?","story.map2-dungeon5.029":"Wir haben noch eine Menge zu planen...","story.map2-dungeon5.030":"...also warum ziehst du nicht einfach allein weiter!","story.map2-dungeon5.031":"Hä? <wait=20>H-<wait=20>Hey, Seria! <wait=40><rep_handlename>!!","story.map2-dungeon6.001":"<rep_handlename>! <wait=40>Alles in Ordnung?!","story.map2-dungeon6.002":"Du bist einfach losgezogen, nachdem Seria dich angeschrien hat. <wait=20>Ich dachte schon, du wärst sauer.","story.map2-dungeon6.003":"Na ja, <wait=20>ich bin froh, dass es dir gut geht.","story.map2-dungeon6.004":"Wir haben es selbst gerade erst durch den Schrein von Lystia geschafft.","story.map2-dungeon6.005":"Hey, <wait=40>warum tauchst du eigentlich überall auf, wo wir hingehen?!","story.map2-dungeon6.006":"Du verfolgst uns doch nicht etwa, oder?!","story.map2-dungeon6.007":"Hörst du endlich mit dieser sinnlosen Feindseligkeit auf?!","story.map2-dungeon6.008":"Warum musst du immer Streit anfangen?","story.map2-dungeon6.009":"I-<wait=20>Ich fange keinen Streit an!","story.map2-dungeon6.010":"So stark ist der doch gar nicht...","story.map2-dungeon6.011":"Es regt mich echt auf, dass du so jemanden lobst. Ehrlich, sieh ihn dir doch an!","story.map2-dungeon6.012":"*Seufz* <wait=40>Wenn das kein Streitanfangen ist, <wait=20>dann weiß ich auch nicht...","story.map2-dungeon6.013":"Falls es dir entgangen ist: <wait=20><rep_handlename> hat es ganz allein bis hierher geschafft.","story.map2-dungeon6.014":"<rep_handlename> hat uns geholfen und Grahams Untergebenen im Nächtlichen Wald besiegt.","story.map2-dungeon6.015":"<rep_handlename> ist ganz sicher kein Schwächling.","story.map2-dungeon6.016":"Pff. <wait=40>Mir ist das sowieso egal.","story.map2-dungeon6.017":"Sonn dich ruhig in ihrem unverdienten Lob, meinetwegen!","story.map2-dungeon6.018":"...<wait=40>Frauen verstehe ich echt nicht.","story.map2-dungeon6.019":"Na ja, <wait=20>wie auch immer...","story.map2-dungeon6.020":"Wir gehen durch diese zerstörte Kathedrale zum Turm von Morgan...","story.map2-dungeon6.021":"<rep_handlename>, willst du mitkommen?","story.map2-dungeon6.022":"<size=24>Einspruch!","story.map2-dungeon6.023":"Heh, <wait=20>wusste ich doch, dass du das sagst.","story.map2-dungeon6.024":"Na ja, <wait=20>wir können nicht gemeinsam in den Kampf ziehen, wenn wir uns untereinander so zanken. Erzwingen sollten wir\'s wohl nicht.","story.map2-dungeon6.025":"Wir gehen unseren Weg, du deinen.","story.map2-dungeon6.026":"Wir sehen uns am Turm von Morgan!","story.map2-dungeon7.001":"<rep_handlename>!! <wait=40>Du bist schnell, <wait=20>ich hätte nicht gedacht, dass du schon hier bist.","story.map2-dungeon7.002":"Heh, <wait=40>das ist ja wohl das Mindeste...","story.map2-dungeon7.003":"Wie immer gleich auf Streit aus...","story.map2-dungeon7.004":"Also, <wait=20>wie auch immer... <wait=40>Das ist Abaddons Festung, <wait=20>der Turm von Morgan.","story.map2-dungeon7.005":"Abaddon und Graham sind wahrscheinlich hier.","story.map2-dungeon7.006":"Das ist so ziemlich der einzige Ort, an den Graham fliehen konnte.","story.map2-dungeon7.007":"Wir schnappen uns Graham. <wait=40><br>Und du, <rep_handlename>, nimmst es mit Abaddon auf.","story.map2-dungeon7.008":"Wir sind so weit gekommen, <wait=40>jetzt machen wir sie fertig!","story.map2-dungeon7.009":"Aber vielleicht besiegen wir Abaddon ja, bevor du überhaupt die Chance dazu hast!","story.map2-dungeon7.010":"Und was sagst du, wenn <rep_handlename> Graham vor uns besiegt?","story.map2-dungeon7.011":"Na ja, <wait=40>natürlich willst du die Feinde deines Freundes selbst bekämpfen...","story.map2-dungeon7.012":"Aber ich finde, wir sollten zusammenarbeiten, jeder an seiner eigenen Front, und alles geben!","story.map2-dungeon7.013":"Hey... <wait=20>hey! <wait=40>Klingt wie ein Beben, hörst du das?","story.map2-dungeon7.014":"Da drüben!!","story.map2-dungeon7.015":"W-<wait=20>Was ist das!? <wait=40>Horden von... <wait=20>Monstern?!","story.map2-dungeon7.016":"...Maxwell. <wait=40>Sie will uns also hier aufhalten...","story.map2-dungeon7.017":"Es gibt kein Zurück... <wait=40>Uns bleibt nichts, als zu kämpfen... <wait=40>Hier und jetzt...","story.map2-dungeon7.018":"...<wait=40>Moment, <wait=40>es gibt vielleicht noch einen anderen Weg.","story.map2-dungeon7.019":"Wir müssen nur bis zur Spitze des Turms von Morgan klettern <wait=40>und dort Abaddon besiegen.","story.map2-dungeon7.020":"Das ist unmöglich!","story.map2-dungeon7.021":"Wir können es niemals mit all diesen Monstern und Abaddon aufnehmen...","story.map2-dungeon7.022":"Vergiss es. <wait=40>Wir kämen wahrscheinlich nicht mal nah genug heran, um Abaddon auch nur zu sehen.","story.map2-dungeon7.023":"Du hast recht. <wait=40>Aber <wait=20>diese Monster kommen keinen Schritt weiter.","story.map2-dungeon7.024":"Ich halte sie genau hier auf!","story.map2-dungeon7.025":"Karl!? <wait=40>Was redest du da!?","story.map2-dungeon7.026":"Willst du sie wirklich hier aufhalten, während wir uns Abaddon stellen?!","story.map2-dungeon7.027":"Genau. <wait=40>Es ist unsere einzige Möglichkeit...","story.map2-dungeon7.028":"Aber sieh sie dir an. <wait=40>Mit denen wird niemand allein fertig!","story.map2-dungeon7.029":"Ja... <wait=40>das weiß ich.","story.map2-dungeon7.030":"Aber wenn hier alles enden soll, setze ich auf das, was uns die besten Chancen gibt, Abaddon zu besiegen.","story.map2-dungeon7.031":"Karl...","story.map2-dungeon7.032":"<rep_handlename>, <wait=40>geh mit Seria voraus.","story.map2-dungeon7.033":"Ich halte diese Monster auf. <wait=40>Du musst Abaddon ausschalten.","story.map2-dungeon7.034":"...<wait=40>Ich gehe nicht.","story.map2-dungeon7.035":"Seria!!","story.map2-dungeon7.036":"Diese Horde <wait=20>ist zu viel für dich allein, Karl.","story.map2-dungeon7.037":"Wenn ich dir helfe, sie <wait=20>nur ein bisschen länger aufzuhalten...","story.map2-dungeon7.038":"...verschafft uns das vielleicht genau die Zeit, die wir brauchen, <wait=20>um Abaddon zu besiegen.","story.map2-dungeon7.039":"Seria, <wait=40>du...","story.map2-dungeon7.040":"<rep_handlename>!","story.map2-dungeon7.041":"Du da, <wait=40>die Beschwörer der Alten Zeit haben deine Stärke als Beschwörer anerkannt, nicht wahr?","story.map2-dungeon7.042":"Dann beweise es mir.","story.map2-dungeon7.043":"Ich prügle dich windelweich, wenn du Abaddon nicht besiegst!!","story.map2-dungeon7.044":"...<wait=40>Also dann, <wait=20>legen wir los!!","story.map2-dungeon7.045":"Tss... <wait=20>Dieses Mädchen...","story.map2-dungeon7.046":"<rep_handlename>, <wait=40>wir geben alles, um sie aufzuhalten.","story.map2-dungeon7.047":"Du musst Abaddon besiegen.","story.map2-dungeon7.048":"Wir zählen auf dich, <wait=40><rep_handlename>.","story.map2-dungeon7.049":"Und jetzt, <wait=40>in den Kampf!!","story.map2-ending.001":"<size=20><rep_handlename>! Alles in Ordnung?!</size>","story.map2-ending.002":"Oh, <wait=20>hast du etwa... <wait=40>Abaddon besiegt?","story.map2-ending.003":"Wow... <wait=40>Du bist wirklich ganz schön stark.","story.map2-ending.004":"Ich kann kaum glauben, dass du Abaddon ganz allein besiegt hast...","story.map2-ending.005":"Oh, ich? <wait=20>Mir geht\'s gut.","story.map2-ending.006":"Nachdem wir uns getrennt hatten, <wait=20>habe ich alles gegeben, um den Eingang zum Turm zu verteidigen.","story.map2-ending.007":"Seria und ich sind beide bis an unsere Grenzen gegangen, es hätte uns fast erwischt...","story.map2-ending.008":"Aber zum Glück kam die Verstärkung aus der Beschwörerhalle gerade noch rechtzeitig.","story.map2-ending.009":"Sie haben alles gegeben, um uns zu helfen...","story.map2-ending.010":"Hm? <wait=20>Seria? <wait=40>Sie ist da drüben... <wait=40>Hä? <wait=20>Seria?","story.map2-ending.011":"Wo ist sie hin? <wait=40>...<wait=40>Hm, <wait=20>na egal.","story.map2-ending.012":"Übrigens <wait=20>hat sie sich ziemliche Sorgen um dich gemacht.","story.map2-ending.013":"Sie war völlig zerschunden und erschöpft, aber sie bestand darauf, dir zu helfen, und ist direkt den Turm hinaufgestürmt...","story.map2-ending.014":"Hehe, <wait=20>wer weiß, was sie anstellt, wenn sie erfährt, dass ich dir das alles erzählt habe...","story.map2-ending.015":"Also verrat ihr nicht, dass du das von mir hast, OK?","story.map2-ending.016":"Aber mal im Ernst, <wait=40>du bist wirklich stark geworden.","story.map2-ending.017":"Wir sind dir zu Hilfe geeilt, <wait=40>aber anscheinend brauchtest du gar keine Verstärkung.","story.map2-ending.018":"Für mich bist du schon jetzt ein Beschwörer der Spitzenklasse.","story.map2-ending.019":"Ach, <wait=20>richtig...","story.map2-ending.020":"Graham konnten wir am Ende nicht erledigen.","story.map2-ending.021":"Aber wir haben ein paar Monster gefangen und sie dazu gebracht, Grahams Versteck auszuspucken.","story.map2-ending.022":"Doch er ist an einen Ort geflohen, an den wir nicht herankommen... <wait=20>Verfluchtes Scheusal... ","story.map2-ending.023":"Es wird nicht leicht, ihn aufzuspüren.","story.map2-ending.024":"Ich muss der Akras-Beschwörerhalle Bericht erstatten...","story.map2-ending.025":"Und du... <wait=40>Na ja, <wait=40>du hast wohl deine eigenen Angelegenheiten zu erledigen.","story.map2-ending.026":"...<wait=20>Ich mache mich besser auf den Weg.","story.map2-ending.027":"Unsere Ziele mögen verschieden sein, <wait=40>aber ich stehe immer auf deiner Seite.","story.map2-ending.028":"Und sieh zu, dass du am Leben bleibst! <wait=40>Bis dann!","story.map2-ending.029":"Hey! <wait=40><rep_handlename>!!","story.map2-ending.030":"Endlich hab ich dich eingeholt!","story.map2-ending.031":"Du bist einfach unglaublich!!","story.map2-ending.032":"Während ich am Brisenstrand mit der Eiskönigin Selena darum gewetteifert habe, wer süßer ist...","story.map2-ending.033":"...hast du anscheinend Abaddon besiegt! Unglaublich!","story.map2-ending.034":"...Hä?!","story.map2-ending.035":"V-<wait=20>Versteh mich nicht falsch! <wait=40>Wir hatten doch keinen Schönheitswettbewerb oder so...","story.map2-ending.036":"Ich meine, Selena ist ja nicht mal aufgetaucht!","story.map2-ending.037":"Außerdem, <rep_handlename>, du warst ja nicht da, also gab es eh niemanden, der hätte urteilen können, oder?!","story.map2-ending.038":"...<wait=40>Was soll denn dieser Blick!","story.map2-ending.039":"Ich hatte am Brisenstrand wirklich etwas Wichtiges zu erledigen!","story.map2-ending.040":"Ah! <wait=20>Hörst du das?<br><wait=40>Klingt, als würde Lord Lucius dich rufen?","story.map2-ending.041":"<speed=12>Gute <wait=10>Rei<wait=20>se<wait=30>...","story.map2-ending.042":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ich bin Lucius...<br><wait=40>Gott dieses Tores...","story.map2-ending.043":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Retter von Morgan...","story.map2-ending.044":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Nutze meine Kraft <wait=40>und zieh in neue Länder...","story.map2-ending.045":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Schreite voran <wait=20>und bringe dieser Welt mit deiner Kraft Frieden...","story.map2-ending.046":"Oh, <wait=20>du bist wach.","story.map2-ending.047":"Guten Morgen, <wait=20> <rep_handlename>.","story.map2-ending.048":"Sieh mal... <wait=40>Wir sind endlich in St. Lamia angekommen.","story.map2-ending.049":"Das hier ist... <wait=40>Maxwells Reich.","story.map2-ending.050":"...<wait=40><rep_handlename>, spürst du es auch?","story.map2-ending.051":"Ich spüre, wie eine gewaltige Macht hier pulsiert...","story.map2-ending.052":"Die Monster sind auch stärker als vorher. <wait=40>Wir müssen konzentriert bleiben...","story.map2-ending.053":"Maxwell ist im Palast von St. Lamia.","story.map2-ending.054":"Harte Kämpfe erwarten uns, <wait=40>geben wir gemeinsam unser Bestes!","story.map2-ending.055":"Was? <wait=40>Wo ich war, als du in Morgan gekämpft hast, fragst du?","story.map2-ending.056":"Sei doch nicht so kleinlich...","story.map2-ending.057":"Ich verspreche, in St. Lamia mein Bestes zu geben, <wait=40>OK?","story.map2-ending.058":"Also dann, <wait=20>auf geht\'s!!","story.map3-dungeon1.001":"<size=13>Hier ist es glühend heiß! <wait=40>Ich will nach Hause... <wait=40>Meine arme Haut hält das nicht mehr aus...","story.map3-dungeon1.002":"<size=20>Hey! <wait=20><rep_handlename>!","story.map3-dungeon1.003":"Du! <wait=20>Du bist schon wieder zu spät!!","story.map3-dungeon1.004":"Sag bloß, du hast es dir irgendwo im Kühlen gemütlich gemacht!?","story.map3-dungeon1.005":"Das ist keine Zeit zum Herumalbern! <wait=40>Was hast du zu deiner Verteidigung zu sagen?","story.map3-dungeon1.006":"Hä? <wait=20>Was ist mit mir?","story.map3-dungeon1.007":"<size=15>Ich <size=14>habe <size=13>es <size=12>mir <size=11>kein <size=10>bisschen <size=9>gemütlich <size=8>gemacht<size=7>...<size=6>","story.map3-dungeon1.008":"Wie auch immer, <wait=40>ab heute besteigen wir den Vulkan Eldent.","story.map3-dungeon1.009":"Der Vulkan Eldent ist ein aktiver Vulkan, also ist es hier richtig gefährlich.","story.map3-dungeon1.010":"Pass bloß auf Lavaströme auf!","story.map3-dungeon1.011":"Also dann, <wait=20>bon voyage!","story.map3-dungeon1.012":"Was? <wait=40>Du willst nützlichere Ratschläge?","story.map3-dungeon1.013":"Es ist zu heiß... Ich bin schon am Ende!","story.map3-dungeon1.014":"<size=20>Ah! <wait=40>Ich halte es nicht mehr aus!","story.map3-dungeon1.015":"Ich gehe nach Hause und nehme ein Bad,<wait=20> lass dich bloß nicht umbringen, bis ich zurück bin!","story.map3-dungeon2.001":"<size=12>Brr...","story.map3-dungeon2.002":"Oh, <wait=20><rep_handlename>! <wait=40>Mensch, <wait=20>wo bleibst du denn!","story.map3-dungeon2.003":"Hä? <wait=40>Was mit mir los ist?","story.map3-dungeon2.004":"Gar nichts. <wait=40>Ich bin dieselbe energiegeladene Tilith wie immer!","story.map3-dungeon2.005":"Na ja, <wait=20>ich gebe zu, dass es hier ein bisschen kalt wird.","story.map3-dungeon2.006":"Aber nur, weil du mich so lange hast warten lassen, <rep_handlename>!","story.map3-dungeon2.007":"Davon abgesehen <wait=20>sollte ich dir wohl noch etwas mehr über den Heiligen Berg Craylia erzählen.","story.map3-dungeon2.008":"Dieser heilige Berg, der Craylia, ist der höchste Berg in St. Lamia.","story.map3-dungeon2.009":"Auf seinem Gipfel soll eine Quelle spiritueller Kraft liegen, die wohl diesen ewigen Schneesturm verursacht.","story.map3-dungeon2.010":"Obendrein <wait=40>soll dort auch der Meereskönig Leviathan hausen.","story.map3-dungeon2.011":"Warum er wohl das Meer verlassen hat, um ganz oben auf einem Berg zu leben...","story.map3-dungeon2.012":"Hmm<wait=20>...","story.map3-dungeon2.013":"<size=12><wait=20>Äh... <wait=20>Brr...","story.map3-dungeon2.014":"Was? <wait=40>Nein, wirklich, <wait=20>mir geht\'s bestens!","story.map3-dungeon2.015":"Aber anscheinend habe ich so lange an diesem eisigen Ort gestanden, dass ich mich erkältet habe...","story.map3-dungeon2.016":"Ich geh dann mal vor. <wait=40>Viel Glück beim Aufstieg auf diesen verschneiten Berg!","story.map3-dungeon3.001":"*Seufz* <wait=20>Hmpf... <wait=40>Nur noch ein bisschen...","story.map3-dungeon3.002":"Oh, <wait=20><rep_handlename>! <wait=40>Ich habe auf dich gewartet.","story.map3-dungeon3.003":"Um zu Maxwell zu gelangen, müssen wir hier durch, <wait=40>durch den Blutwald.","story.map3-dungeon3.004":"Blutwald, was für ein gruseliger Name...","story.map3-dungeon3.005":"Man munkelt, dass alle, die diesen Wald durchqueren wollen, irgendwann blutüberströmt aufgefunden werden...","story.map3-dungeon3.006":"<size=20><size=18>Das <size=20>ist <size=16>so, <size=19><size=17>so, <size=18>absolut, <size=15>total <size=17>gruselig<size=19>!","story.map3-dungeon3.007":"Was? <wait=40>Du findest, ich benehme mich komisch?","story.map3-dungeon3.008":"Ich benehme mich nicht komisch! <wait=40>Ich bin so anmutig wie immer, findest du nicht?","story.map3-dungeon3.009":"Du machst dir Sorgen... <wait=20>um mich?","story.map3-dungeon3.010":"Verstehe, <wait=20>aber wenn du Zeit hast, so einen Unsinn zu reden, dann mach dich lieber endlich auf und nimm es mit diesem Wald auf!","story.map3-dungeon3.011":"Viel Glück!!","story.map3-dungeon3.012":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon4.001":"*Hust* <wait=20>*Hust*... <wait=40>Ahh, <wait=20>ugh...","story.map3-dungeon4.002":"Oh, <wait=40><rep_handlename>... <wait=40>Du bist da...","story.map3-dungeon4.003":"Ich... <wait=40>kann es <wait=40>nicht länger vor dir verbergen...","story.map3-dungeon4.004":"Mein Zustand <wait=20>ist keine Krankheit. <wait=40>Ich bin nicht krank.","story.map3-dungeon4.005":"Maxwell... <wait=40>Sie hat mich verflucht.","story.map3-dungeon4.006":"Seit... <wait=20>wir St. Lamia betreten haben.","story.map3-dungeon4.007":"Jetzt, wo wir dem Palast von St. Lamia näher kommen, <wait=40>wird es immer schlimmer...","story.map3-dungeon4.008":"Maxwell hat mich wohl <wait=40>als lästig empfunden...","story.map3-dungeon4.009":"Hm? <wait=40>Dass es dich nicht trifft, liegt daran...","story.map3-dungeon4.010":"...dass ich... <wait=40>dich davor beschütze.","story.map3-dungeon4.011":"...<wait=40>Schon gut. <wait=40>Es macht mir nichts aus.","story.map3-dungeon4.012":"Danke, dass du dir Sorgen machst... <wait=40>aber ich komme klar.","story.map3-dungeon4.013":"Ich bin eine Göttin, <wait=40>deine Führerin...","story.map3-dungeon4.014":"Ich werde dich ganz bestimmt <wait=40>beschützen...","story.map3-dungeon4.015":"Bald... <wait=40>kriegen wir Maxwell.","story.map3-dungeon4.016":"<wait=20>Packen wir\'s an, <rep_handlename>!!","story.map3-dungeon4.017":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon5.001":"<speed=12>...Ugh. <wait=40>*Hust* <wait=20>*Keuch*... <wait=40>*Keuch*...","story.map3-dungeon5.002":"<speed=12><rep_handlename>... <wait=40>Es tut mir leid... <wait=40>Ich...","story.map3-dungeon5.003":"<speed=12>Ich kann... <wait=40>nicht mehr weiter<wait=40>...","story.map3-dungeon5.004":"<speed=12><rep_handlename>, <wait=40>ich...","story.map3-dungeon5.005":"<speed=12>Ich tue das nicht, weil Lord Lucius es mir befohlen hat...","story.map3-dungeon5.006":"<speed=12>Ich tue es, weil du <rep_handlename> bist... <wait=40>I-<wait=20>Ich wollte dich einfach beschützen.","story.map3-dungeon5.007":"<speed=12>Ich habe Lord Lucius darum gebeten, dass ich... <wait=40>*Hust* <wait=20>*Hust*","story.map3-dungeon5.008":"<speed=12>Es gibt noch so viele Orte, <wait=40>die ich mit dir besuchen wollte...","story.map3-dungeon5.009":"<speed=12>Ich wollte <wait=40>noch mehr reisen...","story.map3-dungeon5.010":"<speed=12>Aber... <wait=40>mir läuft wohl die Zeit davon...","story.map3-dungeon5.011":"<speed=12>Selbst wenn ich falle... <wait=40>wird meine Magie dich weiter beschützen.","story.map3-dungeon5.012":"<speed=12>Versprich es mir<wait=20>.<wait=20>.<wait=40>.","story.map3-dungeon5.013":"<speed=10>...dass du <wait=40>Maxwell <wait=40>ganz bestimmt <wait=12>be<wait=10>sie<wait=7>gen <wait=5>wirst...","story.map3-dungeon5.014":"<speed=10>Ugh...","story.map3-dungeon5.015":"<size=24>(Wird ohnmächtig)","story.map3-dungeon5.016":"...<wait=40>...<wait=40>...","story.map3-dungeon5.017":"Hey! <wait=40>Bist du das wirklich, <rep_handlename>!?","story.map3-dungeon5.018":"Du musst ganz schön zäh sein, <wait=40>wenn du es allein bis hierher geschafft hast...","story.map3-dungeon5.019":"Und, wie lief\'s mit Abaddon??<wait=40>","story.map3-dungeon5.020":"<size=18>Hey, <wait=20>was ist mit dem Mädchen los?! <wait=40>Die ist ja ganz blau angelaufen!!","story.map3-dungeon5.021":"<rep_handlename>... <wait=40>Sag bloß<wait=20>...","story.map3-dungeon5.022":"Sag bloß, du kannst immer noch keine Gegengifte herstellen?!","story.map3-dungeon5.023":"Schon gut, schon gut. <wait=40>War nur ein Scherz.","story.map3-dungeon5.024":"...Ein Fluch? <wait=40>Wie meinst du das?","story.map3-dungeon5.025":"Ach komm, wovon redest du!?","story.map3-dungeon5.026":"...<wait=60>...<wait=60>...<wait=60>!","story.map3-dungeon5.027":"Moment... <wait=40>willst du damit sagen, <wait=20>dieses Mädchen ist eine Göttin?","story.map3-dungeon5.028":"Du willst mich...<wait=40> doch nicht <wait=20>auf den Arm nehmen, <wait=40>oder?","story.map3-dungeon5.029":"Und?","story.map3-dungeon5.030":"...<wait=60>...<wait=60>...","story.map3-dungeon5.031":"Also... <wait=40>war es Maxwell, was...","story.map3-dungeon5.032":"Ich würde ja gern helfen, <wait=40>aber das übersteigt meine Fähigkeiten...","story.map3-dungeon5.033":"Das ist nichts, was wir mit selbst gebrauten Tränken heilen können...","story.map3-dungeon5.034":"Aber Moment mal, <wait=40>diesen Fluch hat Maxwell gewirkt, oder?","story.map3-dungeon5.035":"Dann sollte der Fluch doch verschwinden, wenn wir Maxwell besiegen, meinst du nicht?","story.map3-dungeon5.036":"Und wenn es nicht reicht, Maxwell zu besiegen, kannst du sie immer noch verprügeln, bis sie mit der Lösung rausrückt!","story.map3-dungeon5.037":"Etwas anderes fällt mir gerade nicht ein.","story.map3-dungeon5.038":"...<wait=20>Na klar. <wait=40>Ich kümmere mich um sie.","story.map3-dungeon5.039":"Mein Team hat in der Nähe ein Lager aufgeschlagen, ich bringe sie dorthin.","story.map3-dungeon5.040":"Du solltest dich beeilen.","story.map3-dungeon5.041":"<size=22>Steh nicht rum und starr Löcher in die Luft!!","story.map3-dungeon5.042":"Sie leidet deinetwegen!","story.map3-dungeon5.043":"Das ist keine Zeit zum Herumtrödeln, du solltest zum Palast von St. Lamia stürmen!","story.map3-dungeon5.044":"<size=14>...<wait=20>Was für ein Trottel.","story.map3-dungeon7.001":"<size=20><rep_handlename>! <wait=40>Schön, dich lebend zu sehen!!","story.map3-dungeon7.002":"Warum ich hier bin? <wait=40>Na, um dir zu helfen!","story.map3-dungeon7.003":"<size=20>Verflucht!","story.map3-dungeon7.004":"<size=24>*Zack*","story.map3-dungeon7.005":"<size=24>*Zack*","story.map3-dungeon7.006":"...Verdammt noch mal, <wait=40>das ist ja eine ganz schöne Horde, was?","story.map3-dungeon7.007":"Seria hat mir alles erzählt.","story.map3-dungeon7.008":"Lass mich das hier erledigen.","story.map3-dungeon7.009":"Dir läuft die Zeit davon, oder? <wait=40>Beeil dich!","story.map3-dungeon7.010":"<size=20>Ugh!","story.map3-dungeon7.011":"<size=24>*Zack*","story.map3-dungeon7.012":"<size=20>Verschwinde von hier!!","story.map3-dungeon7.013":"<rep_handlename>... <wait=40>wir zählen auf dich...","story.map3-ending.001":"<size=20><rep_handlename>!!","story.map3-ending.002":"*Keuch*... <wait=40>hmpf...","story.map3-ending.003":"Meine Güte, <wait=40>der Beschwörer hat es geschafft...","story.map3-ending.004":"Maxwell, einer der Vier Gefallenen Götter, ist besiegt!!","story.map3-ending.005":"Puh... <wait=40>Aber das war verdammt knapp...","story.map3-ending.006":"<size=20><rep_handlename>, gut gemacht!!","story.map3-ending.007":"Wie es aussieht, hat Maxwells Niederlage tatsächlich den Fluch aufgehoben.","story.map3-ending.008":"Allerdings, <wait=40>schön zu sehen, dass diese feine junge Göttin wieder auf den Beinen ist...","story.map3-ending.009":"Sag mal, <wait=20>wie bist du eigentlich vor mir hier angekommen?!","story.map3-ending.010":"...<wait=20>Sie muss wirklich eine Göttin sein. <wait=40>Wahrscheinlich sind ihre Kräfte zurückgekehrt, als der Fluch aufgehoben wurde.","story.map3-ending.011":"Kaum zu glauben, dass <rep_handlename> die ganze Zeit eine Göttin an der Seite hatte<wait=40>...","story.map3-ending.012":"Und Seria, du überraschst mich sogar. Du hast dich für die beiden ja richtig ins Zeug gelegt, was?","story.map3-ending.013":"Ich, <wait=30>ich habe das nicht für <rep_handlename> getan.","story.map3-ending.014":"Ich habe getan, was ich getan habe, für die Göttin und für die Welt.","story.map3-ending.015":"Schon gut, schon gut... <wait=40>Hör schon auf.","story.map3-ending.016":"<size=18>Du hast Maxwell besiegt! Das ist mein <rep_handlename>!!","story.map3-ending.017":"...<wait=40>Na, <wait=20>meinetwegen.","story.map3-ending.018":"Jedenfalls, <wait=40>dass ein Neuling sich so schnell verbessert...","story.map3-ending.019":"Also, <wait=40>das ist schon was.","story.map3-ending.020":"<rep_handlename>! <wait=40>Ich erkenne an, dass du ein vollwertiger...","story.map3-ending.021":"<rep_handlename> hat es geschafft!! <wait=40><rep_handlename> hat gewonnen!!","story.map3-ending.022":"Abaddon und sogar Maxwell, sie sind alle besiegt!!","story.map3-ending.023":"Als wir uns kennengelernt haben, war ich ein bisschen besorgt...","story.map3-ending.024":"...aber jetzt <wait=20>gibt es keinen Zweifel: Du bist der stärkste Beschwörer weit und breit!!","story.map3-ending.025":"<size=18>E-<wait=20>Entschuldige mal! <wait=40>Du nervst gewaltig, beruhig dich endlich!","story.map3-ending.026":"Kannst du mir nicht verübeln. <wait=40>Mein Beschwörer hat einen der Vier Gefallenen Götter besiegt!","story.map3-ending.027":"Ich war noch nie so glücklich!","story.map3-ending.028":"Ach, sei still! <wait=40>Hör auf, dazwischenzureden, wenn jemand spricht!!","story.map3-ending.029":"Und was soll dieses kitschige <wait=40>„mein <rep_handlename>“-Getue!?","story.map3-ending.030":"Ihr seid doch nicht etwa ein Paar, oder?!","story.map3-ending.031":"Mein <rep_handlename> ist mein <rep_handlename>!","story.map3-ending.032":"Ich habe mein Leben riskiert, um <rep_handlename> am Leben zu halten.","story.map3-ending.033":"Und außerdem <wait=20>hat <rep_handlename> so hart gekämpft, um mich zu retten...","story.map3-ending.034":"<rep_handlename> und ich sind durch das Schicksal verbunden!","story.map3-ending.035":"Na, was ist? <wait=40>Bist du etwa eifersüchtig?","story.map3-ending.036":"<size=20>W-Wer-Wer wäre denn auf so eine Göre eifersüchtig!?","story.map3-ending.037":"<size=18>Und was soll das heißen, Schicksal? <wait=40><size=24>Bist du blöd!?","story.map3-ending.038":"...Hey, <wait=20>beruhigt euch, ihr zwei...","story.map3-ending.039":"Nur ein Narr nimmt für jemanden wie <rep_handlename> einen Fluch auf sich. <wait=20>Wie dumm!","story.map3-ending.040":"<rep_handlename> wäre auch klargekommen, wenn du ihn einfach in Ruhe gelassen hättest!!","story.map3-ending.041":"Außerdem, <wait=20>solltest du nicht eine Göttin sein?!","story.map3-ending.042":"Hättest du den Fluch nicht einfach selbst brechen können?!","story.map3-ending.043":"Was soll das denn heißen!? <wait=40>Willst du behaupten, ich hätte mir keine Mühe gegeben!?","story.map3-ending.044":"Du warst im Abgeschiedenen Heiligtum dem Tod nahe!","story.map3-ending.045":"Wäre ich nicht da gewesen, hätten dich diese Monster verschlungen!!","story.map3-ending.046":"So ein Unsinn! <wait=40><rep_handlename> hätte mich auch ohne dich beschützt!","story.map3-ending.047":"Du redest nur, getan hast du auch nichts!","story.map3-ending.048":"M-<wait=10>Moment mal!! <wait=40>Wer hat dich denn bitte gepflegt?!","story.map3-ending.049":"Ich war bewusstlos, ich kann mich an nichts erinnern...","story.map3-ending.050":"Na warte, du kleine...!!","story.map3-ending.051":"Hey, ihr zwei... <wait=40>Hört doch endlich auf.","story.map3-ending.052":"<size=24>Klappe!!","story.map3-ending.053":"Hui...","story.map3-ending.054":"Überhaupt, warum kommandiert Seria <rep_handlename> ständig so herum!?","story.map3-ending.055":"Sie konnte nicht mal Graham besiegen, von Abaddon ganz zu schweigen!","story.map3-ending.056":"<size=12>Autsch... <wait=40>Ich war an dem Kampf auch beteiligt, weißt du...","story.map3-ending.057":"Hör auf, dich über meinen <rep_handlename> lustig zu machen!!","story.map3-ending.058":"I-<wait=20>Ich sage, was ich will! <wait=40>Willst du etwa Streit!?","story.map3-ending.059":"Du hast angefangen!","story.map3-ending.060":"Und weißt du was, ohne Fluch bin ich ziemlich mächtig!","story.map3-ending.061":"<size=24>Herrgott noch mal! <wait=40>Jetzt reicht\'s!!","story.map3-ending.062":"<rep_handlename> hat Maxwell besiegt!","story.map3-ending.063":"Das ist nicht der Moment zum Streiten.","story.map3-ending.064":"...Hmpf.","story.map3-ending.065":"Hmpf.","story.map3-ending.066":"Ihr Mädels <wait=20>benehmt euch beide schlimmer als Maxwell selbst...","story.map3-ending.067":"Aber egal, <wait=20>Hut ab vor dir, <wait=20><rep_handlename>.","story.map3-ending.068":"Ich bin stolz, dein Freund zu sein.","story.map3-ending.069":"...<wait=40>Ich sag\'s nicht gern, <wait=40>aber ich kann nicht leugnen, dass du Maxwell tatsächlich besiegt hast.","story.map3-ending.070":"<wait=40>Gute Arbeit.","story.map3-ending.071":"Puh.","story.map3-ending.072":"Also gut, <wait=20>Seria und ich müssen jetzt los.","story.map3-ending.073":"...Hm? <wait=40>Du musst mir nicht danken.","story.map3-ending.074":"Versprich einfach, dass du uns hilfst, wenn wir das nächste Mal in Not sind!","story.map3-ending.075":"Wir sehen uns, mein Freund.","story.map3-ending.076":"Hmpf, <wait=20>leb wohl.","story.map3-ending.077":"...Also, <wait=40>lass es mich noch einmal sagen.","story.map3-ending.078":"Herzlichen Glückwunsch! <wait=40><rep_handlename>.","story.map3-ending.079":"Ich habe fest daran geglaubt, dass du Maxwell besiegen würdest.","story.map3-ending.080":"Aber statt dir zu helfen... <wait=40>hast am Ende du mir geholfen.","story.map3-ending.081":"Ich bin wirklich glücklich. <wait=40>Danke.","story.map3-ending.082":"Hehe. <wait=40>Mensch, ist das peinlich.","story.map3-ending.083":"Ach, <wait=20>richtig. Wir haben uns doch versprochen, zusammen viele Orte zu besuchen, oder?","story.map3-ending.084":"Ich dachte, ich würde sterben, <wait=40>deshalb habe ich dir dieses Versprechen abgenommen.","story.map3-ending.085":"Aber jetzt, wo du Maxwell besiegt hast, wird es wohl noch hektischer werden.","story.map3-ending.086":"Maxwell ist zwar besiegt, <wait=40>aber es gibt insgesamt Vier Gefallene Götter.","story.map3-ending.087":"Drei von ihnen sind noch da draußen.","story.map3-ending.088":"Bis du nicht alle Gefallenen Götter besiegt hast, <wait=40>wird in Grand Gaia kein Frieden einkehren.","story.map3-ending.089":"Deshalb <wait=40>müssen wir das Abenteuer, das wir uns versprochen haben, leider verschieben.","story.map3-ending.090":"Tut mir wirklich leid, <wait=40>aber Göttinnen haben eben viel zu tun.","story.map3-ending.091":"Na ja, <wait=40>es wird Zeit, dass ich Lord Lucius Bericht erstatte.","story.map3-ending.092":"Trainier weiter fleißig, <wait=20>du musst noch stärker werden, wenn du die restlichen Gefallenen Götter besiegen willst.","story.map3-ending.093":"Ach, <wait=40>und noch etwas...","story.map3-ending.094":"Wenn du die beiden wiedersiehst, richte ihnen meinen Dank aus.","story.map3-ending.095":"Sag ihnen, dass ich ihnen für alles, was sie für uns getan haben, wirklich dankbar bin.","story.map3-ending.096":"Also dann, <wait=20>ich mache mich auf den Weg!","story.map3-ending.097":"Wir sehen uns bald wieder, <wait=20>da bin ich mir sicher!","story.map3-ending.098":"Tschüss!!!","story.map4-dungeon1.001":"Pff... Seit ich hier bin, ist mir noch<br>kein einziges Monster begegnet!","story.map4-dungeon1.002":"Nicht zu fassen... <wait=40> Warum muss ausgerechnet ich, der mächtige Lugina, solche öden Aufgaben erledigen...","story.map4-dungeon1.003":"Hm?<wait=40><br>He, du da! <wait=20>Wer bist du?!","story.map4-dungeon1.004":"Aha! <wait=20>Ein Mitglied der Akras-Armee, was?<br>Wie heißt du?","story.map4-dungeon1.005":"<rep_handlename>?<wait=40><br>Pff... <wait=40>Ziemlich komischer Name, wenn du mich fragst.","story.map4-dungeon1.006":"Was ist?<wait=40><br>Du willst wissen, wie ich heiße?","story.map4-dungeon1.007":"Nicht dass ich irgendeinen Grund hätte, mich<br>einem Mitglied der regulären Armee vorzustellen, aber...","story.map4-dungeon1.008":"<wait=20>...Na gut, wenn du es unbedingt wissen willst, kann es ja nicht schaden.","story.map4-dungeon1.009":"Ich bin der mächtige Beschwörer Lugina,<wait=40><br>verehrter Anführer der 23. Dämonenjäger-Division,<wait=40>","story.map4-dungeon1.010":"auch bekannt als Sky Garden!<br>Merk dir das gefälligst!","story.map4-dungeon1.011":"Also,<wait=40> suchst du hier irgendwas oder was?","story.map4-dungeon1.012":"Hä?<wait=40> Du sollst die Vier Gefallenen Götter besiegen?","story.map4-dungeon1.013":"Pff... Hehe... <size=24>Bwahaha!","story.map4-dungeon1.014":"Die alten Knacker in Akras haben also<br>wirklich nicht mehr alle Tassen im Schrank!","story.map4-dungeon1.015":"Du glaubst doch nicht ernsthaft, dass die reguläre Armee<br>eine Chance gegen die Vier Gefallenen Götter hat, oder?","story.map4-dungeon1.016":"Es wird Zeit, dass die alten Knacker in Rente gehen<br>und das Dämonenjagen Profis wie mir überlassen.","story.map4-dungeon1.017":"Hm? <wait=40>Du bekommst deine Befehle von einer Göttin, sagst du?<br>Nicht von der Beschwörerhalle?","story.map4-dungeon1.018":"...Soll das ein Witz sein?<wait=40><br>Oder bist du wirklich so dumm?","story.map4-dungeon1.019":"Weißt du überhaupt, was ich<br>hier draußen mache?","story.map4-dungeon1.020":"Unglaublich... <wait=40>Genau deshalb sage ich immer:","story.map4-dungeon1.021":"Einem Mitglied der regulären Armee kann man nicht trauen.","story.map4-dungeon1.022":"Weißt du überhaupt, dass dieses Gebiet, in dem wir stehen,<br>erst kürzlich von der Akras-Beschwörerhalle entdeckt wurde?","story.map4-dungeon1.023":"Es ist noch nicht richtig erkundet,<br>also pass lieber auf, wo du hintrittst.","story.map4-dungeon1.024":"Du weißt schon, Monster und so Zeug.","story.map4-dungeon1.025":"Jedenfalls ist es Aufgabe mächtiger<br>Beschwörer wie meiner Wenigkeit,","story.map4-dungeon1.026":"dafür zu sorgen, dass gefährliche<br>Gegenden wie diese sicher genug werden,","story.map4-dungeon1.027":"damit Anfänger-Beschwörer<br>wie du überhaupt einen Fuß hineinsetzen können.","story.map4-dungeon1.028":"Wenn du schlau bist,<br>suchst du dir einen sichereren Ort, bis ich hier fertig bin!","story.map4-dungeon1.029":"In Grand Gaia gibt es noch jede Menge Gegenden,<br>die nicht richtig erkundet sind.","story.map4-dungeon1.030":"Was? Hab ich gestottert oder so?<wait=40><br>Mann, du bist genauso dumm, wie du aussiehst.","story.map4-dungeon1.031":"Hier, ich sag\'s noch deutlicher...<br><wait=40>Geh mir aus dem Weg und lass mich in Ruhe arbeiten!<wait=40>","story.map4-dungeon1.032":"Hör auf, deine Zeit mit diesen kleinen Fischen zu verschwenden, und such woanders!","story.map4-dungeon1.033":"Tss... Bei solchen Trotteln in der regulären Armee ist es kein Wunder, dass die Beschwörerhalle in Schwierigkeiten steckt...","story.map4-dungeon2.001":"Du schon wieder?!<wait=40><br>Ich hab dir doch gesagt, du sollst verschwinden!","story.map4-dungeon2.002":"Du hast ja Nerven,<br>mich einfach so zu ignorieren!","story.map4-dungeon2.003":"Oder brauchst du jemanden, der dich<br>an die Hand nimmt und nach Hause bringt?","story.map4-dungeon2.004":"Mann... <wait=40>Nicht mal die kaiserliche Armee ist so unfähig.","story.map4-dungeon2.005":"Hä?<wait=40><br>Was soll denn der ahnungslose Blick?","story.map4-dungeon2.006":"Moment mal... <wait=40>Sag bloß, du hast <br>noch nie von der kaiserlichen Armee von Randall gehört?","story.map4-dungeon2.007":"Wow. Einfach nur wow...","story.map4-dungeon2.008":"Ehrlich, du tust mir<br>fast schon leid.","story.map4-dungeon2.009":"Dann bleibt mir wohl nichts anderes übrig.","story.map4-dungeon2.010":"Ich, Lugina, rein und tugendhaft von Herzen, werde dir alles beibringen, was du wissen musst!","story.map4-dungeon2.011":"Wisch dir die Tränen der Dankbarkeit ab<br>und merk dir, was ich dir jetzt erzähle!","story.map4-dungeon2.012":"Fangen wir einfach an. <wait=40>Du weißt ja, dass unser Land Elgaia von Grand Gaia getrennt wurde.","story.map4-dungeon2.013":"Du weißt schon, das Land der Götter,<br>oder?","story.map4-dungeon2.014":"Na also,<wait=40> wenigstens weißt du überhaupt was!","story.map4-dungeon2.015":"Ich weiß nicht, worauf du so stolz bist!<wait=40> Das ist Allgemeinwissen, wie es allgemeiner nicht geht.","story.map4-dungeon2.016":"Mann...","story.map4-dungeon2.017":"OK, weiter im Text. <wait=40>Elgaia besteht aus zwei großen Ländern.","story.map4-dungeon2.018":"Eins davon, das Randall-Imperium, ist die Heimat der Akras-Beschwörerhalle.","story.map4-dungeon2.019":"Die Akras-Beschwörerhalle kümmert sich um die Wirtschafts-","story.map4-dungeon2.020":"und Militärangelegenheiten des Landes, das ganze Imperium ist also eigentlich nur Fassade.","story.map4-dungeon2.021":"Randalls Oberschicht stammt von denen ab,<br>die das Land wieder aufgebaut haben, nachdem es","story.map4-dungeon2.022":"von Grand Gaia getrennt wurde. Das erklärt wohl auch, warum sie sich so aufspielen.","story.map4-dungeon2.023":"Heutzutage sind sie nur noch ein Haufen alter Knacker, die ihr verwöhntes Leben genießen.","story.map4-dungeon2.024":"Ihre Armee ist natürlich größtenteils Fassade, eine Machtdemonstration, wenn du so willst.","story.map4-dungeon2.025":"Obwohl ab und zu wohl auch mal ein, zwei talentierte Soldaten durch ihre Reihen gegangen sind.","story.map4-dungeon2.026":"Jedenfalls, <wait=40>das andere Land ist die Elgaia-Föderation,","story.map4-dungeon2.027":"aber bei denen sieht\'s ziemlich ähnlich aus.","story.map4-dungeon2.028":"Keins der beiden Länder hat das Zeug dazu, sich gegen die Akras-Beschwörerhalle zu stellen,","story.map4-dungeon2.029":"also herrscht die Halle praktisch<br>über ganz Elgaia.","story.map4-dungeon2.030":"Und da ich der mächtigste Beschwörer<br>der Akras-Beschwörerhalle bin,","story.map4-dungeon2.031":"bin ich auch der mächtigste in ganz Elgaia!","story.map4-dungeon2.032":"Na?<wait=40><br>Du willst bestimmt ein Autogramm, was?","story.map4-dungeon2.033":"<size=14>(Grollen, grollen)","story.map4-dungeon2.034":"W-<wait=20>Wah!","story.map4-dungeon2.035":"W-<wait=20>War das ein Erdbeben?!","story.map4-dungeon2.036":"Aber das fühlte sich nicht wie ein gewöhnliches<br>Erdbeben an...","story.map4-dungeon2.037":"Verstehst du jetzt, was ich meine?!","story.map4-dungeon2.038":"Cordelica ist nicht sicher, bis wir herausfinden, was hier los ist.","story.map4-dungeon2.039":"Also hör auf meine weisen Worte und verschwinde, solange du noch kannst!","story.map4-dungeon2.040":"Wenn wir uns noch mal über den Weg laufen, wirst du es bereuen!","story.map4-dungeon3.001":"<size=20>Du schon wieder?!<wait=40> <rep_handlename>!","story.map4-dungeon3.002":"Warum bist du immer noch hier!?","story.map4-dungeon3.003":"So, jetzt reicht\'s!","story.map4-dungeon3.004":"Wenn du nicht auf meinen Rat hörst,<wait=40> muss ich dir eben Vernunft einprügeln!","story.map4-dungeon3.005":"Halt still!","story.map4-dungeon3.006":"<size=14>(Grollen, grollen)","story.map4-dungeon3.007":"N-Nicht schon wieder!<wait=40><br>Was ist bloß mit diesen ganzen Erdbeben los?","story.map4-dungeon3.008":"He!<wait=40> <rep_handlename>!","story.map4-dungeon3.009":"Verstehst du jetzt, wovon<br>ich rede?","story.map4-dungeon3.010":"Das hier ist kein Ort, an dem sich ein Anfänger-Beschwörer wie du herumtreiben sollte.","story.map4-dungeon3.011":"Geh nach Hause und pass auf,<br>dass nicht bloß die kaiserliche Armee etwas im Schilde führt!","story.map4-dungeon3.012":"...<wait=20>Was soll der Blick?","story.map4-dungeon3.013":"Ich hab das Gefühl, du hast immer noch nicht kapiert, wie großartig ich bin...","story.map4-dungeon3.014":"Also gut, hör zu.<wait=40><br>Ich hab\'s dir ja vorhin schon gesagt,","story.map4-dungeon3.015":"aber hier in Elgaia gibt es mehrere Fraktionen,<br>jede mit ihrem eigenen Militär.","story.map4-dungeon3.016":"Das stärkste davon gehört der Akras-Beschwörerhalle.","story.map4-dungeon3.017":"Logisch, oder?<br>Immerhin stellen die fast alle","story.map4-dungeon3.018":"Beschwörer in Elgaia...","story.map4-dungeon3.019":"Jedenfalls besteht das Akras-Militär<br>aus drei verschiedenen Streitkräften.","story.map4-dungeon3.020":"Als Erstes <wait=40>hast du die Beschwörerarmee, auch reguläre Armee genannt, in der jeder Anfänger-Beschwörer","story.map4-dungeon3.021":"anfängt. Das ist übrigens deine Einheit.","story.map4-dungeon3.022":"Euer offizieller Auftrag ist es, die Vier Gefallenen Götter zu besiegen, aber... na ja, wie soll ich sagen?","story.map4-dungeon3.023":"Ehrlich gesagt erwartet niemand, dass<br>die reguläre Armee irgendwas zustande bringt.","story.map4-dungeon3.024":"Und von wem erwartet man es dann, fragst du?<br>Na, von meinen Leuten, den Dämonenjägern!","story.map4-dungeon3.025":"Wir sind eine Spitzentruppe aus Elite-Beschwörern,<br>handverlesen aus den Reihen der regulären Armee.","story.map4-dungeon3.026":"Die Stärksten davon, ich zum Beispiel, bekommen dann das Kommando über kleinere Trupps.","story.map4-dungeon3.027":"Und der stärkste davon ist natürlich der, den ich anführe:","story.map4-dungeon3.028":"Die 23. Dämonenjäger-Division Sky Garden!","story.map4-dungeon3.029":"Und du dachtest schon, ich könnte<br>mich nicht mehr übertreffen, was?","story.map4-dungeon3.030":"Hm? <wait=40>Was ist mit den Armeen von Randall<br>und der Elgaia-Föderation, sagst du?","story.map4-dungeon3.031":"Ha! Die haben zusammen kaum eine Handvoll Beschwörer. Die sind noch nutzloser als unsere reguläre Armee.","story.map4-dungeon3.032":"Jetzt hör auf, mich mit Fragen zu löchern, und lauf nach Hause, wo du hingehörst!","story.map4-dungeon3.033":"Die Monster hier sind keine<br>Weicheier wie die, mit denen du es sonst zu tun hast!","story.map4-dungeon3.034":"Hast du gehört? Verschwinde!","story.map4-dungeon3.035":"*Seufz* <wait=40>Womit hab ich verdient,<br>bis hierher abkommandiert zu werden?","story.map4-dungeon3.036":"Sie haben also den Dämonenjäger Lugina vom Sky Garden geschickt...","story.map4-dungeon3.037":"Heh. Wahrscheinlich wollten sie nur,<br>dass er sie eine Weile in Ruhe lässt...","story.map4-dungeon3.038":"Trotzdem scheint er sich leicht genug für meine Zwecke einspannen zu lassen.","story.map4-dungeon3.039":"Jetzt fehlt nur noch ein Plan...","story.map4-dungeon4.001":"<size=20>Du schon wieder?! <rep_handlename>!","story.map4-dungeon4.002":"Jetzt reicht\'s! Schluss mit nett!","story.map4-dungeon4.003":"Ich hoffe, dir gefällt die Stelle, an der du stehst, denn genau da werde ich dich begraben, wenn ich fertig bin!","story.map4-dungeon4.004":"<size=18>(Grollen, grollen)","story.map4-dungeon4.005":"Schon wieder eins...?<br>Diese Erdbeben sind definitiv nicht normal.","story.map4-dungeon4.006":"Diese alten Narren von der Beschwörerhalle...<br>Zum Teufel mit allen!","story.map4-dungeon4.007":"Hör zu, <rep_handlename>!","story.map4-dungeon4.008":"Hier ist es zu gefährlich,<br>als dass wir uns hier herumtreiben könnten.","story.map4-dungeon4.009":"Ich schreibe meinen Bericht und kehre<br>sofort nach Elgaia zurück. <wait=40>Du bist mein Zeuge, klar?","story.map4-dungeon4.010":"Denk an all das, was ich dir beigebracht habe!<br>Du lässt doch einen alten Kumpel nicht hängen, oder?","story.map4-dungeon4.011":"Ziemlich feige Worte für einen selbsternannten Dämonenjäger-Anführer, findest du nicht?","story.map4-dungeon4.012":"...?!<br><wait=40>Wer bist du denn?","story.map4-dungeon4.013":"D-Dieses Wappen...","story.map4-dungeon4.014":"Das kann nicht sein!<br>Ein Mitglied der Kaiserlichen Garde?!","story.map4-dungeon4.015":"Ganz recht.<br>Vielleicht taugst du ja doch zum Lehrer.","story.map4-dungeon4.016":"Mein Name ist Paris. Ich gehöre zu einer<br>der „nutzlosen“ Truppen, die du eben beschrieben hast.","story.map4-dungeon4.017":"Du hast die ganze Zeit gelauscht?<br>Hat dir nie jemand Manieren beigebracht?","story.map4-dungeon4.018":"Dasselbe könnte ich dich fragen.","story.map4-dungeon4.019":"Oder hältst du es etwa für ehrenhaft, die Befehle<br>deines Landes zu missachten, ganz zu schweigen davon,","story.map4-dungeon4.020":"die kaiserliche Armee herabzusetzen,<br>die sich für das Wohl unseres Reiches abmüht?","story.map4-dungeon4.021":"Pff...<br><wait=40>Oh, das tut mir ja sooo leid! Bitte verzeih mir!","story.map4-dungeon4.022":"Wie erwartet: Ihr von der Beschwörerhalle<br>seid einer ungehobelter als der andere...","story.map4-dungeon4.023":"Erzähl das jemandem, den\'s interessiert,<br>Lady!","story.map4-dungeon4.024":"Außerdem beschützt ihr Trottel von der Kaiserlichen<br>Garde doch die Kaiserfamilie, oder?","story.map4-dungeon4.025":"Was machst du dann hier draußen?","story.map4-dungeon4.026":"Ich hab nicht den ganzen Tag Zeit,<br>also rück endlich mit der Sprache raus!","story.map4-dungeon4.027":"Heh...<br>Ganz schön temperamentvoll für einen Handlanger.","story.map4-dungeon4.028":"Wen nennst du hier Handlanger?!","story.map4-dungeon4.029":"Du glaubst, ich und dieser Trottel hier wären Partner? Ha!","story.map4-dungeon4.030":"Egal, Lady.<br>Ich hab Besseres mit meiner Zeit","story.map4-dungeon4.031":"zu tun, als mich hier in der Pampa<br>mit der Kaiserlichen Garde anzulegen.","story.map4-dungeon4.032":"Ah, die berühmte Diplomatie der Dämonenjäger.<br>Wenigstens wissen wir alle, woran wir sind.","story.map4-dungeon4.033":"Nun, ehrlich gesagt bin ich den ganzen Weg gekommen, um dich um einen Gefallen zu bitten.","story.map4-dungeon4.034":"Wir möchten dich um Hilfe<br>bei der Erkundung von Cordelica bitten.","story.map4-dungeon4.035":"Ha!<wait=40><br>Hast du gerade gesagt, was ich glaube?","story.map4-dungeon4.036":"Ich suche keinen Streit, <wait=40>aber ich werde auch nicht nach deiner Pfeife tanzen!","story.map4-dungeon4.037":"Falls du es noch nicht gemerkt hast:<br>Hier ist es nicht sicher für uns.","story.map4-dungeon4.038":"Wie ich sehe, ist dir die Gefahr<br>dieser Region bewusst.","story.map4-dungeon4.039":"Natürlich würde ich nichts anderes<br>von einem selbsternannten Dämonenjäger-Anführer erwarten.","story.map4-dungeon4.040":"Was willst du damit andeuten, hä?","story.map4-dungeon4.041":"Andeuten?<wait=40> Nein, ich stelle nur Tatsachen fest.","story.map4-dungeon4.042":"Jemand, der Angst vor ein paar<br>harmlosen Erdbeben hat, könnte doch","story.map4-dungeon4.043":"unmöglich eine so talentierte Truppe anführen, wie du behauptest.","story.map4-dungeon4.044":"Du...!<wait=40><br>Pass auf, was du sagst!","story.map4-dungeon4.045":"Du nennst mich einen Feigling?!","story.map4-dungeon4.046":"Dass ich nicht lache!<wait=40><br>Ich zeig dir, was Angst bedeutet!","story.map4-dungeon4.047":"He!<wait=40> <rep_handlename>!","story.map4-dungeon4.048":"Zeit, dass du hier auch mal was leistest!","story.map4-dungeon4.049":"Bisher hast du alles ignoriert,<br>was ich dir gesagt habe.","story.map4-dungeon4.050":"Du hältst dich wohl für ganz toll, was?","story.map4-dungeon4.051":"Wenn du so ein Ass bist, dann beweis es doch und erledige den Knirps, der sich in der Festung da drüben versteckt!","story.map4-dungeon4.052":"Die Monster, auf die wir treffen,<br>werden ab hier immer stärker,","story.map4-dungeon4.053":"aber selbst du solltest mit denen<br>da drüben keine Probleme haben.","story.map4-dungeon4.054":"Hehe... <wait=40>Das könnte interessant werden.","story.map4-dungeon4.055":"...Na?! Steh nicht so rum und glotz!<wait=40><br>Geh raus und zeig\'s ihnen!","story.map4-dungeon4.056":"Du hast den Mann gehört,<br><rep_handlename>... Hehe.","story.map4-dungeon5.001":"Hmpf! <wait=40>Du hast dir ja ganz<br>schön Zeit gelassen.","story.map4-dungeon5.002":"Und da wundern sich die Leute, warum ich<br>keinen Respekt vor euch von der regulären Armee habe.","story.map4-dungeon5.003":"Aber immerhin warst du vor dieser selbstgerechten Kaiserlichen Garde hier, das ist ja schon mal was.","story.map4-dungeon5.004":"Und wer soll das bitte sein?","story.map4-dungeon5.005":"Wa-? <wait=20>Du?!<wait=40><br>Wie lange stehst du schon da!","story.map4-dungeon5.006":"Seit kurz bevor du ankamst und<br>anfingst, dich zum Narren zu machen.","story.map4-dungeon5.007":"Du...! <wait=40>Du hast mich<br>die ganze Zeit beobachtet!","story.map4-dungeon5.008":"Ach, beruhig dich doch.","story.map4-dungeon5.009":"Ich habe Wichtigeres zu tun,<br>als jede deiner kleinen Bewegungen zu analysieren.","story.map4-dungeon5.010":"Argh, lasst mich an sie ran!","story.map4-dungeon5.011":"Darum hasse ich euch von der Kaiserlichen Garde,<br>ihr seid immer so verdammt selbstgefällig!","story.map4-dungeon5.012":"Deinen Groll kannst du später loswerden.<wait=40><br>Sag mir erst, was du hier machst.","story.map4-dungeon5.013":"Hä?<wait=40> <br>Soll das ein Witz sein?","story.map4-dungeon5.014":"Ich erkunde natürlich die Ruinen.","story.map4-dungeon5.015":"Sieh sie dir an! Die müssen schon<br>vor dem Großen Zusammenbruch hier gewesen sein.","story.map4-dungeon5.016":"Hast du je einen Ort gesehen, der<br>so laut danach schreit, erforscht zu werden?","story.map4-dungeon5.017":"Jedenfalls bin ich hergekommen, um sie mir<br>anzusehen, und der hier ist mir hinterhergelaufen.","story.map4-dungeon5.018":"Verstehe...<wait=40><br>Du kannst also alte Schriften lesen?","story.map4-dungeon5.019":"Ich dachte eigentlich, ich<br>sollte hier die Erkundung übernehmen...","story.map4-dungeon5.020":"Was soll das heißen? Du traust mir das wohl nicht zu, was!?","story.map4-dungeon5.021":"Du bist wohl die Einzige, die zu<br>irgendwas Geistigem fähig ist, ja?","story.map4-dungeon5.022":"Nein, <wait=40>ich bin ehrlich gesagt ziemlich beeindruckt.","story.map4-dungeon5.023":"Vielleicht bist du doch nicht so dumm,<br>wie dein grobes Äußeres vermuten lässt.","story.map4-dungeon5.024":"...<wait=40>Ich warne dich,<br>Lady.","story.map4-dungeon5.025":"Glaub nicht, dass ich mir das ewig gefallen lasse.","story.map4-dungeon5.026":"Und glaub mir, wenn ich wütend werde,<br>zerschlage ich alles zu Staub!","story.map4-dungeon5.027":"Kaiserliche Garde hin oder her.","story.map4-dungeon5.028":"Oh, das klingt ja furchterregend.<br>Dann bleibe ich wohl besser auf deiner guten Seite.","story.map4-dungeon5.029":"Grrr...<wait=40><br>Ich wusste es! Du machst dich über mich lustig!","story.map4-dungeon5.030":"Hehe...<wait=40><br>Glaubst du wirklich, ich wäre so grausam?","story.map4-dungeon5.031":"Am besten verärgerst du Lugina auch nicht, verstanden?","story.map4-dungeon5.032":"Nicht dass ich mir vorstellen könnte,<br>dass ein Freund von Karl","story.map4-dungeon5.033":"sich von einem Mitglied des Sky Garden einschüchtern lässt...","story.map4-dungeon5.034":"Hä?<wait=40><br>Dieser Karl, von dem du sprichst... <wait=40>Ist das etwa Karl aus Nyonne?","story.map4-dungeon5.035":"<size=20>Bwahaha!","story.map4-dungeon5.036":"Oh, so hab ich schon ewig nicht mehr gelacht.<wait=40><br>Allein die Vorstellung, dass dieser Trottel mit Karl befreundet sein soll!","story.map4-dungeon5.037":"Jetzt hab ich wirklich alles gehört...","story.map4-dungeon5.038":"He, wo willst du hin!","story.map4-dungeon5.039":"Erkunden.<wait=40><br>Wenn wir uns aufteilen, schaffen wir mehr, findest du nicht?","story.map4-dungeon5.040":"Lugina,<wait=40><br>du siehst dort drüben nach.","story.map4-dungeon5.041":"W-Warte!<wait=40><br>Woher soll ich denn wissen, wo ich...","story.map4-dungeon5.042":"...Hmpf.","story.map4-dungeon5.043":"Wenn sie mich schon anlügt,<br>könnte sie es wenigstens halbwegs glaubwürdig machen.","story.map4-dungeon5.044":"Heh, als ob dieser trottelige Ignorant<br>wirklich Karl kennen könnte...","story.map4-dungeon5.045":"Grr... <wait=40>Wenn ich nur an diesen<br>Schönling mit dem Mädchengesicht denke, kocht mir das Blut!","story.map4-dungeon5.046":"He, du! <wait=40>Steh nicht so dumm rum! Geh raus und kümmer dich um die Monster!","story.map4-dungeon6.001":"<size=20>Argh, <wait=40>jetzt reicht\'s!","story.map4-dungeon6.002":"Ich hab die Nase voll!<br>Womit hab ich das verdient, hä?!","story.map4-dungeon6.003":"Warum muss ausgerechnet ich gegen<br>so monströse Bestien antreten!","story.map4-dungeon6.004":"Das ist unfair!<wait=40><br>Ich hab das nicht verdient!","story.map4-dungeon6.005":"Iiih!!<wait=40><br>...Ach, du bist\'s nur, <rep_handlename>.","story.map4-dungeon6.006":"Tss... Seit ich dir begegnet bin,<br>hab ich nichts als Ärger.","story.map4-dungeon6.007":"Wie immer am Jammern, wie ich sehe?<br>Wirklich, Lugina, das steht einem Mann deines Ranges nicht gut.","story.map4-dungeon6.008":"Halt die Klappe!<wait=40><br>Was soll das überhaupt, dich immer so an mich ranzuschleichen!","story.map4-dungeon6.009":"Du bist einer der Gründe, warum ich<br>überhaupt in diesen Schlamassel reingezogen wurde!","story.map4-dungeon6.010":"Unsere Lage ist alles andere als ideal,<br>das gebe ich zu.","story.map4-dungeon6.011":"Aber Leute zu beschimpfen und herumzujammern ändert nichts daran.","story.map4-dungeon6.012":"Glaubst du, das weiß ich<br>nicht selbst?!","story.map4-dungeon6.013":"Ich hab Neuigkeiten für dich: Ich krieche nicht zum Spaß durch diese dreckigen Tunnel, okay!","story.map4-dungeon6.014":"Hehe...<wait=40><br>Nein, das sehe ich.","story.map4-dungeon6.015":"Trotzdem scheinst du zu wissen,<br>was zu tun ist.","story.map4-dungeon6.016":"Genau. <wait=40>Und genau darüber beschwere ich mich.","story.map4-dungeon6.017":"Na gut! Bringen wir diesen Tunnel endlich<br>hinter uns und beeilen uns zu den Ruinen des Riesen.","story.map4-dungeon6.018":"Oh, da hat es aber jemand eilig...<wait=40> Du solltest dich auch lieber sputen.","story.map4-dungeon6.019":"Wenn wir uns nicht beeilen, erwachen die großen<br>Götter und legen den ganzen Kontinent in Schutt und Asche.","story.map4-dungeon6.020":"Wir haben keine Zeit, diesem Dummkopf alles zu erklären!","story.map4-dungeon6.021":"Ich gehe voran.","story.map4-dungeon6.022":"Du erledigst alle Nachzügler, die<br>es an mir vorbei schaffen!","story.map4-dungeon6.023":"Heh...<wait=40><br>Gesprochen wie ein wahrer Krieger, Lugina.","story.map4-dungeon6.024":"Aber in einem Punkt irrst du dich.","story.map4-dungeon6.025":"<rep_handlename> hat das Recht, von der<br>Gefahr unserer Lage zu erfahren.","story.map4-dungeon6.026":"Du hast <rep_handlename> doch kämpfen sehen,<br>oder nicht?","story.map4-dungeon6.027":"Wir sollten jede militärische Stärke<br>nutzen, die uns zur Verfügung steht.","story.map4-dungeon6.028":"Hmpf! <wait=40>Wie du meinst.<br>Aber das Erklären überlasse ich komplett dir!","story.map4-dungeon6.029":"Ich hab die Nase gestrichen voll davon,<br>für dieses zu groß geratene Kleinkind den Babysitter zu spielen.","story.map4-dungeon6.030":"Sieht so aus, als wäre er doch<br>allein losgezogen.","story.map4-dungeon6.031":"Tss... Mit dieser miesepetrigen Art<br>wird er nie Freunde finden.","story.map4-dungeon6.032":"Nun,<wait=40><br>endlich sind wir zwei unter uns!","story.map4-dungeon6.033":"Von dir sprechen also die Ältesten – ein Freund von Karl,","story.map4-dungeon6.034":"dem Anführer der allmächtigen 24. Dämonenjäger, Rebluens.","story.map4-dungeon6.035":"Ich habe schon viel Großes über dich gehört,<br><rep_handlename>.","story.map4-dungeon6.036":"Du musst nicht so<br>erschrocken dreinschauen.","story.map4-dungeon6.037":"Ganz ruhig.<wait=40><br>Ich bin auf deiner Seite, weißt du.","story.map4-dungeon6.038":"Deinem Gesichtsausdruck nach muss ich mir dein Vertrauen wohl erst noch verdienen.","story.map4-dungeon6.039":"Wo war ich?<wait=40><br>Ach ja, die Riesen.","story.map4-dungeon6.040":"Eigentlich ist es gar nicht so kompliziert.","story.map4-dungeon6.041":"Vor langer Zeit lebte hier in Cordelica<br>ein Volk von Riesen.","story.map4-dungeon6.042":"Doch ihr ganzes Volk wurde von Mächten<br>ausgelöscht, die unser Verständnis übersteigen.","story.map4-dungeon6.043":"Alle, bis auf einen:<br>den, den man heute als Riesengott kennt.","story.map4-dungeon6.044":"Aus Wut und Verzweiflung über<br>seine gefallenen Gefährten ","story.map4-dungeon6.045":"versiegelte sich der Riese in diesem Land.","story.map4-dungeon6.046":"So lautet die Legende, wie sie am<br>Turm des Lichts eingraviert ist. <wait=40>Wer sie schrieb, wissen wir nicht.","story.map4-dungeon6.047":"Lugina muss auf dieselbe Inschrift<br>gestoßen sein.","story.map4-dungeon6.048":"Nachdem er sie gelesen hatte, <wait=40>muss er<br>zum selben Schluss gekommen sein wie ich...","story.map4-dungeon6.049":"Nämlich, dass der Riesengott bald<br>voller Zorn aus seinem Schlummer erwachen wird.","story.map4-dungeon6.050":"Heh...<wait=40> <br>Jetzt habe ich wohl endlich deine volle Aufmerksamkeit.","story.map4-dungeon6.051":"Ganz ruhig.<wait=40><br>Der Stärke der Beben nach zu urteilen,","story.map4-dungeon6.052":"ist der Riesengott noch nicht vollständig erwacht.","story.map4-dungeon6.053":"Laut der Inschrift der Ruinen wird,<br>wenn der Riese endlich erwacht,","story.map4-dungeon6.054":"diese ganze Insel im Nu<br>verschlungen.","story.map4-dungeon6.055":"Komm.<wait=40><br>Wir müssen sofort aufbrechen.","story.map4-dungeon6.056":"Die Ruinen, in denen der Riesengott liegt, sollten gleich hinter diesem Tunnel sein.","story.map4-dungeon7.001":"...Ja. <wait=40>Grantos ist noch schläfrig,<br>aber er ist jetzt wach.","story.map4-dungeon7.002":"Nein, Herr, <wait=40>das wird<br>kein Problem sein.","story.map4-dungeon7.003":"Selbstverständlich, Herr.<wait=40><br>Ich melde mich, sobald es Neuigkeiten gibt.","story.map4-dungeon7.004":"He, <wait=40>Weib!","story.map4-dungeon7.005":"Bist du da drüben bald fertig<br>mit Tratschen?","story.map4-dungeon7.006":"Verpetzt du mich etwa bei einem deiner<br>kaiserlichen Kumpel, oder was?","story.map4-dungeon7.007":"Heh. Dir entgeht wirklich nichts, was?","story.map4-dungeon7.008":"Das Imperium hat großes Interesse an<br>talentierten jungen Beschwörern.","story.map4-dungeon7.009":"Pah!<wait=40><br>Tja, das Interesse beruht nicht auf Gegenseitigkeit!","story.map4-dungeon7.010":"...!","story.map4-dungeon7.011":"He, <rep_handlename>!<br>Kannst du dich vielleicht mal ein bisschen beeilen?","story.map4-dungeon7.012":"Falls du es noch nicht gemerkt hast,<br>wir stecken hier mitten in einem Notfall!","story.map4-dungeon7.013":"Wenn du es so eilig hast,<br>warum bist du dann nicht ohne uns vorgegangen?","story.map4-dungeon7.014":"Ihr könnt dem großen Lugina vielleicht nicht das Wasser reichen, aber selbst ihr Amateure seid zu was nütze!","story.map4-dungeon7.015":"Heh...","story.map4-dungeon7.016":"Also gut, hört zu.<wait=40><br>Ich werde jetzt Grantos erledigen,","story.map4-dungeon7.017":"den Riesengott, der seit Hunderten<br>von Jahren schläft.","story.map4-dungeon7.018":"Da ich ja so mächtig bin,<br>übernehme ich die schwere Arbeit.","story.map4-dungeon7.019":"Allerdings will ich dabei nicht von<br>lästigen kleinen Schergen gestört werden.","story.map4-dungeon7.020":"Da kommt ihr ins Spiel.<wait=40> Ihr lenkt sie ab, während ich mir den großen Kerl vornehme!","story.map4-dungeon7.021":"Du willst ganz allein gegen so ein<br>riesiges Monster antreten? Wie galant von dir...","story.map4-dungeon7.022":"Sarkastisch, oder was?","story.map4-dungeon7.023":"Als ob ihr das Zeug dazu hättet, es mit<br>so einem Riesen aufzunehmen!","story.map4-dungeon7.024":"Lieber nehm ich\'s selbst mit ihm auf, als euch zwei rauszuhauen, wenn alles den Bach runtergeht.","story.map4-dungeon7.025":"Ihr werdet sehen, <wait=40>ich zeige euch, was wahre Macht bedeutet.","story.map4-dungeon7.026":"Alles klar? <wait=40>Ihr lenkt die Schergen ab, während ich die Welt rette!","story.map4-dungeon7.027":"Und denkt dran: Wenn ihr das vermasselt,<br>nehme ich euch mit euren eigenen Schwertern aus!","story.map4-dungeon7.028":"Herrisch genug, um ein Dämonenjäger-Regiment<br>zu führen, ist er jedenfalls...","story.map4-dungeon7.029":"Sein Ton lässt zwar zu wünschen übrig,","story.map4-dungeon7.030":"aber er scheint zumindest fähig<br>und kenntnisreich genug zu sein.","story.map4-dungeon7.031":"Ganz zu schweigen davon, dass er mehr<br>Daten gesammelt hat, als ich erwartet hatte.","story.map4-dungeon7.032":"Trotzdem, nach meinen Erkenntnissen","story.map4-dungeon7.033":"kann er es unmöglich allein mit<br>Grantos aufnehmen.","story.map4-dungeon7.034":"Ich werde ihm wohl unter die Arme greifen müssen.","story.map4-dungeon7.035":"Natürlich<wait=40><br>braucht er auch deine Hilfe.","story.map4-dungeon7.036":"Zeit zu zeigen, was du wirklich<br>draufhast.","story.map4-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_clear.002":"Du hast es geschafft, <rep_handlename>!","story.map4-dungeon_ex_clear.003":"Vielen, vielen Dank!","story.map4-dungeon_ex_clear.004":"Ich wusste, dass du das draufhast!","story.map4-dungeon_ex_clear.005":"Du bist einfach super!","story.map4-dungeon_ex_clear.006":"Hehe, <wait=20>tut mir leid, da bin ich wohl ein bisschen übers Ziel hinausgeschossen.","story.map4-dungeon_ex_clear.007":"Jedenfalls wissen wir jetzt, was das für ein Monster war.","story.map4-dungeon_ex_clear.008":"Anscheinend wurde es ursprünglich von den Riesen gehalten, um den Müll zu beseitigen.","story.map4-dungeon_ex_clear.009":"Doch bald wurde es so groß, dass selbst sie es nicht mehr bändigen konnten. ","story.map4-dungeon_ex_clear.010":"Schließlich wurde es von einem gewissen Helden an diesem Ort eingesperrt.","story.map4-dungeon_ex_clear.011":"Dieser Held muss unglaublich stark gewesen sein, wenn er ein Monster bezwungen hat, mit dem nicht mal die Riesen fertig wurden.","story.map4-dungeon_ex_clear.012":"Oh, <wait=20>aber du bist natürlich auch stark!","story.map4-dungeon_ex_clear.013":"Ich meine, du hast dieses riesige Monster ganz allein besiegt!","story.map4-dungeon_ex_clear.014":"Und es war so schleimig und eklig...","story.map4-dungeon_ex_clear.015":"Ich bewundere dich wirklich, <rep_handlename>!","story.map4-dungeon_ex_clear.016":"Äh, was ist das?","story.map4-dungeon_ex_clear.017":"Da ist was auf deiner Schulter. <wait=20>Ist das etwa...","story.map4-dungeon_ex_clear.018":"<size=21>Kyaaaaahh!</size>","story.map4-dungeon_ex_clear.019":"<size=21>Igitt, das ist ganz schleimig!!</size>","story.map4-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_open.002":"Herr, <wait=20>wir haben ein Problem! <wait=40>Ein großes Problem!","story.map4-dungeon_ex_open.003":"Entschuldigung! Ich wollte keine Panik auslösen...","story.map4-dungeon_ex_open.004":"Lin Merylham von der Logistikunterstützung...","story.map4-dungeon_ex_open.005":"...des Ermittlungsbüros im Vermessungsamt von Grand Gaia, zu deinen Diensten.","story.map4-dungeon_ex_open.006":"W-<wait=20>Wie kannst du in so einem Moment so ruhig bleiben!?","story.map4-dungeon_ex_open.007":"<rep_handlename>, als Mitglied der Beschwörerarmee der Akras-Beschwörerhalle...","story.map4-dungeon_ex_open.008":"...bitten wir dich, die Ignia-Grotte zu untersuchen!","story.map4-dungeon_ex_open.009":"Anscheinend schlief hinter den Ignia-Fällen ein Monster.","story.map4-dungeon_ex_open.010":"Aber das Erdbeben in Cordelica neulich scheint es geweckt zu haben.","story.map4-dungeon_ex_open.011":"Und was das Monster selbst angeht...","story.map4-dungeon_ex_open.012":"Es ist ganz nass und klebrig und frisst einfach alles!","story.map4-dungeon_ex_open.013":"Wenn ich mir so ein riesiges, ekliges Monster nur vorstelle, krieg ich Gänsehaut.","story.map4-dungeon_ex_open.014":"<size=21>Kyaaaaaahh! Igitt!!</size>","story.map4-ending.001":"Heh, <wait=40>ganz wie ich vermutet hatte.","story.map4-ending.002":"Kein Wunder, dass Karl so viel von dir hält.","story.map4-ending.003":"(Keuch... <wait=40>schnauf...)","story.map4-ending.004":"Na, <wait=40>sieh mal, wer es endlich geschafft hat!","story.map4-ending.005":"...<wait=40>Ugh, nicht schon wieder.","story.map4-ending.006":"Du hast die Neuigkeiten sicher schon gehört?","story.map4-ending.007":"<rep_handlename> hat gerade<br>Grantos besiegt.","story.map4-ending.008":"Deine Dienste wurden also doch nicht gebraucht.<br>Und das nach all den großen Tönen vorhin...","story.map4-ending.009":"D-Du...<wait=40><br>Wenn du große Töne willst, nehm ich\'s gleich hier mit dir auf!","story.map4-ending.010":"Du kannst dir das falsche Heldengetue sparen.<wait=40><br>Du hattest deine Chance und hast sie vermasselt.","story.map4-ending.011":"H-Halt die Klappe!<wait=40><br>An meinen Informationen war nichts falsch!","story.map4-ending.012":"Dieser verfluchte Riese muss seine Position verändert haben oder so...","story.map4-ending.013":"Eins muss ich dir lassen: Du bist zu denselben Schlüssen gekommen wie ich,","story.map4-ending.014":"und du hast auf dem Weg hierher einige zähe Monster erledigt.","story.map4-ending.015":"Trotzdem hast du deine Mission nicht erfüllt.","story.map4-ending.016":"Was nützt es, wie gut du bist, wenn du versagst, wenn es wirklich darauf ankommt?","story.map4-ending.017":"Grr...<wait=40> Dir zeig ich\'s!<br>Was weißt du schon?!","story.map4-ending.018":"Jetzt reicht\'s! Ich bin raus!","story.map4-ending.019":"Ich wollte nie den Babysitter für euch spielen, und sieh, was ich davon habe!","story.map4-ending.020":"Ich gehe zurück nach Elgaia!","story.map4-ending.021":"Außerdem muss ich den alten Knackern<br>in der Beschwörerhalle meinen Bericht abliefern.","story.map4-ending.022":"......","story.map4-ending.023":"He!<wait=40> <rep_handlename>!","story.map4-ending.024":"Bild dir bloß nichts darauf ein, dass du mit Glück Grantos besiegt hast!","story.map4-ending.025":"Den hätte ich mit geschlossenen Augen<br>und einer Hand auf dem Rücken geschlagen!","story.map4-ending.026":"Eigentlich solltest du mir dankbar sein!","story.map4-ending.027":"Ja, genau! <wait=40>Dankbar, dass der mächtigste Beschwörer der ganzen Akras-Beschwörerhalle auf dich aufgepasst hat!","story.map4-ending.028":"Ähem.<wait=40> Ist nicht Karl vom Rebluens-Trupp der Mächtigste in der Beschwörerhalle?","story.map4-ending.029":"Willst du ein blaues Auge<br>oder was?","story.map4-ending.030":"Hör auf, diesen Namen zu sagen!","story.map4-ending.031":"Ich hab mehr Talent im kleinen Finger als dieser Angeber im ganzen Körper!","story.map4-ending.032":"Dieser Langweiler war einfach nur zur richtigen Zeit am richtigen Ort, sonst nichts!","story.map4-ending.033":"In Randall erzählt man sich, er habe Sagamur, den Infernodrachen, im Alleingang besiegt.","story.map4-ending.034":"Danach soll er persönlich für die Kaiserliche Garde angeworben worden sein.","story.map4-ending.035":"Ha! Der?!<wait=40><br>Er hat vielleicht den Todesstoß versetzt,","story.map4-ending.036":"aber es war ein anderes Regiment,<br>das ihn erst in die Knie gezwungen hat!","story.map4-ending.037":"Und ja,<wait=40> falls du dich fragst,<wait=40>","story.map4-ending.038":"dieses andere Regiment war der Sky Garden, vielen Dank auch!","story.map4-ending.039":"Ach ja, <wait=40>jetzt erinnere ich mich.","story.map4-ending.040":"Da war doch was, dass der Anführer des Sky Garden in Ohnmacht fiel, als er Geheul in der Dunkelheit hörte...","story.map4-ending.041":"Was zum?!","story.map4-ending.042":"D-Das ist nicht so passiert!","story.map4-ending.043":"Ich hab mein Leben riskiert, um diese Schwächlinge vor dem zu schützen, was da hinten lauerte!","story.map4-ending.044":"Nur dank mir konnten sie<br>überhaupt erst kämpfen!","story.map4-ending.045":"Ohne mich hätten sie nicht den Hauch einer Chance gehabt zu gewinnen!","story.map4-ending.046":"Hehe. <wait=40>In dem Fall muss ich<br>mich entschuldigen, dass ich am großen Anführer des Sky Garden gezweifelt habe.","story.map4-ending.047":"Das will ich wohl meinen!","story.map4-ending.048":"Tss... <wait=40>Genau deshalb kann ich<br>diesen Hochstapler Karl nicht ausstehen.","story.map4-ending.049":"Wo bleibt sein Respekt?<br>Ich bin sein Vorgesetzter, verdammt noch mal!","story.map4-ending.050":"Ist mir egal, ob du es bist<br>oder dieses dämliche kaiserliche Flittchen,","story.map4-ending.051":"jeder, der zu Karl hält, ist mir ein Dorn im Auge!","story.map4-ending.052":"Hör gut zu, <rep_handlename>, denn ich sag das nur einmal!","story.map4-ending.053":"Wenn du mir das nächste Mal in die Quere kommst,","story.map4-ending.054":"verpass ich dir eine solche Abreibung, dass du eine Woche lang nicht sitzen kannst!","story.map4-ending.055":"Wenn du darauf keine Lust hast, zeigst du mir besser mal ein bisschen Respekt!","story.map4-ending.056":"Ich bin der große und mächtige Lugina, und das vergisst du besser nicht!","story.map4-ending.057":"Heh...<wait=40> <br>Nun, das hätte besser laufen können.","story.map4-ending.058":"Apropos,<wait=40><br>es wird Zeit, dass ich mich auch auf den Weg mache.","story.map4-ending.059":"Wenn du die Vier Gefallenen Götter weiter verfolgst,<wait=40> kreuzen sich unsere Wege vielleicht eines Tages wieder.","story.map4-ending.060":"Ich freue mich darauf, in Zukunft<br>an deiner Seite zu kämpfen.","story.map4-ending.061":"Viel Glück,<br>tapferer Krieger.","story.map4-ending.062":"––Verstehe.<wait=40><br>Es war also doch nicht in Cordelica...","story.map4-ending.063":"––Ich hatte es schon vermutet,<wait=40><br>aber ich bin trotzdem ein wenig enttäuscht.","story.map4-ending.064":"––Hm?<wait=40><br>Du musst dich für nichts entschuldigen.","story.map4-ending.065":"––Wenn überhaupt, sollte ich mich entschuldigen,<br>dass ich dich auf eine sinnlose Suche geschickt habe.","story.map4-ending.066":"––Ja, natürlich.<wait=40><br>Mach weiter so.","story.map4-ending.067":"––Denk daran, ich zähle auf dich.","story.map4-ending.068":"Hehe...","story.map4-ending.069":"Der junge Beschwörer hat also <wait=40>Grantos<br>besiegt...","story.map4-ending.070":"Ganz wie ich erwartet hatte.","story.map4-ending.071":"Die Welt scheint sich tatsächlich<br>in die richtige Richtung zu bewegen.","story.map4-ending.072":"Jetzt muss Paris sich nur noch beeilen<br>und finden, was in Grand Gaia wirklich schlummert.","story.map4-ending.073":"......","story.map4-ending.074":"Du hörst doch zu, nehme ich an?","story.map4-ending.075":"Die Uhr tickt.<wait=40><br>Jetzt gibt es kein Zurück mehr.","story.map4-ending.076":"Dein Meister sollte sich besser<br>auf das vorbereiten, was kommt.","story.map4-ending.077":"......","story.map4-ending.078":"...<wait=40>Hehe.","story.map4-ending.079":"<size=20>Muahaha!","story.map4-open.001":"(Klopf, <wait=20>klopf.)","story.map4-open.002":"Verzeihung, Herr.","story.map4-open.003":"Laut unseren Quellen in der Regierung","story.map4-open.004":"hat die Akras-Beschwörerhalle die Kontrolle<br>über die südliche Region von Mistral übernommen.","story.map4-open.005":"...<wait=40>Ja, <wait=40>das habe ich gehört.","story.map4-open.006":"Sie werden auch in Grand Gaia<br>zu einer recht beachtlichen Macht.","story.map4-open.007":"So scheint es...","story.map4-open.008":"Paris,<wait=40><br>ich möchte, dass du nach Cordelica gehst.","story.map4-open.009":"Halte mich über alle neuen<br>Entwicklungen an der Grenze auf dem Laufenden.","story.map4-open.010":"...<wait=40>Selbstverständlich, Herr.<wait=40><br>...<wait=40>Und was ist mit meinen üblichen Pflichten?","story.map4-open.011":"Ich werde dem Kaiser die Lage erklären.","story.map4-open.012":"Danke, Herr.<wait=40><br>Dann verabschiede ich mich.","story.map4-open.013":"......","story.map4-open.014":"...Oh,<wait=40><br>ich hatte dich gar nicht bemerkt.","story.map4-open.015":"Anklopfen war noch nie dein Ding, was?","story.map4-open.016":"......","story.map4-open.017":"Die Akras-Beschwörerhalle <wait=40>und die Regierung der Elgaia-Föderation...<wait=60><br>Die Abel-Fraktion macht ihren Zug...","story.map4-open.018":"......","story.map4-open.019":"...<wait=40>Hehe.","story.map4-open.020":"<size=20>Muahaha!","story.map4-open.021":"Sieht so aus, als würde es<br>gleich interessant werden...","story.map5-dungeon1.001":"...<wait=40>Dieser Ort ist ganz schön trostlos. ","story.map5-dungeon1.002":"Die Kämpfe scheinen auch bis hierher gekommen zu sein.","story.map5-dungeon1.003":"Wie tragisch...","story.map5-dungeon1.004":"Wir müssen alles tun, damit so etwas nie wieder passiert.","story.map5-dungeon1.005":"Na, <wait=40><rep_handlename>,<wait=40> du siehst ja richtig selbstsicher aus!","story.map5-dungeon1.006":"Genau, <wait=40>machen wir diesen ungezogenen Cardes fertig!","story.map5-dungeon1.007":"Hm? <wait=40>Wer Cardes ist, fragst du?","story.map5-dungeon1.008":"Oh, tut mir leid!<wait=40> <br>Ich hab dir noch gar nichts von ihm erzählt, oder!?","story.map5-dungeon1.009":"Ähem, <wait=40>nun denn, <wait=40>Zeit für Tiliths Geschichtsstunde!","story.map5-dungeon1.010":"Dieser Palmyna-Archipel wird von \\"Cardes dem Bösartigen\\" beherrscht, einem der Vier Gefallenen Götter. ","story.map5-dungeon1.011":"Unser aktuelles Ziel, <rep_handlename>, ist es, ihn zu besiegen!","story.map5-dungeon1.012":"Und du musst auf der Hut sein, denn er ist viel stärker als Maxwell! ","story.map5-dungeon1.013":"Aber keine Sorge!","story.map5-dungeon1.014":"Der größte Teil von Cardes\' Kraft <wait=20>ist nämlich gerade versiegelt.","story.map5-dungeon1.015":"Man sagt, sie wurde im großen Krieg tief in Palmyna versiegelt, an einem Ort namens \\"Geisterwelt\\"...","story.map5-dungeon1.016":"Außer dir muss es hier also noch ein paar ziemlich beeindruckende Menschen gegeben haben, <rep_handlename>.","story.map5-dungeon1.017":"Moment,<wait=40> warte mal...","story.map5-dungeon1.018":"Das heißt doch, dass Cardes dieses Land weiter beherrscht hat, obwohl seine Kräfte versiegelt waren, oder? ","story.map5-dungeon1.019":"Vielleicht ist er sogar noch mächtiger, als ich dachte...","story.map5-dungeon1.020":"...<wait=20>...","story.map5-dungeon1.021":"Egal, <wait=40>wir müssen ihn so oder so besiegen!","story.map5-dungeon1.022":"Aber für dich ist das bestimmt kein Problem, <rep_handlename>!","story.map5-dungeon1.023":"Ich sollte los. <wait=20>Ich muss noch mehr über Cardes herausfinden!","story.map5-dungeon1.024":"Viel Glück!!","story.map5-dungeon2.001":"<size=14><rep_handlename>!","story.map5-dungeon2.002":"<size=14>W-<wait=20>Wo bist du?","story.map5-dungeon2.003":"<size=20>Aaaah!!","story.map5-dungeon2.004":"...S-<wait=40>Schleich dich doch nicht so an!","story.map5-dungeon2.005":"Hä?<wait=40><br>Wovor ich Angst habe?","story.map5-dungeon2.006":"V-<wait=40>Vor gar nichts!","story.map5-dungeon2.007":"I-<wait=41>Ich hab vor überhaupt nichts Angst!","story.map5-dungeon2.008":"Geisterschiffe und so was sind doch kein bisschen gruselig!","story.map5-dungeon2.009":"Ich könnte sogar hier wohnen, <wait=40>weißt du!","story.map5-dungeon2.010":"Ah!<wait=40> Ich verstehe!","story.map5-dungeon2.011":"Das sagst du nur, weil du selbst Angst hast, <wait=40>stimmt\'s, <rep_handlename>!?","story.map5-dungeon2.012":"Hihi, <wait=40><rep_handlename> ist ein richtiger Angsthase!","story.map5-dungeon2.013":"Du hättest was sagen sollen, <wait=40>ich hätte dich doch beschützt.","story.map5-dungeon2.014":"Ich meine, <wait=20>als Göttin bin ich nicht nur hübsch, sondern auch stark!","story.map5-dungeon2.015":"Ja, <wait=20>genau!","story.map5-dungeon2.016":"Hier soll ein Monster herumspuken, das Menschenseelen verschlingt, also pass gut auf!","story.map5-dungeon2.017":"<size=18>*Platsch*","story.map5-dungeon2.018":"<size=20>Hä?<wait=40> W-Was war das!","story.map5-dungeon2.019":"H-Hast du das gehört, <wait=20>dieses komische Geräusch gerade!?","story.map5-dungeon2.020":"Hä?<wait=40> Das waren nur deine Schritte?","story.map5-dungeon2.021":"...<wait=40>...<wait=40>...","story.map5-dungeon2.022":"<size=20><rep_handlename>, du Idiot!","story.map5-dungeon2.023":"Ich hab dir wichtige Informationen mitgebracht, <wait=40>aber jetzt hab ich keine Lust mehr, sie dir zu erzählen!","story.map5-dungeon2.024":"Ich geh nach Hause!","story.map5-dungeon2.025":"Hihi, <wait=40>hast du mir das etwa geglaubt?","story.map5-dungeon2.026":"Hast du dich erschreckt?","story.map5-dungeon2.027":"Eine Göttin würde sich nie so aufregen. ","story.map5-dungeon2.028":"Jedenfalls, <wait=40>laut meinen Nachforschungen liegt Palmyna, der Ort, an dem Cardes versiegelt ist...","story.map5-dungeon2.029":"...hinter Encervis, <wait=40>und das liegt gleich hinter Amdahl.","story.map5-dungeon2.030":"Zuerst müssen wir an Schloss Amdahl vorbei, <wait=40>dann können wir uns durch Encervis schlagen!","story.map5-dungeon2.031":"Also beeilen wir uns hier durch, <wait=40>diese Gegend ist mir echt unheimlich...","story.map5-dungeon2.032":"<size=18>*Platsch* *Platsch*","story.map5-dungeon2.033":"Hä?","story.map5-dungeon2.034":"*Quatsch* *Quatsch*","story.map5-dungeon2.035":"<size=20>Aaaah!!","story.map5-dungeon3.001":"<speed=10>Was haben wir denn hier...<wait=40><br>Dieser hier ist ganz anders als die anderen Beschwörer.","story.map5-dungeon3.002":"Ich habe mich entschieden, <wait=20>hier mache ich dir ein Ende.","story.map5-dungeon3.003":"Du brauchst dir keine Sorgen zu machen.<wait=50><br>Es ist gleich vorbei.","story.map5-dungeon3.004":"Diese Präsenz...<wait=20>...","story.map5-dungeon3.005":"Ach, so ist das...","story.map5-dungeon3.006":"Da bist du ja!","story.map5-dungeon3.007":"Hey, <wait=40>ist was los?<wait=40> Du siehst so besorgt aus.","story.map5-dungeon3.008":"Bei so schönem Wetter solltest du fröhlicher sein! Komm schon, lächle mal für mich!","story.map5-dungeon3.009":"Außerdem hast du ja mich, <wait=40>also reiß dich zusammen!","story.map5-dungeon3.010":"Und überhaupt, <wait=40>schau doch mal, wie friedlich es hier ist.","story.map5-dungeon3.011":"Ich würde mich an solchen Orten wirklich gern mal mit dir entspannen, <rep_handlename>.","story.map5-dungeon3.012":"Hihi, <wait=40>nur ein Scherz!","story.map5-dungeon3.013":"Du hast eine wichtige Mission: die Vier Gefallenen Götter zu besiegen, <rep_handlename>.","story.map5-dungeon3.014":"Da hast du keine Zeit zum Faulenzen!","story.map5-dungeon3.015":"Hm? <wait=40>Und was ist mit mir?","story.map5-dungeon3.016":"Natürlich hab ich auch keine Zeit dafür...<wait=40> Ich meine...","story.map5-dungeon3.017":"Sieht es für dich etwa so aus,<wait=40> als würde ich hier nur herumtrödeln!?","story.map5-dungeon3.018":"Also wirklich!!","story.map5-dungeon3.019":"Ich tue alles, was ich kann, um dir zu helfen, <rep_handlename>!","story.map5-dungeon3.020":"Hm? <wait=40>Zum Beispiel?","story.map5-dungeon3.021":"D-<wait=40>Das ist so viel, das kann ich gar nicht in Worte fassen...<wait=40> *M<size=15>u<size=14>r<size=13>m<size=12>e<size=11>l* <size=12>*M<size=11>u<size=10>r<size=9>m<size=8>e<size=7>l<size=6>*","story.map5-dungeon3.022":"Egal, <wait=40>genug von mir!","story.map5-dungeon3.023":"Wichtig ist jetzt der Weg, der vor uns liegt!","story.map5-dungeon3.024":"Also dann, <wait=40>machen wir uns auf zu Schloss Amdahl!","story.map5-dungeon4.001":"Igitt, <wait=20>wie furchtbar! <wait=40>Hier ist es so eklig!","story.map5-dungeon4.002":"Nicht mal Graham würde einen Fuß an so einen Ort setzen!","story.map5-dungeon4.003":"Das habe ich dir doch schon erklärt, oder nicht?","story.map5-dungeon4.004":"Graham ist sehr wahrscheinlich in Edila, der Geisterstadt gleich hinter diesen Minen.","story.map5-dungeon4.005":"Hör endlich auf zu jammern! <wait=40> Wir müssen weiter!","story.map5-dungeon4.006":"Jedenfalls bekommen wir von der Beschwörerhalle <wait=40>anscheinend nichts als falsche Informationen!","story.map5-dungeon4.007":"Ehrlich, Seria, <wait=40>du bist die strengste Frau, die ich kenne...","story.map5-dungeon4.008":"Hm?<wait=40> Oh!<wait=40> <rep_handlename>!","story.map5-dungeon4.009":"Pff...","story.map5-dungeon4.010":"Du bist also doch auch zum Palmyna-Archipel gekommen!","story.map5-dungeon4.011":"Ich dachte mir, wenn es einer schafft, dann du, <rep_handlename>.","story.map5-dungeon4.012":"Du bist sicher hinter Cardes her, oder?","story.map5-dungeon4.013":"Haha, <wait=40>nach dem, wie du mit Maxwell fertig geworden bist, hat er gegen dich wohl keine Chance. ","story.map5-dungeon4.014":"Pff! <wait=40>Werd bloß nicht übermütig, <wait=40>sonst passiert dir noch was.","story.map5-dungeon4.015":"Was redest du denn jetzt schon wieder? <wait=50> Warum behandelst du <rep_handlename> nicht mit etwas mehr Respekt?<wait=40>","story.map5-dungeon4.016":"*Bonk*","story.map5-dungeon4.017":"<size=18>D-<wait=20>Das war nichts! <wait=40>Wirklich, ich hör ja schon auf!","story.map5-dungeon4.018":"Jedenfalls gibt es im Palmyna-Archipel <wait=40>einen Untergebenen von Cardes, den selbst die stärksten Streitkräfte fürchten...","story.map5-dungeon4.019":"Zögerst du auch nur einen Moment, ist es aus mit dir!","story.map5-dungeon4.020":"Ach, Seria...","story.map5-dungeon4.021":"Obwohl, <wait=40>an dem, was sie sagt, ist schon etwas Wahres dran. ","story.map5-dungeon4.022":"Tatsächlich gibt es, <wait=40>abgesehen von Graham, den wir gerade verfolgen...","story.map5-dungeon4.023":"...Gerüchte über eine ebenso mächtige, wenn nicht noch mächtigere Bestie in dieser Gegend namens Zebra. ","story.map5-dungeon4.024":"Wir können nicht vorsichtig genug sein, <wait=40>also passen wir alle gut auf, wenn wir weiterziehen. ","story.map5-dungeon4.025":"Ach ja, <wait=40>was ist eigentlich mit dieser Göttin passiert?","story.map5-dungeon4.026":"Ihr zwei wart doch unzertrennlich wie Pech und Schwefel...","story.map5-dungeon4.027":"Ach, ich verstehe!<wait=40> Hat sie endlich genug davon, wie langweilig du bist!?","story.map5-dungeon4.028":"Seria, <wait=40>das reicht jetzt.","story.map5-dungeon4.029":"...<wait=40>Das war doch nur ein kleiner Scherz.","story.map5-dungeon4.030":"Wir sind auf dem Weg nach Edila, das gleich vor uns liegt, um Graham zu verfolgen. ","story.map5-dungeon4.031":"Ich würde gern gemeinsam mit dir kämpfen, <wait=40>aber mit so einer nervigen Begleiterin...","story.map5-dungeon4.032":"Ich war doch gar nicht nervig...","story.map5-dungeon4.033":"Haha... <wait=40>Und, hast du vor, allein weiterzuziehen?","story.map5-dungeon4.034":"Da vorne warten ziemlich harte Gegner auf dich,<wait=40> aber ich glaube, wir überleben und sehen uns wieder!","story.map5-dungeon4.035":"Karl! <wait=40>Wir haben keine Zeit zum Herumtrödeln, gehen wir weiter!","story.map5-dungeon4.036":"Pass bloß auf, dass du nicht zur Beute dieser Dämonen wirst!","story.map5-dungeon4.037":"H-<wait=40>Hey, <wait=40>warte doch!","story.map5-dungeon4.038":"Meine Güte... <wait=40>Also dann, <wait=20>bis zum nächsten Mal, <rep_handlename>!","story.map5-dungeon5.001":"Ah, <wait=40>wie herrlich!","story.map5-dungeon5.002":"Oh, <wait=40><rep_handlename>!","story.map5-dungeon5.003":"Du hast es heil hierher geschafft. <wait=40>Ich wusste, dass du das kannst!","story.map5-dungeon5.004":"Auch wenn ich an dich geglaubt habe, bin ich trotzdem erleichtert, dich zu sehen.","story.map5-dungeon5.005":"Hm? <wait=40>Was ich gemacht habe?","story.map5-dungeon5.006":"Hihi, <wait=40>ich hab natürlich das Heiligtum genossen!","story.map5-dungeon5.007":"Jeder Winkel voller Licht, <wait=20>es geht nichts über ein schönes Heiligtum.","story.map5-dungeon5.008":"Die feierliche Atmosphäre und all das wunderschöne Licht sind für eine Göttin wie mich einfach unwiderstehlich.","story.map5-dungeon5.009":"Und hier gibt es keine komischen Geräusche wie auf dem Geisterschiff!","story.map5-dungeon5.010":"<size=18>*Raschel* *Raschel*","story.map5-dungeon5.011":"Was war das!?<wait=40> Wer ist da!?","story.map5-dungeon5.012":"Ho ho ho. <wait=40><br>Habe ich dich erschreckt?","story.map5-dungeon5.013":"Verzeih mir, <wait=20>junge Dame.","story.map5-dungeon5.014":"Ich wollte dir keine Angst machen, <wait=40>du hast nur so eine liebliche Stimme. ","story.map5-dungeon5.015":"Ah, <wait=40>ä-<wait=40>ähm...","story.map5-dungeon5.016":"Wer bist du denn, alter Mann?","story.map5-dungeon5.017":"Ho ho ho. <wait=40><br>Entschuldige bitte.","story.map5-dungeon5.018":"Mein Name ist Grah. <wait=40><br>Nenn mich bitte Elder Grah.","story.map5-dungeon5.019":"Elder Grah, also...","story.map5-dungeon5.020":"Ho ho ho. <wait=40><br>Ein schöner Name, nicht wahr?","story.map5-dungeon5.021":"Ich habe dir meinen Namen genannt, <wait=40>verrätst du mir auch deinen?","story.map5-dungeon5.022":"Ähm, <wait=40>ich heiße Tilith! <wait=40>Ich bin ein ganz normales Mädchen, wie man es überall findet.","story.map5-dungeon5.023":"Und diese tolle Person hier ist <rep_handlename>!","story.map5-dungeon5.024":"<rep_handlename> ist ein unglaublich starker Beschwörer!","story.map5-dungeon5.025":"Wie mutig.","story.map5-dungeon5.026":"Und, Elder Grah, <wait=40>was führt dich an so einen Ort?","story.map5-dungeon5.027":"Nun, <wait=40>ich wollte gerade dort drüben einen Spaziergang machen.","story.map5-dungeon5.028":"Einen Spaziergang, sagst du...","story.map5-dungeon5.029":"Ich dachte, diese Gegend wimmelt von Monstern...","story.map5-dungeon5.030":"Hm, <wait=20>nun, offenbar haben sie mich nicht beachtet. ","story.map5-dungeon5.031":"Hmm...<wait=40> Du kommst mir immer noch ein bisschen verdächtig vor...","story.map5-dungeon5.032":"Schau dir nur diese mächtigen Waffen an, die du trägst...","story.map5-dungeon5.033":"He he he...","story.map5-dungeon5.034":"Wie es scheint, bin ich ertappt!","story.map5-dungeon5.035":"In Wahrheit <wait=20>bin ich Grah, der Gott, der über dieses Land herrscht!","story.map5-dungeon5.036":"Und nun sorge ich dafür, dass ihr zwei sofort daraus verschwindet!","story.map5-dungeon5.037":"Was zum!?","story.map5-dungeon5.038":"Ich nehme euch nur auf den Arm.","story.map5-dungeon5.039":"Ho ho ho. <wait=40><br>Habe ich euch erschreckt?","story.map5-dungeon5.040":"Wenn du überrascht bist, siehst du unglaublich niedlich aus, junge Dame.","story.map5-dungeon5.041":"Pfff!","story.map5-dungeon5.042":"Verzeih mir bitte.","story.map5-dungeon5.043":"Vor langer Zeit habe ich mich auf eine Art Abenteuer begeben. ","story.map5-dungeon5.044":"Damals habe ich diesen Speer benutzt, <wait=40>heute dient er kaum mehr als zur Zierde.","story.map5-dungeon5.045":"Ich bin hier, um die Legende der Vier Helden von einst zu erforschen, <wait=40>aber wichtige Hinweise werde ich hier wohl kaum finden.","story.map5-dungeon5.046":"Nun denn, <wait=40>ich denke, es ist Zeit für mich zu gehen.","story.map5-dungeon5.047":"Einen so interessanten Beschwörer kennenzulernen, <wait=40>das war wohl ein guter Tag. ","story.map5-dungeon5.048":"Also dann, <wait=40>ich freue mich auf unser nächstes Treffen.","story.map5-dungeon5.049":"Dieser alte Mann <wait=40>war irgendwie seltsam, oder?","story.map5-dungeon5.050":"Ein ganz normaler Mensch kann doch nicht einfach hier herumspazieren.","story.map5-dungeon5.051":"Bestimmt verheimlicht er irgendetwas<wait=20>.<wait=20>.<wait=20>.","story.map5-dungeon5.052":"Egal, <wait=40>sich jetzt darüber Sorgen zu machen, bringt nichts.","story.map5-dungeon5.053":"Mit unserem Ziel hat es ja sowieso nichts zu tun!","story.map5-dungeon5.054":"Also gut, <wait=40>schlagen wir uns schnell hier durch und gehen dann zu Schloss Amdahl!","story.map5-dungeon6.001":"Seria!<wait=40> Wie sieht\'s bei dir aus!?","story.map5-dungeon6.002":"Nichts!<wait=40> Keine Spur von ihm...","story.map5-dungeon6.003":"Verdammt! <wait=40>Er ist uns schon wieder entwischt!","story.map5-dungeon6.004":"So <wait=40>werden wir sie nie rächen können...","story.map5-dungeon6.005":"Karl...","story.map5-dungeon6.006":"<size=18>Hä!?<wait=40> <size=16>Wo kommst du denn her?","story.map5-dungeon6.007":"Wenn das nicht <rep_handlename> ist...","story.map5-dungeon6.008":"Hehe, <wait=40>du erwischst uns wohl in einem schlechten Moment.","story.map5-dungeon6.009":"Wieder einmal <wait=20>ist uns Graham durch die Finger geschlüpft.","story.map5-dungeon6.010":"Neben dir, der so tapfer gegen die Vier Gefallenen Götter gekämpft hat, <wait=20>müssen wir erbärmlich wirken...","story.map5-dungeon6.011":"Was redest du denn da!","story.map5-dungeon6.012":"<rep_handlename> hat nur Glück!<wait=40> Karl, du hast Gegner besiegt, die hundertmal stärker waren als seine!","story.map5-dungeon6.013":"Haha, <wait=40>vielen Dank, Seria.","story.map5-dungeon6.014":"Ein Kompliment von dir ist wirklich etwas Besonderes.","story.map5-dungeon6.015":"Dann habe ich wohl keinen Grund, den Kopf hängen zu lassen, was!","story.map5-dungeon6.016":"Was meinst du mit \\"Besonderes\\"?","story.map5-dungeon6.017":"Haha, <wait=40>ich will mich nur bei dir bedanken, das ist alles. ","story.map5-dungeon6.018":"Ach, und <rep_handlename>...","story.map5-dungeon6.019":"Graham ist uns nicht nur entkommen, weil er so stark war...","story.map5-dungeon6.020":"Als wir ihn diesmal eingeholt hatten, <wait=40>war noch ein anderes, unglaublich starkes Monster bei ihm.","story.map5-dungeon6.021":"Entschuldige, dass ich mich so vage ausdrücke.","story.map5-dungeon6.022":"Ehrlich gesagt <wait=40>haben wir das andere Monster gar nicht gesehen.","story.map5-dungeon6.023":"Kaum hatten wir seine unglaubliche Kraft gespürt, <wait=40>wurden wir buchstäblich weggeschleudert.","story.map5-dungeon6.024":"Als wir wieder zu uns kamen, <wait=40>war Graham irgendwohin verschwunden.","story.map5-dungeon6.025":"Ohne diesen Angriff hätten wir ihn gehabt...","story.map5-dungeon6.026":"Da hast du wohl recht...","story.map5-dungeon6.027":"Aber <wait=40>wir wissen nur sicher, dass kein gewöhnlicher Mensch so eine Kraft besitzen könnte...","story.map5-dungeon6.028":"Allerdings...","story.map5-dungeon6.029":"Jedenfalls <wait=40>hatten wir Glück, dass wir nicht so viele Verluste erlitten haben.","story.map5-dungeon6.030":"Wir setzen unsere Suche nach Graham fort.","story.map5-dungeon6.031":"Du willst zum Schloss Amdahl da vorne, richtig?","story.map5-dungeon6.032":"Ich spüre auch von dort eine starke, gefährliche Präsenz.","story.map5-dungeon6.033":"Sei bloß äußerst vorsichtig.","story.map5-dungeon6.034":"Wenn du diesem Monster begegnest, bist du erledigt!","story.map5-dungeon6.035":"Haha, <wait=40>streng zu <rep_handlename> wie immer, was?","story.map5-dungeon6.036":"I-<wait=40>Ich bin nicht nur zu <rep_handlename> streng...","story.map5-dungeon6.037":"Da bist du ja!","story.map5-dungeon6.038":"Wo warst du denn! <wait=40>Ich hab dich überall gesucht!","story.map5-dungeon6.039":"Hm?<wait=40> Was ist denn hier los?<wait=40><br>Euch kenne ich doch alle, oder?","story.map5-dungeon6.040":"...<wait=20>...","story.map5-dungeon6.041":"Hallo, Göttin.<wait=40> Lange nicht gesehen.","story.map5-dungeon6.042":"Ja, wirklich lange nicht!<wait=40> Du siehst fit aus wie immer, Karl!","story.map5-dungeon6.043":"Und du, <wait=40>hast du wieder wie üblich meinen kleinen <rep_handlename> geärgert?","story.map5-dungeon6.044":"<size=18>Was soll das heißen, \\"geärgert\\"!","story.map5-dungeon6.045":"Und wie ich schon gesagt habe, <wait=40><rep_handlename> gehört nicht dir!","story.map5-dungeon6.046":"Was regst du dich so auf?<wait=40> Bist du etwa <wait=20>eifersüchtig? ","story.map5-dungeon6.047":"...<wait=20>...","story.map5-dungeon6.048":"<size=18>*Klirr*","story.map5-dungeon6.049":"<size=18>M-Moment mal!","story.map5-dungeon6.050":"Beruhige dich, Seria!","story.map5-dungeon6.051":"K-<wait=20>Komm schon, <wait=40>wir müssen wieder Grahams Spur aufnehmen!","story.map5-dungeon6.052":"R-<wait=40>Richtig!?","story.map5-dungeon6.053":"<speed=14>Also dann, <wait=20><rep_handlename>!","story.map5-dungeon6.054":"<speed=14>Versprechen wir uns, auf dem Weg vor uns unser Bestes zu geben!","story.map5-dungeon6.055":"<speed=14>Gut, wir sind weg! Du auch, Seria!","story.map5-dungeon6.056":"Karl! <wait=20> Warte!<wait=40> Ich hab\'s verstanden, <wait=40>du musst nicht so zerren!","story.map5-dungeon6.057":"Göttin! <wait=40>Benimm dich ja!","story.map5-dungeon6.058":"Pfff!!","story.map5-dungeon6.059":"Puh, <wait=40>endlich ist sie weg.","story.map5-dungeon6.060":"Trotzdem, <wait=40>ich hoffe, sie schaffen es, Graham zu besiegen!","story.map5-dungeon6.061":"Wir sind fast da. <wait=40>Wenn wir hier durch sind, stehen wir vor den Toren von Schloss Amdahl!","story.map5-dungeon6.062":"Ich zähle auf dich!","story.map5-dungeon7.001":"Endlich sind wir da.","story.map5-dungeon7.002":"Wenn wir durch Schloss Amdahl kommen, ist der Weg nach Encervis frei.","story.map5-dungeon7.003":"Dann sind wir Cardes und dem Land, in dem er versiegelt ist, einen Schritt näher.","story.map5-dungeon7.004":"Hihi, <wait=40>schau nicht so nervös.","story.map5-dungeon7.005":"Ich weiß, dass du das schaffst, <rep_handlename>!","story.map5-dungeon7.006":"Beeilen wir uns und schlagen uns durch dieses Schloss!","story.map5-dungeon7.007":"Glaubst du wirklich, dass es so einfach wird?","story.map5-dungeon7.008":"Wa-!!","story.map5-dungeon7.009":"Habe ich dich schon wieder erschreckt?","story.map5-dungeon7.010":"Wie kannst du nur! <wait=40>Schleich dich nicht so an mich ran!!","story.map5-dungeon7.011":"Ho ho ho.","story.map5-dungeon7.012":"Du bist genauso niedlich, wie ich dich in Erinnerung hatte, junge Dame.","story.map5-dungeon7.013":"Pff, <wait=40>du alter Fiesling...","story.map5-dungeon7.014":"Ho ho ho.","story.map5-dungeon7.015":"Jedenfalls, <wait=40><rep_handlename>...","story.map5-dungeon7.016":"Du hast es auch bemerkt, nicht wahr? <wait=40>Die böse Präsenz da vorne...","story.map5-dungeon7.017":"Ja, <wait=40>ich sehe es dir an.","story.map5-dungeon7.018":"Nun denn, <wait=40>dann tue ich dir den Gefallen und sage dir, was dich erwartet.","story.map5-dungeon7.019":"Gleich da vorne erwartet dich der einstige Herr dieses Schlosses.","story.map5-dungeon7.020":"Der letzte Kaiser des Amdahl-Imperiums, das von Palmyna zerstört wurde. ","story.map5-dungeon7.021":"Jetzt, als Geist, hegt er großen Groll gegen die Menschen.","story.map5-dungeon7.022":"Ein Geist, der Menschen hasst...","story.map5-dungeon7.023":"Ho ho ho.","story.map5-dungeon7.024":"Was hast du denn erwartet?","story.map5-dungeon7.025":"Nicht alles, was hier in Grand Gaia existiert, hat unbedingt mit den Göttern zu tun.","story.map5-dungeon7.026":"Das sieht man leicht, wenn man die Geschichte der Menschen betrachtet...","story.map5-dungeon7.027":"Menschen haben weit mehr ihresgleichen getötet, als die Götter je vernichtet haben.","story.map5-dungeon7.028":"......","story.map5-dungeon7.029":"Ho ho ho.","story.map5-dungeon7.030":"Jedenfalls <wait=40>bin ich für so etwas etwas zu alt, <wait=40>ich mache mich wohl besser auf den Weg.","story.map5-dungeon7.031":"Aber bevor ich gehe: <wait=40>Auch wenn sie eine Göttin ist, hat sie ihre Schwächen.","story.map5-dungeon7.032":"Gib dir Mühe, sie zu beschützen.","story.map5-dungeon7.033":"Hä?<wait=40> Moment mal!","story.map5-dungeon7.034":"Ho ho ho.","story.map5-dungeon7.035":"Er ist weg...","story.map5-dungeon7.036":"Wann hab ich Elder Grah gesagt, dass ich eine Göttin bin?","story.map5-dungeon7.037":"Er weiß so viel, <wait=40>wer um alles in der Welt ist er?","story.map5-dungeon7.038":"Ach, <wait=40>egal!","story.map5-dungeon7.039":"Sich jetzt darüber Sorgen zu machen, bringt nichts! <wait=40>","story.map5-dungeon7.040":"Wir müssen hier durch, bevor wir es mit Cardes aufnehmen können!","story.map5-dungeon7.041":"Also, <rep_handlename>, ich weiß nicht, was ich von dieser ganzen Geistersache halten soll...","story.map5-dungeon7.042":"...aber egal, was es ist, hauen wir es um! <wait=40>Das wird Elder Grah bestimmt überraschen!","story.map5-ending.001":"Du hast es geschafft, <rep_handlename>!","story.map5-ending.002":"Der war ja ein Kinderspiel!","story.map5-ending.003":"Nicht mal die Geister vergangener Kaiser haben gegen dich eine Chance, <rep_handlename>!","story.map5-ending.004":"<size=18>Wow!","story.map5-ending.005":"Wa-!!","story.map5-ending.006":"Hey, <wait=40>warum versuchst du immer, mich zu erschrecken...","story.map5-ending.007":"Verzeih, <wait=40>es ist nur so, dass ich genauso empfinde wie du, Tilith...","story.map5-ending.008":"Auch ich war überrascht, wie <rep_handlename> mit diesem Gespenst fertig wurde.","story.map5-ending.009":"Pff.","story.map5-ending.010":"Ho ho ho.","story.map5-ending.011":"Dass <rep_handlename> jedoch <wait=40>den Geist eines Kaisers einfach so besiegt hat...","story.map5-ending.012":"Hihi, <wait=40>ja?","story.map5-ending.013":"Das heißt, <rep_handlename> ist wirklich ein großartiger Beschwörer, oder?","story.map5-ending.014":"Hm, <wait=40>das war wahrlich ein prächtiges Klingenkreuzen.","story.map5-ending.015":"Ich muss schon sagen, <wait=40>gut gemacht.","story.map5-ending.016":"<size=18><rep_handlename>!<wait=40> Du lebst ja noch!!","story.map5-ending.017":"Keuch... <wait=40>keuch...","story.map5-ending.018":"M-<wait=40>Moment mal...","story.map5-ending.019":"W-<wait=40>Was ist mit diesem Geist passiert?","story.map5-ending.020":"<rep_handlename> hat ihn erledigt!","story.map5-ending.021":"...<wait=40>...","story.map5-ending.022":"<size=14>Pff...<wait=40><br>Kaaaaaarl!!","story.map5-ending.023":"Du hast dir also doch Sorgen um <rep_handlename> gemacht, nicht wahr, Seria!?","story.map5-ending.024":"Du hast wohl doch eine fürsorgliche Seite.","story.map5-ending.025":"D-<wait=40>Das ist es nicht!<wait=40> Ich hab nur gehört, dass Graham hier irgendwo aufgetaucht ist...","story.map5-ending.026":"Na komm, <wait=20>du musst dich nicht hinter so einer offensichtlichen Lüge verstecken.","story.map5-ending.027":"Grr...","story.map5-ending.028":"Ho ho ho.","story.map5-ending.029":"<size=20>!?","story.map5-ending.030":"Ich glaube, wir wurden einander noch nicht vorgestellt.","story.map5-ending.031":"Fräulein Seria, <wait=40>nenn mich bitte Elder Grah.","story.map5-ending.032":"Hä!?<wait=40> E-<wait=40>Elder Grah?","story.map5-ending.033":"Ganz recht.","story.map5-ending.034":"Hä, <wait=40>aber... <wait=40>I-<wait=40>Ich meine...","story.map5-ending.035":"Elder Grah.","story.map5-ending.036":"Merk dir das gut, <wait=40>Fräulein Seria.","story.map5-ending.037":"Elder Grah, <wait=40>du bist wirklich ein seltsamer alter Mann!","story.map5-ending.038":"Du tauchst immer plötzlich an seltsamen Orten auf, <wait=40>und du weißt die abwegigsten Dinge.","story.map5-ending.039":"Und du versuchst ständig, mich zu erschrecken!","story.map5-ending.040":"W-<wait=40>W-<wait=40>Was redest du denn da!?<wait=40> Dieser Mann ist...","story.map5-ending.041":"...Elder Grah, nur ein verspielter alter Mann.","story.map5-ending.042":"Nicht wahr, <wait=40>Fräulein Seria?","story.map5-ending.043":"Hä?<wait=40> Ä-<wait=40>Äh, <wait=20>genau...","story.map5-ending.044":"Ho ho ho.","story.map5-ending.045":"Pff, <wait=40>irgendwas stimmt nicht mit dir, Seria!","story.map5-ending.046":"W-<wait=40>Egal! <wait=40>Mir geht nur einiges durch den Kopf!","story.map5-ending.047":"Was denn?","story.map5-ending.048":"D-<wait=40>Das musst du nicht wissen!","story.map5-ending.049":"Pff, <wait=40>was ist denn los mit dir!","story.map5-ending.050":"Bist du vielleicht sauer, weil Karl dich dazu gebracht hat, uns hinterherzulaufen?","story.map5-ending.051":"W-<wait=40>Was? <wait=20>Woher weißt du das!?","story.map5-ending.052":"Eine Göttin weiß alles!","story.map5-ending.053":"Was bist du denn für eine Göttin!?<wait=40> Du kriegst doch allein nichts hin!","story.map5-ending.054":"Wie gemein von dir!","story.map5-ending.055":"Hey, <rep_handlename>, <wait=40>jetzt hilf mir doch mal und sag was!","story.map5-ending.056":"Wozu?<wait=40> Du weißt doch schon, was <rep_handlename> sagen würde, oder?","story.map5-ending.057":"Ho ho ho.","story.map5-ending.058":"Die Jugend ist so voller Leben.","story.map5-ending.059":"Jedenfalls, <rep_handlename>...","story.map5-ending.060":"Mit dem Sieg über das Gespenst <wait=40>hast du die Barriere über dieser Region gebrochen.","story.map5-ending.061":"Bald wird sich der Weg nach Encervis öffnen.","story.map5-ending.062":"Dort sollte Zebra auf dich warten...","story.map5-ending.063":"...der Dämon, der den Palmyna-Archipel derzeit an Cardes\' Stelle beherrscht.","story.map5-ending.064":"Trainiere hart und lass dir deinen Stolz nicht im Weg stehen.","story.map5-ending.065":"Ah!<wait=40> Das wollte ich gerade sagen!","story.map5-ending.066":"Alles, was du sagst, ist dämlich, <wait=40>überlass das lieber Grahde...","story.map5-ending.067":"Elder Grah! Überlass es Elder Grah!","story.map5-ending.068":"Dämlich, sagst du!?","story.map5-ending.069":"Was ist so schlimm daran, dir zu sagen, was du wirklich bist?","story.map5-ending.070":"Jetzt reicht\'s!<wait=40> Ich zeig dir die wahre Macht einer Göttin!","story.map5-ending.071":"Nur zu!<wait=50> Ich zeig dir, wie viel stärker ich bin als du!","story.map5-ending.072":"<size=20>Mach dich auf was gefasst!!","story.map5-ending.073":"Ho ho ho.","story.map5-ending.074":"Ihr seid ja ein ganz schön hitzköpfiges Paar junger Damen.","story.map5-ending.075":"Jedenfalls, <wait=40><rep_handlename>...","story.map5-ending.076":"Wir sollten uns auf den Rückweg nach Elgaia machen.","story.map5-ending.077":"<rep_handlename>! <wait=40>Warte kurz!","story.map5-ending.078":"Ich habe eine Nachricht von Karl!","story.map5-ending.079":"Er sagt: \\"Ich glaube an deine Stärke.\\"","story.map5-ending.080":"Ist das jetzt wirklich der richtige Zeitpunkt dafür!?","story.map5-ending.081":"<rep_handlename>!","story.map5-ending.082":"Gehen wir nach Encervis, nachdem ich Seria eine kleine Lektion in Respekt erteilt habe!","story.map5-ending.083":"Wenn du glaubst, dass du mich schlagen kannst, <wait=40>dann versuch\'s doch!","story.map5-ending.084":"Jetzt reicht\'s!!<wait=40> Jetzt zeig ich dir meine gewaltige Zauberkraft!","story.map5-ending.085":"Pff, <wait=40>du meinst es also ernst. <wait=40>OK, <wait=40>dann los!","story.map5-ending.086":"<size=20>Nimm das!!","story.map5-ending.087":"Na gut, <wait=40>dann gehen wir wohl...","story.map5-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Du, <rep_handlename>,<wait=40> der Maxwell, die Göttin der Schöpfung, besiegt hat…","story.map5-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Die Krise, die die Vier Gefallenen Götter heraufbeschworen,<wait=40> besteht noch immer…","story.map5-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Um dieser von Trauer durchdrungenen Welt neue Hoffnung zu bringen…","story.map5-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>musst du an deine Kraft glauben <wait=20>und weiter voranschreiten…","story.map5-open.005":"<size=22>Du bist spät dran!","story.map5-open.006":"Was hat denn so lange gedauert!?","story.map5-open.007":"Ich warte schon so lange, lange auf dich, <rep_handlename>!","story.map5-open.008":"Findest du nicht, dass du seit deinem Sieg über Maxwell ein bisschen zu nachlässig geworden bist?","story.map5-open.009":"<size=20>Hihi, <wait=20>reingelegt!!","story.map5-open.010":"Ich hab mit Lucius geredet, <wait=40>bin selbst gerade erst angekommen. ","story.map5-open.011":"Jedenfalls, <wait=40>als Nächstes kommt der Palmyna-Archipel!","story.map5-open.012":"Nachdem ich in St. Lamia gesehen habe, wie stark du wirklich bist...","story.map5-open.013":"...habe ich diesmal große Hoffnungen in dich!","story.map5-open.014":"Geben wir unser Bestes!","story.map5-open.015":"*Klopf* <wait=20>*Klopf*","story.map5-open.016":"Entschuldigt die Störung. ","story.map5-open.017":"Ich habe neue Informationen vom Nachrichtendienst.","story.map5-open.018":"Anscheinend wurde die Barriere, die den Palmyna-Archipel schützt, durchbrochen. ","story.map5-open.019":"...<wait=40>Ja, <wait=40>ich habe den Bericht vor Kurzem erhalten. ","story.map5-open.020":"Sie scheinen immer ehrgeiziger zu werden. ","story.map5-open.021":"Ich werde sofort nachforschen.","story.map5-open.022":"Nein, <wait=40>kümmere dich weiter um deine jetzigen Aufgaben. ","story.map5-open.023":"Ich kann nicht zulassen, dass mein geschätzter Untergebener in die Pläne dieser Bande hineingezogen wird. ","story.map5-open.024":"D-<wait=20>Danke...<br>Nun denn, <wait=20>ich sollte mich wieder an die Arbeit machen. ","story.map5-open.025":"Die Vier Gefallenen Götter...","story.map5-open.026":"Man sagt, sie besitzen die Macht, ganz Grand Gaia zu zerstören. ","story.map5-open.027":"Ich würde gern sehen, wie stark sie wirklich sind...","story.map6-dungeon1.001":"Heiß, heiß, heiß!!","story.map6-dungeon1.002":"Warum ist es hier überall so glühend heiß!","story.map6-dungeon1.003":"Eine kühle Brise ab und zu wäre echt schön!","story.map6-dungeon1.004":"Schau nur, wie sehr ich schwitze!","story.map6-dungeon1.005":"Ich hab\'s dir schon mal gesagt, <wait=40>aber ich hasse heiße Orte!","story.map6-dungeon1.006":"Denk nächstes Mal daran, wenn du einen Treffpunkt aussuchst, <rep_handlename>!","story.map6-dungeon1.007":"Hm, <wait=40>aber so oder so zählt Lord Lucius wirklich auf dich, <rep_handlename>...","story.map6-dungeon1.008":"Ich muss mich wohl selbst auch viel mehr anstrengen als bisher...","story.map6-dungeon1.009":"W-<wait=20>Was soll denn dieses Gesicht!?","story.map6-dungeon1.010":"W-<wait=40>Wie, ich strenge mich nie an!?","story.map6-dungeon1.011":"Grr, <wait=40>du bist so gemein.","story.map6-dungeon1.012":"Du wirst nur deshalb nicht öfter angegriffen, weil ich an deiner Seite bin!","story.map6-dungeon1.013":"Niemand würde es wagen, mir zu nahe zu kommen, <wait=40>alle haben viel zu viel Angst vor meiner großartigen Kraft!","story.map6-dungeon1.014":"Bestimmt haben es sogar jetzt irgendwelche Bösewichte auf dich abgesehen, <rep_handlename>.","story.map6-dungeon1.015":"Hehe, <wait=40>war nur Spaß!","story.map6-dungeon1.016":"Wenn so jemand wirklich in der Nähe wäre, würde ich das auf keinen Fall übersehen!","story.map6-dungeon1.017":"Wenn du diesen unglaublich heißen Ort verlässt, findest du einen See...","story.map6-dungeon1.018":"Gleich dahinter liegt ein wunderschönes Schloss, <wait=40>das wird unser nächster Treffpunkt!","story.map6-dungeon1.019":"Pass bis dahin gut auf dich auf.","story.map6-dungeon1.020":"Und falls du in Schwierigkeiten gerätst, kannst du jederzeit zu deiner wunderschönen Göttin beten!","story.map6-dungeon2.001":"<size=18>*Klirr*","story.map6-dungeon2.002":"<speed=10>He he he...<wait=40> Hätte nie gedacht, dass ich meine Kräfte so einsetzen muss.","story.map6-dungeon2.003":"Du bist wohl wirklich gefährlich.","story.map6-dungeon2.004":"Wie auch immer, ich mache jedem, der meinen Plänen im Weg steht, sofort ein Ende.","story.map6-dungeon2.005":"Ich lösche dich aus dieser Welt, ehe du es überhaupt merkst.","story.map6-dungeon2.006":"Glaubst du wirklich, dass es so leicht wird?","story.map6-dungeon2.007":"!?","story.map6-dungeon2.008":"Obwohl du ein Gott bist, <wait=40>willst du dich so vor einem einsamen Beschwörer aufspielen?","story.map6-dungeon2.009":"Ahh...<wait=40> Du weißt also, wer ich bin.","story.map6-dungeon2.010":"Wie es scheint, bin ich auf einen weiteren unbekannten Faktor gestoßen.","story.map6-dungeon2.011":"Doch das spielt keine Rolle. <wait=40>Was auch immer jetzt geschieht, das Ergebnis bleibt dasselbe.","story.map6-dungeon2.012":"Was ich in Gang gesetzt habe, wird der gesamten Menschheit letztlich ein Ende bereiten.","story.map6-dungeon2.013":"Wa-!? <wait=40>Willst du damit sagen, du hast die Himmelsfestung schon gestartet?","story.map6-dungeon2.014":"...<wait=40>Wer genau bist du?","story.map6-dungeon2.015":"Vielleicht sollte ich mich gleich hier und jetzt um dich kümmern...","story.map6-dungeon2.016":"Ho ho ho.<wait=40> Soll ich es noch einmal sagen?","story.map6-dungeon2.017":"Glaubst du wirklich, dass es so leicht wird?","story.map6-dungeon2.018":"Diese Kraft...<wait=40>...","story.map6-dungeon2.019":"Ich verstehe. <wait=40>Dann musst du also... ","story.map6-dungeon2.020":"Beschwörer, <wait=40>du hast mein Interesse geweckt.","story.map6-dungeon2.021":"Außerdem scheinst du mehr als nur ein paar Götter auf deiner Seite zu haben. ","story.map6-dungeon2.022":"Ich werde deine Schritte noch eine Weile im Auge behalten...","story.map6-dungeon2.023":"Ho ho ho.<wait=40> Wie es scheint, sind wir noch mal davongekommen.","story.map6-dungeon2.024":"Doch <wait=40>die Lage ist weiterhin ernst. ","story.map6-dungeon2.025":"Das war Zebra, <wait=20>Diener von Cardes dem Bösartigen, <wait=40>einem der Vier Gefallenen Götter.","story.map6-dungeon2.026":"Offenbar ist es ihm irgendwie gelungen, die legendäre Himmelsfestung des Amdahl-Imperiums wiederzuerwecken.","story.map6-dungeon2.027":"So etwas braucht diese Welt nicht.","story.map6-dungeon2.028":"So etwas heraufzubeschwören, kann nur zu noch mehr Kämpfen führen.","story.map6-dungeon2.029":"Du willst nach Palmyna, nicht wahr?","story.map6-dungeon2.030":"Wenn du schon Zebra verfolgst, <wait=40>warum zerstörst du nicht gleich auch die Himmelsfestung?","story.map6-dungeon2.031":"Ho ho ho.","story.map6-dungeon2.032":"Was ist denn?<wait=40> Du musst dir keine Sorgen machen.","story.map6-dungeon2.033":"Du hast doch die junge Dame bei dir, nicht wahr?","story.map6-dungeon2.034":"Solange du den Schutz der Göttin hast, <wait=40>sollte dir nichts passieren.","story.map6-dungeon2.035":"Ich bitte dich nur, auf das zu hören, was sie sagt!","story.map6-dungeon2.036":"Hmpf<wait=40>...","story.map6-dungeon2.037":"Wobei,<wait=40> bei euch beiden ist wohl nicht mehr so klar, wer hier wen rettet.","story.map6-dungeon2.038":"Ho ho ho.","story.map6-dungeon2.039":"Ich sollte mich auf den Weg machen.<wait=40> Grüß die junge Dame von mir.","story.map6-dungeon3.001":"Hey, <wait=40><rep_handlename>!","story.map6-dungeon3.002":"Ich hab schon gewartet.","story.map6-dungeon3.003":"Hm? <wait=40>Was ist passiert?<wait=40> Warum guckst du so finster?","story.map6-dungeon3.004":"Was hast du gesagt!?<wait=40> Zebra hat die Himmelsfestung wiedererweckt!?","story.map6-dungeon3.005":"Wie konnte er nur...","story.map6-dungeon3.006":"Aber Moment mal, <wait=40>was ist eine Himmelsfestung? Ist die wichtig?","story.map6-dungeon3.007":"W-<wait=20>Was soll dieser Blick!? <wait=40>Es gibt Dinge, die selbst Göttinnen nicht wissen!","story.map6-dungeon3.008":"Ho ho ho.","story.map6-dungeon3.009":"Gewiss, für eine Göttin wären solche Waffen der Menschen wohl belanglos.","story.map6-dungeon3.010":"Oh, <wait=40>Elder Grah.","story.map6-dungeon3.011":"Hä? <wait=40>Du versuchst diesmal gar nicht, mich zu erschrecken?","story.map6-dungeon3.012":"Oh, <wait=40>das tut mir leid.","story.map6-dungeon3.013":"Wie es scheint, habe ich die Erwartungen der jungen Dame enttäuscht.","story.map6-dungeon3.014":"Nun denn, <wait=40>erlaube mir, noch einmal von vorn anzufangen.","story.map6-dungeon3.015":"Das ist nicht nötig!","story.map6-dungeon3.016":"Ho ho ho.","story.map6-dungeon3.017":"Übrigens <wait=40>habe ich euch etwas zu erzählen. Würdet ihr mir kurz zuhören?","story.map6-dungeon3.018":"Es ist die Geschichte der legendären „Himmelsfestung“ des Amdahl-Imperiums.","story.map6-dungeon3.019":"Davon hat <rep_handlename> gesprochen, <wait=40>das Ding, das Zebra wiedererweckt hat, oder?","story.map6-dungeon3.020":"Ja, <wait=40>ganz recht.","story.map6-dungeon3.021":"Auch Menschen haben einst versucht, sie wiederzuerwecken.","story.map6-dungeon3.022":"Man weiß nicht, wer sie erschaffen hat, wann sie erschaffen wurde, nicht einmal wie...","story.map6-dungeon3.023":"Im Amdahl-Imperium blieben offenbar nur Anweisungen zu ihrer Bedienung und eine Beschreibung ihrer Fähigkeiten zurück.","story.map6-dungeon3.024":"Lange Zeit galt sie der Kaiserfamilie als unantastbar... ","story.map6-dungeon3.025":"...doch dann beschloss ein Kaiser, sich darüber hinwegzusetzen.","story.map6-dungeon3.026":"Generation um Generation hielt das Amdahl-Imperium sie versiegelt...","story.map6-dungeon3.027":"...bis der letzte Kaiser des Amdahl-Imperiums, Myzelion der Vierte, das Siegel brach...","story.map6-dungeon3.028":"...und mit der Macht der Himmelsfestung die Nachbarländer angriff, um sie unter seine Herrschaft zu bringen. ","story.map6-dungeon3.029":"Inzwischen <wait=20>erfuhr der König von Palmyna von den Plänen des Kaisers.","story.map6-dungeon3.030":"Er flehte Myzelion den Vierten an, doch der blieb stur und gab nicht nach. ","story.map6-dungeon3.031":"Am Ende <wait=20>unterwarf der König von Palmyna Amdahl mit seiner Macht...","story.map6-dungeon3.032":"...und zerschlug es, bevor es die Himmelsfestung wiedererwecken konnte. ","story.map6-dungeon3.033":"Ähm, <wait=40>also im Grunde...","story.map6-dungeon3.034":"Die Himmelsfestung ist so gefährlich, dass es sich lohnt, ein ganzes Land zu vernichten, damit sie nicht wiedererweckt wird?","story.map6-dungeon3.035":"Ja, <wait=40>ganz genau.","story.map6-dungeon3.036":"Nicht im Ernst!?<wait=40> Und genau die hat Zebra wieder zum Leben erweckt!?","story.map6-dungeon3.037":"Genau.","story.map6-dungeon3.038":"Dann stecken wir ja in großen Schwierigkeiten!!","story.map6-dungeon3.039":"Trotzdem <wait=40>hat das nichts mit unserem Ziel zu tun!","story.map6-dungeon3.040":"<rep_handlename>!<wait=40> Bleiben wir an Cardes dran!","story.map6-dungeon3.041":"Und du, Elder Grah, <wait=40>kannst ja die Himmelsfestung erledigen!","story.map6-dungeon3.042":"Hä!?<wait=40> Junge Dame, das wäre doch wohl unmöglich.","story.map6-dungeon3.043":"Solltest nicht lieber du dich dieser Herausforderung stellen?","story.map6-dungeon3.044":"Ehhh, <wait=40>aber ich krieg Ärger, wenn wir vom Weg abweichen...","story.map6-dungeon3.045":"Keine Sorge!","story.map6-dungeon3.046":"Die Himmelsfestung liegt auf dem Weg nach Palmyna, <wait=40>ihr müsst nur immer geradeaus gehen!","story.map6-dungeon3.047":"Würdet ihr euch also für mich darum kümmern?<wait=40> Betrachtet es als Wunsch eines alten Mannes am Ende seines Lebens.","story.map6-dungeon3.048":"Hey, <wait=40><rep_handlename>!","story.map6-dungeon3.049":"Würdet ihr mir hier aushelfen?","story.map6-dungeon3.050":"Na schön, <wait=40>mir bleibt wohl keine Wahl.","story.map6-dungeon3.051":"Wenn du so ein Theater darum machst, können wir es ja versuchen...","story.map6-dungeon3.052":"...aber du hilfst uns trotzdem, oder, Elder Grah?","story.map6-dungeon3.053":"Ho ho ho,<wait=40> bist du sicher, dass ich mitkommen soll?","story.map6-dungeon3.054":"Hehe, <wait=40>na klar!","story.map6-dungeon3.055":"Außerdem darf nur ich <rep_handlename> um etwas bitten!","story.map6-dungeon3.056":"Ahh, <wait=40>verstehe.","story.map6-dungeon3.057":"Ho ho ho. <wait=40>Verzeih mir jede Unhöflichkeit meinerseits.","story.map6-dungeon3.058":"Ich werde mein Bestes geben, alter Mann, der ich bin.","story.map6-dungeon3.059":"Lebt wohl, <rep_handlename>!<wait=40> Wir sehen uns in der Himmelsfestung!","story.map6-dungeon3.060":"Hm, <wait=40>ich glaube, Elder Grah ist viel stärker, als er zugibt. <wait=20>Was meinst du?","story.map6-dungeon3.061":"Ach, <wait=40>hat sowieso nichts mit uns zu tun!","story.map6-dungeon3.062":"Also gut!<wait=40> Machen wir uns auf zur Himmelsfestung!","story.map6-dungeon4.001":"......<wait=40>Deine Art, Dinge anzugehen, ist umständlich wie eh und je.","story.map6-dungeon4.002":"Das ist Cardes\' Gebiet.<wait=40> Ich bewege mich, wie es mir beliebt.","story.map6-dungeon4.003":"Heh, <wait=40>mir soll\'s recht sein. <wait=40>Ich würde gern sehen, wozu du wirklich fähig bist, Zebra.","story.map6-dungeon4.004":"Welch ein Pech dieser Beschwörer und sein Gefolge doch haben...","story.map6-dungeon4.005":"Sie ahnen nicht, dass der Gott, den sie im Visier haben, einst Zehntausende Menschen begraben hat.","story.map6-dungeon4.006":"...<wait=40>...<wait=40>Diese Präsenz.","story.map6-dungeon4.007":"Wie es scheint, sind sie eingetroffen.","story.map6-dungeon4.008":"Hmpf...","story.map6-dungeon4.009":"Du hast wohl auch Pech.","story.map6-dungeon4.010":"Ich werde deine Ehre verteidigen<wait=40> und dafür sorgen, dass sie diesen Ort verlassen.","story.map6-dungeon4.011":"Komm schon, <rep_handlename>!<wait=40> Beeil dich!","story.map6-dungeon4.012":"Hä? <wait=40>Wo ist es hin?","story.map6-dungeon4.013":"Diese unheilvolle Präsenz kam ganz sicher aus dieser Gegend...","story.map6-dungeon4.014":"<rep_handlename>!<wait=40> Das liegt nur daran, dass du den ganzen Weg hierher getrödelt hast.","story.map6-dungeon4.015":"Wie auch immer, fühlt es sich hier nicht seltsam an?<wait=40> Ich spüre überhaupt niemanden mehr...","story.map6-dungeon4.016":"Ich bin sicher, ich habe vorhin die Präsenz eines Gottes gespürt...","story.map6-dungeon4.017":"Hab ich mir das vielleicht nur eingebildet?","story.map6-dungeon4.018":"Hm, <wait=40>na ja, so oder so sollten wir uns auf den Weg zur Himmelsfestung machen!","story.map6-dungeon4.019":"Auf zur Gadillian-Schlucht!","story.map6-dungeon5.001":"<size=18>Hey!<wait=40> <rep_handlename>!","story.map6-dungeon5.002":"Keuch, keuch, keuch.<wait=40> Endlich hab ich dich gefunden...","story.map6-dungeon5.003":"Seria!<wait=40> Hier drüben!","story.map6-dungeon5.004":"Keuch, keuch, keuch, keuch.<wait=40> Wer hätte gedacht, dass du es so weit schaffst...","story.map6-dungeon5.005":"Du Dummkopf!<wait=40> Sei nächstes Mal irgendwo, wo man dich leichter findet!","story.map6-dungeon5.006":"Das ist doch wohl unmöglich...","story.map6-dungeon5.007":"Puh. <wait=40>Aber ehrlich gesagt haben wir überall nach dir gesucht.","story.map6-dungeon5.008":"Wir dachten, du wärst vielleicht noch irgendwo bei Schloss Avenia...","story.map6-dungeon5.009":"...aber wie es aussieht, hast du es auch schon nach Encervis geschafft.","story.map6-dungeon5.010":"Du bist so eine Plage.","story.map6-dungeon5.011":"Warum müssen die Dämonenjäger nach so einem Idioten wie dir suchen?","story.map6-dungeon5.012":"Wir von der Beschwörerhalle sollten uns um die Angelegenheiten der Beschwörerhalle kümmern.","story.map6-dungeon5.013":"Uns plötzlich zu bitten, <rep_handlename> zu unterstützen – was denken die sich nur?","story.map6-dungeon5.014":"Genug davon.","story.map6-dungeon5.015":"Wir können nichts an der Lage ändern, in der wir gelandet sind.","story.map6-dungeon5.016":"Die Himmelsfestung aufzuhalten hat Vorrang vor Graham. <wait=20>Das weißt sogar du, oder, Seria?","story.map6-dungeon5.017":"Ich weiß, ich weiß!","story.map6-dungeon5.018":"Ich hasse es nur, dass <rep_handlename> an diesem Plan beteiligt ist!","story.map6-dungeon5.019":"Haha, <wait=40>das sieht dir ähnlich, Seria.","story.map6-dungeon5.020":"Aber ich sag es noch mal: <wait=40>Wir sind hier, um Zebra aufzuhalten. ","story.map6-dungeon5.021":"Wir dürfen nicht zulassen, dass er Elgaia mit der Himmelsfestung angreift.","story.map6-dungeon5.022":"Ich weiß, es war bis jetzt ein harter Kampf, <wait=40>aber von hier an müssen wir uns noch ein bisschen mehr ins Zeug legen!","story.map6-dungeon5.023":"...Was ist?","story.map6-dungeon5.024":"Hä? <wait=40>Du hast nichts davon gehört? <wait=50>Ist das dein Ernst??","story.map6-dungeon5.025":"*Seufz* <wait=40>Wie peinlich...","story.map6-dungeon5.026":"Ich muss ja wie ein Narr aussehen, wie ich mich hier ganz allein aufrege!","story.map6-dungeon5.027":"Da hat jemand in der Beschwörerhalle wohl ordentlich geschlampt!","story.map6-dungeon5.028":"Wie traurig. <wait=40>Dabei sollten wir in höchster Alarmbereitschaft sein.","story.map6-dungeon5.029":"Ich dachte, du hättest dieselben Informationen bekommen wie wir...","story.map6-dungeon5.030":"Vielleicht hat er einfach falsche Informationen bekommen?","story.map6-dungeon5.031":"Das passt so gar nicht zur Beschwörerhalle.","story.map6-dungeon5.032":"Da hast du wohl recht...","story.map6-dungeon5.033":"Jedenfalls <wait=40>muss ich es dir wohl selbst erzählen.","story.map6-dungeon5.034":"Du bist hinter Zebra her, der die Himmelsfestung wiedererweckt hat, <wait=40>stimmt\'s?","story.map6-dungeon5.035":"Na gut, <wait=40>das weißt du wenigstens.","story.map6-dungeon5.036":"Die Himmelsfestung <wait=40>ist wahrlich ein böses Ding. ","story.map6-dungeon5.037":"Wenn sie voll einsatzbereit wäre...","story.map6-dungeon5.038":"...<wait=40>könnte Zebra mit ihr durch Lucius’ Tor fliegen und Elgaia angreifen.","story.map6-dungeon5.039":"Deshalb hat sogar die Führung der Beschwörerhalle den Notstand anerkannt...","story.map6-dungeon5.040":"Und sie hat alle Beschwörer in der Nähe der Himmelsfestung um Hilfe gebeten...","story.map6-dungeon5.041":"Dich eingeschlossen, <rep_handlename>.","story.map6-dungeon5.042":"Auch wenn wir Dämonenjäger das alles allein erledigen könnten...","story.map6-dungeon5.043":"...seit du Maxwell besiegt hast, besteht Karl darauf, dass auch ich deine Fähigkeiten anerkenne...","story.map6-dungeon5.044":"Diesmal helfen wir dir, <wait=40>also sei gefälligst dankbar!","story.map6-dungeon5.045":"Ha ha ha.","story.map6-dungeon5.046":"Wie dem auch sei, <wait=40>du musst einfach weiter der Himmelsfestung nachjagen wie bisher. ","story.map6-dungeon5.047":"Wir unterstützen dein Vorankommen, indem wir uns um alle Hindernisse kümmern, die sich auftun. ","story.map6-dungeon5.048":"Ehrlich gesagt <wait=40>ziehen wir hier den Kürzeren.","story.map6-dungeon5.049":"Das zahlst du uns hinterher gefälligst zurück!","story.map6-dungeon5.050":"Laut Informationen der Akras-Beschwörerhalle...","story.map6-dungeon5.051":"...erreichen wir die Himmelsfestung, wenn wir das Land der Toten vor uns durchqueren. ","story.map6-dungeon5.052":"Wir machen dir den Weg frei.","story.map6-dungeon5.053":"Du gehst einfach weiter, die Himmelsfestung fest im Blick!","story.map6-dungeon5.054":"Packen wir\'s an, Seria!","story.map6-dungeon5.055":"Hey, <wait=40>Karl, <wait=20>warte auf mich!","story.map6-dungeon5.056":"<rep_handlename>!","story.map6-dungeon5.057":"Sorg dafür, dass diese Göttin auch mithilft! <wait=40>Verstanden?","story.map6-dungeon5.058":"Ehrlich, <wait=40>warum mache ich mir überhaupt Sorgen um so ein Gör wie dich...","story.map6-dungeon6.001":"Ah! <wait=40>Da bist du ja!","story.map6-dungeon6.002":"<rep_handlename>!<wait=40> Hier drüben!","story.map6-dungeon6.003":"Dieser Ort ist mir echt unheimlich...","story.map6-dungeon6.004":"Warum sind die Orte, über die die Vier Gefallenen Götter herrschen, nur so gruselig...","story.map6-dungeon6.005":"Du musst Licht in diese Gegenden bringen, <rep_handlename>!","story.map6-dungeon6.006":"Oh, <wait=40>heute habe ich ganz besondere Infos für dich!","story.map6-dungeon6.007":"Ich erzähl dir, wie wir zur Himmelsfestung kommen. ","story.map6-dungeon6.008":"Hör gut zu, wenn deine hübsche kleine Göttin es dir erklärt!","story.map6-dungeon6.009":"Zuerst mal: <wait=40>Der richtige Name der Himmelsfestung ist Solaris. ","story.map6-dungeon6.010":"Wie lange sie schon in der Gegend ist, konnte ich nicht herausfinden...","story.map6-dungeon6.011":"...aber anscheinend schwebt sie gleich hinter dem Land der Toten am Himmel.","story.map6-dungeon6.012":"Haha, <wait=40>ich wusste, dass dich das überrascht. ","story.map6-dungeon6.013":"Du fragst dich bestimmt: „Wie sollen wir denn in den Himmel kommen?“, stimmt\'s?","story.map6-dungeon6.014":"Überlass das der Göttin!","story.map6-dungeon6.015":"Sobald du hier durch bist und dich zur Himmelsfestung aufmachst...","story.map6-dungeon6.016":"...schicke ich dich mit meinen besonderen Kräften nach oben!","story.map6-dungeon6.017":"Hehe, <wait=40>was würdest du nur ohne mich machen?","story.map6-dungeon6.018":"Du darfst mir so viel danken, wie du willst!","story.map6-dungeon6.019":"Aber werd nicht leichtsinnig!","story.map6-dungeon6.020":"Da vorne soll ein supergruseliges Mädchen sein, das ein ordentliches Gemetzel einfach liebt...","story.map6-dungeon6.021":"Ich gehe schon mal zur Himmelsfestung vor, <rep_handlename>, <wait=40>also lass dir nicht zu viel Zeit!","story.map6-dungeon6.022":"U-<wait=40>Und glaub ja nicht, dass ich nur vorgehe, weil ich Angst habe, kapiert!?","story.map6-dungeon7.001":"Wir haben es geschafft!","story.map6-dungeon7.002":"Ich hab dich direkt mitten in die Himmelsfestung gebracht!","story.map6-dungeon7.003":"Ich bin schon ziemlich toll, oder?","story.map6-dungeon7.004":"Autsch... <wait=40>Wo genau sind wir?","story.map6-dungeon7.005":"Mir ist <wait=40>schwindelig...","story.map6-dungeon7.006":"Wir haben doch gerade noch im Land der Toten gegen Dämonen gekämpft, oder?","story.map6-dungeon7.007":"Ah! <wait=40>Karl!","story.map6-dungeon7.008":"Und deine kleine Freundin Seria!","story.map6-dungeon7.009":"Was soll das heißen, „kleine Freundin“!?","story.map6-dungeon7.010":"Wenn das nicht <rep_handlename> ist!","story.map6-dungeon7.011":"Aber wenn du hier bist, <wait=40>dann heißt das ja...","story.map6-dungeon7.012":"Wir sind in der Himmelsfestung!","story.map6-dungeon7.013":"...<wait=40>Sieht ganz so aus.","story.map6-dungeon7.014":"<size=18>Wie dumm bist du eigentlich!?","story.map6-dungeon7.015":"Es ist doch ganz allein deine Schuld, dass wir hier oben sind, oder!?","story.map6-dungeon7.016":"Siehst du nicht, dass da unten alle noch kämpfen?","story.map6-dungeon7.017":"Du solltest dir etwas mehr Zeit nehmen, die Lage zu erfassen, bevor du handelst, Göttin!","story.map6-dungeon7.018":"W-<wait=40>Wovon redest du? <wait=40>Ich hab doch nichts falsch gemacht...","story.map6-dungeon7.019":"Du musst ja ganz schön eingebildet sein, so etwas zu sagen!","story.map6-dungeon7.020":"Können wir es nicht einfach dabei belassen? Wir haben doch viel wichtigere Probleme, oder nicht?","story.map6-dungeon7.021":"Außerdem können wir <rep_handlename> jetzt leichter unterstützen.","story.map6-dungeon7.022":"Und überhaupt, <wait=40>es macht für die, die unten noch kämpfen, kaum einen Unterschied, ob wir zwei fehlen.","story.map6-dungeon7.023":"Da hast du wohl recht, aber...","story.map6-dungeon7.024":"Jedenfalls <wait=40>bist du so eine großartige Göttin wie eh und je.","story.map6-dungeon7.025":"Trotz der gefährlichen Lage, in der wir stecken, hast du uns die Sache ein bisschen leichter gemacht. ","story.map6-dungeon7.026":"Wenn sich jemand etwas vornimmt und es durchzieht, <wait=40>dann wusste ich, dass du es sein musst.","story.map6-dungeon7.027":"Da liegst du völlig falsch, Karl!<wait=40> Du bist zu gutgläubig!","story.map6-dungeon7.028":"Haha...","story.map6-dungeon7.029":"<size=18>!?<wait=40> Wer ist da!?","story.map6-dungeon7.030":"<speed=10>Ah...","story.map6-dungeon7.031":"<speed=10>Wie es scheint, könnt sogar ihr Menschen meine Präsenz spüren.","story.map6-dungeon7.032":"Zebra!!","story.map6-dungeon7.033":"Das ist Zebra, der wahnsinnige Gott... <wait=40>Vorsicht, er ist so gefährlich, wie er aussieht...","story.map6-dungeon7.034":"Du wirst für das bezahlen, was du in Edila getan hast!","story.map6-dungeon7.035":"Mach dich auf was gefasst!","story.map6-dungeon7.036":"Mit euch erbärmlichen Würmern kann ich nichts anfangen.","story.map6-dungeon7.037":"Ich bin hinter <wait=40>Tilith her, der Schülerin von Lucius.","story.map6-dungeon7.038":"<size=18>Da bist du ja!","story.map6-dungeon7.039":"<size=18>*Bonk*","story.map6-dungeon7.040":"Kyaahh!!","story.map6-dungeon7.041":"Du wirkst erschöpft.<wait=40> Kein Wunder, du hast ja so viel Kraft aufgewandt, um sie hierherzubringen.","story.map6-dungeon7.042":"Du hast dir für diese erbärmlichen Würmer ganz schön viel zugemutet.","story.map6-dungeon7.043":"Wenn du einen Kampf zwischen Göttern willst, würde Lucius dich bestimmt aufhalten...","story.map6-dungeon7.044":"...aber wenn du vorhast, uns jetzt anzugreifen, werde ich dich nicht schonen!","story.map6-dungeon7.045":"<size=18>Ihr alle, tretet zurück!","story.map6-dungeon7.046":"Was ist das für eine Kraft...<wait=40> Ugh...<wait=40>Ich kann mich nicht bewegen...","story.map6-dungeon7.047":"Gyah...<wait=40> Wie kannst du nach all dem noch solche Kraft haben...<wait=40> Könnte es sein...","story.map6-dungeon7.048":"Keuch... keuch... ","story.map6-dungeon7.049":"Ich bin jetzt vielleicht etwas geschwächt...<wait=40> aber gegen dich verliere ich auf keinen Fall...","story.map6-dungeon7.050":"<size=18>Glaub ja nicht, dass du mich zum Narren halten kannst! <wait=40>Du bist doch nur Lucius\' Schoßhündchen!!","story.map6-dungeon7.051":"<size=18>Kyaaahh!!","story.map6-dungeon7.052":"<size=20>Tilith!!","story.map6-dungeon7.053":"Nngh... <wait=40>Sie hat sich heftiger gewehrt, als ich erwartet hatte...","story.map6-dungeon7.054":"Doch das spielt jetzt keine Rolle mehr. <wait=40>Ich habe beseitigt, was mir im Weg stand. ","story.map6-dungeon7.055":"Es sind keine Götter mehr da, die euch beschützen.","story.map6-dungeon7.056":"Ihr werdet meinen Untergebenen eine gute Übung sein. ","story.map6-dungeon7.057":"Glaubst du, wir lassen dich einfach entkommen?","story.map6-dungeon7.058":"Eure Absichten kümmern mich nicht.","story.map6-dungeon7.059":"Ihr erbärmlichen Würmer seid in meiner Gegenwart nicht einmal zu einem einzigen Schritt fähig.","story.map6-dungeon7.060":"Ich benutze diese Himmelsfestung einzig und allein, um Lord Cardes von seinen Fesseln zu befreien.","story.map6-dungeon7.061":"Wenn ihr mir wirklich entschlossen entgegentreten wollt, <wait=40>dann findet ihr mich tief im Inneren, wo ich euch erwarte. ","story.map6-dungeon7.062":"Ich werde euch alle die Furcht vor den Göttern lehren!","story.map6-dungeon7.063":"<size=18>Halt!!","story.map6-dungeon7.064":"Verdammt! <wait=40>Er ist entkommen!","story.map6-dungeon7.065":"<size=18>Karl!!","story.map6-dungeon7.066":"<size=18>Was zum!?<wait=40> Wo kommen all diese Monster her!?","story.map6-dungeon7.067":"N-<wait=40>Nngh...","story.map6-dungeon7.068":"E-<wait=40>Es tut mir leid...<wait=40> <rep_handlename>...","story.map6-dungeon7.069":"Hör auf zu reden!<wait=40> Du musst deine Kräfte schonen!","story.map6-dungeon7.070":"Karl, <wait=40>du weißt, was wir zu tun haben!","story.map6-dungeon7.071":"Ja! <wait=40><rep_handlename>!","story.map6-dungeon7.072":"Du verfolgst Zebra. <wait=20>Seria und ich kümmern uns um alles hier!","story.map6-dungeon7.073":"Ich habe keine Ahnung, wie er diese Festung einsetzen will...","story.map6-dungeon7.074":"...aber wenn es ihm gelingt, Cardes zu befreien, stecken wir in großen Schwierigkeiten!","story.map6-dungeon7.075":"Steh nicht so rum, <wait=40>beweg dich endlich!","story.map6-dungeon7.076":"Glaubst du, solche Monster sind eine Herausforderung für uns?","story.map6-dungeon7.077":"Wie kannst du es wagen, am Anführer der Dämonenjäger zu zweifeln!","story.map6-dungeon7.078":"Wenn du Zeit für solch unnötige Sorgen hast, <wait=40>dann hör auf zu trödeln und jag ihm nach!","story.map6-dungeon7.079":"Außerdem <wait=40>weißt gerade du doch, dass diese Göttin noch kämpfen kann, oder?","story.map6-dungeon7.080":"Richtig, Seria.","story.map6-dungeon7.081":"Diese Monster sind keine Bedrohung für uns.","story.map6-dungeon7.082":"Und mach dir keine Sorgen um die Göttin, sie steht jetzt unter unserem Schutz.","story.map6-dungeon7.083":"Also geh jetzt <wait=40>und besiege diesen niederträchtigen Zebra!","story.map6-dungeon7.084":"Wir zählen auf dich, <rep_handlename>!","story.map6-dungeon7.085":"Zeig uns, was für ein Beschwörer du wirklich bist!","story.map6-dungeon7.086":"Seria!!","story.map6-dungeon7.087":"Jawohl!","story.map6-dungeon7.088":"<speed=20><size=20>Los geht\'s!!","story.map6-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_clear.002":"Du hast es geschafft, <rep_handlename>!","story.map6-dungeon_ex_clear.003":"Du hast die Kreatur erledigt, noch bevor unsere Logistikoffiziere dort ankamen.","story.map6-dungeon_ex_clear.004":"Ich wusste, dass du das schaffst, Herr!","story.map6-dungeon_ex_clear.005":"Ah, <wait=20>aber anscheinend wollen sie trotzdem zu diesen Ruinen.","story.map6-dungeon_ex_clear.006":"Offenbar beherbergten diese Ruinen ursprünglich etwas Gigantisches.","story.map6-dungeon_ex_clear.007":"Es wirkt wie eine Art Schiffswerft, aber das war wohl die einzige Möglichkeit.","story.map6-dungeon_ex_clear.008":"Hm? <wait=40>Ist dir drinnen etwas aufgefallen, Herr?","story.map6-dungeon_ex_clear.009":"Übrigens gibt es anscheinend Aufzeichnungen, nach denen Valmodora auch im Krieg der Götter aufgetaucht ist.","story.map6-dungeon_ex_clear.010":"Selbst damals hauste es wohl in irgendwelchen Ruinen.","story.map6-dungeon_ex_clear.011":"Allerdings soll es von einem gewissen Krieger vernichtet worden sein.","story.map6-dungeon_ex_clear.012":"Bestimmt gehst du mit deiner Tat auch in die Geschichte ein.","story.map6-dungeon_ex_clear.013":"Aber trotzdem, <wait=20>sei in Zukunft nicht mehr so leichtsinnig!","story.map6-dungeon_ex_clear.014":"Aber du gehst sowieso, egal was ich sage, oder?","story.map6-dungeon_ex_clear.015":"Ich mache mir wirklich große Sorgen um dich, weißt du!","story.map6-dungeon_ex_clear.016":"......","story.map6-dungeon_ex_clear.017":"Hehe, <wait=20>es ist lange her, dass ich diesen ratlosen Blick in deinem Gesicht gesehen habe.","story.map6-dungeon_ex_clear.018":"Jedenfalls, bitte setz deine Untersuchungen in anderen Gebieten fort!","story.map6-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_open.002":"Hörst du mich, <wait=40>Herr Beschwörer?","story.map6-dungeon_ex_open.003":"<size=20><rep_handlename>!</size>","story.map6-dungeon_ex_open.004":"Hörst du mich?","story.map6-dungeon_ex_open.005":"Lin Merylham von der Logistikunterstützung...","story.map6-dungeon_ex_open.006":"...des Ermittlungsbüros im Vermessungsamt von Grand Gaia, zu deinen Diensten.","story.map6-dungeon_ex_open.007":"Ich melde mich heute mit neuen Informationen.","story.map6-dungeon_ex_open.008":"Die Beschwörerhalle hat in den alten Ruinen in Encervis eine erschreckende Entdeckung gemacht.","story.map6-dungeon_ex_open.009":"Offenbar hat sich dort eine unglaublich gefährliche Kreatur eingenistet.","story.map6-dungeon_ex_open.010":"Im Moment <wait=20>scheint alles ruhig zu sein.","story.map6-dungeon_ex_open.011":"Allerdings scheint sie Kraft aus den umliegenden Ruinen zu ziehen, um ihr Revier auszuweiten.","story.map6-dungeon_ex_open.012":"Wir schicken bald wieder unsere Logistikoffiziere hin, also halt dich bis dahin bitte fern!","story.map6-dungeon_ex_open.013":"......","story.map6-dungeon_ex_open.014":"W-<wait=20>Wie bitte, Herr? <wait=40>Du bist schon dort?","story.map6-dungeon_ex_open.015":"Hmpf, <wait=40>Herr, du bist zu leichtsinnig!","story.map6-dungeon_ex_open.016":"Aber du gehst sowieso, egal was ich sage, oder?","story.map6-dungeon_ex_open.017":"Verstanden!","story.map6-dungeon_ex_open.018":"Ich werde nicht versuchen, dich aufzuhalten!","story.map6-dungeon_ex_open.019":"Das Monster, das dich drinnen erwartet, heißt Valmodora.","story.map6-dungeon_ex_open.020":"Es scheint ein ziemlich großes Monster zu sein, also sei bitte besonders vorsichtig.","story.map6-dungeon_ex_open.021":"Ich mache mir immer solche Sorgen um dich, <wait=20>weißt du...","story.map6-ending.001":"<speed=10>D-<wait=40>Du Narr...","story.map6-ending.002":"<speed=10>T-<wait=40>Typisch Mensch...","story.map6-ending.003":"Gyah!<wait=40> <speed=10>Als Schüler...<wait=40> von Lord Cardes...","story.map6-ending.004":"<speed=10>k-<wait=40>kann ich n-nicht..<wait=40> so leicht...<wait=40> besiegt werden...","story.map6-ending.005":"<speed=10>Nngh...<wait=40> Mir bleibt keine Wahl...","story.map6-ending.006":"<speed=10>Ich bringe die Himmelsfestung zum Absturz, <wait=40>und ich nehme euch alle mit!!","story.map6-ending.007":"<size=18>*Klirr*","story.map6-ending.008":"<size=18>D-<wait=40>Duuuuuuu!!","story.map6-ending.009":"Selbst ein Gott muss wissen, wann es genug ist.","story.map6-ending.010":"Wer das nicht weiß, ist wohl kaum mehr als ein zweitklassiger Dämon, würde ich meinen.","story.map6-ending.011":"Du solltest dir etwas Zeit nehmen, darüber nachzudenken. ","story.map6-ending.012":"<size=18>Gwaaaahhh!!","story.map6-ending.013":"Hm!?","story.map6-ending.014":"Was soll der überraschte Blick?","story.map6-ending.015":"Egal, <wait=40>ruf schnell die junge Dame herbei.","story.map6-ending.016":"Jetzt, wo Zebra fort ist, <wait=40>wird die Himmelsfestung wohl wieder verschlossen.","story.map6-ending.017":"Hm!? <wait=40>Dieses Licht...","story.map6-ending.018":"<speed=10>Kommt das etwa... <wait=40>vom Aldela-See?","story.map6-ending.019":"<size=18><rep_handlename>!!","story.map6-ending.020":"Auaaa...<wait=40> Wohin wurden wir diesmal geschleudert?","story.map6-ending.021":"<rep_handlename>!!","story.map6-ending.022":"...<wait=40>...<wait=40>Du hast es geschafft!","story.map6-ending.023":"Du bist echt unglaublich, wirklich!","story.map6-ending.024":"Nngh, <wait=40>das hat meinem Hintern wehgetan...","story.map6-ending.025":"Hey du!<wait=40> Wie wär\'s nächstes Mal mit einer sanfteren Landung!","story.map6-ending.026":"Ho ho ho.","story.map6-ending.027":"Bei einem so großen Hintern sollte das doch kein Problem sein, findest du nicht, Seria?","story.map6-ending.028":"Gr-<wait=40>Grahde...<wait=40> Elder Grah!<wait=40> Was machst du überhaupt hier!?","story.map6-ending.029":"Elder Grah?<wait=40> Was ist denn das für ein Name?","story.map6-ending.030":"Moment mal, <wait=40>bist du nicht Grahdens?","story.map6-ending.031":"Was macht ein Ältester Beschwörer wie du an so einem Ort?","story.map6-ending.032":"Wie kannst du nur, <wait=40>du Narr!","story.map6-ending.033":"Und dabei <wait=40>hatte Tilith mich endlich als netten alten Mann gesehen...","story.map6-ending.034":"Und jetzt tauchst du auf und machst alles kaputt!","story.map6-ending.035":"Hä?<wait=40> Was soll das heißen, „netter alter Mann“?","story.map6-ending.036":"Als einer der Leiter der Beschwörerhalle<wait=40> solltest du nicht dort arbeiten!?","story.map6-ending.037":"Hm, <wait=40>ich verstehe nicht ganz, was hier los ist, <wait=40>aber anscheinend war Elder Grah die ganze Zeit ziemlich wichtig.","story.map6-ending.038":"Er ist nicht nur der seltsame alte Mann, als den wir ihn kennengelernt haben...","story.map6-ending.039":"Hey, <wait=40>jetzt, wo du weißt, wer Lord Grahdens ist, solltest du ihn mit etwas mehr Respekt behandeln!","story.map6-ending.040":"Aber das hat doch nichts mit mir zu tun...","story.map6-ending.041":"Und außerdem weiß ich nicht, wie ihr das hier in der Menschenwelt seht...","story.map6-ending.042":"...aber wenn du wählen müsstest, wäre ich als Göttin doch wohl wichtiger, oder?","story.map6-ending.043":"Du solltest mich mit mehr Respekt behandeln, Seria!","story.map6-ending.044":"Wenn du das so siehst, warum benimmst du dich dann nicht mal mehr wie eine Göttin?","story.map6-ending.045":"Worauf willst du hinaus!?","story.map6-ending.046":"Beruhigt euch, <wait=40>wollt ihr wirklich streiten, obwohl <rep_handlename> gerade Zebra besiegt hat?","story.map6-ending.047":"Ho ho ho.","story.map6-ending.048":"Seria, <wait=40>es ist genau so, wie Tilith sagt.","story.map6-ending.049":"Verglichen mit den Göttern <wait=40>ist mein Dasein recht unbedeutend. ","story.map6-ending.050":"Tilith, <wait=40>ich möchte, dass du mich weiterhin einfach Elder Grah nennst.","story.map6-ending.051":"Das hatte ich sowieso vor.","story.map6-ending.052":"Jetzt weiß ich, wer du wirklich bist, Elder Grah.<wait=40> Du bist anders als die andere Nervensäge, die ich kenne!","story.map6-ending.053":"Von wem redest du da!?","story.map6-ending.054":"Hm, wer weiß...","story.map6-ending.055":"Ehrlich, <wait=40>werdet ihr zwei euch jemals ändern?","story.map6-ending.056":"Jedenfalls, <wait=40>Grahdens...","story.map6-ending.057":"Zurück zu meiner Frage von vorhin: <wait=40>Warum bist du hier?","story.map6-ending.058":"Karl...","story.map6-ending.059":"Du bist auch ein Beschwörer, <wait=40>warum zeigst du mir nicht etwas mehr Respekt?","story.map6-ending.060":"Hör schon auf. <wait=40>Ich lasse nicht zu, dass du schon wieder das Thema wechselst.","story.map6-ending.061":"Ich kenne dich schon lange und bin an deine Art gewöhnt.","story.map6-ending.062":"Ho ho ho.<wait=40> Schonungslos ehrlich wie immer, wie ich sehe.","story.map6-ending.063":"Karl, <wait=40>lass mich die Einzelheiten später erklären.","story.map6-ending.064":"Zuerst muss ich mit <rep_handlename> über etwas sprechen.","story.map6-ending.065":"<rep_handlename>, <wait=40>dafür, dass du Zebra wie erbeten besiegt hast...","story.map6-ending.066":"...spreche ich dir als Ältester Beschwörer der Verteidigungsabteilung der Akras-Beschwörerhalle meinen Dank aus.","story.map6-ending.067":"Hehe, <wait=40>hast du von einem guten Freund von mir etwa weniger erwartet?","story.map6-ending.068":"Ich wusste, dass du das schaffst, mein <rep_handlename>!","story.map6-ending.069":"Hey, <wait=20>hör auf, ihn deinen zu nennen!","story.map6-ending.070":"J-<wait=40>Jedenfalls, da <rep_handlename> Lord Grahdens\' Bitte erfüllt hat...","story.map6-ending.071":"...kann ich es wohl rechtfertigen, dich als Mitbeschwörer zu loben.","story.map6-ending.072":"Wie offen du bist!","story.map6-ending.073":"W-<wait=40>Wovon redest du!?","story.map6-ending.074":"Ho ho ho.<wait=40> Wie es scheint, sind alle recht dankbar für das, was du getan hast.","story.map6-ending.075":"Doch <wait=40>so stark er auch war, <wait=40>vergiss nicht, dass Zebra nur ein Schüler von Cardes war.","story.map6-ending.076":"Zebras Macht ist nichts im Vergleich zu dem gefallenen Gott, den du gerade verfolgst. ","story.map6-ending.077":"In Palmyna <wait=40>erwarten dich gewiss Kämpfe von beispielloser Härte.","story.map6-ending.078":"Jetzt mehr denn je <wait=40>musst du mit Vorsicht vorgehen.","story.map6-ending.079":"Keine Sorge um ihn. <wait=40>Er steht unter meinem Schutz.","story.map6-ending.080":"Was soll das heißen, „unter meinem Schutz“? <wait=40>Du warst doch eben noch dem Tode nahe, weißt du nicht mehr?","story.map6-ending.081":"Seria!","story.map6-ending.082":"W-<wait=40>Was!?","story.map6-ending.083":"Danke...<wait=40> dass du mich vorhin beschützt hast.","story.map6-ending.084":"W-<wait=20>W-<wait=10>Was ist d-<wait=10>denn plötzlich mit dir los?","story.map6-ending.085":"E-<wait=40>Es ist ja nicht so, als wäre ich auf Dank aus gewesen oder so...","story.map6-ending.086":"I-<wait=40>Ich hab doch nur... <wait=20>*Murmel* <size=14>*Murmel* <size=12>*Murmel*","story.map6-ending.087":"Haha, <wait=40>ein bisschen kleinlaut, was?","story.map6-ending.088":"Ho ho ho.","story.map6-ending.089":"<rep_handlename>!","story.map6-ending.090":"Endlich geht\'s nach Palmyna, dem Land, in dem Cardes versiegelt ist!","story.map6-ending.091":"Ich glaube an dich...","story.map6-ending.092":"<rep_handlename>, <wait=40>du bist der Beschwörer, der die Welt retten wird!","story.map6-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Du, <rep_handlename>,<wait=39> der Amdahl erschlossen hat...","story.map6-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Nutze meine Kraft, wenn du deine Reise in diesem neuen Land beginnst...","story.map6-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Um dieser von Trauer durchdrungenen Welt neue Hoffnung zu bringen…","story.map6-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Musst du an deine Kraft glauben <wait=20>und weiter voranschreiten…","story.map6-open.005":"Oh, <wait=40>du bist wach!","story.map6-open.006":"Schau! <wait=40>Wir sind in Encervis.","story.map6-open.007":"Mit seinen tiefen Gewässern und hohen Vulkanen <wait=40>ist dieser Ort für seine extremen Bedingungen bekannt.","story.map6-open.008":"Vor langer Zeit <wait=40>fand hier eine Schlacht zwischen Menschen statt...","story.map6-open.009":"...<wait=40>...","story.map6-open.010":"Aber die ist nicht besonders spannend, also vergessen wir sie einfach!","story.map6-open.011":"Außerdem <wait=40>gibt es so viel anderes, was du noch lernen musst!","story.map6-open.012":"Und mit uns hat das sowieso nichts zu tun.","story.map6-open.013":"Hier mitten im Palmyna-Archipel sind wir noch ziemlich weit von Palmyna selbst entfernt...","story.map6-open.014":"Aber werd nicht leichtsinnig <wait=20>und bleib immer konzentriert!","story.map6-open.015":"Ich erwarte auch hier Großes von dir!","story.map6-open.016":"Also gut, <wait=20>geben wir unser Bestes und arbeiten hart daran, Cardes zu besiegen!!","story.map7-dungeon1.001":"<rep_handlename>!","story.map7-dungeon1.002":"Wir stecken in Schwierigkeiten!<wait=40> In riesigen Schwierigkeiten!!","story.map7-dungeon1.003":"Kyaah!","story.map7-dungeon1.004":"<size=18>*Plumps*","story.map7-dungeon1.005":"Auuutsch...","story.map7-dungeon1.006":"He!<wait=40> <rep_handlename>! <wait=40>Steh nicht einfach so rum!","story.map7-dungeon1.007":"Hä? <wait=40>Du dachtest, ich warte im Schloss Obselion auf dich?","story.map7-dungeon1.008":"Für solche Kleinigkeiten haben wir jetzt keine Zeit!","story.map7-dungeon1.009":"Wir stecken wirklich in riesigen Schwierigkeiten!","story.map7-dungeon1.010":"Das Siegel um Cardes hat begonnen, sich aufzulösen!!","story.map7-dungeon1.011":"Ich weiß nicht, warum es sich plötzlich auflöst...","story.map7-dungeon1.012":"...aber er bereitet sich ganz sicher auf seinen Ausbruch vor!","story.map7-dungeon1.013":"Ich glaube aber nicht, dass jemand von außen etwas damit zu tun hatte.","story.map7-dungeon1.014":"Mann!","story.map7-dungeon1.015":"Nachdem du mit Zebra fertig geworden bist, dachte ich, er wäre kein Problem für uns.","story.map7-dungeon1.016":"Hmpf, <wait=40>sieht so aus, als gäb\'s wieder jede Menge zu tun...","story.map7-dungeon1.017":"Ich hab für Lord Lucius noch so viel zu erledigen...","story.map7-dungeon1.018":"Und jetzt muss ich mich auch noch um Cardes\' Pläne kümmern...","story.map7-dungeon1.019":"Warum krieg ich nie mal eine Pause!","story.map7-dungeon1.020":"Oh, <wait=40>fast hätte ich\'s vergessen!","story.map7-dungeon1.021":"Ich hab immer noch keinen Weg in die Geisterwelt gefunden!","story.map7-dungeon1.022":"Aber ich verspreche dir, ich finde einen, bis du im Schloss Obselion ankommst, <rep_handlename>.","story.map7-dungeon1.023":"Viel Glück, <wait=40>und diesmal treffen wir uns ganz bestimmt im Schloss Obselion!","story.map7-dungeon2.001":"Ho ho ho. <wait=40>Wenn das nicht <rep_handlename> ist?","story.map7-dungeon2.002":"Du bist wohl auf dem Weg in das Land, in dem Cardes versiegelt ist?","story.map7-dungeon2.003":"Hm? <wait=40>Was ist los?<wait=40> Du wirkst beunruhigt.","story.map7-dungeon2.004":"Falls du Tilith suchst: Die habe ich hier nicht gesehen. ","story.map7-dungeon2.005":"Was soll diese besorgte Miene? <wait=40>Um sie musst du dir keine Sorgen machen, weißt du?","story.map7-dungeon2.006":"Sie steht weit über den Sorgen von uns einfachen Beschwörern. ","story.map7-dungeon2.007":"Wobei mich ihr hinreißender Blick auf dich auch nervös machen würde. ","story.map7-dungeon2.008":"Ho ho ho.","story.map7-dungeon2.009":"Hmpf. <wait=40>Es ist wohl eine Weile her, dass wir zwei unter uns waren. ","story.map7-dungeon2.010":"Da wir gerade etwas Zeit haben, <wait=40>erzähle ich dir eine kleine Geschichte.","story.map7-dungeon2.011":"Eine Geschichte über eine grausame Schlacht zwischen Menschen und Göttern.","story.map7-dungeon2.012":"Vor langer Zeit <wait=40>war Schloss Obselion die Heimat der Königsfamilie von Palmyna. ","story.map7-dungeon2.013":"Ursprünglich war es ein malerisches Schloss, <wait=40>umgeben von viel Grün. ","story.map7-dungeon2.014":"Doch nach der Schlacht mit den Göttern wurde es zu dem hier. ","story.map7-dungeon2.015":"Kennst du die Vier Helden von Palmyna?","story.map7-dungeon2.016":"Einer Legende nach kämpften vier Krieger gegen Cardes, um dieses Land zu retten.","story.map7-dungeon2.017":"Es heißt sogar, Edea, die Prinzessin von Palmyna, sei unter ihnen gewesen.","story.map7-dungeon2.018":"Wenn die Legende stimmt, waren es diese Vier Helden, die Cardes versiegelten. ","story.map7-dungeon2.019":"Doch es heißt, dass die Vier Helden als Preis dafür, Cardes versiegeln zu können...","story.map7-dungeon2.020":"...ihr eigenes Leben opfern mussten. ","story.map7-dungeon2.021":"Ich frage mich, was ihnen am Ende wohl durch den Kopf ging. ","story.map7-dungeon2.022":"Waren sie glücklich im Glauben, Cardes\' Versiegelung würde Palmyna retten? ","story.map7-dungeon2.023":"Konnten sie dem Tod deshalb so furchtlos ins Auge sehen?","story.map7-dungeon2.024":"So tapfer sie auch ihr Leben riskierten, um diesen Ort zu beschützen...","story.map7-dungeon2.025":"...als ihr Kampf begann, war er bereits verloren.","story.map7-dungeon2.026":"Eine wahrhaft traurige Geschichte...","story.map7-dungeon2.027":"<rep_handlename>, <wait=40>verstehst du, was ich dir sagen will?","story.map7-dungeon2.028":"Ho ho ho. <wait=40>Keine Sorge.","story.map7-dungeon2.029":"Gewiss <wait=40>wirst du dich eines Tages in einer ähnlich unvorstellbaren Lage wiederfinden. ","story.map7-dungeon2.030":"Bis dahin <wait=40>behalte deine Umgebung genau im Auge, während sie sich weiter wandelt. ","story.map7-dungeon2.031":"Was du entdeckst, wird dir auf deinem weiteren Weg Kraft geben. ","story.map7-dungeon2.032":"Ho ho ho.<wait=40> Verzeih den langen Vortrag. ","story.map7-dungeon2.033":"Wenn du Tilith wiedersiehst, richte ihr bitte Folgendes aus:","story.map7-dungeon2.034":"Cardes\' Siegel ist fast gebrochen.","story.map7-dungeon2.035":"Leb wohl, und gib auf dich acht.","story.map7-dungeon3.001":"<size=18>*Zack*","story.map7-dungeon3.002":"Puh. <wait=40>Sieht aus, als wären wir mit den Monstern hier so gut wie fertig. ","story.map7-dungeon3.003":"Wobei ich zugeben muss, <wait=40>dass sie viel stärker waren, als ich erwartet hatte.","story.map7-dungeon3.004":"Hm?","story.map7-dungeon3.005":"He! <wait=40><rep_handlename>!","story.map7-dungeon3.006":"Willkommen in Palmyna!","story.map7-dungeon3.007":"Wir sind nicht mehr weit von dem Ort, an dem Cardes versiegelt ist. <wait=40>Geben wir auf den letzten Metern alles!","story.map7-dungeon3.008":"He! <wait=40>Seria!<wait=40> <rep_handlename> hat es auch geschafft!","story.map7-dungeon3.009":"Das musst du mir nicht jedes Mal sagen. <wait=40>Außerdem habe ich <rep_handlename> gerade ignoriert.","story.map7-dungeon3.010":"Haha. <wait=40>Ganz die Alte, was, Seria?","story.map7-dungeon3.011":"Wie auch immer, <wait=40>wo ist diese Göttin, die dir ständig hinterherläuft?","story.map7-dungeon3.012":"...Hm, sie sucht also einen Weg in die Geisterwelt.","story.map7-dungeon3.013":"Wenn wir es mit Cardes aufnehmen wollen, müssen wir wohl dorthin...","story.map7-dungeon3.014":"Was ist los?<wait=40> Du siehst etwas blass aus.","story.map7-dungeon3.015":"D-<wait=40>Das ist nichts!","story.map7-dungeon3.016":"Ich bin nur ein bisschen genervt!","story.map7-dungeon3.017":"Ich meine, <wait=40>siehst du denn nicht, was hier los ist, Karl!?","story.map7-dungeon3.018":"Unser Ziel war schon immer, Graham zur Strecke zu bringen!","story.map7-dungeon3.019":"Warum verschwenden wir unsere Zeit damit, <rep_handlename> zu helfen!?","story.map7-dungeon3.020":"Na komm, <wait=40>die Vier Gefallenen Götter zu besiegen hat doch Vorrang vor Graham. ","story.map7-dungeon3.021":"Ich weiß, ich weiß!","story.map7-dungeon3.022":"Aber du weißt doch, wie ich mich fühle, oder, Karl?","story.map7-dungeon3.023":"Mehr als alles andere will ich Graham erledigen!","story.map7-dungeon3.024":"Ja, <wait=40>ich verstehe, wie du dich fühlst. <wait=50>Verzeih mir, <wait=40>Seria...","story.map7-dungeon3.025":"Ich wollte dir doch keine Vorwürfe machen, Karl...","story.map7-dungeon3.026":"Grrr!!<wait=40> Das ist alles deine Schuld!","story.map7-dungeon3.027":"Warum kannst du es nicht einfach allein mit Cardes aufnehmen!","story.map7-dungeon3.028":"Ein bisschen absurd,<wait=40> findest du nicht?","story.map7-dungeon3.029":"Ich hab doch gesagt, ich weiß!","story.map7-dungeon3.030":"Karl, <wait=40>mit dir kann man in letzter Zeit echt nicht mehr diskutieren!","story.map7-dungeon3.031":"Nein, <wait=40>du sagst in letzter Zeit nur so lächerliche Dinge...","story.map7-dungeon3.032":"Ich hab keine Ahnung, wovon du redest!","story.map7-dungeon3.033":"<rep_handlename>! <wait=40>Beeil dich und such diese Göttin...","story.map7-dungeon3.034":"...und finde heraus, wie wir in die Geisterwelt kommen sollen!","story.map7-dungeon3.035":"H-<wait=20>He!<wait=40> Warte doch!","story.map7-dungeon3.036":"<rep_handlename>! Wir räumen den Weg vor uns frei.","story.map7-dungeon3.037":"Sorg du nur dafür, dass du bereit bist, dich Cardes zu stellen!","story.map7-dungeon4.001":"...<rep_handlename>.","story.map7-dungeon4.002":"Schön, dich zu sehen... <wait=40>Dir scheint\'s gut zu gehen...","story.map7-dungeon4.003":"Keuch...<wait=40> keuch...","story.map7-dungeon4.004":"M-<wait=40>Mir geht\'s gut...","story.map7-dungeon4.005":"Nngh...<wait=40> Sieht aus, als hätte ich\'s ein bisschen vermasselt...","story.map7-dungeon4.006":"Während ich nach einem Weg in die Geisterwelt gesucht habe, <wait=40>ist etwas Unerwartetes passiert...","story.map7-dungeon4.007":"Tut mir leid, dass du dir Sorgen gemacht hast.","story.map7-dungeon4.008":"Ich komm schon klar, <wait=20>ich brauch nur eine kurze Pause.","story.map7-dungeon4.009":"Aber viel wichtiger: <wait=40>Ich muss dir etwas sagen...","story.map7-dungeon4.010":"<rep_handlename>...","story.map7-dungeon4.011":"Das Siegel um Cardes...<wait=40> es hat nicht einfach nur Risse bekommen...","story.map7-dungeon4.012":"Cardes... <wait=40>zerstört es... <wait=40>von innen...","story.map7-dungeon4.013":"Weil er so lange versiegelt war, ist er jetzt geschwächt...","story.map7-dungeon4.014":"Aber seine Kräfte als Gott sind noch immer gewaltig...","story.map7-dungeon4.015":"Sie strömen schon aus der Geisterwelt heraus <wait=40>und zerstören alles, was ihnen im Weg steht...","story.map7-dungeon4.016":"Ich hab versucht, das Siegel zu reparieren, aber es ist mir nicht gelungen...","story.map7-dungeon4.017":"Keuch...<wait=40> keuch...","story.map7-dungeon4.018":"A-<wait=40>Aber... <wait=40>wir haben noch eine Chance.","story.map7-dungeon4.019":"Der Weg in die Geisterwelt ist jetzt offen.","story.map7-dungeon4.020":"Geh zum Noera-Schlachtfeld. <wait=40>Gleich dahinter liegt der Eingang zur Geisterwelt...","story.map7-dungeon4.021":"Geh schon vor <wait=40>und mach dir keine Sorgen um mich!","story.map7-dungeon4.022":"Hol dir dabei Hilfe von Karl, Seria und Elder Grah. ","story.map7-dungeon4.023":"Ich ruh mich kurz aus, bevor ich nachkomme...","story.map7-dungeon4.024":"Mach dir keine Sorgen um mich...","story.map7-dungeon4.025":"Ich bin eine wunderschöne und unbesiegbare Göttin!","story.map7-dungeon4.026":"Ich bin nur, <wait=40>gerade ein kleines bisschen müde...","story.map7-dungeon4.027":"Aber keine Sorge... <wait=50>Wir sehen uns an der Front...","story.map7-dungeon5.001":"Wenn das nicht <rep_handlename> ist.","story.map7-dungeon5.002":"Was soll diese ernste Miene?","story.map7-dungeon5.003":"Was sagst du da!?<wait=40> Was ist mit Tilith passiert!?","story.map7-dungeon5.004":"Hmpf. <wait=40>Die Lage scheint ernster zu sein, als ich es mir hätte vorstellen können. ","story.map7-dungeon5.005":"Es tut mir leid, aber ich habe hier etwas zu erledigen, <wait=40>daher kann ich dir nicht helfen. ","story.map7-dungeon5.006":"Ich habe Karl und Seria bereits gebeten, dich zu unterstützen. ","story.map7-dungeon5.007":"Ihr solltet gemeinsam Cardes besiegen.","story.map7-dungeon5.008":"......<wait=50><rep_handlename>.","story.map7-dungeon5.009":"Bevor du dich dem Gefallenen Gott stellst, muss ich dir noch etwas sagen.","story.map7-dungeon5.010":"Einer der Vier Helden von Palmyna wirkte hier im Arlind-Seminar.","story.map7-dungeon5.011":"Sein Name war Lorand, und er war Lehrer. ","story.map7-dungeon5.012":"Obwohl er sich schon längst vom Soldatenleben zurückgezogen hatte...","story.map7-dungeon5.013":"...überredete ihn Edea, die Prinzessin von Palmyna, <wait=40>gegen die einfallenden Götter zu kämpfen. ","story.map7-dungeon5.014":"Es endete genau so, wie ich es dir schon erzählt habe. ","story.map7-dungeon5.015":"Die Vier Helden opferten ihr Leben, um Cardes zu versiegeln. ","story.map7-dungeon5.016":"Doch <wait=40>es gibt noch viele weitere Geschichten von Menschen, die ähnlich wie die Vier Helden kämpften. ","story.map7-dungeon5.017":"Vor langer Zeit <wait=40>kämpften hier viele Menschen gegen die Götter.","story.map7-dungeon5.018":"Die meisten von ihnen verloren dabei ihr Leben.","story.map7-dungeon5.019":"Der Legende nach <wait=40>ließ Lucius einige der Überlebenden nach Elgaia entkommen. ","story.map7-dungeon5.020":"Alle, die in Grand Gaia zurückblieben, kamen um. ","story.map7-dungeon5.021":"<rep_handlename>.<wait=50> Was glaubst du, warum die Götter die Menschen vernichtet haben?","story.map7-dungeon5.022":"Es gibt unzählige Theorien, <wait=40>aber eine Antwort hat man bis heute nicht gefunden.","story.map7-dungeon5.023":"Doch nach langer Zeit <wait=40>öffnete Lucius den Weg nach Grand Gaia erneut.","story.map7-dungeon5.024":"Er muss wohl auch die Stärke der Menschen brauchen, um die Vier Gefallenen Götter zu besiegen. ","story.map7-dungeon5.025":"Aber warum genau wüten die Vier Gefallenen Götter überhaupt?","story.map7-dungeon5.026":"Und warum hat der Heilige Kaiser Karna Masta, Herr der Götter, nicht darauf reagiert?","story.map7-dungeon5.027":"Es gibt zu vieles, was wir Menschen einfach nie verstehen werden.","story.map7-dungeon5.028":"Aber Tilith als Schülerin von Lucius sollte es doch verstehen, meinst du nicht?","story.map7-dungeon5.029":"Bist du sicher, dass sie es nicht weiß? <wait=40>Vielleicht verschweigt sie dir nur gewisse Dinge.","story.map7-dungeon5.030":"Oder vielleicht <wait=40>denkt sie einfach überhaupt nicht nach. ","story.map7-dungeon5.031":"Ho ho ho.","story.map7-dungeon5.032":"Tilith ist so ein gutes, hübsches Mädchen, ich hoffe, dass es nur das ist. ","story.map7-dungeon5.033":"Wie auch immer, <wait=40><rep_handlename>.","story.map7-dungeon5.034":"Verzeih, dass ich so ins Plaudern geraten bin, <wait=40>aber du verstehst sicher, worauf ich hinauswill.","story.map7-dungeon5.035":"Lass dich nicht von allem mitreißen, was geschieht, <wait=40>sondern handle nach deinen eigenen Gedanken und deinem Willen. ","story.map7-dungeon5.036":"Deine Rolle darin ist schon größer geworden, als ein einzelner Beschwörer tragen können sollte. ","story.map7-dungeon5.037":"Du solltest dich jetzt auf den Weg machen.","story.map7-dungeon5.038":"Hinter dem Noera-Schlachtfeld direkt vor dir liegt der Eingang zur Geisterwelt.","story.map7-dungeon5.039":"Und vergiss nicht: <wait=20>Tilith und die Götter sind nicht die Einzigen, die auf dich zählen.","story.map7-dungeon6.001":"Yo, <rep_handlename>!<wait=40> Du bist ja schon da.","story.map7-dungeon6.002":"Sieh mal!<wait=40> Der Eingang zur Geisterwelt liegt direkt vor uns.","story.map7-dungeon6.003":"Sag mal, <wait=40>diese Göttin hat dir doch erklärt, wie wir in die Geisterwelt kommen, oder?","story.map7-dungeon6.004":"Und wo steckt sie? <wait=40>Wie kann sie sich in so einem entscheidenden Moment rumtreiben!?","story.map7-dungeon6.005":"Äh......<wait=50> Ach so......","story.map7-dungeon6.006":"A-<wait=40>Aber das ist doch kein Grund zur Sorge, oder?<wait=40> Sie ist schließlich eine Göttin, nicht wahr!?","story.map7-dungeon6.007":"Die taucht bestimmt früher oder später mit ihrem selbstgefälligen Grinsen wieder auf!","story.map7-dungeon6.008":"Also wisch dir diese jämmerliche Miene aus dem Gesicht und mach deinen Job!","story.map7-dungeon6.009":"Sie hat das alles nur getan, weil sie glaubt, dass du Cardes besiegen kannst!","story.map7-dungeon6.010":"Jetzt musst du alles geben! <wait=40>Du darfst nicht zulassen, dass alles, was sie getan hat, umsonst war!","story.map7-dungeon6.011":"Sie hat recht.","story.map7-dungeon6.012":"Ich weiß, dass du dir Sorgen machst, <rep_handlename>, <wait=40>aber zuerst müssen wir Cardes besiegen.","story.map7-dungeon6.013":"Wenn der Eingang zur Geisterwelt wirklich offen ist...","story.map7-dungeon6.014":"...dann hindert uns nichts daran, dir ebenfalls zu helfen.","story.map7-dungeon6.015":"Der Göttin zuliebe <wait=40>tun wir alles, um zu helfen!","story.map7-dungeon6.016":"I-<wait=40>Ich folge nur meinen Befehlen von der Beschwörerhalle!","story.map7-dungeon6.017":"Was ich tue, hat nichts mit dieser dummen Göttin zu tun!","story.map7-dungeon6.018":"Außerdem <wait=40>wär\'s mal schön, wenn sie zur Abwechslung in unserer Schuld stünde. ","story.map7-dungeon6.019":"Dann streng ich mich diesmal eben ein bisschen mehr an als sonst.","story.map7-dungeon6.020":"Heh, <wait=40>selbst sie wäre sicher beruhigt, wenn sie sehen würde, wie motiviert du bist, Seria.","story.map7-dungeon6.021":"W-<wait=40>Wovon redest du da!?","story.map7-dungeon6.022":"Ich sag ja nur, dass wir uns wohl auf dich verlassen können, Seria. <wait=40>Stimmt\'s, <rep_handlename>?","story.map7-dungeon6.023":"Bestärk ihn nicht auch noch!","story.map7-dungeon6.024":"Also dann, <wait=40>kämpfen wir uns in die Geisterwelt vor!","story.map7-dungeon6.025":"<rep_handlename>!<wait=40> Seria!<wait=40> Los geht\'s!","story.map7-dungeon7.001":"Das ist also die Geisterwelt Palmyna...<wait=40> Ziemlich unheimlich, muss ich sagen.","story.map7-dungeon7.002":"Ich bin froh, dass es hier viel geräumiger ist, als ich dachte.","story.map7-dungeon7.003":"Hä?<wait=40> Wird es nicht schwerer, Cardes zu finden, wenn es so geräumig ist?","story.map7-dungeon7.004":"Ä-<wait=20>Äh, ich meine...<wait=40> So war das nicht gemeint...","story.map7-dungeon7.005":"Ich dachte nur, dass es schwierig wäre, auf engem Raum gegen Cardes zu kämpfen. ","story.map7-dungeon7.006":"Ja, <wait=40>da hast du recht.","story.map7-dungeon7.007":"Mit so viel Platz <wait=40>haben wir unbegrenzte Möglichkeiten, es mit Cardes aufzunehmen. ","story.map7-dungeon7.008":"Ja, <wait=40>sieht ganz so aus.","story.map7-dungeon7.009":"<size=16>*Grollen*","story.map7-dungeon7.010":"W-<wait=20>Was war das!<wait=20> Warum bebt alles?","story.map7-dungeon7.011":"Verdammt! <wait=40>Sieht aus, als wäre es doch nicht so friedlich, wie es schien!","story.map7-dungeon7.012":"Ich hatte gehofft, wir hätten mehr Zeit, um nach Cardes zu suchen...","story.map7-dungeon7.013":"<rep_handlename>!<wait=40> Seria!","story.map7-dungeon7.014":"Teilen wir uns auf und suchen nach Cardes!","story.map7-dungeon7.015":"Hältst du das in so einer Lage wirklich für eine gute Idee!?","story.map7-dungeon7.016":"Uns läuft die Zeit davon.","story.map7-dungeon7.017":"Wenn wir Cardes nicht besiegen, bevor er sich befreit...","story.map7-dungeon7.018":"...könnten wir gut zusammen mit der Geisterwelt verschwinden.","story.map7-dungeon7.019":"......<wait=40>Verstanden.","story.map7-dungeon7.020":"Wenn ihr Schwerter klirren hört, <wait=40>hat dort sicher der Kampf begonnen. ","story.map7-dungeon7.021":"Haltet die Ohren offen und eure Umgebung genau im Blick!","story.map7-dungeon7.022":"<rep_handlename>!","story.map7-dungeon7.023":"Du bist noch ein Neuling, <wait=40>also wenn du Cardes siehst, wartest du gefälligst auf uns!","story.map7-dungeon7.024":"Sie hat recht. <wait=40>Egal, was passiert, keiner von uns sollte es allein mit ihm aufnehmen!","story.map7-dungeon7.025":"Ich will, dass wir alle überleben und gemeinsam nach Elgaia zurückkehren!","story.map7-ending.001":"Keuch...<wait=40> keuch...<wait=40> Wir waren zu spät!","story.map7-ending.002":"<size=20>*Grollen*","story.map7-ending.003":"<anchor=center><speed=10>Seria...<wait=40> Nimm meine Hand......","story.map7-ending.004":"Hallo zusammen! <wait=40>Tut mir leid, dass ich so spät komme!!","story.map7-ending.005":"<rep_handlename>! <wait=40>Ich wusste, dass du es schaffst!","story.map7-ending.006":"D-<wait=20>Du! <wait=40>Was machst du denn hier!?","story.map7-ending.007":"Ich dachte, du wärst schwer verletzt...","story.map7-ending.008":"Ich hatte so ein Gefühl, dass <rep_handlename> in Schwierigkeiten steckt, <wait=40>also hab ich meine Erholung verschoben, um zu helfen.","story.map7-ending.009":"Ein bisschen tut\'s aber noch weh.","story.map7-ending.010":"Wie dumm von dir, so etwas aus einer bloßen Ahnung heraus zu tun!","story.map7-ending.011":"Ich bin froh, dass ich auch dir rechtzeitig helfen konnte, <wait=40>Seria.","story.map7-ending.012":"......","story.map7-ending.013":"D-<wait=40>Danke dafür...","story.map7-ending.014":"Keine Ursache! <wait=40>Ich bin einfach froh, dass ihr alle in Sicherheit seid!","story.map7-ending.015":"Ja, <wait=40>danke, dass du uns gerettet hast!","story.map7-ending.016":"Es wäre ziemlich bitter gewesen, an so einem Ort draufzugehen, <wait=40> nachdem wir Cardes besiegt haben. ","story.map7-ending.017":"Danke, <wait=40>Göttin.","story.map7-ending.018":"Das ist der Karl, den ich kenne! <wait=40>Du darfst mir auch gern noch mehr danken, Seria!","story.map7-ending.019":"Ü-<wait=40>Übertreib\'s nicht!","story.map7-ending.020":"Ich meine, <wait=40>wenn du eine Göttin bist, warum tauchst du dann jedes einzelne Mal erst in letzter Minute auf!","story.map7-ending.021":"W-<wait=40>Was ist denn mit dir los!","story.map7-ending.022":"Und noch was: Warum hast du uns nicht gesagt, wie wir aus der Geisterwelt wieder rauskommen!?","story.map7-ending.023":"Ä-<wait=40>Äh, <wait=20>das muss ich wohl...","story.map7-ending.024":"Lassen wir es einfach dabei.","story.map7-ending.025":"Und egal, wie es aussieht: Seria ist dir wirklich dankbar für das, was du für sie getan hast.","story.map7-ending.026":"Ja, <wait=40>ich weiß.","story.map7-ending.027":"Das sehe ich daran, wie sie rot wird!","story.map7-ending.028":"Ich hab Seria auch total gern!","story.map7-ending.029":"Hör endlich auf damit! <wait=40>Mir wird schlecht!!","story.map7-ending.030":"<size=12>Du bist so ein Trottel...","story.map7-ending.031":"Karl! <wait=40>Ich gehe!","story.map7-ending.032":"Wir haben getan, worum uns die Beschwörerhalle gebeten hat!","story.map7-ending.033":"Jetzt ist es Zeit, Graham zu jagen!","story.map7-ending.034":"W-<wait=20>Warte doch!","story.map7-ending.035":"<rep_handlename>!","story.map7-ending.036":"Ich war noch nie so stolz, dich meinen Freund zu nennen!","story.map7-ending.037":"Wenn sich alles beruhigt hat, <wait=20>lass uns zusammen ein Abenteuer in Grand Gaia erleben!","story.map7-ending.038":"Bild dir bloß nichts darauf ein, dass du Cardes besiegt hast!","story.map7-ending.039":"Dein Glück wird irgendwann aufgebraucht sein, weißt du.","story.map7-ending.040":"Wenn wir uns das nächste Mal treffen, zeige ich dir die wahre Macht der Beschwörerin, die die Dämonenjäger anführt. ","story.map7-ending.041":"Aber bis dahin <wait=20>erwarte ich, dass du heil bleibst!","story.map7-ending.042":"Sie sind weg.","story.map7-ending.043":"Ich hoffe, wir kämpfen eines Tages wieder zusammen!","story.map7-ending.044":"<rep_handlename>! <wait=40>Vielen, vielen Dank, dass du Cardes besiegt hast!","story.map7-ending.045":"Ich geb zu, als wir uns kennenlernten, konnte ich mich kaum auf dich verlassen, <wait=40>aber jetzt hast du schon zwei der Vier Gefallenen Götter besiegt.","story.map7-ending.046":"Ihr Menschen seid echt interessant!","story.map7-ending.047":"Seit ich Karl, Seria<wait=40> und dich getroffen habe...","story.map7-ending.048":"...mag ich euch Menschen mehr denn je!","story.map7-ending.049":"Ich freu mich auf noch mehr Abenteuer mit dir, <wait=40>mein <rep_handlename>.","story.map7-ending.050":"......<wait=40>Wie es scheint, wurde der große Cardes besiegt.","story.map7-ending.051":"Die einzigen verbliebenen Gefallenen Götter sind Zevalhua der Erhabene <wait=40>und der Bestiengott Afla Dilith. ","story.map7-ending.052":"Gewiss ist es an der Zeit, dass auch sie mitmischen.","story.map7-ending.053":"Wir müssen unsere Vorbereitungen beschleunigen.","story.map7-ending.054":"<rep_handlename>...","story.map7-ending.055":"Ich bin gespannt, welchen Weg du in der nächsten Schlacht einschlagen wirst...","story.map7-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Du, <rep_handlename>,<wait=39> der du Encervis erschlossen hast...","story.map7-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Nutze meine Macht, wenn du nach Palmyna aufbrichst, <wait=40>ins Land des versiegelten Gefallenen Gottes...","story.map7-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Um dieser von Trauer durchdrungenen Welt neue Hoffnung zu bringen...","story.map7-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Musst du an deine Kraft glauben <wait=20>und weiter voranschreiten...","story.map7-open.005":"<rep_handlename>!<wait=40> Du hast es also endlich nach Palmyna geschafft!","story.map7-open.006":"Es ist nicht mehr weit bis zur Geisterwelt, in der Cardes eingesperrt ist!","story.map7-open.007":"Da du Zebra besiegen konntest, wirst du sicher kein Problem haben, rechtzeitig hinzukommen, <rep_handlename>.","story.map7-open.008":"Aber trotzdem: <wait=40>Werd bloß nicht leichtsinnig!","story.map7-open.009":"Vor langer Zeit gab es hier ein Königreich namens Palmyna, das tapfer gegen die Götter kämpfte. ","story.map7-open.010":"Überreste dieses Krieges sieht man noch heute...","story.map7-open.011":"...zusammen mit all den Geistern und Monstern, die hier noch umherstreifen.","story.map7-open.012":"Also dann, <wait=40>ich such uns einen Weg in die Geisterwelt. ","story.map7-open.013":"Lass dir Zeit beim Vorankommen, <rep_handlename>.","story.map7-open.014":"Ich warte gleich vorn im Schloss Obselion auf dich!","story.map8-dungeon1.001":"Verdammt! <wait=40>Es ist immer noch so weit weg.","story.map8-dungeon1.002":"Aber na ja, <wait=20>Jammern bringt jetzt auch nichts.","story.map8-dungeon1.003":"Hm? <wait=40>He, du!","story.map8-dungeon1.004":"Tss, <wait=20>wenn das nicht unser lieber <rep_handlename> ist.","story.map8-dungeon1.005":"Was machst du hier?","story.map8-dungeon1.006":"Kann es sein!?","story.map8-dungeon1.007":"Du willst dich mit meiner harten Arbeit schmücken, stimmt\'s!?","story.map8-dungeon1.008":"Wie auch immer, <wait=20>was höre ich da über Cordelica?","story.map8-dungeon1.009":"Gerüchten zufolge hast du ganz allein einen der Vier Gefallenen Götter erledigt?","story.map8-dungeon1.010":"Pff, <wait=40>oder vielleicht <wait=20>mussten Karl und Seria dich retten, frage ich mich?","story.map8-dungeon1.011":"Egal, <wait=20>macht sowieso keinen Unterschied.","story.map8-dungeon1.012":"Klappe! <wait=40>Ich hab dich nicht um eine Erklärung gebeten!","story.map8-dungeon1.013":"Wenn du auch nur ein halbes Hirn im Kopf hast, hörst du dir an, was ich zu sagen habe!","story.map8-dungeon1.014":"Je<wait=20>den<wait=20>falls.","story.map8-dungeon1.015":"Komm mir bloß nicht in die Quere! Das ist alles!","story.map8-dungeon1.016":"Ich führe gerade eine ungeheuer wichtige Mission im Auftrag der Beschwörerhalle aus.","story.map8-dungeon1.017":"Wobei das für eine Elite wie mich natürlich ein Klacks ist.","story.map8-dungeon1.018":"Wenn du verstehst, was ich meine, solltest du dich am besten irgendwohin verziehen!","story.map8-dungeon1.019":"Und ich verspreche dir: Wenn ich dich in Cordelica herumlungern sehe, mache ich kurzen Prozess mit dir.","story.map8-dungeon1.020":"Kapiert?","story.map8-dungeon2.001":"Puh, <wait=40>dieser Ort ist gefährlicher, als ich dachte.","story.map8-dungeon2.002":"So wie es aussieht, ist es noch ein langer Weg bis zum Turm.","story.map8-dungeon2.003":"Oh, <wait=40>wenn das nicht <rep_handlename> ist.","story.map8-dungeon2.004":"Was machst du hier?","story.map8-dungeon2.005":"Hehe, <wait=40>eigentlich muss ich gar nicht fragen.","story.map8-dungeon2.006":"Die Beschwörerhalle muss es wirklich ernst meinen, wenn sie dich den ganzen Weg hierher schickt.","story.map8-dungeon2.007":"Trotzdem <wait=20>habe ich nicht vor, nachzugeben.","story.map8-dungeon2.008":"Die Kaiserliche Garde wird sich die Macht holen, die in Lizeria verborgen liegt.","story.map8-dungeon2.009":"Hehe, <wait=40>du musst gar nicht so schauen.","story.map8-dungeon2.010":"Ich habe in Cordelica gesehen, was wirklich in dir steckt.","story.map8-dungeon2.011":"Warum lässt du diesen Akras-Haufen nicht hinter dir und schließt dich uns an?","story.map8-dungeon2.012":"Um wahren Frieden zu schaffen, musst du dich aus der Kontrolle der Ältesten befreien!","story.map8-dungeon2.013":"Was redest du da, <wait=40>du kaiserlicher Hund!","story.map8-dungeon2.014":"Alles, was du <rep_handlename> erzählst, ist sinnlos.","story.map8-dungeon2.015":"Diese ordinäre Stimme...","story.map8-dungeon2.016":"Lange nicht gesehen...","story.map8-dungeon2.017":"Fräulein Kaiserliche Garde.","story.map8-dungeon2.018":"Ich bin überrascht. <wait=40>Wie um alles in der Welt bist du hierhergekommen?","story.map8-dungeon2.019":"Das war wirklich gar nichts.","story.map8-dungeon2.020":"Ich bin nun mal der Beschwörer, den die Beschwörerhalle eigens auserwählt hat, um hier draußen Nachforschungen anzustellen.","story.map8-dungeon2.021":"Dieser dämlich aussehende Beschwörer da ist bloß ein Tourist auf der Suche nach billigem Nervenkitzel.","story.map8-dungeon2.022":"<rep_handlename> hat keinen blassen Schimmer, was hier los ist.","story.map8-dungeon2.023":"Ich meine, du hast diesem Trottel doch wohl keine wichtigen Informationen verraten, oder?","story.map8-dungeon2.024":"Ngh...","story.map8-dungeon2.025":"Jedenfalls, <wait=20>die wahren Narren hier sind die Leute in der Beschwörerhalle.","story.map8-dungeon2.026":"Wie können sie einen zweitklassigen Beschwörer wie dich an einen Ort wie diesen schicken?","story.map8-dungeon2.027":"Das beweist nur, dass sie keine Ahnung haben, wie wertvoll dieses Gebiet wirklich ist.","story.map8-dungeon2.028":"Und wenn das wirklich so ist, <wait=20>dürfte es mir keine Probleme bereiten, mir die hier verborgene Macht zu holen.","story.map8-dungeon2.029":"He! <wait=40>Pass auf, was du sagst!","story.map8-dungeon2.030":"Du hättest keine Chance gegen mich, wenn ich alles gebe!","story.map8-dungeon2.031":"Hehe, <wait=40>was für ein Gesichtsausdruck.","story.map8-dungeon2.032":"Aber wirklich, <wait=20>du musst nicht den harten Kerl spielen.","story.map8-dungeon2.033":"Ich habe ohnehin keine Zeit, mit dir herumzuspielen.","story.map8-dungeon2.034":"Läufst du etwa weg?","story.map8-dungeon2.035":"Nein, <wait=40>ich vermeide nur fruchtlose Begegnungen, während ich mein Ziel verfolge.","story.map8-dungeon2.036":"<rep_handlename>, <wait=40>denk über das nach, worüber wir gerade gesprochen haben.","story.map8-dungeon2.037":"Ich bin sicher, es würde dir mehr nützen als so törichte Verbündete wie er.","story.map8-dungeon2.038":"<size=22>Was redest du da!</size>","story.map8-dungeon2.039":"Heh, <wait=40>sie ist also doch weggelaufen.","story.map8-dungeon2.040":"He! <wait=40><rep_handlename>!","story.map8-dungeon2.041":"Warum finde ich dich eigentlich immer an solchen Orten?","story.map8-dungeon2.042":"Willst du mir etwa sagen, dass du nicht vorhast, auf mich zu hören?","story.map8-dungeon2.043":"Oder vielleicht <wait=20>willst du ihr Angebot annehmen und die Beschwörerhalle verraten?","story.map8-dungeon2.044":"Mir ist es eigentlich egal, was du machst.","story.map8-dungeon2.045":"Wenn du meine Warnung noch einmal ignorierst, <wait=20>dann beim nächsten Mal, wenn ich dich sehe...","story.map8-dungeon2.046":"...bleibt mir nichts anderes übrig, als dich zu Staub zu verwandeln.","story.map8-dungeon2.047":"Heh, <wait=40>du bist echt eine Plage!","story.map8-dungeon2.048":"Keine Sorge, <wait=40>ich will dir nicht drohen oder so.","story.map8-dungeon2.049":"Ich wollte nur, dass du weißt, dass ich mir von niemandem in die Quere kommen lasse!","story.map8-dungeon2.050":"Kapiert?","story.map8-dungeon3.001":"He, <wait=40><rep_handlename>.","story.map8-dungeon3.002":"Du scheinst ja gut gelaunt zu sein.","story.map8-dungeon3.003":"Warte!","story.map8-dungeon3.004":"Dass du meine Warnung ignorierst und herkommst, kann nur heißen, dass du die Beschwörerhalle verraten willst, hab ich recht?","story.map8-dungeon3.005":"Was für Bedingungen hat dir diese Frau gestellt?","story.map8-dungeon3.006":"Hm? <wait=40>Du sagst, du bist kein Verräter?","story.map8-dungeon3.007":"<size=22>Ha ha ha!</size>","story.map8-dungeon3.008":"Für so einen Narren hast du eine interessante Wahl getroffen.","story.map8-dungeon3.009":"Das kann nur eins bedeuten...","story.map8-dungeon3.010":"Du bist hergekommen, um mir Ärger zu machen, stimmt\'s?","story.map8-dungeon3.011":"Ha ha ha! <wait=40>Du bist ja lustig!","story.map8-dungeon3.012":"<size=22>Werd bloß nicht übermütig!</size>","story.map8-dungeon3.013":"Soll ich dir zeigen, wie unterlegen du mir bist?","story.map8-dungeon3.014":"Was für ein Trottel.","story.map8-dungeon3.015":"Ich kann dich einfach nicht ausstehen.","story.map8-dungeon3.016":"Ach, und übrigens, ich habe gehört, du bist auch mit diesem Dummkopf Karl befreundet.","story.map8-dungeon3.017":"Sieht so aus, als bliebe mir nichts anderes übrig, als dir eine Lektion zu erteilen und dir zu zeigen, wie großartig ich wirklich bin.","story.map8-dungeon3.018":"Klingt gut? <wait=20>Ich warte gleich hinter diesem gefrorenen See auf dich.","story.map8-dungeon3.019":"Ich bringe es dir persönlich bei, also freu dich schon mal drauf!","story.map8-dungeon4.001":"D-<wait=20>Das kann nicht sein! <wait=40>Das ist unmöglich.","story.map8-dungeon4.002":"Auch Cardes wurde besiegt!?","story.map8-dungeon4.003":"N-<wait=20>Nein, <wait=40>ich zweifle nicht an Euch...","story.map8-dungeon4.004":"Verstanden. <wait=40>Ich kümmere mich so sorgfältig wie möglich darum.","story.map8-dungeon4.005":"Ja. <wait=40>Darüber müsst Ihr Euch keine Sorgen machen.","story.map8-dungeon4.006":"Ich werde mein Bestes geben, Euch nicht zu enttäuschen.","story.map8-dungeon4.007":"Puh... <wait=40>Die Dinge entwickeln sich viel schneller als erwartet.","story.map8-dungeon4.008":"Oh, <wait=20>könnte das etwa...","story.map8-dungeon4.009":"Hehe, <wait=40>wir treffen uns also wieder.","story.map8-dungeon4.010":"Du hast Lugina also besiegt?","story.map8-dungeon4.011":"Einen so schwachen Beschwörer zu besiegen, war für dich sicher kein Problem, nachdem du schon zwei der Vier Gefallenen Götter bezwungen hast?","story.map8-dungeon4.012":"Hehe, <wait=20>schau mich nicht so an.","story.map8-dungeon4.013":"Ich weiß, wie viel mächtiger du in Wahrheit bist als er.","story.map8-dungeon4.014":"Also, <wait=20>lass mich dich noch einmal fragen.","story.map8-dungeon4.015":"Willst du nicht die Akras-Beschwörerhalle hinter dir lassen und mit uns zusammenarbeiten?","story.map8-dungeon4.016":"Letztes Mal hatten wir nicht genug Zeit zum Reden, weil wir so unhöflich unterbrochen wurden.","story.map8-dungeon4.017":"Aber ich meine es ernst.","story.map8-dungeon4.018":"Hehe, <wait=20>natürlich verwirrt dich so eine plötzliche Einladung.","story.map8-dungeon4.019":"Lass mich dir nur eins sagen. <wait=40>Das herrschende System in Elgaia ist kaputt.","story.map8-dungeon4.020":"Und nur wir können es reparieren.","story.map8-dungeon4.021":"Du siehst doch auch, was vor sich geht, oder?","story.map8-dungeon4.022":"Statt einer Republik wird die Welt von einer Organisation von Beschwörern regiert.","story.map8-dungeon4.023":"Vor langer Zeit <wait=20>entkamen einige wenige dem tragischen Zusammenstoß mit den Göttern.","story.map8-dungeon4.024":"Sie führten das Volk an und gründeten das Randall-Imperium.","story.map8-dungeon4.025":"Dann, <wait=20>lange nach der Gründung des Imperiums...","story.map8-dungeon4.026":"...bildeten sich mehrere Gruppen, die sich gegen die privilegierte Klasse des Randall-Imperiums stellten.","story.map8-dungeon4.027":"Sie gründeten die Elgaia-Föderation.","story.map8-dungeon4.028":"In jüngerer Zeit war es Elgaia, das sich als Erstes zu wandeln begann.","story.map8-dungeon4.029":"Während dieses Wandels erschienen die Beschwörer, <wait=20>und mit ihnen jemand, der sie alle vereinen wollte.","story.map8-dungeon4.030":"Sie gründeten die Akras-Beschwörerhalle.","story.map8-dungeon4.031":"Die Beschwörer von einst, die die Akras-Beschwörerhalle aufbauten...","story.map8-dungeon4.032":"...auch „Ur-Beschwörer“ genannt, weil sie als Erste durch das Tor gingen...","story.map8-dungeon4.033":"...nutzten die gewaltigen Beschwörungskräfte, die sie erlangt hatten...","story.map8-dungeon4.034":"...und schufen eine der größten Organisationen in ganz Elgaia.","story.map8-dungeon4.035":"Mit der immensen Macht der Beschwörer übernahm diese Organisation nach und nach auch die wirtschaftliche Kontrolle.","story.map8-dungeon4.036":"Ehe es jemand bemerkte, war die Republik nur noch eine leere Hülle ihrer selbst.","story.map8-dungeon4.037":"Heute sind sowohl das Randall-Imperium als auch die Elgaia-Föderation nichts weiter als leere Gerüste.","story.map8-dungeon4.038":"Hehe, <wait=40>dein Gesicht verrät mir, dass du das schon begriffen hast.","story.map8-dungeon4.039":"Allerdings <wait=40>scheinst du kein Problem damit zu haben.","story.map8-dungeon4.040":"Natürlich <wait=20>hat es mit gewöhnlichen Menschen nichts zu tun, wer was kontrolliert.","story.map8-dungeon4.041":"Aber man sollte die Welt nicht so auf die leichte Schulter nehmen.","story.map8-dungeon4.042":"Ob du wohl noch an der Seite der Beschwörerhalle stehen würdest, wenn du ihre dunkle Seite kennen würdest?","story.map8-dungeon4.043":"Wenn du versprichst, dich von nun an uns anzuschließen, erzähle ich dir alles.","story.map8-dungeon4.044":"Hehe, <wait=20>aber es gibt keinen Grund zur Eile.","story.map8-dungeon4.045":"Denn egal, was passiert: Sobald ich die Macht in Händen halte, die hier verborgen ist...","story.map8-dungeon4.046":"...bleibt dir nichts anderes übrig, als uns auf unserem rechtschaffenen Weg zu folgen.","story.map8-dungeon4.047":"......","story.map8-dungeon4.048":"Nun denn, <wait=40>ich sollte gehen.","story.map8-dungeon4.049":"Ich freue mich darauf, wieder mit dir zu sprechen, ohne dass uns dieser ordinäre Narr unterbricht.","story.map8-dungeon5.001":"<rep_handlename>.","story.map8-dungeon5.002":"He, <wait=40>was ist denn plötzlich mit dir los?","story.map8-dungeon5.003":"Glaubst du etwa, du warst im letzten Kampf stärker als ich?","story.map8-dungeon5.004":"Du hast wohl nicht gemerkt, wie sehr ich dich geschont habe.","story.map8-dungeon5.005":"Sieht so aus, als bräuchtest du eine Erinnerung.","story.map8-dungeon5.006":"Hä? <wait=40>Ob ich von der dunklen Seite der Beschwörerhalle weiß?","story.map8-dungeon5.007":"Du Idiot, <wait=20>was für eine verrückte Geschichte hast du dir von dieser Frau in den Kopf setzen lassen?","story.map8-dungeon5.008":"Ich hab dir doch gesagt, du sollst nicht auf diese Frau hören!","story.map8-dungeon5.009":"Und außerdem hat das, was die Beschwörerhalle tut, nichts mit uns zu tun.","story.map8-dungeon5.010":"Im Grunde zählt nur, wer in Elgaia am mächtigsten ist.","story.map8-dungeon5.011":"Wird es die Elgaia-Föderation mit ihren eifrigen Massen sein?","story.map8-dungeon5.012":"Oder das Randall-Imperium mit seinem altmodischen Militär?","story.map8-dungeon5.013":"Oder vielleicht keiner von beiden.","story.map8-dungeon5.014":"Ich halte allerdings die Akras-Beschwörerhalle für die stärkste.","story.map8-dungeon5.015":"Die Elite der Beschwörerhalle ist die Elite von Elgaia.","story.map8-dungeon5.016":"Mehr ist dazu nicht zu sagen.","story.map8-dungeon5.017":"Und genau deshalb muss ich für die Beschwörerhalle mein Bestes geben.","story.map8-dungeon5.018":"Dass du mir in die Quere kommst, während ich schon hart arbeite, geht mir langsam echt auf die Nerven.","story.map8-dungeon5.019":"Darum werde ich dich heute nicht schonen.","story.map8-dungeon5.020":"Ich warte weiter vorn auf dich.","story.map8-dungeon5.021":"<size=20>Ich zeige dir, wie verschieden wir sind!</size>","story.map8-dungeon5.022":"<size=20>Mach dich besser auf was gefasst!</size>","story.map8-dungeon6.001":"<rep_handlename>. <wait=40>Du bist also gekommen.","story.map8-dungeon6.002":"Sieh nur. <wait=40>Ist das nicht unglaublich?","story.map8-dungeon6.003":"Vor langer Zeit lag hier die Republik La Veda, deren Volk zum Gott des Lichts betete.","story.map8-dungeon6.004":"Doch <wait=20>genau dieses Volk wurde von dem Gott vernichtet, zu dem es betete.","story.map8-dungeon6.005":"Was für ein schrecklicher Anblick.","story.map8-dungeon6.006":"Es gibt verschiedene Aufzeichnungen über den Kampf gegen die Götter.","story.map8-dungeon6.007":"Allen voran die Legende der Sechs Helden.","story.map8-dungeon6.008":"Doch <wait=20>vieles ist noch immer unbekannt.","story.map8-dungeon6.009":"Vor allem <wait=20>weiß man wenig darüber, was in Grand Gaia geschah...","story.map8-dungeon6.010":"...nachdem Lucius die Menschen gerettet hatte.","story.map8-dungeon6.011":"Was genau tat Lucius eigentlich...","story.map8-dungeon6.012":"...während die Vier Gefallenen Götter so viel Grausamkeit verübten?","story.map8-dungeon6.013":"Und warum hat der große Anführer der Götter, Carna Masta, noch nichts unternommen?","story.map8-dungeon6.014":"Hehe, <wait=20>wenn man darüber nachdenkt, fragt man sich wirklich, wie sicher wir eigentlich sind.","story.map8-dungeon6.015":"Ich...","story.map8-dungeon6.016":"Nein, <wait=20>wir leben in Angst vor der jetzigen Lage.","story.map8-dungeon6.017":"In so unsicheren Zeiten wie diesen...","story.map8-dungeon6.018":"...wer weiß schon, wann die Götter beschließen, erneut zu vernichten, und Elgaia ins Visier nehmen?","story.map8-dungeon6.019":"Deshalb müssen wir die große Macht in die Hände bekommen, die hier ruht.","story.map8-dungeon6.020":"Die Macht, die in dem Land ruhen soll, in dem die Menschen einst den Gott des Lichts verehrten.","story.map8-dungeon6.021":"Hehe, <wait=40>da ist er wieder, dieser besorgte Gesichtsausdruck.","story.map8-dungeon6.022":"Es gibt keinen Grund zur Eile. <wait=40>Nimm dir ruhig Zeit, das alles zu verarbeiten.","story.map8-dungeon6.023":"Aber <wait=20>ich möchte auch, dass du nach vorn denkst.","story.map8-dungeon6.024":"Welcher ist der rechtschaffene Weg zu einer Welt, in der die Menschen in Frieden leben können?","story.map8-dungeon6.025":"Nun denn, <wait=20>ich muss los.","story.map8-dungeon6.026":"Oh, <wait=20>und noch etwas...","story.map8-dungeon6.027":"Vorhin habe ich Lugina mit sehr bedrohlicher Miene zu einer schwarzen Brücke gleich da vorn gehen sehen.","story.map8-dungeon6.028":"Sei vorsichtig, ja?","story.map8-dungeon6.029":"Hehehe.","story.map8-dungeon7-2.001":"U-<wait=40>Unmöglich...","story.map8-dungeon7-2.002":"Wie konnte ich nur gegen...","story.map8-dungeon7-2.003":"Ngh...","story.map8-dungeon7-2.004":"<size=18>Das kann nicht wahr sein...</size>","story.map8-dungeon7-2.005":"<size=24>Das akzeptiere ich nicht!</size>","story.map8-dungeon7-2.006":"Ich darf auf keinen Fall gegen dich verlieren!","story.map8-dungeon7-2.007":"Unmöglich...","story.map8-dungeon7-2.008":"<size=20>Nein! <wait=40>Nein! <wait=40>Nein!","story.map8-dungeon7-2.009":"<size=18>Wie konnte ich verlieren...</size>","story.map8-dungeon7-2.010":"Pff, <wait=40>was glotzt du so?","story.map8-dungeon7-2.011":"Verschwinde endlich!","story.map8-dungeon7-2.012":"<size=20>Verflucht sollst du sein!!</size>","story.map8-dungeon7-2.013":"Mist...","story.map8-dungeon7.001":"Ich hab das Warten satt, <rep_handlename>.","story.map8-dungeon7.002":"Ich war mir sicher, dass du hier vorbeikommst.","story.map8-dungeon7.003":"Das, worauf diese Frau und ich aus sind, befindet sich anscheinend im Turm gleich da vorn.","story.map8-dungeon7.004":"<size=20>Argh!</size>","story.map8-dungeon7.005":"Da ist wieder dieses nervige Gesicht!","story.map8-dungeon7.006":"Trotz deiner gleichgültigen Miene bist du kein bisschen anders als sie: Deine Neugier steht mir im Weg.","story.map8-dungeon7.007":"So ahnungslos wie du bist, willst du mir wirklich meine Trophäe streitig machen?","story.map8-dungeon7.008":"Du gehst mir langsam echt auf den Senkel.","story.map8-dungeon7.009":"Diese Mission ist meine Chance, den alten Knackern meine wahre Macht zu zeigen.","story.map8-dungeon7.010":"Ich lasse mir von einem Neuling wie dir nicht in die Quere kommen!","story.map8-dungeon7.011":"Diesen Erfolg lasse ich mir von niemandem wegschnappen!","story.map8-dungeon7.012":"Ich zermalme jeden, der mir in die Quere kommt!","story.map8-dungeon7.013":"Ngh, <wait=20>was soll dieser Blick! Jetzt bloß keine Angst kriegen!","story.map8-dungeon7.014":"Egal.","story.map8-dungeon7.015":"Das ist meine letzte Warnung.","story.map8-dungeon7.016":"Wenn ich dir das nächste Mal begegne...","story.map8-dungeon7.017":"<size=22>ist es aus mit dir!</size>","story.map8-dungeon7.018":"<size=22>Kapiert?</size>","story.map8-dungeon8.001":"Ngh...","story.map8-dungeon8.002":"Das ist unerwartet, <wait=20>ich hätte nicht gedacht, dass es so hart wird.","story.map8-dungeon8.003":"Trotzdem <wait=20>bringen mich diese lächerlichen Verletzungen nicht zum Aufgeben!","story.map8-dungeon8.004":"Ich muss das Tor für Eriole unbedingt finden.","story.map8-dungeon8.005":"He! <wait=40><rep_handlename>!","story.map8-dungeon8.006":"Ich fasse es nicht, dass du mich eingeholt hast.","story.map8-dungeon8.007":"Wenn du hier bist, heißt das wohl, dass du Lugina besiegen konntest, oder?","story.map8-dungeon8.008":"Er mag etwas ungehobelt sein, <wait=20>aber als Anführer der Dämonenjäger ist er mehr als nur ein ernstzunehmender Gegner.","story.map8-dungeon8.009":"Du musst wirklich einiges an Macht haben, wenn du ihn besiegen konntest.","story.map8-dungeon8.010":"Ngh...","story.map8-dungeon8.011":"Hehe, <wait=20>diese Wunden sind nichts, keine Sorge.","story.map8-dungeon8.012":"Es gab nur ein kleines Problem.","story.map8-dungeon8.013":"Mehr denn je ist mein Ziel, die verborgene Macht zu erlangen, die hier wartet.","story.map8-dungeon8.014":"Nicht einmal dir würde ich erlauben, mir in die Quere zu kommen.","story.map8-dungeon8.015":"Haha, <wait=40>was für ein furchterregender Gesichtsausdruck.","story.map8-dungeon8.016":"Aber <wait=20>ich meine es ernst.","story.map8-dungeon8.017":"Ich glaube, dass die Macht, die hier ruht, die Welt wieder so machen kann, wie sie sein sollte.","story.map8-dungeon8.018":"Weißt du, was uns hier erwartet?","story.map8-dungeon8.019":"Es ist ein Turm, der angeblich schon existierte, bevor La Veda überhaupt gegründet wurde.","story.map8-dungeon8.020":"Vielleicht wurde La Veda sogar erbaut, um über den Turm zu wachen.","story.map8-dungeon8.021":"Mit anderen Worten: <wait=40>Was uns hier erwartet, ist mehr als nur wichtig.","story.map8-dungeon8.022":"Wahrscheinlich gibt es auch unzählige Fallen, die zu seinem Schutz aufgestellt wurden.","story.map8-dungeon8.023":"Verstehst du, was ich meine?","story.map8-dungeon8.024":"Wenn ja, <wait=40>solltest du besser nicht weitergehen.","story.map8-dungeon8.025":"Du willst doch nicht gegen mich kämpfen müssen, oder?","story.map8-dungeon8.026":"Hehehe.","story.map8-dungeon8.027":"Ich erwarte, dass du meinen Rat befolgst und umkehrst.","story.map8-dungeon8.028":"Nun denn, <wait=40>ich gehe.","story.map8-dungeon8.029":"Wir unterhalten uns wieder, sobald ich mein Ziel erfolgreich erreicht habe.","story.map8-dungeon8.030":"Glaub nicht, dass ich es aufgegeben habe, dich auf unsere Seite zu holen.","story.map8-dungeon8.031":"Hehehe.","story.map8-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_clear.002":"Herr! <wait=40>Geht es dir gut?","story.map8-dungeon_ex_clear.003":"*Seufz* <wait=20>Was für eine Erleichterung.","story.map8-dungeon_ex_clear.004":"Offiziere der Beschwörerhalle haben den unterirdischen See nach deinem Aufbruch weiter untersucht.","story.map8-dungeon_ex_clear.005":"Anscheinend ruhte dort der Gott Lagzal.","story.map8-dungeon_ex_clear.006":"Er erschien auch in Grand Gaia, während der großen Schlacht zwischen Göttern und Menschen.","story.map8-dungeon_ex_clear.007":"Laut unseren Aufzeichnungen wurde er damals von einem einzigen Helden besiegt.","story.map8-dungeon_ex_clear.008":"Doch wie es scheint, wurde er nicht vollständig vernichtet, sondern zog sich hierher zurück.","story.map8-dungeon_ex_clear.009":"Mir ist fast das Herz stehen geblieben, als wir auf diese Information gestoßen sind.","story.map8-dungeon_ex_clear.010":"Ich meine, er hat im Kampf so vielen Menschen das Leben genommen!","story.map8-dungeon_ex_clear.011":"Ich habe mir solche Sorgen gemacht, als ich erfahren habe, dass du gegen ihn kämpfen würdest...","story.map8-dungeon_ex_clear.012":"......","story.map8-dungeon_ex_clear.013":"Für eine Entschuldigung ist es zu spät!","story.map8-dungeon_ex_clear.014":"......","story.map8-dungeon_ex_clear.015":"*Seufz* <wait=40>Aber du bist nun mal ein Beschwörer.","story.map8-dungeon_ex_clear.016":"Von jetzt an wirst du immer gefährlichere Orte erkunden.","story.map8-dungeon_ex_clear.017":"Wenn ich dich wirklich unterstützen will, sollte ich nicht versuchen, dich aufzuhalten.","story.map8-dungeon_ex_clear.018":"Verstanden!","story.map8-dungeon_ex_clear.019":"Ich glaube an dich, Herr!","story.map8-dungeon_ex_clear.020":"Und du kannst dich immer auf mich verlassen, Herr!","story.map8-dungeon_ex_clear.021":"Hehehe.","story.map8-dungeon_ex_clear.022":"Also dann, ich melde mich, sobald neue Informationen eintreffen!","story.map8-dungeon_ex_clear.023":"Bitte pass bis dahin auf dich auf!","story.map8-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_open.002":"Herr, <wait=40>hörst du mich?","story.map8-dungeon_ex_open.003":"Super, <wait=20>diesmal bin ich direkt zu dir durchgekommen.","story.map8-dungeon_ex_open.004":"Lin Merylham von der Logistikunterstützung...","story.map8-dungeon_ex_open.005":"...des Ermittlungsbüros im Vermessungsamt von Grand Gaia, zu deinen Diensten.","story.map8-dungeon_ex_open.006":"<rep_handlename>, als Mitglied der Beschwörerarmee der Akras-Beschwörerhalle...","story.map8-dungeon_ex_open.007":"...bitten wir dich heute, den Unterirdischen See von Golzo zu untersuchen!","story.map8-dungeon_ex_open.008":"Vor ein paar Tagen hat die Beschwörerhalle das Verschwinden einer großen Kraft in Lizeria gespürt.","story.map8-dungeon_ex_open.009":"Gleich danach haben wir hier in diesem unterirdischen See eine noch größere Kraft gespürt.","story.map8-dungeon_ex_open.010":"Wir möchten, dass du untersuchst, was hier genau vor sich geht.","story.map8-dungeon_ex_open.011":"Ich persönlich habe dabei ein ganz schlechtes Gefühl, also ist es in Ordnung, wenn du lieber ablehnst...","story.map8-dungeon_ex_open.012":"...aber dein Tonfall sagt etwas anderes.","story.map8-dungeon_ex_open.013":"Voller Ehrgeiz wie immer!","story.map8-dungeon_ex_open.014":"Verstanden!","story.map8-dungeon_ex_open.015":"So besorgt ich auch bin, ich drücke dir wie immer die Daumen!","story.map8-dungeon_ex_open.016":"Also bitte, <wait=40>komm heil zu mir zurück!","story.map8-dungeon_ex_open.017":"Verstanden?","story.map8-dungeon_ex_open.018":"Pff...","story.map8-ending.001":"So ein Verteidigungssystem einfach auszuschalten...","story.map8-ending.002":"Das ist wohl die Macht, die man von jemandem erwarten kann, der einen Gefallenen Gott besiegt hat.","story.map8-ending.003":"Trotzdem <wait=20>werde ich auf keinen Fall aufgeben, was hinter dem Tor da vorn versiegelt ist!","story.map8-ending.004":"Sieh dich nur an, <rep_handlename>.","story.map8-ending.005":"Du bist nicht mal schlimm verletzt und kannst dich trotzdem nicht bewegen?","story.map8-ending.006":"Tss, <wait=40>es ärgert mich maßlos, dass ich mit dir solche Schwierigkeiten hatte.","story.map8-ending.007":"Hä? <wait=40>Was meinst du mit „schnell weiter“?","story.map8-ending.008":"Heh, <wait=20>dir hat man wohl gar nichts erzählt, was?","story.map8-ending.009":"Komm mit.","story.map8-ending.010":"Sehen wir mal nach, in was für interessante Schwierigkeiten sich diese Frau gebracht hat.","story.map8-ending.011":"W-<wait=20>Warte. <wait=20>Wie kann hier nichts sein?","story.map8-ending.012":"Heißt das, wir wurden getäuscht?","story.map8-ending.013":"Wie konnten wir nur...","story.map8-ending.014":"Was gewinnt man dadurch, uns so an der Nase herumzuführen?","story.map8-ending.015":"He, <rep_handlename>! <wait=40>Sieh nur!","story.map8-ending.016":"Genau wie ich gesagt habe.","story.map8-ending.017":"Das kleine Fräulein von der Kaiserlichen Garde scheint ein bisschen in der Klemme zu stecken.","story.map8-ending.018":"Lugina...","story.map8-ending.019":"Heh hehe. <wait=40>Lass die finsteren Blicke.","story.map8-ending.020":"Die Macht, nach der du suchst, ist hier nirgends.","story.map8-ending.021":"Sie ist in den Ruinen des Tors.","story.map8-ending.022":"Das weiß ich, weil die Ältesten Beschwörer mich geschickt haben, um sie zu untersuchen.","story.map8-ending.023":"Allerdings hat es mir Spaß gemacht, deinem leidenschaftlichen Geschwätz zuzuhören.","story.map8-ending.024":"Du ordinärer Schwachkopf.","story.map8-ending.025":"<size=20>Bwa ha ha ha!</size>","story.map8-ending.026":"Starr mich an, so viel du willst, das Tor geht trotzdem nicht auf.","story.map8-ending.027":"Ngh...","story.map8-ending.028":"<rep_handlename>.","story.map8-ending.029":"Wie hältst du es nur so lange mit so einem ordinären Kerl aus?","story.map8-ending.030":"Du weißt, was ich meine, oder?","story.map8-ending.031":"Dieser Mann ist absoluter Abschaum!","story.map8-ending.032":"Ich warte nur auf den Tag, an dem du meine Einladung annimmst.","story.map8-ending.033":"Oh, <wait=20>wie neidisch ich bin! <wait=40>Ich wollte auch eingeladen werden, weißt du!","story.map8-ending.034":"Obwohl es schade wäre, meine Zeit an deine fruchtlose Sache zu verschwenden.","story.map8-ending.035":"Ngh.","story.map8-ending.036":"Merk dir das.","story.map8-ending.037":"Eines Tages werde ich dich alles bereuen lassen, was du getan hast.","story.map8-ending.038":"Heh, <wait=20>endlich ist sie weg.","story.map8-ending.039":"He, <rep_handlename>.","story.map8-ending.040":"Warum siehst du plötzlich so ruhig aus?","story.map8-ending.041":"Du glaubst doch nicht etwa, dass ich dir vergeben habe, oder?","story.map8-ending.042":"Ich werde noch mächtiger werden, als ich vorher war.","story.map8-ending.043":"Und wenn es so weit ist, werde ich dich so gut ausnutzen, wie ich kann.","story.map8-ending.044":"Vergiss das nicht!","story.map8-ending.045":"Heh.","story.map8-ending.046":"Oh, <wait=20>und noch etwas...","story.map8-ending.047":"Sieht so aus, als hättest du wirklich keine Ahnung gehabt, worauf wir diesmal aus waren.","story.map8-ending.048":"Zuerst dachte ich, du willst mich nur austricksen, um mir zuvorzukommen.","story.map8-ending.049":"Aber am Ende warst du wohl genauso dämlich, wie du aussiehst!","story.map8-ending.050":"<size=20>Bwa ha ha ha!</size>","story.map8-ending.051":"Der nächste große Erfolg wird meiner sein.","story.map8-ending.052":"Und du solltest dankbar sein für alles, was ich, der unglaublich mächtigste Beschwörer aller Zeiten, für dich getan habe!","story.map8-ending.053":"Verstehe, <wait=20>das Tor ist also verschwunden.","story.map8-ending.054":"Schon gut. <wait=20>Du musst dich nicht entschuldigen.","story.map8-ending.055":"Du hast bei einer schwierigen Aufgabe dein Bestes gegeben.","story.map8-ending.056":"Ja, <wait=20>pass auf dich auf und komm sicher zurück.","story.map8-ending.057":"Hehehe.","story.map8-ending.058":"Es scheint alles genau so gewesen zu sein, wie du gesagt hast.","story.map8-ending.059":"Der Vertrag scheint erfüllt zu sein.","story.map8-ending.060":"Es wird Zeit, dass auch wir aufbrechen.","story.map8-ending.061":"Ja, <wait=40>auch mein Meister erwartet deinen Einsatz.","story.map8-ending.062":"Hehehe.","story.map8-ending.063":"<size=20>Lasst uns die Welt in ihre wahre Form zurückführen!</size>","story.map8-ending.064":"<size=20>Wir werden sehen, wie sie sich vor unseren Augen wandelt und entwickelt!</size>","story.map8-ending.065":"<size=20>Wartet nur ab!</size>","story.map8-ending.066":"<size=20>Bald wird ein neuer Held geboren!</size>","story.map8-open.001":"Randall,<wait=40> Hauptstadt des Randall-Imperiums.","story.map8-open.002":"Die Privatgemächer der Leibwächter der Kaiserfamilie, <wait=40>der Kaiserlichen Garde.","story.map8-open.003":"*Klopf* <wait=20>*klopf*","story.map8-open.004":"Herein.","story.map8-open.005":"Verzeiht die Störung.","story.map8-open.006":"Oh, <wait=40> was für ein erfreulicher Gesichtsausdruck. <wait=20>Du hast also gute Neuigkeiten für mich?","story.map8-open.007":"Ja, <wait=20>und verzeiht, dass es so lange gedauert hat.","story.map8-open.008":"Unsere Untersuchungen lassen darauf schließen, dass das gesuchte Tor in Lizeria liegt.","story.map8-open.009":"...Lizeria.","story.map8-open.010":"Wenn ich mich recht erinnere, soll dort einst La Veda gelegen haben.","story.map8-open.011":"Verstehe. <wait=20>Man hat uns also doch nicht belogen.","story.map8-open.012":"So ist es.","story.map8-open.013":"Ich bezweifle zwar, dass alle Informationen, die wir erhalten haben, stimmen, aber diese zumindest wohl schon.","story.map8-open.014":"......","story.map8-open.015":"Ich möchte selbst dorthin, um es zu bestätigen.","story.map8-open.016":"Erteilt Ihr mir die Erlaubnis dazu?","story.map8-open.017":"Soweit ich weiß, hat die Beschwörerarmee eine neue Untersuchung in diesem Gebiet begonnen.","story.map8-open.018":"Verstanden. <wait=40>Ich werde mein Bestes tun, so schnell wie möglich fertig zu werden.","story.map8-open.019":"Das ist ein ziemlich gefährliches Unterfangen, weißt du?","story.map8-open.020":"Für wahren Frieden bin ich bereit, mich zu opfern.","story.map8-open.021":"Ich zähle auf dich.","story.map8-open.022":"Das müsst Ihr nicht sagen.","story.map8-open.023":"Ich sorge dafür, dass alles erledigt wird!","story.map8-open.024":"Viel Glück.","story.map8-open.025":"Wer ist da!?","story.map8-open.026":"Sieht aus, als hättest du etwas zu sagen.","story.map8-open.027":"Hast du gelauscht? <wait=40>Warum kommst du nicht heraus?","story.map8-open.028":"......","story.map8-open.029":"Verstehe. <wait=40>Du musst es gar nicht aussprechen.","story.map8-open.030":"Wir haben keine Zeit zu verlieren. <wait=20>Wir müssen die Welt in ihre richtige Form zurückführen.","story.map8-open.031":"Ob dieser Haufen von der Beschwörerarmee es wohl je begreifen wird...","story.map8-open.032":"...wie diese Welt wirklich sein sollte.","story.map9-dungeon1.001":"Hey, <wait=20><rep_handlename>!","story.map9-dungeon1.002":"Du bist also auch nach Ryvern gekommen, <wait=20>dem Tor zur Agni-Region. ","story.map9-dungeon1.003":"Ich nehme an, du bist hinter Zevalhua her, <wait=20>dem nächsten der Gefallenen Götter. ","story.map9-dungeon1.004":"Natürlich helfen wir dir auch diesmal wieder, also sollte es kein Problem geben!","story.map9-dungeon1.005":"Karl! <wait=40>Wir haben unsere eigenen Ziele, schon vergessen!?","story.map9-dungeon1.006":"Ich habe keine Lust, <rep_handlename> zu helfen, <wait=20>zumal die Beschwörerhalle uns nie darum gebeten hat.","story.map9-dungeon1.007":"Haha, <wait=20>du bist wie immer, Seria.","story.map9-dungeon1.008":"<rep_handlename> hat schon zwei der Vier Gefallenen Götter besiegt. ","story.map9-dungeon1.009":"Findest du nicht, dass du das wenigstens anerkennen solltest?","story.map9-dungeon1.010":"Hmpf, <wait=20>ich erkenne die Stärke an, die das gebraucht hat.","story.map9-dungeon1.011":"Aber schau dir nur diesen selbstgefälligen Blick an!","story.map9-dungeon1.012":"Ich warne nur fair vor, <wait=20>das ist alles!","story.map9-dungeon1.013":"<rep_handlename>! <wait=20>Du solltest mir dankbar sein!","story.map9-dungeon1.014":"Ah! <wait=20>Da bist du ja!","story.map9-dungeon1.015":"<rep_handlename>! <wait=20>Was hat denn so lange gedauert?","story.map9-dungeon1.016":"Oh, <wait=20>Karl und Seria!","story.map9-dungeon1.017":"Hey, <wait=20>Göttin.","story.map9-dungeon1.018":"Sie ist also doch aufgetaucht...","story.map9-dungeon1.019":"Hey, ihr zwei!","story.map9-dungeon1.020":"Ihr helft <rep_handlename> diesmal doch auch wieder, oder?","story.map9-dungeon1.021":"Wir sind hinter Graham her!","story.map9-dungeon1.022":"Mach dir darüber jetzt keine Gedanken.","story.map9-dungeon1.023":"Der entwischt euch doch sowieso, <wait=20>also warum helft ihr diesmal nicht gleich von Anfang an?","story.map9-dungeon1.024":"Das ist ganz schön gemein.","story.map9-dungeon1.025":"Du!","story.map9-dungeon1.026":"Es macht so viel Spaß, mit euch allen solche Abenteuer zu erleben.","story.map9-dungeon1.027":"Ich habe einfach das Gefühl, dass wir es irgendwie schaffen, egal wie hart der Kampf ist. Ihr nicht?","story.map9-dungeon1.028":"Haha, <wait=20>wenn die Göttin das sagt, bleibt uns wohl keine Wahl.","story.map9-dungeon1.029":"Stimmt\'s, <wait=20>Seria?","story.map9-dungeon1.030":"Du bist so leicht rumzukriegen, Karl...","story.map9-dungeon1.031":"Na ja, <wait=20>Lord Grahdens wird uns sowieso darum bitten, also können wir wohl helfen. ","story.map9-dungeon1.032":"Du bist ja doch ein Schatz, Seria!","story.map9-dungeon1.033":"W-<wait=20>Was ist denn mit dir los!","story.map9-dungeon1.034":"Ich helfe nur, weil uns nichts anderes übrig bleibt.","story.map9-dungeon1.035":"Ha ha ha. <wait=20>Sieht aus, als hätten wir uns entschieden.","story.map9-dungeon1.036":"Damit stecken wir alle gemeinsam drin, <rep_handlename>!","story.map9-dungeon1.037":"Geben wir unser Bestes und verpassen diesem Zevalhua eine Abreibung!","story.map9-dungeon1.038":"Super! <wait=40>Gebt alle euer Bestes!","story.map9-dungeon1.039":"*Seufz* <wait=20>Ich weiß immer noch nicht recht...","story.map9-dungeon1.040":"Hmm. <wait=40>Wie erbärmlich...","story.map9-dungeon2.001":"Hey, <rep_handlename>. <wait=40>Du bist etwas spät dran. ","story.map9-dungeon2.002":"Die Göttin war gerade eben noch hier.","story.map9-dungeon2.003":"Dann hat sie sich mit Seria gestritten, <wait=20>und beide sind vorausgestürmt. ","story.map9-dungeon2.004":"Ha ha ha. <wait=40>Die beiden <wait=40>sind sich echt nähergekommen, was?","story.map9-dungeon2.005":"Helfen wir uns gegenseitig, damit wir nicht gegen sie verlieren!","story.map9-dungeon2.006":"Was für wahrhaft erbärmliche Wesen ihr Menschen doch seid.","story.map9-dungeon2.007":"Wer ist da?","story.map9-dungeon2.008":"Kein Grund, Angst zu haben.","story.map9-dungeon2.009":"Mein Name ist Mare.","story.map9-dungeon2.010":"Ich bin eine Jüngerin von Zevalhua dem Erhabenen.","story.map9-dungeon2.011":"Eine Jüngerin von Zevalhua?","story.map9-dungeon2.012":"Du bist also gekommen, um uns zu töten? ","story.map9-dungeon2.013":"Wie respektlos, so schlecht über Lord Zevalhua zu sprechen...","story.map9-dungeon2.014":"Nur ein weiteres Zeichen eurer Unwissenheit. Wie traurig...","story.map9-dungeon2.015":"Dennoch, versteht mich nicht falsch.","story.map9-dungeon2.016":"Euch zwei zu erledigen ist nichts, wofür ich meinen Namen aufs Spiel setzen müsste.","story.map9-dungeon2.017":"Mein Ziel bist nicht du, Beschwörer, <wait=40>sondern der Blauhaarige. <wait=40>Ich bin hinter dir her.","story.map9-dungeon2.018":"Ich bin dein Ziel?","story.map9-dungeon2.019":"Was willst du von mir?","story.map9-dungeon2.020":"Ich dachte, ich spiele die Rolle eines Gottes und enthülle dir die Wahrheit. ","story.map9-dungeon2.021":"Die Wahrheit?","story.map9-dungeon2.022":"Du hast dich von diesem Narren Grahdens täuschen lassen, und nun ist dein Leben ein einziges Durcheinander.","story.map9-dungeon2.023":"Du... <wait=60>Was genau hast du vor?","story.map9-dungeon2.024":"Du musst nicht misstrauisch sein. ","story.map9-dungeon2.025":"Es waren deine Ältesten, die dich so bald nach deinem Auffinden in fremde Obhut gaben.","story.map9-dungeon2.026":"Du hattest eine traurige Kindheit und hast nie die Wärme von Eltern gekannt.","story.map9-dungeon2.027":"Darum werde ich dir, der von diesen verantwortungslosen alten Männern aufgenommen wurde...","story.map9-dungeon2.028":"...als mitfühlender Gott die Wahrheit sagen.","story.map9-dungeon2.029":"Hör auf mit dem Unsinn!","story.map9-dungeon2.030":"Was weißt du schon über den Ältesten Grahdens!","story.map9-dungeon2.031":"Als einer der Ältesten Beschwörer war er immer so beschäftigt...","story.map9-dungeon2.032":"...aber er hat sich immer um mich gekümmert!","story.map9-dungeon2.033":"Er ist überhaupt nicht so, wie du ihn hinstellst, du Jüngerin eines Gefallenen Gottes!","story.map9-dungeon2.034":"Du bist genauso wortgewandt wie Grahdens. ","story.map9-dungeon2.035":"Man hat dir offenbar gründlich das Hirn gewaschen. ","story.map9-dungeon2.036":"Halt den Mund! <wait=40>Ich lasse nicht zu, dass du noch ein Wort gegen ihn sagst!","story.map9-dungeon2.037":"Du bist ein ahnungsloser, törichter Idiot.","story.map9-dungeon2.038":"Ich werde dir den Weg zeigen.","story.map9-dungeon2.039":"Ich warte in den Azura-Ruinen gleich da vorne auf dich. ","story.map9-dungeon2.040":"Komm allein, wenn du die Wahrheit wissen willst.","story.map9-dungeon2.041":"<rep_handlename>, <wait=40>ich verdanke dem Ältesten Grahdens alles.","story.map9-dungeon2.042":"Er ist vielleicht etwas seltsam, aber er ist vertrauenswürdig und er liegt mir sehr am Herzen!","story.map9-dungeon2.043":"Was sie über ihn gesagt hat, kann ich nicht verzeihen. ","story.map9-dungeon2.044":"Tut mir leid, aber du musst ohne mich weitergehen.","story.map9-dungeon2.045":"Ich gehe zu den Azura-Ruinen und stelle sie zur Rede.","story.map9-dungeon2.046":"Ich überlasse Zevalhua dir!","story.map9-dungeon2.047":"Ich flehe dich an, <rep_handlename>, <wait=20>bitte!","story.map9-dungeon3.001":"<rep_handlename>!","story.map9-dungeon3.002":"Hast du Karl gesehen?","story.map9-dungeon3.003":"Er hat mir in Khelne gesagt, ich soll vorausgehen, <wait=20>also hab ich das gemacht, aber...","story.map9-dungeon3.004":"Er wirkte ruhig, <wait=20>aber ich glaube, er war eigentlich total aufgewühlt. ","story.map9-dungeon3.005":"So aufgewühlt habe ich ihn noch nie gesehen.","story.map9-dungeon3.006":"Hä? <wait=40>Eine Jüngerin von Zevalhua ist aufgetaucht und hat über ihn und Lord Grahdens geredet?","story.map9-dungeon3.007":"Verstehe.","story.map9-dungeon3.008":"Lord Grahdens ist für Karl ein sehr wichtiger Mensch.","story.map9-dungeon3.009":"Ihr seid doch seit eurer Kindheit befreundet, oder? <wait=40>Du kennst die ganze Geschichte, oder?","story.map9-dungeon3.010":"Trotzdem <wait=40>redet Karl wirklich nicht gern über sich selbst, was...","story.map9-dungeon3.011":"Wenn er uns einfach sagen würde, was los ist, <wait=20>könnten wir vielleicht helfen.","story.map9-dungeon3.012":"Wie auch immer, <wait=20>beeilen wir uns zu den Azura-Ruinen!","story.map9-dungeon3.013":"Karl geht\'s bestimmt gut, aber ich mache mir trotzdem Sorgen.","story.map9-dungeon3.014":"Du bist recht fürsorglich <wait=40>für einen Wurm wie dich.","story.map9-dungeon3.015":"Er gehört bereits uns.","story.map9-dungeon3.016":"Er wird nicht mehr zu euch zurückkehren. ","story.map9-dungeon3.017":"Du bist also Mare!","story.map9-dungeon3.018":"Törichte Menschen. <wait=40>Habt ihr Angst, die Wahrheit zu sehen?","story.map9-dungeon3.019":"Wenn nicht, solltet ihr ebenfalls kommen.","story.map9-dungeon3.020":"Seht ihn euch an, jetzt, da er die Wahrheit akzeptiert hat.","story.map9-dungeon3.021":"Das reicht!","story.map9-dungeon3.022":"Tilith!","story.map9-dungeon3.023":"Hehe, <wait=20>das ist das erste Mal, dass du mich beim Namen nennst.","story.map9-dungeon3.024":"D-<wait=20>Du Idiotin! <wait=40>Dafür ist jetzt keine Zeit!","story.map9-dungeon3.025":"Du hast recht. <wait=20>Wir müssen etwas gegen Mare unternehmen.","story.map9-dungeon3.026":"Was will eine niedere Göttin wie du von mir?","story.map9-dungeon3.027":"Wie gemein!","story.map9-dungeon3.028":"Ich bin immerhin die wunderbare Schülerin von Lord Lucius!","story.map9-dungeon3.029":"Und noch etwas, Seria. <wait=20>Lass dich nicht täuschen.","story.map9-dungeon3.030":"Mare ist gut darin, die Herzen anderer zu verwirren. ","story.map9-dungeon3.031":"In dem, was sie sagt, steckt kaum Wahrheit.","story.map9-dungeon3.032":"Kannst du denn entscheiden, was wahr ist und was nicht?","story.map9-dungeon3.033":"Du, <wait=20>die blind jedem Wort von Lucius folgt <wait=20>und Menschen ihre Kräfte leiht und so weiter.","story.map9-dungeon3.034":"Willst du etwa sagen, dass Lord Lucius sich irrt?","story.map9-dungeon3.035":"Es spielt keine Rolle. <wait=40>Bei so törichten Gottheiten ist nichts zu machen. ","story.map9-dungeon3.036":"Ich rede von dir, weißt du.","story.map9-dungeon3.037":"Wenn du die Wahrheit wissen willst, musst du einfach glauben, was ich sage.","story.map9-dungeon3.038":"Dann wirst du diesen Mann wiedersehen. ","story.map9-dungeon3.039":"Warte mal kurz!","story.map9-dungeon3.040":"Meine Güte! <wait=40>Sie ist genauso unausstehlich, wie ich gehört habe!","story.map9-dungeon3.041":"Seria! <wait=20>Karl geht\'s bestimmt gut!","story.map9-dungeon3.042":"Also tu nichts Unüberlegtes!","story.map9-dungeon3.043":"Ich weiß. <wait=40>Mir geht\'s jetzt gut.","story.map9-dungeon3.044":"Aber ich mache mir trotzdem Sorgen um Karl.","story.map9-dungeon3.045":"Ich weiß, dass es eine Falle sein könnte...","story.map9-dungeon3.046":"...aber Karl ist ganz sicher gerade auf dem Weg dorthin.","story.map9-dungeon3.047":"<rep_handlename>, ich will, dass du hier so viel Wirbel wie möglich machst.","story.map9-dungeon3.048":"Ich brauche eine Ablenkung, wenn ich schnell zu Karl kommen will. ","story.map9-dungeon3.049":"Ja, <wait=20>dir geht\'s wirklich gut, wie mir scheint!","story.map9-dungeon3.050":"Sogar wie du so tust, als würdest du <rep_handlename> herumkommandieren, passt perfekt zu dir!","story.map9-dungeon3.051":"Ich tue überhaupt nicht so!","story.map9-dungeon3.052":"*Seufz* <wait=40>Wie auch immer, genug davon.","story.map9-dungeon3.053":"Tilith, <wait=20>beschütze <rep_handlename> für mich.","story.map9-dungeon3.054":"Wer weiß, was diese Jüngerin Mare versuchen wird.","story.map9-dungeon3.055":"Ich kann mir nicht vorstellen, dass sie jemanden in Ruhe lässt, der schon zwei der Vier Gefallenen Götter besiegt hat.","story.map9-dungeon3.056":"Verstanden. <wait=40>Aber <wait=20>tu bitte nichts Leichtsinniges.","story.map9-dungeon3.057":"Mach dir um mich keine Sorgen.","story.map9-dungeon3.058":"So schwach bin ich nicht, dass sich eine törichte Göttin wie du um mich sorgen müsste.","story.map9-dungeon3.059":"Bescheiden wie immer, was, Seria!","story.map9-dungeon3.060":"Hehe, <wait=40>jedenfalls bin ich weg.","story.map9-dungeon3.061":"<rep_handlename>, <wait=40>pass du auch gut auf dich auf, ja?","story.map9-dungeon4.001":"<rep_handlename>...","story.map9-dungeon4.002":"Es tut mir leid...","story.map9-dungeon4.003":"Mare...<wait=20> Sie hat uns reingelegt...","story.map9-dungeon4.004":"Seria! <wait=40>Bist du in Ordnung?","story.map9-dungeon4.005":"Mir geht\'s...<wait=40>gut...","story.map9-dungeon4.006":"Aber...<wait=20>Karl ist...","story.map9-dungeon4.007":"Überanstreng dich nicht!","story.map9-dungeon4.008":"Mare...<wait=20>und Karl waren...<wait=20>gleich stark...","story.map9-dungeon4.009":"Ich dachte, ich versuche zu helfen...","story.map9-dungeon4.010":"Aber <wait=40>genau das...<wait=20>wollte sie wohl...","story.map9-dungeon4.011":"In dem Moment, als ich mich auf sie konzentrierte...","story.map9-dungeon4.012":"rief sie ihre versteckten Diener herbei. <wait=20>Sie stürzten sich alle auf einmal auf mich...","story.map9-dungeon4.013":"Und gerade als ich ihren Angriffen ausweichen wollte...<wait=20>griff Mare mich von hinten an...","story.map9-dungeon4.014":"Karl...<wait=20>er hat mich <wait=20>vor ihrem Angriff beschützt...","story.map9-dungeon4.015":"Und dann, <wait=20>als ich Karl beschützen wollte, nachdem er gefallen war, <wait=20>ist das passiert...","story.map9-dungeon4.016":"Seria...","story.map9-dungeon4.017":"Sie hat zu mir gesagt...","story.map9-dungeon4.018":"„Ich lasse dich als Botschaft an <rep_handlename> zurück...","story.map9-dungeon4.019":"...Nur deshalb lasse ich dich am Leben.“","story.map9-dungeon4.020":"Ich war so töricht!","story.map9-dungeon4.021":"Nicht nur in ihre Falle zu tappen, sondern jetzt auch noch das. <wait=20>Wie soll ich mit dieser Schande leben? ","story.map9-dungeon4.022":"Ich bin trotzdem froh, das zu hören.","story.map9-dungeon4.023":"Froh worüber?!","story.map9-dungeon4.024":"Du lebst doch, oder? <wait=20>Ich bin einfach froh, dass du noch da bist.","story.map9-dungeon4.025":"Tilith...","story.map9-dungeon4.026":"Und wenn Karl gefangen genommen wurde, <wait=20>dann lebt er auch noch!","story.map9-dungeon4.027":"Mein <rep_handlename> kann ihn bestimmt retten!","story.map9-dungeon4.028":"Mir gefällt nicht, wie du <rep_handlename> als deins bezeichnest, <wait=20>und auch nicht, wie blind du vertraust...","story.map9-dungeon4.029":"Aber...<wait=20>du hast recht...","story.map9-dungeon4.030":"Karl wird anscheinend an einem Ort namens Weißer Turm festgehalten. ","story.map9-dungeon4.031":"Mare sagte, sie wartet dort auf dich.","story.map9-dungeon4.032":"Das ist zweifellos eine Falle.","story.map9-dungeon4.033":"Trotzdem flehe ich dich an, es zu versuchen.","story.map9-dungeon4.034":"<size=20><rep_handlename>, <wait=40>rette Karl!</size>","story.map9-dungeon4.035":"Hmpf, <wait=20>was soll das, einfach zu nicken und auf cool zu machen?","story.map9-dungeon4.036":"Du würdest ihn sowieso retten, auch wenn ich nichts sage, oder?","story.map9-dungeon4.037":"Nngh...","story.map9-dungeon4.038":"Seria! <wait=20>Überanstreng dich nicht!","story.map9-dungeon4.039":"<rep_handlename>! <wait=40>Überlass Seria mir!","story.map9-dungeon4.040":"Ich bringe sie sicher zurück nach Elgaia. ","story.map9-dungeon4.041":"Also bitte, <rep_handlename>, <wait=20>geh und rette Karl.","story.map9-dungeon4.042":"Seria und ich <wait=20>glauben an dich, <rep_handlename>.","story.map9-dungeon4.043":"Ich glaube nicht unbedingt an dich...","story.map9-dungeon4.044":"Seria, <wait=20>schon gut.","story.map9-dungeon4.045":"Mein <rep_handlename> ist der Stärkste von allen!","story.map9-dungeon4.046":"Wen nennst du hier deins?","story.map9-dungeon4.047":"Ach, <wait=40>egal...","story.map9-dungeon4.048":"<rep_handlename>...","story.map9-dungeon4.049":"Bitte...<wait=40>hol Karl für mich zurück...","story.map9-dungeon5.001":"<rep_handlename>. <wait=40>Ich habe auf dich gewartet.","story.map9-dungeon5.002":"Ich dachte mir, dass du auf dem Weg zum Weißen Turm hier vorbeikommst.","story.map9-dungeon5.003":"Der Weiße Turm liegt auf der anderen Seite des Ryvern-Gebirges, <wait=20>gleich hinter dem Ausgang der Höhle. ","story.map9-dungeon5.004":"Selbst mit deinen Fähigkeiten wird es wohl nicht leicht, dort durchzukommen.","story.map9-dungeon5.005":"Aber <wait=20>fürchte dich nicht. ","story.map9-dungeon5.006":"Ich werde den jungen Karl retten.","story.map9-dungeon5.007":"Er ist schließlich mein geliebter Sohn. ","story.map9-dungeon5.008":"Ho ho ho. <wait=40>Was ist das für ein zweifelnder Blick?","story.map9-dungeon5.009":"Ich habe keine Ahnung, was diese Jüngerin Mare gesagt hat.","story.map9-dungeon5.010":"Aber ich war es, der dieses ausgesetzte Baby aufgenommen und wie mein eigenes großgezogen hat.","story.map9-dungeon5.011":"Allerdings <wait=20>stimmt es, dass ich ihn irgendwann in die Obhut eines vertrauenswürdigen Bekannten gegeben habe. ","story.map9-dungeon5.012":"Das Leben eines Ältesten Beschwörers ist einfach zu hektisch.","story.map9-dungeon5.013":"Den Rest der Geschichte kennst du aber, oder?","story.map9-dungeon5.014":"Ich bin dir dankbar, dass du als Kind immer mit Karl gespielt hast. ","story.map9-dungeon5.015":"Ho ho ho.","story.map9-dungeon5.016":"Aber egal, wie beschäftigt ich war...","story.map9-dungeon5.017":"...ich hätte ihn nie einfach bei jemand anderem gelassen.","story.map9-dungeon5.018":"Ab und zu habe ich mich heimlich davongeschlichen, um nach ihm zu sehen. ","story.map9-dungeon5.019":"Ich hätte großen Ärger bekommen, wenn jemand gewusst hätte, dass ich als Ältester Beschwörer ein Kind habe.","story.map9-dungeon5.020":"Aber <wait=20>so heimlich ich auch sein musste, er hat mich trotzdem angenommen.","story.map9-dungeon5.021":"Ho ho ho. <wait=40>Wie nostalgisch.","story.map9-dungeon5.022":"Nun denn, <wait=20>ich sollte mich wohl auf den Weg machen.","story.map9-dungeon5.023":"Ein verlorenes Kind zurückzuholen ist die Pflicht der Eltern.","story.map9-dungeon5.024":"Und außerdem <wait=20>muss ich die Person bestrafen, die es gewagt hat, meinen lieben Sohn zu täuschen.","story.map9-dungeon5.025":"Ho ho ho. <wait=20>Keine Sorge.","story.map9-dungeon5.026":"Ich mag älter geworden sein, <wait=20>aber ich bin wohl immer noch um ein Vielfaches stärker als jeder von euch.","story.map9-dungeon5.027":"Und <wait=20>selbst wenn mir etwas zustoßen sollte...","story.map9-dungeon5.028":"...habe ich die anderen Ältesten Beschwörer gebeten, auf euch alle aufzupassen. ","story.map9-dungeon5.029":"Ho ho ho. <wait=40>Bin ich vielleicht zu vorsichtig?","story.map9-dungeon5.030":"Fürchte dich nicht und mach dich auf den Weg zu Zevalhua.","story.map9-dungeon5.031":"Karl will dich bestimmt auch nicht aufhalten.","story.map9-dungeon5.032":"Aber trotzdem willst du zum Weißen Turm, nicht wahr?","story.map9-dungeon5.033":"Karl hat wirklich gute Freunde. ","story.map9-dungeon5.034":"Nun denn, <wait=20>ich rette Karl und warte dann am Weißen Turm auf dich. ","story.map9-dungeon5.035":"Ho ho ho.","story.map9-dungeon6.001":"Sieht aus, als wäre nur noch einer übrig. ","story.map9-dungeon6.002":"Ihr Menschen seid wahrhaft törichte Wesen, wie es scheint. ","story.map9-dungeon6.003":"Ich vernichte dich genau wie den Rest dieser törichten Krieger.","story.map9-dungeon6.004":"<size=20>Das lasse ich nicht zu!</size>","story.map9-dungeon6.005":"Ich beschütze <rep_handlename>!","story.map9-dungeon6.006":"Du bist es...","story.map9-dungeon6.007":"Du bist viel früher zurück, als ich gedacht hätte.","story.map9-dungeon6.008":"Ich würde dich eine Närrin nennen, <wait=20>aber was hätte ich von einer Schülerin von Lucius auch erwarten sollen.","story.map9-dungeon6.009":"Wie auch immer...","story.map9-dungeon6.010":"Beschwörer, <wait=40>ich erwarte dich am Weißen Turm.","story.map9-dungeon6.011":"Dein Freund wird auch bei mir sein.","story.map9-dungeon6.012":"<rep_handlename>, bist du in Ordnung?","story.map9-dungeon6.013":"Wenn du dir Sorgen um Seria machst, ist das unnötig.","story.map9-dungeon6.014":"Ich habe sie sicher nach Elgaia zurückgebracht, und jetzt ruht sie sich friedlich in der Beschwörerhalle aus. ","story.map9-dungeon6.015":"Also, <wait=20>retten wir Karl gemeinsam!","story.map9-dungeon6.016":"Du und ich schaffen das, <wait=20>egal wie viele Fallen Mare aufstellt!","story.map9-dungeon6.017":"Solange wir zusammen sind, gibt es keinen Gegner, den wir nicht besiegen können!","story.map9-dungeon6.018":"Karl! Halte nur noch ein bisschen durch!","story.map9-dungeon7.001":"Obwohl es so hell ist, ist mir dieser Ort echt unheimlich.","story.map9-dungeon7.002":"Ob das wieder eine von Mares Fallen ist?","story.map9-dungeon7.003":"Für euch muss ich keine meiner kostbaren Fallen verschwenden.","story.map9-dungeon7.004":"Das ist Mares Stimme!","story.map9-dungeon7.005":"Ich habe einen Gegner für euch vorbereitet.","story.map9-dungeon7.006":"Granvalm, Wächter dieses Turms. <wait=40>Vernichte diese Eindringlinge!","story.map9-dungeon7.007":"<size=20>Kyaaaah! <wait=40>Sieh dir diesen Drachen an!</size>","story.map9-dungeon7.008":"Er sollte der perfekte Gegner für ein paar Narren wie euch sein.","story.map9-dungeon7.009":"Warte!","story.map9-dungeon7.010":"Jetzt bin ich echt sauer! <wait=40><rep_handlename>, geh zurück!","story.map9-dungeon7.011":"Ha ha ha...","story.map9-dungeon7.012":"Sie sind abgehauen...","story.map9-dungeon7.013":"Aber <wait=20>dieser Drache sah aus, als würde er zurückeilen, um etwas zu beschützen...","story.map9-dungeon7.014":"Vielleicht wollte er sichergehen, dass Karl nicht entkommt.","story.map9-dungeon7.015":"<rep_handlename>!","story.map9-dungeon7.016":"Bestimmt ist es das!","story.map9-dungeon7.017":"Lauf diesem Drachen hinterher, mir geht\'s gut!","story.map9-dungeon7.018":"Ich muss mich hier nur kurz ausruhen!","story.map9-dungeon7.019":"Wir müssen Serias Vertrauen in uns gerecht werden.","story.map9-dungeon7.020":"Für meinen <rep_handlename> ist das kein Problem!","story.map9-dungeon7.021":"Halte dein Versprechen an Seria und rette Karl!","story.map9-ending.001":"Beschwörer. <wait=40>Du stehst ja noch.","story.map9-ending.002":"Entspann dich. <wait=40>Ich sorge dafür, dass dein Ende schnell und schmerzlos ist.","story.map9-ending.003":"Nach dir wird niemand mehr übrig sein, der Lord Zevalhua bedrohen könnte. ","story.map9-ending.004":"Was soll dieser überraschte Blick?","story.map9-ending.005":"Ich hatte es von Anfang an auf dich abgesehen.","story.map9-ending.006":"Auf dich, den von Lucius erwählten Beschwörer.","story.map9-ending.007":"Jetzt, da ich alle ausgelöscht habe, die dich einst beschützt haben...","story.map9-ending.008":"...ist niemand mehr übrig, der dich retten kann.","story.map9-ending.009":"Sogar der Alte wurde besiegt, als er jemanden retten wollte, der gar nicht hier war.","story.map9-ending.010":"Obendrein <wait=20>ist auch die Kraft dieser törichten Göttin, die ihren Glauben in dich gesetzt hat, erschöpft.","story.map9-ending.011":"Es spielt keine Rolle, wie viele von Lucius\' Schülern er entsendet.","story.map9-ending.012":"Sie verstehen doch sicher, dass der weiße Drache Schwächlinge wie sie einfach erstarren lässt.","story.map9-ending.013":"Er ist töricht geworden, weil er übermäßig viel Zeit mit euch Menschen verbracht hat.","story.map9-ending.014":"Ihr menschlichen Würmer seid wahrhaft erbärmlich.","story.map9-ending.015":"Ihr regt euch schnell auf und handelt dann auf eigene Faust.","story.map9-ending.016":"Selbst wenn ihr wisst, dass es eine Falle ist, sagt ihr, es sei, um eure Freunde zu retten, und zieht andere mit ins Unglück. ","story.map9-ending.017":"Allein zu handeln, wenn man für so vieles verantwortlich ist, führt nur ins Scheitern. ","story.map9-ending.018":"Und <wait=20>wer große Ziele hat und sich auf kleine konzentriert, verliert am Ende alles.","story.map9-ending.019":"Was für eine törichte Art zu leben.","story.map9-ending.020":"Du bist sicher nicht anders.","story.map9-ending.021":"Beschwörer...","story.map9-ending.022":"Hmpf, <wait=40>mir ist langweilig geworden.","story.map9-ending.023":"Ich habe geredet, weil ich dachte, du würdest dich vielleicht wehren, aber du bist wohl schon am Ende.","story.map9-ending.024":"Schön. <wait=40>Dann mache ich dir eben hier ein Ende!","story.map9-ending.025":"<size=20>Halt, sofort!</size>","story.map9-ending.026":"......","story.map9-ending.027":"......","story.map9-ending.028":"Du hast offenbar doch noch ein paar Verbündete.","story.map9-ending.029":"Aber das spielt keine Rolle.","story.map9-ending.030":"Der Mann, den du suchst, wird in der Hauptstadt von Agni festgehalten. ","story.map9-ending.031":"Du solltest ihm besser nachjagen, wenn du ihn retten willst.","story.map9-ending.032":"Und du hast keine Zeit zu warten, bis sich deine Freunde erholt haben.","story.map9-ending.033":"Sonst kommst du zu spät, um ihn zu retten.","story.map9-ending.034":"......","story.map9-ending.035":"Hey, <rep_handlename>, <wait=20>steh nicht einfach rum!","story.map9-ending.036":"Reden können wir später. <wait=40>Jetzt sollten wir uns auf den Weg zur Hauptstadt von Agni machen.","story.map9-ending.037":"Ich muss dir etwas sagen, wenn wir dort sind.","story.map9-ending.038":"Du solltest mir dankbar sein!","story.map9-ending.039":"<size=20>Ah ha ha ha!</size>","story.map9-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Ich bin Lucius...<br><wait=40>Gott dieses Tors...","story.map9-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Die Krise, die die Vier Gefallenen Götter heraufbeschworen,<wait=40> besteht noch immer...","story.map9-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Nutze meine Kraft <wait=40>und wage dich in neue Länder...","story.map9-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Um dieser Welt ohne Ordnung neue Hoffnung zu bringen...","story.map9-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Du musst an deine Kraft glauben <wait=20>und weiter voranschreiten...","story.map9-open.006":"<rep_handlename>! <wait=40>Sorry, dass du warten musstest!","story.map9-open.007":"Aber weil ich immer auf dich warte, <rep_handlename>...","story.map9-open.008":"...dachte ich, diesmal lasse ich dich warten!","story.map9-open.009":"Wie bitte? <wait=20>Du sagst, du hast gar nicht so lange gewartet?","story.map9-open.010":"Das ist unfair!","story.map9-open.011":"Ich hatte erwartet, dass du beim Warten auf mich wenigstens ins Schwitzen kommst!","story.map9-open.012":"Aber egal! <wait=40>Wichtig ist, dass wir schnell den nächsten Gefallenen Gott besiegen!","story.map9-open.013":"Nur noch die Hälfte der Vier Gefallenen Götter ist übrig!","story.map9-open.014":"Und als Nächstes forderst du...","story.map9-open.015":"...den großen Kaiser Zevalhua heraus, der die Agni-Region beherrscht. ","story.map9-open.016":"Es heißt, er sei mit Afla Dilith, einem anderen der Gefallenen Götter, verfeindet...","story.map9-open.017":"...aber er hat unsere Ankunft hier bestimmt schon bemerkt.","story.map9-open.018":"Er wird wahrscheinlich versuchen, uns Fallen zu stellen!","story.map9-open.019":"Aber du würdest doch nicht in so eine tappen, oder, <rep_handlename>?","story.map9-open.020":"Also dann, <wait=20>ich mache mich auf nach Milvana, wo Zevalhua wartet!","story.map9-open.021":"Randall,<wait=40> Hauptstadt des Randall-Imperiums.","story.map9-open.022":"Schloss Randall, in den Privatgemächern der Leibwächter der Kaiserfamilie, <wait=40>der Kaiserlichen Garde.","story.map9-open.023":"*Klopf* <wait=20>*klopf*","story.map9-open.024":"Verzeiht die Störung.","story.map9-open.025":"......","story.map9-open.026":"Die Vorbereitungen für den Aufbruch in die Agni-Region sind abgeschlossen. ","story.map9-open.027":"Ist das so.","story.map9-open.028":"Nun denn, lass auch uns aufbrechen. ","story.map9-open.029":"Nach Grand Gaia, in das Land, das die Götter beherrschen. ","storylog.category.10000.description":"Auf seiner Reise durch Grand Gaia stellt sich ein Beschwörer mit Freunden und einer mächtigen Göttin Dämonen in erbitterten Kämpfen.","storylog.category.10000.name":"Chroniken von Grand Gaia","storylog.category.10100.description":"Geführt von Tilith, die dem Gott Lucius dient, beginnt der Beschwörer ein großes Abenteuer. Die Vier Gefallenen Götter müssen besiegt werden, zuerst Maxwell.","storylog.category.10100.name":"Mistral","storylog.category.10101.description":"Eine einst von Riesen bewohnte Insel scheint das nächste Ziel des Beschwörers zu sein. Doch auch Paris von der Kaiserlichen Garde ist auf dem Weg nach Cordelica...","storylog.category.10101.name":"Cordelica","storylog.category.10102.description":"Der Beschwörer erreicht das Land, das Cardes der Bösartige zerstören will. Wo einst die legendären 4 Helden von Palmyna standen, beginnt ein neuer Kampf.","storylog.category.10102.name":"Palmyna","storylog.category.10103.description":"Paris reist auf die Insel der einstigen Republik La Veda, um nach einem sagenumwobenen Tor zu suchen, doch die Beschwörerhalle hat ihre Untersuchung bereits begonnen.","storylog.category.10103.name":"Lizeria","storylog.category.10104.description":"Zevalhua der Erhabene muss besiegt werden, bevor er alles zerstört. Es heißt, er liege im Streit mit Afla Dilith, einem der Vier Gefallenen Götter.","storylog.category.10104.name":"Agni-Region","storylog.category.11001.description":"Während Karl den Dämon Graham verfolgt, will der Beschwörer Maxwells Jünger Abaddon herausfordern. Doch kann Abaddon wirklich besiegt werden?","storylog.category.11001.name":"Morgan","storylog.category.11002.description":"Das Land unter der Herrschaft der Schöpferin Maxwell ist das neue Ziel. Mit Tilith geht es zu Maxwells Festung, dem Palast von St. Lamia.","storylog.category.11002.name":"St. Lamia","storylog.category.11010.description":"Der Beschwörer landet dort, wo einst das große Amdahl-Imperium blühte. Tilith erwartet, dass diese Reise mit dem Sieg über Cardes den Bösartigen endet.","storylog.category.11010.name":"Amdahl","storylog.category.11011.description":"Laut Tilith war dieses Land einst Schauplatz eines Bürgerkriegs der Menschen. Mitten in der Wildnis brechen heftige Kämpfe aus.","storylog.category.11011.name":"Encervis","storylog.category.11040.description":"Zevalhua der Erhabene ist das neue Ziel. Tilith befürchtet, dass ein Komplott im Gange ist.","storylog.category.11040.name":"Ryvern","storylog.category.11041.description":"Der Beschwörer betritt das Land, in dem einst ein stolzes Imperium stand. Grahdens hat dir und Lugina Karls Rettung anvertraut, doch...","storylog.category.11041.name":"Agni","storylog.category.11042.description":"Endlich ist Zevalhuas Festung erreicht. Auf diesem alten Schlachtfeld beginnt ein neuer Kampf, um den gefangenen Grahdens zu retten.","storylog.category.11042.name":"Mirvana","storylog.category.20000.description":"Der Beschwörer soll ein neu entdecktes, geheimnisvolles Land erkunden. Doch die Gegner dort sind viel stärker als gedacht...","storylog.category.20000.name":"Eine neue Region","storylog.scenario.10001.description":"In der Höhle der Flammen erklärt Tilith die Lage in Grand Gaia. Um die Vier Gefallenen Götter zu besiegen, muss der Beschwörer eine weite, lange Reise antreten...","storylog.scenario.10001.title":"Beginn der Reise","storylog.scenario.10002.description":"Auf dem Egor-Schneefeld erklärt Tilith, wie wichtig die Elemente der Einheiten sind. Donner schlägt Wasser usw. Gut zu wissen für künftige Kämpfe.","storylog.scenario.10002.title":"Element-Vorteile","storylog.scenario.10003.description":"Der Beschwörer erreicht den Wald der Bestien, wo Gegner wilde Tiere jagen. Hier wird auch der Einsatz von Sphären genau erklärt.","storylog.scenario.10003.title":"Ausrüstung zählt","storylog.scenario.10004.description":"Die Feuchtigkeit im Magutagal-Sumpf verdirbt Tilith die Laune, doch sie erklärt die Funken, die durch gleichzeitige Angriffe entstehen.","storylog.scenario.10004.title":"Kampftechnik","storylog.scenario.10005.description":"Tilith ist beeindruckt, dass der Beschwörer die Überreste von Mirza sicher erreicht hat. Zur Belohnung erklärt sie die Vorteile von Leader-Skills.","storylog.scenario.10005.title":"Führungsstärke","storylog.scenario.10006.description":"Gerüchten zufolge lauert im Monsternest ein geheimnisvoller Schwertkämpfer. Tilith schwört, dass sie keine Angst hat, wirkt aber ziemlich verängstigt...","storylog.scenario.10006.title":"Ich hab keine Angst!","storylog.scenario.10007.description":"Am Turm von Mistral ist die Befreiung der ganzen Region nur noch einen Schritt entfernt. Doch die Schöpferin Maxwell hat einen furchterregenden Gegner erschaffen...","storylog.scenario.10007.title":"Mistral befreit","storylog.scenario.10008.description":"Der Beschwörer besiegt den Juggernaut und erntet Tiliths Lob. Lucius öffnet nun den Weg ins unbekannte Land Morgan.","storylog.scenario.10008.title":"Auf zu neuen Ländern","storylog.scenario.10009.description":"Auf der Suche nach Tilith betritt unser Beschwörer die Kagan-Wüste. Ein zufälliges Treffen mit Karl enthüllt, dass er den Dämon Graham jagt.","storylog.scenario.10009.title":"Wiedersehen mit Karl","storylog.scenario.10010.description":"Am Brisenstrand hört Tilith von einer schönen, aber kühlen Schwertkämpferin. Sie ist sich jedoch sicher, viel hübscher als diese Schönheit zu sein.","storylog.scenario.10010.title":"Schöne Schwertkämpferin","storylog.scenario.10011.description":"Karl verletzt sich bei der Jagd auf Graham. Der Nächtliche Wald soll das Revier eines von Grahams Untergebenen sein, der viele Beschwörer angreift.","storylog.scenario.10011.title":"Grahams Untergebener","storylog.scenario.10012.description":"Karl vertreibt Graham erfolgreich aus dem Nächtlichen Wald. Ohne Fluchtweg ist es Zeit, im Asekutt-Ödland alles zu klären.","storylog.scenario.10012.title":"Karls Verfolgung","storylog.scenario.10013.description":"Seria von den Dämonenjägern zeigt sich am Schrein von Lystia. Ihr zufolge ist Graham einer von Abaddons wertvollsten Handlangern.","storylog.scenario.10013.title":"Abaddon & Graham","storylog.scenario.10014.description":"Seria wird dem Beschwörer gegenüber feindselig. Karl will zu dritt zur Zerstörten Kathedrale weiter, doch Seria macht es ihm nicht leicht...","storylog.scenario.10014.title":"Abfuhr","storylog.scenario.10015.description":"Endlich an Abaddons Festung im Turm von Morgan angekommen, wehren Karl und Seria heranstürmende Gegner ab, damit der Beschwörer vorrücken kann.","storylog.scenario.10015.title":"Für meine Kameraden","storylog.scenario.10016.description":"Abaddon ist besiegt. Nach einem Treffen und erneuten Abschied von Karl brechen Tilith und der Beschwörer nach St. Lamia auf, um Maxwell zu finden.","storylog.scenario.10016.title":"Zur feindlichen Basis","storylog.scenario.10017.description":"Am Vulkan Eldent warnt Tilith, dass es inakzeptabel ist, seine Pflichten zu vernachlässigen. Sie selbst habe bei ihrer Arbeit nie gefaulenzt, aber...","storylog.scenario.10017.title":"Nicht faulenzen!","storylog.scenario.10018.description":"Tilith versucht, etwas über den Heiligen Berg Craylia zu erzählen, doch es geht ihr offenbar nicht gut. Angeblich hat sie sich erkältet...","storylog.scenario.10018.title":"Ein schlechtes Omen","storylog.scenario.10019.description":"Im Blutwald gibt sich Tilith alle Mühe, so zu tun, als ginge es ihr nicht schlechter. Doch man sieht deutlich, wie sehr es sie mitnimmt...","storylog.scenario.10019.title":"Bluff","storylog.scenario.10020.description":"Am Berg Wistorea gesteht Tilith endlich ihren schlechten Zustand. Je näher sie dem Palast von St. Lamia kommt, desto stärker wirkt Maxwells Fluch.","storylog.scenario.10020.title":"Der Fluch","storylog.scenario.10021.description":"Im Abgeschiedenen Heiligtum bricht Tilith zusammen. Der Beschwörer vertraut sie Seria an und zieht allein zum Palast von St. Lamia, um den Fluch zu brechen.","storylog.scenario.10021.title":"Ein Versprechen","storylog.scenario.10022.description":"Von Karl gerettet, verfolgt der Beschwörer Maxwell im Palast von St. Lamia. Kann Tilith wirklich von diesem schrecklichen Fluch befreit werden?!","storylog.scenario.10022.title":"Etwas, das man beschützen will","storylog.scenario.10023.description":"Mit gebrochenem Fluch ist Tilith wieder ganz die Alte, gerät aber irgendwie in einen dramatischen Streit mit Seria...","storylog.scenario.10023.title":"Fall der Schöpferin","storylog.scenario.10100.description":"Als Eriole erfährt, dass die Akras-Beschwörerhalle die südliche Region von Mistral geöffnet hat, schickt er Paris nach Cordelica...","storylog.scenario.10100.title":"Der Plan beginnt","storylog.scenario.10101.description":"In den Greskya-Höhlen trifft der Beschwörer auf den Dämonenjäger Lugina. Er hat keinen Respekt vor der regulären Armee und verlangt, dass der Beschwörer verschwindet.","storylog.scenario.10101.title":"Dämonenjäger Lugina","storylog.scenario.10102.description":"An den Ignia-Fällen erklärt Lugina, wie das Randall-Imperium und die Akras-Beschwörerhalle das Leben in Elgaia beeinflussen.","storylog.scenario.10102.title":"Lage in Elgaia","storylog.scenario.10103.description":"Im Lomass-Wald erklärt Lugina, wie die Beschwörerarmee funktioniert. Als Elite verlangt er, dass der Beschwörer seine Autorität respektiert.","storylog.scenario.10103.title":"Die Beschwörerarmee","storylog.scenario.10104.description":"Paris zeigt sich in der Festung Valtan. Sie bittet den Beschwörer um Mithilfe bei der Landvermessung von Cordelica, aber...","storylog.scenario.10104.title":"Paris\' Bitte","storylog.scenario.10105.description":"Auf dem Weg zum Turm des Lichts erwähnt Paris, dass der Beschwörer ein Freund von Karl ist, doch Lugina kauft es ihr nicht ab. Er scheint Karl nicht zu mögen.","storylog.scenario.10105.title":"Dieser Schnösel!","storylog.scenario.10106.description":"In der Cordelica-Mine erklärt Paris, dass einst ein Volk von Riesen die Insel bewohnte. Anscheinend ist auch der Gott der Riesen erwacht.","storylog.scenario.10106.title":"Ein Riesengott","storylog.scenario.10107.description":"Während Lugina in den Ruinen des Riesen den Riesengott Grantos besiegen soll, bittet Paris den Beschwörer, wahre Stärke zu zeigen.","storylog.scenario.10107.title":"Eifriger Lugina","storylog.scenario.10108.description":"Als er erfährt, dass der Beschwörer Grantos besiegt hat, verkündet Eriole lachend, dass sich die Welt in die richtige Richtung bewegt...","storylog.scenario.10108.title":"Erioles Motive","storylog.scenario.10200.description":"Lucius führt den Beschwörer zum Palmyna-Archipel, während ein gewisser Mann in Randall erfährt, dass die Barriere über diesen Inseln verschwunden ist.","storylog.scenario.10200.title":"Ritteraufseher","storylog.scenario.10201.description":"Das nächste Ziel ist Cardes der Bösartige, ein weiterer der Vier Gefallenen Götter. Im Dorf Julep hörst du, dass die Hälfte seiner Kraft noch versiegelt ist.","storylog.scenario.10201.title":"Cardes der Bösartige","storylog.scenario.10202.description":"Tilith behauptet, auf dem Geisterschiff Legnia keine Angst zu haben. Immerhin erzählt sie etwas über Palmyna, wo Cardes versiegelt ist...","storylog.scenario.10202.title":"Weg nach Palmyna","storylog.scenario.10203.description":"In der Elios-Ebene wird der Beschwörer plötzlich von einem seltsamen Mann angegriffen. Doch seine Präsenz verschwindet so schnell, wie sie aufgetaucht ist.","storylog.scenario.10203.title":"Ein geheimnisvoller Mann","storylog.scenario.10204.description":"Bei einem Treffen mit Seria und Karl in den Saji-Minen zeigt sich, dass sie noch hinter Graham her sind. Karl warnt den Beschwörer vor einem gewissen Zebra.","storylog.scenario.10204.title":"Sein Name ist Zebra","storylog.scenario.10205.description":"Tilith und ihr Beschwörer treffen im Lamellia-Tempel auf „Elder Grah“. Der alte Mann gibt an, die Legenden um die Vier Gefallenen Götter zu erforschen.","storylog.scenario.10205.title":"Ein geheimnisvoller Alter","storylog.scenario.10206.description":"Karl und Seria stellen Graham in der Geisterstadt Edila, werden aber von einer unbekannten, mächtigen Kraft weggeschleudert, sodass Graham entkommt.","storylog.scenario.10206.title":"Unbekannte Kraft","storylog.scenario.10207.description":"Im Schloss Amdahl erzählt Elder Grah vom rachsüchtigen Geist des letzten Kaisers von Amdahl, der wohl noch immer im Schloss umgeht.","storylog.scenario.10207.title":"Amdahls letzter Kaiser","storylog.scenario.10208.description":"Elder Grah ist beeindruckt, dass der Beschwörer den bösen Geist bezwungen hat. Seria eilt herbei und scheint den Alten irgendwie zu kennen.","storylog.scenario.10208.title":"Seria & Elder Grah","storylog.scenario.10209.description":"Von Lucius geführt, erreicht der Beschwörer Encervis. Laut Tilith verwüstete hier vor langer Zeit ein Bürgerkrieg der Menschen das Land.","storylog.scenario.10209.title":"Ruinen der Vergangenheit","storylog.scenario.10210.description":"Am Elsta-Krater erzählt Tilith dem Beschwörer, wie hart sie bisher gearbeitet hat. Ihre Behauptungen wirken aber irgendwie fragwürdig...","storylog.scenario.10210.title":"Fleißige Tilith","storylog.scenario.10211.description":"Zebra greift plötzlich am Aldela-See an, doch dank Elder Grahs Hilfe bleibt ernster Schaden aus. Dieser mächtige Gegner scheint in einer schwebenden Festung zu leben.","storylog.scenario.10211.title":"Die Himmelsfestung erwacht","storylog.scenario.10212.description":"Elder Grah erzählt von Amdahls Geschichte und grübelt über Schloss Avenia. Er bittet den Beschwörer, die Himmelsfestung zu zerstören, doch Tilith ist gleichgültig...","storylog.scenario.10212.title":"Amdahls Geschichte","storylog.scenario.10213.description":"In der Gadillian-Schlucht beraten Zebra und die Dunkle Gestalt, wie sie mit dem Beschwörer verfahren sollen. Was verbindet die beiden nur...?","storylog.scenario.10213.title":"Zebra & eine dunkle Gestalt","storylog.scenario.10214.description":"Seria und Karl suchen den Beschwörer im Alman-Mausoleum. Beide wollen mit ihrer Kraft helfen, die Himmelsfestung zu Fall zu bringen.","storylog.scenario.10214.title":"Beruhigende Unterstützung","storylog.scenario.10215.description":"Im Land der Toten verrät Tilith, dass die Himmelsfestung offiziell Solaris heißt. Sie will mit ihren Kräften beim Eindringen helfen.","storylog.scenario.10215.title":"In die Festung","storylog.scenario.10216.description":"Dank Tiliths Kräften gelingt das Eindringen in die Himmelsfestung Solaris. Zebra sieht darin eine Gelegenheit, die erschöpfte Göttin anzugreifen.","storylog.scenario.10216.title":"Zebra gegen Tilith","storylog.scenario.10217.description":"Zebra ist endlich besiegt. Doch er zerstört Solaris, um den Beschwörer mit in den Abgrund zu reißen. Wer kann diese Tragödie verhindern...?","storylog.scenario.10217.title":"Zebra & Grahdens","storylog.scenario.10218.description":"Durch Lucius\' Führung erreicht der Beschwörer Palmyna. Die Spuren eines Königreichs, das gegen die Götter kämpfte, sind hier noch deutlich zu sehen.","storylog.scenario.10218.title":"Das Schlachtfeld","storylog.scenario.10219.description":"Tilith ist zunächst im Schloss Obselion, eilt aber zu den Dejour-Ruinen, um zu warnen, dass das Siegel von Cardes zu schwinden beginnt.","storylog.scenario.10219.title":"Das schwindende Siegel","storylog.scenario.10220.description":"Im Schloss Obselion ist Grahdens mit dem Beschwörer allein. Er erzählt von den 4 Helden von Palmyna, die Cardes den Bösartigen versiegelten.","storylog.scenario.10220.title":"4 Helden von Palmyna","storylog.scenario.10221.description":"Auf dem Smaragdpfad erfahren Seria und Karl, dass sie in die Geisterwelt reisen müssen, um Cardes zu besiegen. Doch Seria benimmt sich seltsam...","storylog.scenario.10221.title":"Seltsame Seria","storylog.scenario.10222.description":"In den Grandelt-Ruinen verrät Tilith, dass Cardes\' Körper langsam zerfällt und seine göttlichen Kräfte außer Kontrolle geraten.","storylog.scenario.10222.title":"Amoklauf der Götter","storylog.scenario.10223.description":"Im Arlind-Seminar äußert Grahdens Zweifel an den früheren und jüngsten Taten der Götter. Seine Gedanken scheinen den Beschwörer zu beeinflussen.","storylog.scenario.10223.title":"Grahdens\' Zweifel","storylog.scenario.10224.description":"Karl und Seria begleiten den Beschwörer auf dem Noera-Schlachtfeld zu den Toren der Unterwelt. Beide sorgen sich um Tilith.","storylog.scenario.10224.title":"Der Eingang zum Hades","storylog.scenario.10225.description":"In der Geisterwelt Palmyna trennen sich der Beschwörer und die anderen, um Cardes zu finden. Kann er besiegt werden, bevor er alles zerstört?","storylog.scenario.10225.title":"Kampf gegen Cardes","storylog.scenario.10226.description":"Als alle aus der zerfallenden Unterwelt fliehen wollen, wird Seria verletzt. In dieser verzweifelten Lage erscheint Tilith als Retterin.","storylog.scenario.10226.title":"Die wiedergeborene Göttin","storylog.scenario.10300.description":"Nachdem Eriole Paris\' Bericht gehört hat, schickt er sie nach Lizeria. Wonach mag er wohl suchen?","storylog.scenario.10300.title":"Die Suche","storylog.scenario.10301.description":"Lugina taucht in der Erinecht-Ebene auf und behauptet, eine viel wichtigere Mission zu haben als der Beschwörer. Seine streitlustige Art hat sich nicht geändert.","storylog.scenario.10301.title":"Luginas Mission","storylog.scenario.10302.description":"Im Golzo-Gebirge stellt sich heraus, dass Paris nach einer schlummernden Macht in Lizeria sucht. Und anscheinend ist Lugina hinter derselben Sache her.","storylog.scenario.10302.title":"Ein Ziel für zwei","storylog.scenario.10303.description":"Am Lodan-Eissee glaubt Lugina fälschlich, Paris habe den Beschwörer zum Verrat gebracht. Alles klärt sich auf, doch Lugina besteht auf einem Training...","storylog.scenario.10303.title":"Luginas Training","storylog.scenario.10304.description":"In den unpassierbaren Sümpfen spricht Paris über die Gesellschaftsordnung von Elgaia. Es scheint, als misstraue sie der Macht der Beschwörerhalle.","storylog.scenario.10304.title":"Die dunkle Seite der Halle","storylog.scenario.10305.description":"Im Blitzwald Zaljiba erwähnt Paris die dunkle Seite der Beschwörerhalle. Daraufhin wird Lugina danach gefragt, und er antwortet entsprechend.","storylog.scenario.10305.title":"Luginas Beweggründe","storylog.scenario.10306.description":"In der Verlorenen Stadt La Veda teilt Paris ihre Zweifel an den Göttern und spricht über die Instabilität der Welt. Sie will die Dinge selbst in die Hand nehmen.","storylog.scenario.10306.title":"Paris\' Beweggründe","storylog.scenario.10307.description":"Auf der Schwarzen Brücke sagt Lugina, er werde jeden zermalmen, der ihm in die Quere kommt, und macht dem Beschwörer ein letztes Geständnis, bevor er weiterzieht.","storylog.scenario.10307.title":"Letzte Warnung","storylog.scenario.10308.description":"Obwohl Lugina gegen den Beschwörer verliert, behauptet er, er könne unmöglich versagt haben, und leugnet weiter seine eigene Niederlage.","storylog.scenario.10308.title":"Luginas Niederlage","storylog.scenario.10309.description":"Am Turm der Zerstörung weigert sich die verletzte Paris noch immer, die schlummernde Macht der Region aufzugeben. Sie wird dem Beschwörer sein Eindringen nicht verzeihen.","storylog.scenario.10309.title":"Paris\' Entschlossenheit","storylog.scenario.10310.description":"Ein Verteidigungssystem, das Beschwörer vernichten kann. Doch das, wonach Paris sucht und das ganz nah sein müsste, ist nirgends zu sehen...","storylog.scenario.10310.title":"Zerstörerische Macht","storylog.scenario.10400.description":"Tilith und der Beschwörer brechen auf, um Zevalhua den Erhabenen zu besiegen. Ohne ihr Wissen sind auch Eriole und Paris auf dem Weg nach Agni...","storylog.scenario.10400.title":"Doppelte Reise","storylog.scenario.10401.description":"In der Glomore-Senke wollen Karl und Seria helfen, Zevalhua zu besiegen, während eine geheimnisvolle Frau sie verächtlich aus der Ferne beobachtet.","storylog.scenario.10401.title":"Kameraden","storylog.scenario.10402.description":"Im Schneegebiet Khelne taucht plötzlich die Jüngerin Mare auf und fordert Karl auf, sie allein in den Azura-Ruinen zu treffen, um ihm ein Geheimnis zu enthüllen.","storylog.scenario.10402.title":"Karls Vergangenheit","storylog.scenario.10403.description":"Seria sorgt sich im Stokhelna-Wald um Karl, als Mare erneut auftaucht und verkündet, dass Karl ihr direkt in die Hände gespielt hat...","storylog.scenario.10403.title":"Jüngerin Mare","storylog.scenario.10404.description":"Seria tappt in den Azura-Ruinen in Mares Falle und wird verletzt. Tilith überlässt Karls Rettung dem Beschwörer, während sie sich um Seria kümmert.","storylog.scenario.10404.title":"Seria in der Falle","storylog.scenario.10405.description":"Grahdens erwartet den Beschwörer im Ryvern-Gebirge und teilt seine Erinnerungen an Karl. Er will sich von Mare gefangen nehmen lassen, um Karl zu befreien.","storylog.scenario.10405.title":"Grahdens & Karl","storylog.scenario.10406.description":"Mare zeigt sich dem einsamen Beschwörer in der Abgrundhöhle. Gerade als sie angreifen will, kehrt Tilith zurück und verhindert es.","storylog.scenario.10406.title":"Tiliths Schleichweg","storylog.scenario.10407.description":"Mare hetzt im Weißen Turm Granvalm auf den Beschwörer und flieht. Doch Tilith lässt sie nicht so leicht entkommen.","storylog.scenario.10407.title":"Granvalm der Weiße","storylog.scenario.10408.description":"Nach Granvalms Niederlage taucht Mare erneut auf, und in dieser ausweglosen Lage rettet ein unerwarteter Verbündeter allen die Haut...","storylog.scenario.10408.title":"Unerwartete Hilfe","storylog.scenario.10409.description":"Lugina rettet den Beschwörer in Ryvern, um Grahdens\' Bitte zu erfüllen. Er besteht darauf, dass man ihn um Hilfe bei Karls Rettung gebeten hat.","storylog.scenario.10409.title":"Sei dankbar","storylog.scenario.10410.description":"Im Agni-Imperium ist Lugina ganz begeistert von der Rettungsmission. Er hält sie für die perfekte Chance, seine Mission zu erfüllen und sich über Karl lustig zu machen.","storylog.scenario.10410.title":"Luginas Bestes","storylog.scenario.10411.description":"Lugina hat es satt, auf Mare zu warten, lässt den Beschwörer an der Agniria-Küste zurück und sucht allein nach Karl...","storylog.scenario.10411.title":"Erneuter Aufbruch","storylog.scenario.10412.description":"Auf der Granasta-Hochebene zeigt sich Mare endlich. Doch sie will nicht kämpfen. Stattdessen verlangt sie, dass der Beschwörer ihr folgt, um Karl zu retten.","storylog.scenario.10412.title":"Mare die Betrügerin","storylog.scenario.10413.description":"Mare erinnert sich an eine Person, die im Krieg gegen die Götter kämpfte, während der gequälte Beschwörer sie bis zum Donnergipfel Navara verfolgt.","storylog.scenario.10413.title":"Mares Erinnerungen","storylog.scenario.10414.description":"Der Beschwörer dringt ins Königsgrab vor, ohne die Hoffnung auf Karls Rettung aufzugeben. Mare versteht diese Hartnäckigkeit nicht und schlägt endlich zu.","storylog.scenario.10414.title":"Gegensätzliche Kräfte","storylog.scenario.10415.description":"Gerade als Mare in der Lognea-Bucht den Todesstoß führen will, springt die eigentlich schwer verletzte Seria ein und rettet den Beschwörer.","storylog.scenario.10415.title":"Gegenangriff","storylog.scenario.10416.description":"Im Meeresschrein Albina taucht eine Horde Gegner auf und bringt Seria und den Beschwörer in die Klemme. Doch Lugina erscheint gerade rechtzeitig mit dem befreiten Karl.","storylog.scenario.10416.title":"Die Rettung","storylog.scenario.10417.description":"Mare wird endlich vom Beschwörer besiegt, doch plötzlich erscheint Paris und meldet, dass Grahdens gefangen genommen wurde.","storylog.scenario.10417.title":"Grahdens gefangen","storylog.scenario.10418.description":"Der Beschwörer betritt endlich Mirvana. Tilith erklärt, dass hier die blutigste Schlacht des großen Krieges gegen die Götter tobte.","storylog.scenario.10418.title":"Altes Schlachtfeld","storylog.scenario.10419.description":"Grahdens wurde von Zevalhua dem Erhabenen gefangen genommen. Um ihn zu retten, teilen sich der Beschwörer und die anderen in der Höhle der Dunkelheit in Gruppen auf.","storylog.scenario.10419.title":"Suchtrupp, sammeln!","storylog.scenario.10420.description":"Auf dem Arvest-Schneefeld fragt sich Paris argwöhnisch, warum die Götter Grahdens gefangen genommen haben, statt ihn einfach sofort zu töten...","storylog.scenario.10420.title":"Verdächtiges Verhalten","storylog.scenario.10421.description":"Bei der Suche nach Grahdens im Baummeer Marleg lädt Paris den Beschwörer erneut ein, sich ihrer Sache anzuschließen. Doch Tilith unterbricht sie.","storylog.scenario.10421.title":"Wessen Beschwörer?","storylog.scenario.10422.description":"Lugina weist Paris im Sumpf des ewigen Regens zurecht. Doch bevor es schlimmer wird, mischt sich Seria ein und gerät mit Lugina in Streit.","storylog.scenario.10422.title":"Lugina & Seria","storylog.scenario.10423.description":"Am Kap Narasta wird Grahdens\' Aufenthaltsort bestätigt, und Paris fragt sich, warum Lucius die Vier Gefallenen Götter nicht selbst besiegt.","storylog.scenario.10423.title":"Paris\' Zweifel","storylog.scenario.10424.description":"Karl dankt Tilith, als sie in den Mirvana-Ruinen mehr über Grahdens verrät. Lugina und Seria setzen derweil ihren üblichen Streit fort.","storylog.scenario.10424.title":"Sie ändern sich nie","storylog.scenario.10425.description":"Die ganze Gruppe hat endlich den Turm der Götter erreicht. Werden sie Zevalhua den Erhabenen besiegen und Grahdens retten können?","storylog.scenario.10425.title":"Zevalhua der Erhabene","storylog.scenario.10426.description":"Grahdens zeigt sich und enthüllt das Geheimnis von Karls Herkunft. Zugleich taucht plötzlich Eriole auf und will mit dem Ältesten sprechen.","storylog.scenario.10426.title":"Das Geheimnis der Herkunft","storylog.scenario.20000.description":"Lin vom Ermittlungsbüro des Vermessungsamts bittet den Beschwörer, das Egor-Gebirge zu erkunden. Dort soll ein Eisdämon schlummern.","storylog.scenario.20000.title":"Bergdämon","storylog.scenario.20001.description":"Lin erzählt von Skramyas Vergangenheit. Der Legende nach versiegelte ein Held den Dämon, nachdem er die Nation zerstören wollte, die ihn benutzen wollte.","storylog.scenario.20001.title":"Die Vergangenheit des Dämons","storylog.scenario.20002.description":"Lin bittet den Beschwörer, die Ignia-Grotte zu erkunden. Anscheinend ist dort nach den Erdbeben in Cordelica ein Dämon erwacht...","storylog.scenario.20002.title":"Klebrig & schleimig","storylog.scenario.20003.description":"Der Beschwörer besiegt den riesigen, unkontrollierbaren Dämon. Lin singt Loblieder auf ihn, doch plötzlich ändert sich ihre Haltung völlig...","storylog.scenario.20003.title":"Was Lin nicht mag","storylog.scenario.20004.description":"Lin übermittelt dem Beschwörer Informationen, laut denen in Valmodoras Nest ein Dämon haust. Sie erwartet, dass der Beschwörer mehr herausfindet.","storylog.scenario.20004.title":"Gigantischer Dämon","storylog.scenario.20005.description":"Der Beschwörer besiegt Valmodora bei der Erkundung des Ortes. Die Ruinen beherbergten tatsächlich etwas Gigantisches.","storylog.scenario.20005.title":"Geheimnisvolle Ruinen","storylog.scenario.20006.description":"Der Beschwörer spürt eine gewaltige Macht vom Grund des Unterirdischen Sees von Golzo ausgehen. Lin hat ein schlechtes Gefühl dabei, bittet aber um eine Erkundung.","storylog.scenario.20006.title":"Lins böse Vorahnung","storylog.scenario.20007.description":"Lagzal, der unter der Erde schlummerte, war ein Gott, der die Menschen vernichten wollte. Anscheinend hat sich Lin während der Expedition große Sorgen um den Beschwörer gemacht.","storylog.scenario.20007.title":"Der Gefallene Gott Lagzal","storylog.scenario.20008.description":"Beim Durchqueren des Agni-Dungeons bittet Lin den Beschwörer, ein gewisses „böses Wesen“ zu bezwingen, das darin eingesperrt ist.","storylog.scenario.20008.title":"Im Dungeon verborgen","storylog.scenario.20009.description":"Laut Lin war das Eingesperrte der Geist eines gefürchteten Tyrannen, den seine eigenen Gefolgsleute versiegelt hatten.","storylog.scenario.20009.title":"Ende eines Tyrannen"}')}]);